	["*bosteza* Cazar contigo es lo mejor de mi día."] = "*打哈欠* 和你一起狩猎是我一天中最开心的事。",
	["*la devora en un segundo* ¡Gracias! Ahora sí, a cazar."] = "*一秒就吞下去了* 谢谢！现在可以去狩猎了。",
	["*levanta la manita* ¿Salchicha? Prometo cuidarte el doble."] = "*举起小爪子* 香肠吗？我保证加倍照顾你。",
