	["*mueve la cola* Huelo una salchicha en tu mochila. ¿Me la das?"] = "*摇着尾巴* 我闻到你背包里有香肠。给我好不好？",
	["*olfatea el aire* Huele a aventura."] = "*嗅了嗅空气* 有冒险的味道。",
	["*olfatea el suelo* Por aquí pasó un jabalí... hace rato."] = "*嗅嗅地面* 有一头野猪从这儿经过……有一阵子了。",
	["*persigue su cola un ratito* …¡Casi la atrapo!"] = "*追了一会儿自己的尾巴* ……差点就抓到了！",
	["*se echa un ratito* No estoy dormida, estoy vigilando con los ojos cerrados."] = "*趴下来歇一会儿* 我没睡着，我是闭着眼睛在站岗。",
	["*se estira y bosteza* Listo, ¡a seguir!"] = "*伸了个懒腰，打了个哈欠* 好了，继续出发！",
	["*se rasca la oreja* Listo, ya me quedé tranquila."] = "*挠挠耳朵* 好了，这下舒服了。",
	["*se sienta y te mira con ojitos tiernos* ¿Me das una salchicha? Solo una… bueno, una."] = "*坐下来用水汪汪的眼睛看着你* 能给我一根香肠吗？就一根……好吧，一根。",
