	["Abrir su guía"] = "打开它的指南",
	["Abrumar casi siempre crítico."] = "压制几乎必定暴击。",
	["Abrumar crítico contra pícaros que esquivan."] = "对会躲闪的潜行者，压制更容易暴击。",
	["Abrumar hace crítico casi siempre."] = "压制几乎每次都暴击。",
	["Abrumar hace crítico mucho más seguido."] = "压制暴击的几率大幅提高。",
	["Acaba de abrirle la puerta a alguien. Prueba en un momento."] = "刚给别人开过门。稍后再试。",
	["Acabas de vencer a un enemigo: este ataque es gratis y te cura."] = "你刚击败了一个敌人：这次攻击免费，还能治疗你。",
	["Accesos rápidos"] = "快捷入口",
	["Acecho"] = "潜行",
	["Acento propio (elegido en Ajustes)"] = "自定义强调色（在设置中选择）",
	["Acento: %s"] = "强调色：%s",
	["Acepta invitaciones de grupo de tus amigos y de tu hermandad."] = "接受好友和公会成员的组队邀请。",
	["Acepta por ti"] = "替你接受",
	["Acepta su invitación al grupo. Al llegar a su guarida, Alfa te avisa para salir del grupo."] = "接受他的组队邀请。到了他的巢穴后，Alfa 会提醒你离队。",
	["Acepta una invocación al momento, salvo en combate."] = "立即接受召唤，战斗中除外。",
	["Acepta una resurrección en cuanto se puede. Nunca en Hardcore."] = "一有机会就接受复活。硬核模式下绝不接受。",
	["Acepta y entrega las demás (normales, diarias y semanales). Nunca las grises ni las que piden oro o materiales."] = "接受并交付其余任务（普通、日常和周常）。绝不接灰色任务，也不接要求金币或材料的任务。",
	["Acepta y entrega tus misiones, elige tu guía y sigue sola, vende, repara y toma tus vuelos. Tú solo juegas."] = "接交任务、选指南并继续、卖东西、修理、坐飞行。你只管玩。",
	["Aceptar"] = "确定",
	["Aceptar invocaciones"] = "接受召唤",
	["Aceptar las misiones de tu guía"] = "接受指南中的任务",
	["Aceptar resurrecciones"] = "接受复活",
	["Aceptar solas las misiones de la guía"] = "自动接受指南中的任务",
	["Aceptar todas las misiones ya no pierde una diaria porque la ventana se cerraba antes de tiempo."] = "接受所有任务时，不会再因为窗口过早关闭而漏掉日常任务。",
	["Aceptar y entregar"] = "接受并交付",
	["Aceptar y entregar misiones"] = "接受和交付任务",
	["Aceptar y entregar solo las misiones de mi ruta"] = "只接受和交付我路线上的任务",
	["Aceptar y entregar todas las misiones"] = "接受并交付所有任务",
	["Acercar"] = "放大",
	["Acomoda con el ratón a Lya, tu guía, la flecha y tus marcos: Ajustes > Estilo y sonido o /alfa acomodar."] = "用鼠标布置 Lya、你的指南、箭头和框体：设置 > 风格与声音，或 /alfa acomodar。",
	["Acomoda tus marcos"] = "摆放你的框体",
	["Acomodar"] = "整理",
	["Acomodar [pantalla]"] = "布置",
	["Acomodar la pantalla"] = "布置界面",
	["Actitud de batalla"] = "战斗姿态",
	["Actitud defensiva"] = "防御姿态",
	["Actitud rabiosa"] = "狂暴姿态",
	["Activa el rastreo de hierbas para verlas en el minimapa mientras viajas."] = "开启寻找草药，旅行时就能在小地图上看到它们。",
	["Activa el rastreo de minerales y sigue las montañas: ahí están las mejores vetas."] = "开启寻找矿物，沿着山脉走：最好的矿脉都在那里。",
	["Activa máquinas en las paredes que sueltan bombas que caminan: pulsa el botón junto a la máquina para apagarla, o maten las bombas antes de que lleguen."] = "他会启动墙上的机器，放出会走路的炸弹：按机器旁的按钮可以关掉它，或者在炸弹走过来之前打掉。",
	["Activar el medidor de daño"] = "启用伤害统计",
	["Activar el modo limpio"] = "开启简洁模式",
	["Activar módulo"] = "开启模块",
	["Activar módulos"] = "开启模块",
	["Activo"] = "已生效",
	["Actual"] = "当前",
	["Actualizar mi guía"] = "更新我的指南",
	["Actualizar mis barras"] = "更新我的动作条",
	["Actualízala con la app de CurseForge o con el zip más reciente y luego usa /reload."] = "请用 CurseForge 应用或最新的 zip 更新，然后输入 /reload。",
	["Actualízalo con la app de CurseForge o con el zip más reciente y luego reinicia el juego o usa /reload."] = "请使用 CurseForge 应用或最新的压缩包更新，然后重启游戏或输入 /reload。",
	["Acércate para usar %s"] = "靠近一点才能使用 %s",
	["Además del ícono, un brillo dorado que late alrededor de su barra."] = "除了图标，其框体周围还会有一圈跳动的金色光芒。",
	["Adopta a un lobo 10 niveles menor que tú. Si acepta, ves su nivel, su zona y su misión (solo tú) y te aviso si se atora."] = "收养一只比你低 10 级的狼。如果他接受，你能看到他的等级、区域和任务（只有你能看到），他卡住时我会告诉你。",
	["Adopta a un lobo nuevo o deja que uno con más nivel te adopte. Lo que comparten queda entre los dos."] = "收养一只新来的狼，或让等级更高的狼收养你。你们分享的内容只有你们两个知道。",
	["Adoptar"] = "收养",
	["Afinar cosa por cosa"] = "逐项细调",
	["Afinar siempre"] = "始终锐化",
	["Aflicción"] = "痛苦",
	["Aflicción para subir"] = "痛苦（升级）",
	["Agarras a varios enemigos a la vez."] = "你能同时拉住多个敌人。",
	["Agilidad"] = "敏捷",
	["Agrega la primera: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota."] = "添加第一个：物品、金币、专业、地点、任务、等级或备注。",
	["Agrega tramos arriba: Alfa elige las misiones por ti."] = "在上方添加路段：Alfa 会为你选择任务。",
	["Agrega una línea con el objetivo de esa unidad; si te tiene a ti, lo dice."] = "添加一行显示该单位的目标；如果目标是你，会特别标出。",
	["Agregada"] = "已加入",
	["Agregada a Cerrar mis misiones"] = "已加入“完成我的任务”",
	["Agregado a tu plan"] = "已添加到你的计划",
