	["Agregar a mi lista"] = "加入我的清单",
	["Agregar a mi ruta"] = "加入我的路线",
	["Agregar lo que me falta"] = "加入我缺的东西",
	["Agregar todo a mi lista"] = "全部加入我的清单",
	["Agregar un tramo:"] = "添加路段：",
	["Agregar una meta"] = "添加目标",
	["Agregué %s ×%d a tu lista."] = "已把 %s ×%d 加入你的清单。",
	["Agregué lo que falta para %s"] = "已添加 %s 所需的前置条件",
	["Agregué lo que te falta para subir %s. Lo ves en Comercio."] = "已把升级 %s 还缺的东西加入清单。你会在交易里看到。",
	["Agrégale una en Mis planes."] = "在“我的计划”中添加一个。",
