	["Agua de manantial refrescante"] = "清凉的泉水",
	["Agua y comida"] = "水和食物",
	["Agua: llevas %d (mejor %d o más). A tu nivel: %s"] = "水：你带了 %d 个（最好 %d 个以上）。适合你等级的：%s",
	["Aguante"] = "耐力",
	["Aguas conocidas"] = "已知水域",
	["Ahora"] = "现在",
	["Ahora corre más que la manada. ¡Auuu!"] = "现在他跑得比狼群还快了。嗷呜！",
	["Ahora estás en la %s. Ya puedes salir del grupo: el plano se queda contigo."] = "你现在在%s。你可以离开队伍了：位面会保留。",
	["Ahora ganas la XP normal"] = "现在获得的是正常经验值",
	["Ahora mismo te ayudaría con"] = "现在我可以帮你",
	["Ahora no"] = "暂不",
	["Ahora no hay nada de Alfa a la vista para mover. Abre tu guía, la pesca o Lya y vuelve a entrar."] = "现在屏幕上没有可以移动的 Alfa 元素。打开你的指南、钓鱼或 Lya 后再进来。",
	["Ahora no pude armar el camino a esta misión."] = "现在无法生成前往这个任务的路线。",
	["Ahora no sale: Alfa busca cómo unirse a la manada."] = "目前未发送：Alfa 正在寻找连接狼群的方式。",
	["Ahora no se puede"] = "现在无法进行",
	["Ahora no se puede anunciar"] = "现在无法通报",
	["Ahora no se puede avisar a la manada. Inténtalo en un momento."] = "现在无法通知狼群。稍后再试。",
	["Ahora no se puede hablar con la manada. Prueba en un rato."] = "现在联系不上狼群。过一会儿再试。",
	["Ahora no se puede llamar a la manada: Alfa busca cómo unirse a ella."] = "现在无法呼唤狼群：Alfa 正在寻找加入的方法。",
	["Ahora no se pueden enviar mensajes (en una instancia o con una cuenta de prueba). %s"] = "现在无法发送消息（在副本中或使用试玩账号）。%s",
	["Ahora toca la colección: completa tu diario, los logros y prueba el concurso de los domingos."] = "接下来就是收集了：填满你的图鉴、完成成就，再去试试周日的钓鱼大赛。",
	["Ahora usan: %s. Activa los pesos de %s para que Alfa compare el equipo como lo pide tu build."] = "目前使用：%s。启用%s的权重，让 Alfa 按你的方案要求比较装备。",
	["Ahora va por el canal oculto de Alfa."] = "现在通过 Alfa 的隐藏频道发送。",
	["Ahora va por tu hermandad: el canal oculto de Alfa no está disponible, así que solo te ven quienes comparten en tu hermandad."] = "现在通过你的公会发送：Alfa 的隐藏频道不可用，所以只有公会中共享位置的人能看到你。",
	["Ahora vas a: %s"] = "现在前往：%s",
	["Ahora · %s"] = "现在 · %s",
	["Ahora: %d %% del nivel %d"] = "现在：%d %%（%d 级）",
	["Ahora: %s"] = "当前：%s",
	["Ahora: %s · De fábrica: %s"] = "当前：%s · 默认：%s",
	["Ahora: %s."] = "现在：%s。",
	["Ahí no hay ninguna zona: pon el marcador sobre tierra."] = "那里没有任何区域：请把标记放在陆地上。",
	["Ahí no se puede poner la flecha."] = "无法在那里设置箭头。",
	["Ahí nos organizamos para todo. Haz clic en el enlace y cópialo con Ctrl+C."] = "我们在那里安排一切活动。点击链接后用 Ctrl+C 复制。",
