	["Ajustar los avisos"] = "调整提醒",
	["Ajustes"] = "设置",
	["Ajustes de Alfa en todos los idiomas: las fechas en el orden de cada uno y los nombres de cada especialización bien puestos."] = "所有语言的 Alfa 调整：日期按各语言的顺序显示，每个专精的名称都正确。",
	["Ajustes de Bolsas"] = "背包设置",
	["Ajustes de Lya"] = "Lya 设置",
	["Ajustes de mazmorras"] = "地下城设置",
	["Ajustes de pesca"] = "钓鱼设置",
	["Ajustes del mapa"] = "地图设置",
	["Ajustes del medidor"] = "伤害统计设置",
	["Ajustes en orden: Comodidades y Calidad de vida son una sola página con pestañas, y todo lo de misiones vive en Ajustes > Misiones. Tu configuración se mudó sola, sin perder nada."] = "设置更有条理：便利功能和生活品质合并为一个带标签页的页面，所有任务相关设置都在“设置 > 任务”中。你的设置已自动迁移，什么都没丢。",
	["Ajustes importados"] = "设置已导入",
	["Al abrir el buzón, un aviso si una carta con objetos vence en menos de 3 días."] = "打开邮箱时，如果有带物品的邮件将在 3 天内过期，会提醒你。",
	["Al abrirse el mapa de vuelo, vuela al destino que marca tu ruta."] = "打开飞行地图时，飞往你路线标记的目的地。",
	["Al acercar o cargar el mapa, cada parte aparece completa de una vez, sin cuadritos sueltos."] = "放大或加载地图时，每个部分都会一次完整出现，不再有零散的小方块。",
	["Al acercar se ven las montañas y el relieve, igual que en el minimapa. Apagado: el mapa pintado del juego."] = "放大后可以看到山脉和地形，与小地图一样。关闭：使用游戏的手绘地图。",
	["Al armar tus rutas, Alfa deja fuera las que piden élites."] = "创建路线时，Alfa 会排除需要对付精英的任务。",
	["Al banco (%d)"] = "存入银行（%d）",
	["Al cambiar de forma o de actitud, el juego usa otra barra de abajo. Si está vacía, Alfa te avisa una vez y puede llenar sus casillas vacías con las habilidades de esa forma que ya sabes, fuera de combate y sin tocar lo que ya tienes."] = "切换形态或姿态时，游戏会改用下方的另一条动作条。如果它是空的，Alfa 会提醒你一次，并可以在非战斗状态下，用你已学会的该形态技能填满它的空格，不会动你已经放好的东西。",
	["Al cambiar de forma, el juego cambia tu barra de abajo por la de esa forma, y esta todavía no tiene nada: por eso parece que desaparece. Alfa puede poner en sus casillas vacías las habilidades de esa forma que ya sabes."] = "切换形态时，游戏会把你下方的动作条换成该形态的动作条，而它还是空的：所以看起来像是消失了。Alfa 可以把你已学会的该形态技能放进它的空格。",
	["Al comerciante"] = "卖给商人",
	["Al comparar objetos, Alfa valora más lo que pide %s: lo de arriba en la lista de estadísticas."] = "比较物品时，Alfa 更看重%s需要的属性：即属性列表上方的那些。",
	["Al completar una misión vuelve a salir en el chat: «[Misión] está lista para entregar» y, al entregarla, «¡Misión completada!». En grupo lo ve todo el grupo; solo, tú."] = "完成任务会再次显示在聊天中：“[任务] 可以交付了”，交付时“任务完成！”。组队时全队可见；单人时只有你看到。",
	["Al completar una misión vuelve a salir en tu chat: «[Misión] está lista para entregar» y «¡Misión completada!». Si lo prendes, también tu grupo lo ve."] = "完成任务会再次显示在你的聊天框：“[任务] 可以交付了”和“任务完成！”。打开后队伍也能看到。",
	["Al curar con un clic, ese compañero queda seleccionado para tus otros poderes."] = "点击治疗时，那名队友会被选中，方便使用你的其他技能。",
	["Al día"] = "已分配完",
	["Al elegir un build, las flechas de mejora de tus bolsas valoran lo que ese build necesita."] = "选择方案后，背包中的提升箭头会按该方案的需要评估。",
	["Al empezar aturde a quien lo despertó en el altar: es normal."] = "开场时他会击晕在祭坛唤醒他的人：这是正常的。",
	["Al enemigo le queda poca vida: Quemadura de las Sombras lo remata."] = "敌人生命值很低：暗影灼烧可以终结它。",
	["Al enemigo le queda poca vida: remátalo al instante."] = "敌人生命值很低：立刻终结它。",
	["Al enemigo le queda poca vida: remátalo."] = "敌人生命值很低：补上最后一击。",
	["Al entrar a una mazmorra, Lya te da un consejo corto y un botón para verla. Nunca en combate."] = "进入地下城时，莉娅会给你一条简短的建议和一个查看按钮。战斗中绝不打扰。",
	["Al entrar a una zona con enemigos muy arriba de tu nivel, un aviso corto (una vez por zona)."] = "进入敌人等级远高于你的区域时，给一条简短提醒（每个区域一次）。",
	["Al entrar al juego"] = "进入游戏时",
	["Al entrar al juego, Lya te dice quién de tu hermandad anda conectado y dónde."] = "登录游戏时，莉娅会告诉你公会里谁在线、在哪儿。",
	["Al entrar o al juntarse tu grupo reviso tu equipo, tus bolsas, tu comida y lo de tu clase. Si falta algo te digo qué y te llevo a conseguirlo. También con /alfa listo."] = "你进去或队伍满员时，我会检查你的装备、背包、食物和职业材料。缺什么我会告诉你，并带你去买。也可以用 /alfa listo。",
	["Al entrar o al juntarse tu grupo: equipo, bolsas, comida, agua, munición y lo de tu clase. Nunca en combate."] = "进入时或队伍满员时：装备、背包、食物、水、弹药和职业材料。战斗中绝不会。",
	["Al entrar solo sale la animación; lo demás te espera en Hoy y con Lya."] = "登录时只播放动画；其余内容在“今日”和 Lya 那里等你。",
	["Al entregar una misión, Lya te ofrece contarte cómo terminó."] = "交付任务时，Lya 会提出给你讲讲它的结局。",
	["Al final de la Tercera Guerra, Arthas subió al Trono Helado, se puso el yelmo y se volvió uno con el Rey Exánime."] = "第三次战争结束时，阿尔萨斯登上冰封王座，戴上头盔，与巫妖王合而为一。",
	["Al final de la pelea se enfurece y pega más rápido: guarda curación para ese momento."] = "战斗末尾他会激怒，攻击变快：留好治疗应对那个阶段。",
	["Al final se enfurece: guarden su mejor daño para el final."] = "她在最后会激怒：把最强的输出留到最后。",
	["Al final, habla con el Discípulo de Naralex y protégelo mientras camina: así aparece el último jefe."] = "最后，与纳拉雷克斯的信徒对话，并在他行走时保护他：这样最终首领才会出现。",
	["Al hablar con el maestro de vuelo, abre su mapa directamente."] = "与飞行管理员交谈时，直接打开其地图。",
	["Al hablar con quien da una misión de tu ruta, se acepta sola."] = "与发放你路线上任务的人交谈时，任务会自动接受。",
	["Al hablar con quien da una misión de tu ruta, se acepta sola. Mayús la deja para ti."] = "与提供你路线上任务的人交谈时，会自动接受。按住 Shift 则由你自己决定。",
	["Al hablar con un PNJ"] = "与 NPC 交谈时",
	["Al hablar con un banquero se abre el banco de Alfa, con depositar rápido. La primera visita de cada personaje muestra el del juego: así recibe su primera pestaña."] = "与银行职员交谈时会打开 Alfa 银行，可快速存放。每个角色第一次访问时会显示游戏自带的银行：这样才能获得第一个标签页。",
	["Al hurtar a los humanoides ganas monedas y a veces cajas cerradas."] = "对人型生物偷窃可以得到钱币，有时还有上锁的箱子。",
	["Al invitar a una comunidad ya no sale el aviso de bloqueo: Alfa te deja el nombre listo para copiar y te abre la ventana. A tu hermandad, un clic como antes."] = "邀请加入社区时不再出现阻止警告：Alfa 会准备好要复制的名字并为你打开窗口。邀请加入公会仍然一键完成。",
	["Al llegar a una ciudad o posada. También repite la nota de entrenar de la guía cuando su ventana está oculta."] = "到达城镇或旅店时提醒。指南窗口隐藏时，也会重复指南里的训练提示。",
	["Al llegar a una zona con una mazmorra para tu nivel, Lya te dice quién de la manada anda cerca y va a tu nivel, con «Invitar»."] = "到达有适合你等级地下城的区域时，莉娅会告诉你狼群里谁在附近且与你等级相仿，并附“邀请”按钮。",
	["Al llegar a una zona con una mazmorra para tu nivel, te digo quién de la manada anda cerca y va a tu nivel, con «Invitar»."] = "到达有适合你等级地下城的区域时，我会告诉你狼群里谁在附近且与你等级相仿，并附“邀请”按钮。",
	["Al llegar en barco o al encontrar un raro, un anuncio grande con animación, como la intro."] = "乘船抵达或发现稀有怪时，会有像开场动画一样的大型动画通知。",
	["Al llegar en barco o cuando Lya encuentra un raro, un anuncio grande con animación, como la intro, en vez de una tarjeta."] = "坐船抵达或莉娅发现稀有怪时，显示像开场动画那样的大幅动态公告，而不是卡片。",
	["Al morir aparecen cuatro abisarios que caminan juntos por el patio: prepárense para pelear con varios."] = "他死后会出现四个虚空行者，一起穿过庭院：准备好同时对付多个敌人。",
	["Al morir en un campo de batalla, liberas tu espíritu al momento."] = "在战场中死亡时，立即释放灵魂。",
	["Al morir llegan muchos aprendices: prepárense para muchos enemigos a la vez."] = "他死后会冲来大量学徒：准备好同时面对很多敌人。",
	["Al moverte, la tecla vuelve a la normal"] = "移动时，按键恢复原本功能",
	["Al moverte, solo de lado"] = "移动时只左右平移",
	["Al norte de estas montañas están las Estepas Ardientes y la Montaña Roca Negra, de donde salen los orcos que amenazan Villa del Lago."] = "这些山脉的北边是燃烧平原和黑石山，威胁湖畔镇的兽人就是从那里来的。",
	["Al objetivo le queda poca vida: Ejecutar lo remata usando tu ira."] = "目标生命值很低：用斩杀消耗怒气终结它。",
	["Al objetivo le queda poca vida: el martillo lo remata a distancia."] = "目标生命值很低：愤怒之锤可在远处终结它。",
	["Al pasar el ratón por un objeto: «Tienes 12 (Lobato: 7 en bolsas, Alt: 5 en banco)», con todos tus personajes."] = "鼠标指向物品时显示：“你有 12 个（Lobato：背包中 7、Alt：银行中 5）”，统计你所有角色。",
	["Al pasar el ratón sobre un objeto: su precio en la subasta, lo que paga el comerciante y qué te conviene."] = "鼠标指向物品时显示：拍卖行价格、商人收购价，以及怎么处理最划算。",
	["Al pie de Cima del Trueno está el poblado Pezuña de Sangre, donde Baine, el hijo de Cairne, cuida a su gente."] = "雷霆崖脚下是血蹄村，凯恩的儿子贝恩在那里照顾他的族人。",
	["Al poner algo a la venta en la subasta: su precio sugerido, su historial de 14 días y un aviso si lo das muy barato."] = "在拍卖行上架物品时：显示建议价格、14 天的价格记录，卖太便宜时还会提醒你。",
	["Al recibir daño suelta pedazos más pequeños: mátenlos con ataques en área."] = "受到伤害时会分裂出更小的碎片：用范围攻击清掉。",
	["Al sacar algo"] = "钓到东西时",
	["Al salir de una mazmorra"] = "离开地下城时",
	["Al seguir, Alfa se recarga para cambiar el idioma y esta configuración sigue donde la dejaste."] = "继续后，Alfa 会重载以切换语言，本设置会从你离开的地方继续。",
	["Al subir de nivel (y al entrar, si te quedan puntos), un aviso dice qué talento poner, con el botón para aplicarlo."] = "升级时（以及登录时若还有未分配点数），会提示该点哪个天赋，并附应用按钮。",
	["Al subir de nivel te muestra qué aprender y cuánto cuesta."] = "升级时显示可学的技能和费用。",
	["Al subir de nivel, un aviso dice qué aprender, cuánto cuesta y con qué entrenador, con el botón Llévame."] = "升级时，会提示该学什么、多少钱、找哪位训练师，并附“带我去”按钮。",
	["Al sur de Cuna del Invierno, una garganta escondida está llena de demonios."] = "冬泉谷南边有一道隐蔽的峡谷，里面满是恶魔。",
	["Al sur de Los Baldíos, el Gran Elevador baja hasta Las Mil Agujas. ¡No mires hacia abajo!"] = "在贫瘠之地南部，大升降梯一路降到千针石林。别往下看！",
	["Al sur está Dalaran, la ciudad de los magos. Archimonde la arrasó en la Tercera Guerra, y sus magos la reconstruyen protegidos bajo una cúpula."] = "南边是法师之城达拉然。阿克蒙德在第三次战争中摧毁了它，法师们正在一座护罩下重建它。",
	["Al sur se alza una muralla enorme: el rey Genn Cringris la levantó para aislar Gilneas del resto del mundo."] = "南边耸立着一道巨大的城墙：吉恩·格雷迈恩国王建起它，把吉尔尼斯与世界其他地方隔绝开来。",
	["Al terminar una guía de nivel, carga la siguiente sin preguntar."] = "完成一份升级指南后，不询问直接载入下一份。",
	["Al terminar una guía, la que sigue para tu nivel a un clic."] = "完成一个指南后，下一个适合你等级的指南一键可达。",
	["Al terminar una pelea, Alfa te deja una tarjeta pequeña con cuánto duró, tu daño y tu curación por segundo y lo que más te pegó. Usa el medidor oficial del juego y solo cuenta lo tuyo."] = "战斗结束后，Alfa 会留给你一张小卡片：战斗持续了多久、你的每秒伤害和每秒治疗，以及打你最痛的东西。使用游戏官方的统计，只计算你自己的。",
	["Al terminar una pelea, aquí queda su resumen: tu daño, tu curación y lo que más te pegó."] = "战斗结束后，这里会留下总结：你的伤害、你的治疗和打你最痛的东西。",
	["Al terminar: cuánto duró, tu daño y tu curación por segundo y lo que más te pegó."] = "结束时：持续了多久、你的每秒伤害和每秒治疗，以及打你最痛的东西。",
	["Al terminarla, te propongo la siguiente para tu nivel. Un clic en «Seguir con…» y seguimos de caza."] = "完成后，我会推荐下一个适合你等级的指南。点一下“继续……”，我们接着狩猎。",
	["Al tomar una misión te la resumo en dos líneas, a mi modo: qué hay que hacer y un consejito. La historia completa sigue en «Historias»."] = "你接任务时，我会用我的方式两行总结：要做什么，再加一个小建议。完整的故事还在“故事”里。",
	["Al tomar una misión, Lya te la resume en dos líneas: qué hay que hacer y un consejito suyo."] = "你接任务时，莉娅会用两行总结：要做什么，再加她的一个小建议。",
	["Al volver con una misión lista, se entrega sola. Si hay recompensas para elegir, eliges tú."] = "带着完成的任务回来时会自动交付。如果有奖励可选，由你来选。",
	["Alamuerte forjó en secreto el Alma de Demonio, un disco dorado cargado con el poder de los demás Aspectos, que se lo dieron sin saber para qué lo quería."] = "死亡之翼秘密铸造了恶魔之魂，那是一个蕴含其他守护巨龙力量的金色圆盘，他们给了他力量，却不知道他想拿它做什么。",
	["Alamuerte se hizo pasar por Lord Daval Prestor, un noble que casi llegó a rey de Alterac. ¡A esa familia le encantan los disfraces!"] = "死亡之翼曾假扮成达瓦尔·普瑞斯托领主，这位贵族差点当上奥特兰克国王。那一家子可真爱乔装打扮！",
	["Alcance de las sombras"] = "阴影距离",
	["Alcanza para %d"] = "够做 %d 份",
	["Alejar"] = "缩小",
	["Alejar la cámara"] = "镜头最远距离",
	["Alejar más la cámara"] = "镜头拉得更远",
	["Alertas"] = "警示",
	["Alexandros Mograine empuñaba la Crematoria, y la Plaga le temía como a nadie. Lo traicionó su propio hijo, Renault."] = "亚历山德罗斯·莫格莱尼手持灰烬使者，天灾军团对他的畏惧无人能及。背叛他的是他的亲生儿子雷诺。",
	["Alfa"] = "Alfa",
	["Alfa %s ya está aquí"] = "Alfa %s 来了",
	["Alfa %s · cliente %s (%s) · %s · Alfa en %s"] = "Alfa %s · 客户端 %s（%s）· %s · Alfa 语言：%s",
	["Alfa (el de siempre), Clásico WoW (marcos y letras del juego), Cristal (transparente), La Jauría nocturno (azul de noche y plata de luna) o Fogata (carbón y brasas). El modo compacto y tus colores funcionan en todos."] = "Alfa（经典的那款）、经典 WoW（游戏的框体和字体）、玻璃（透明）、La Jauría 夜色（夜空蓝和月光银）或篝火（炭黑与余烬）。紧凑模式和你的颜色在所有风格中都可用。",
	["Alfa (el estilo propio, por omisión), Clásico WoW (marcos y letras del juego) o Cristal (transparente, con el acento que elijas). El modo compacto y tus colores funcionan en los tres."] = "Alfa（专属风格，默认）、经典 WoW（游戏的框体和字体）或玻璃（透明，搭配你选择的强调色）。紧凑模式和你的颜色在三种风格中都可用。",
	["Alfa arma el reporte y tú lo pegas en el buzón privado del Discord de La Jauría. También con /alfa reportar."] = "Alfa 会生成报告，你把它粘贴到 La Jauría 的 Discord 私人信箱中。也可以用 /alfa reportar。",
	["Alfa arma la ruta más corta para cobrarlas, junta por PNJ. La flecha usa vuelos y tu piedra de hogar cuando conviene, y te avisa si una entrega queda lejos."] = "Alfa 会规划交付它们的最短路线，按 NPC 分组。箭头会在划算时使用飞行和炉石，并在交付点很远时提醒你。",
	["Alfa atrapó errores"] = "Alfa 捕获到错误",
	["Alfa borrará lo que guardó de %s: sus bolsas, su banco, su equipo y sus recetas de Comercio. Si vuelves a jugar con él, se guarda de nuevo."] = "Alfa 将删除为%s保存的数据：背包、银行、装备以及交易中的配方。再次用该角色登录时会重新保存。",
	["Alfa completo"] = "完整 Alfa",
	["Alfa de La Jauría"] = "La Jauría 的阿尔法",
	["Alfa elige las misiones que más XP dan cerca de ti, en tres tandas."] = "Alfa 会分三批选出你附近经验最多的任务。",
	["Alfa elige por ti: entregar las que tienes listas, cerrar las de esta zona o recoger misiones nuevas."] = "Alfa 替你选：交付已完成的任务、完成本区域的任务，或接新任务。",
	["Alfa elige todo: misiones ordenadas por XP por distancia y tus misiones de clase."] = "全部由 Alfa 挑选：按经验与距离之比排序的任务，再加上你的职业任务。",
	["Alfa es la %s, pero estas son de otra: %s. Reinstala Alfa completo para que todo sea de la misma."] = "Alfa 是 %s，但这些来自其他版本：%s。重新安装整个 Alfa，让一切保持一致。",
	["Alfa es un addon que toxic3000 creó para sus amigos y quiso compartir con todos."] = "Alfa 是 toxic3000 为朋友们制作的插件，他也想把它分享给所有人。",
	["Alfa estable: en orden y en manada"] = "稳定版 Alfa：井然有序，结伴同行",
	["Alfa está armando tu ruta..."] = "Alfa 正在生成你的路线...",
	["Alfa está eligiendo..."] = "Alfa 正在挑选...",
	["Alfa está leyendo tu clase"] = "Alfa 正在读取你的职业",
	["Alfa está oculto: clic para mostrarlo y abrir su ventana"] = "Alfa 已隐藏：点击以显示并打开其窗口",
	["Alfa guarda una copia de tus ajustes y perfiles cada semana y antes de cada actualización. Quedan las últimas 3."] = "Alfa 每周以及每次更新前都会保存一份你的设置和配置档。保留最近 3 份。",
	["Alfa guarda unos %.1f MB. Es mucho: el juego tarda más en entrar. Lo que más pesa: %s."] = "Alfa 保存了约 %.1f MB 数据。这很多：游戏登录会变慢。最大的部分：%s。",
	["Alfa guarda unos %.1f MB. Todo bien."] = "Alfa 保存了约 %.1f MB 数据。一切正常。",
	["Alfa junta tus misiones y las de aquí y busca el camino más corto."] = "Alfa 会把你的任务和这里的任务集合起来，找出最短的路线。",
	["Alfa la vuelve a poner al entrar."] = "登录时 Alfa 会重新套用它。",
	["Alfa las ordena por el camino más corto y te lleva de una en una."] = "Alfa 按最短路线排序，带你逐个去交。",
	["Alfa le agregó lo que ayuda a arreglarlo: versiones, idioma, tu clase y nivel y dónde estás. No lleva tu nombre ni tu reino."] = "Alfa 附上了有助于修复的信息：版本、语言、你的职业和等级以及你所在的位置。不包含你的名字和服务器。",
	["Alfa lee el medidor oficial del juego. Enciéndelo y aquí verás el daño de tu grupo; su ventana puedes ocultarla en el Modo de edición."] = "Alfa 读取游戏官方的伤害统计。开启后，这里会显示你队伍的伤害；它的窗口可以在编辑模式中隐藏。",
	["Alfa lo creó toxic3000 para sus amigos y quiso compartirlo con todos. No juega por ti: te ayuda a entender y disfrutar el juego a tu ritmo."] = "toxic3000 为朋友们做了 Alfa，又想分享给所有人。它不替你玩：它帮你按自己的节奏理解并享受游戏。",
	["Alfa lo hace por ti"] = "Alfa 帮你做",
	["Alfa lo hace toxic3000 para La Jauría. Es software libre (GPL-3.0) y su código está en github.com/toxic3000/alfa-forever."] = "Alfa 由 toxic3000 为 La Jauría 制作。它是自由软件（GPL-3.0），源代码位于 github.com/toxic3000/alfa-forever。",
	["Alfa los cambia por el rango nuevo sin moverlos de lugar."] = "Alfa 会把它们换成新等级，位置不变。",
	["Alfa mantiene %d ajustes que elegiste. Abre la ventana para ver o cambiar cada uno."] = "Alfa 保留了你选择的 %d 项设置。打开窗口即可查看或更改每一项。",
	["Alfa mantiene %d ajustes tuyos y los vuelve a poner al entrar."] = "Alfa 保留了你的 %d 项设置，并在登录时重新套用。",
	["Alfa mide los caminos (vuelos y piedra de hogar): tarda unos segundos."] = "Alfa 正在计算路程（飞行和炉石）：需要几秒钟。",
	["Alfa nació en La Jauría, la comunidad de Toxic (toxic3000) en WoW Forever: un solo addon con todo lo que la manada necesita para jugar, con un solo estilo."] = "Alfa 诞生于 La Jauría，Toxic（toxic3000）在 WoW Forever 的社区：一个插件，装下狼群游戏所需的一切，风格统一。",
	["Alfa no está afiliado a esos proyectos ni ellos lo respaldan; gracias a todos por compartir su trabajo."] = "Alfa 与这些项目没有关联，也未获得其认可；感谢大家分享自己的成果。",
	["Alfa no ha cambiado nada todavía. Prueba «Paisaje de la manada» o abre la ventana para ver los ajustes que el menú del juego no enseña."] = "Alfa 还没有更改任何东西。试试“狼群风景”，或打开窗口查看游戏菜单里没有的设置。",
	["Alfa no pudo armar el camino a %s. Míralo en la Enciclopedia."] = "Alfa 无法规划前往%s的路线。请在百科中查看。",
	["Alfa no sabe dónde estás (en una instancia no hay notas)."] = "Alfa 不知道你在哪（副本里没有笔记）。",
	["Alfa no sabe en qué zona estás."] = "Alfa 不知道你在哪个区域。",
	["Alfa no tiene datos de esto todavía."] = "Alfa 还没有这方面的数据。",
	["Alfa no tiene el instructor de tu raza: busca «equitación» en PNJ."] = "Alfa 不知道你种族的训练师：在 NPC 中搜索“骑术”。",
	["Alfa no toma misiones que no sirven a tu ruta, ni las entrega solas. Lo respeta también «todas las misiones» de Comodidades."] = "Alfa 不会接受对你路线无用的任务，也不会自动交付它们。便利功能中的“所有任务”也会遵守这一点。",
	["Alfa no toma misiones que no sirven a tu ruta, ni las entrega solas. Lo respeta también «todas las misiones»."] = "Alfa 不会接受你的路线用不到的任务，也不会自己交付。“所有任务”同样遵守这一点。",
	["Alfa no toma misiones que no sirven a tu ruta. Tu registro queda limpio."] = "Alfa 不会接对你路线没用的任务。你的任务日志保持整洁。",
	["Alfa nunca apaga otros addons: eso lo decides tú en tu lista de addons."] = "Alfa 从不关闭其他插件：这由你在插件列表里决定。",
	["Alfa ordena las paradas para que no camines de más. Tarda unos segundos y no traba el juego."] = "Alfa 会安排站点顺序，让你不多走冤枉路。需要几秒钟，不会卡住游戏。",
	["Alfa recuerda cuándo cayó cada raro: su cuadro dice hace cuánto lo cazaron y si pudo volver ya."] = "Alfa 记得每个稀有怪何时倒下：它的鼠标提示会显示多久前被击杀，以及是否可能已刷新。",
	["Alfa recuerda lo que llevabas antes de ponerte lo de pesca y te lo vuelve a poner."] = "Alfa 会记住你换上钓鱼装备前穿的东西，并帮你换回来。",
	["Alfa revisa lo que elegiste cuando el juego termina de cargar. Si los cambias en el menú del juego, se queda con lo nuevo."] = "游戏加载完成时，Alfa 会检查你的选择。如果你在游戏菜单中更改了它们，就保留新的设置。",
	["Alfa revisa su base de objetos sin trabar el juego. Tarda unos segundos la primera vez."] = "Alfa 会在不卡住游戏的情况下检查物品数据库。第一次需要几秒钟。",
	["Alfa revisa su base de objetos, se queda con lo que tu clase puede usar cerca de tu nivel y lo compara con lo que llevas, con los pesos de tu build."] = "Alfa 会检查物品数据库，留下你的职业在你等级附近能用的物品，并按你方案的权重与身上的装备比较。",
	["Alfa se encarga de lo repetitivo (aceptar, entregar, vender, reparar) y te pregunta en los cruces del camino."] = "Alfa 负责重复的事（接、交、卖、修），在每个岔路口问你。",
	["Alfa se está uniendo al canal oculto de La Jauría. En unos segundos ves a quien comparte."] = "Alfa 正在加入 La Jauría 的隐藏频道。几秒后就能看到正在共享的人。",
	["Alfa se muestra en el idioma que elijas, aunque tu juego esté en otro."] = "即使游戏是其他语言，Alfa 也会以你选择的语言显示。",
	["Alfa se recarga para cambiar el idioma. La configuración sigue donde la dejaste."] = "Alfa 正在重载以切换语言。设置会从你离开的地方继续。",
	["Alfa sencillo"] = "简洁 Alfa",
	["Alfa solo leyó tus valores: nada cambia hasta que toques un control."] = "Alfa 只读取了你的数值：在你调整某个控件之前，什么都不会改变。",
	["Alfa solo te sugiere: el precio lo pones tú."] = "Alfa 只提供建议：价格由你决定。",
	["Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus recargas, los efectos que el juego activa y la vida del enemigo cuando se puede leer. Con varios enemigos cambia a las de área. Tú decides qué presionar."] = "Alfa 按其针对%s的优先级给出建议，只读取你的角色：你的资源、冷却、游戏触发的效果，以及可读取时的敌人生命值。敌人多时会切换为范围技能。按什么由你决定。",
	["Alfa tampoco tiene todavía una prioridad para tu clase con lo que sabes. Los avisos de reacción y el medidor sí funcionan."] = "Alfa 也还没有针对你的职业和已学技能的优先级。反应提醒和伤害统计仍然可用。",
	["Alfa te avisa aquí de lo importante: equipo por reparar, bolsas llenas, habilidades nuevas, tu buff y tu descanso."] = "Alfa 会在这里提醒你重要的事：需要修理的装备、满了的背包、新技能、你的增益效果和休息状态。",
	["Alfa te avisa del equipo gastado, las bolsas llenas, lo que puedes entrenar, tu buff y tu descanso. Aquí eliges cuáles y cuándo."] = "Alfa 会提醒你装备磨损、背包已满、可训练的技能、你的增益效果和休息状态。在这里选择提醒哪些以及何时提醒。",
	["Alfa te avisa del equipo gastado, las bolsas llenas, lo que puedes entrenar, tu buff, tu descanso, tu comida y lo que te falta para una mazmorra. Aquí eliges cuáles y cuándo."] = "Alfa 会提醒你装备磨损、背包满了、能训练的技能、你的增益、休息、食物以及去地下城还缺什么。在这里选择提醒哪些、什么时候提醒。",
	["Alfa te guía con la flecha y te avisa, pero tú aceptas, entregas, eliges y viajas. Lo mínimo: vender lo gris y reparar."] = "Alfa 用箭头带路并提醒你，但接、交、选、走都由你。最少：卖灰色物品和修理。",
	["Alfa te lleva paso a paso, con la flecha y la ruta en el mapa. Elige la de tu zona y tu nivel."] = "Alfa 会用箭头和地图上的路线一步步带你。选择适合你所在区域和等级的指南。",
	["Alfa te recomienda: %s"] = "Alfa 推荐：%s",
	["Alfa tiene muchas páginas, ¿se puede más sencillo?"] = "Alfa 页面好多，能更简单点吗？",
	["Alfa todavía no tiene builds para tu clase"] = "Alfa 还没有适合你职业的方案",
	["Alfa usa %.1f MB de memoria ahora. Lo que más usa:"] = "Alfa 现在占用 %.1f MB 内存。占用最多的是：",
	["Alfa usa código y datos de estos proyectos libres, con sus avisos de autor y sus licencias incluidos en cada carpeta:"] = "Alfa 使用了以下自由项目的代码和数据，每个文件夹中都附有其作者声明和许可证：",
	["Alfa vuelve a elegir desde donde estás ahora (las misiones fijas se quedan)."] = "Alfa 会从你现在的位置重新挑选（已固定的任务保留）。",
	["Alfa ya no se pone encima de %s. %s sigue como estaba."] = "Alfa 不再妨碍 %s 了。%s 保持原样。",
	["Alfa · Top %d de %s (%s%s)"] = "Alfa · 前 %d 名 %s（%s%s）",
	["Alfa, Clásico WoW o Cristal, la flecha del lobo y el aullido."] = "Alfa、经典 WoW 或玻璃风格，狼形箭头和狼嚎。",
	["Alfa: agregar a Cerrar mis misiones"] = "Alfa：加入“完成我的任务”",
	["Alfa: capas del mapa"] = "Alfa：地图图层",
	["Alfa: cerrar mis misiones"] = "Alfa：完成我的任务",
	["Alfa: quitar de Cerrar mis misiones"] = "Alfa：从“完成我的任务”中移除",
	["Alfa: ver la cadena completa"] = "Alfa：查看完整任务链",
	["Alfa_Codex está apagado en la lista de addons."] = "Alfa_Codex 在插件列表中被关闭了。",
	["Algo de Alfa no funciona, ¿qué reviso?"] = "Alfa 有地方不正常，我该检查什么？",
	["Algo importante pasa aquí; no te lo pierdas."] = "这里会发生重要的事；别错过了。",
	["Algo no anda bien en el árbol: los furbolgs que viven en él se están volviendo agresivos."] = "树上出了点问题：住在上面的熊怪变得具有攻击性了。",
	["Algunas cosas se ven completas al recargar."] = "有些内容重载后才会完整显示。",
	["Algunas fórmulas de encantamiento muy buscadas caen de enemigos en las Tierras de la Peste."] = "一些抢手的附魔公式会从瘟疫之地的敌人身上掉落。",
	["Algunas recetas raras se compran a vendedores lejanos o caen de enemigos; vale la pena buscarlas."] = "有些稀有配方要向远方的商人购买，或从敌人身上掉落；很值得去找。",
	["Algunos ajustes, como el HDR, se ven hasta reiniciar los gráficos. Te pide confirmación."] = "有些设置（例如 HDR）要重启图形后才能看到效果。会请你确认。",
	["Algunos ogros tienen dos cabezas, y no siempre se ponen de acuerdo entre ellas."] = "有些食人魔长着两个脑袋，而且两个脑袋不一定意见一致。",
	["Algunos orcos nunca siguieron a Thrall: los Roca Negra de la montaña sirven a los dragones negros."] = "有些兽人从未追随萨尔：山里的黑石兽人效忠于黑龙。",
	["Alianza"] = "联盟",
	["Alimenta a tu mascota: si está contenta pega más y te es más leal."] = "喂饱你的宠物：它开心时打得更痛，也更忠诚。",
	["Alquimia"] = "炼金术",
	["Alt"] = "Alt",
	["Alt+clic en un objeto abre su ficha"] = "Alt+点击物品可打开其详情页",
	["Alta"] = "高",
	["Altas"] = "高",
	["Alto"] = "高度",
	["Alto [calidad]"] = "高",
	["Alto de las barras"] = "黑边高度",
	["Altos"] = "高",
	["Ambiente mientras pescas"] = "钓鱼时的环境音",
	["Amenaza"] = "威胁",
	["Anasterian, el rey de los altos elfos, dejó la Alianza tras la Segunda Guerra, y murió frente a Arthas defendiendo la Fuente del Sol."] = "高等精灵之王安纳斯特里安在第二次战争后退出了联盟，后来在保卫太阳之井时死在阿尔萨斯面前。",
	["Ancho"] = "宽度",
	["Andan conectados: %s."] = "当前在线：%s。",
	["Andorhal era el granero de Lordaeron. Kel'Thuzad repartió ahí grano apestado y la plaga se extendió por todo el reino."] = "安多哈尔曾是洛丹伦的粮仓。克尔苏加德在那里分发了染疫的谷物，瘟疫随之蔓延整个王国。",
	["Anduin Lothar, el León de Azeroth, llevó a los refugiados de Ventormenta hasta Lordaeron y fue el primer comandante de la Alianza."] = "“艾泽拉斯之狮”安度因·洛萨带领暴风城的难民前往洛丹伦，是联盟的第一位统帅。",
	["Anillos"] = "戒指",
	["Animación anterior"] = "上一个动作",
	["Animación siguiente"] = "下一个动作",
	["Animación y avisos"] = "动画和提醒",
	["Anisotrópico 16x"] = "16 倍各向异性",
	["Anisotrópico 2x"] = "2 倍各向异性",
	["Anisotrópico 4x"] = "4 倍各向异性",
	["Anisotrópico 8x"] = "8 倍各向异性",
	["Ankh"] = "十字章",
	["Anterior"] = "上一场",
	["Antes de %s te falta:"] = "进入 %s 之前你还需要：",
	["Antes de abandonarla"] = "放弃之前",
	["Antes de atacar, mira quién está cerca. Pelear con uno a la vez es más seguro."] = "攻击之前，先看看附近有谁。一次只打一个更安全。",
	["Antes de buscar la espada, Arthas mandó quemar sus propios barcos para que sus soldados no pudieran volver a casa."] = "在寻找那把剑之前，阿尔萨斯下令烧掉自己的船，让士兵们无法回家。",
	["Antes de comprar algo en la subasta, revisa si un vendedor lo tiene más barato."] = "在拍卖行买东西之前，先看看商人是不是卖得更便宜。",
	["Antes de empezar, unas palabras de la manada."] = "开始之前，狼群有几句话要说。",
	["Antes de entrar"] = "进本之前",
	["Antes de entregarla te falta: %s."] = "交付前还差：%s。",
	["Antes de importar"] = "导入之前",
	["Antes de irte: tienes %d misiones listas para entregar. ¿Pasamos a cobrarlas?"] = "走之前：你有 %d 个任务可以交付。去领奖励吗？",
	["Antes de irte: tienes una misión lista para entregar. ¿Pasamos a cobrarla?"] = "走之前：你有一个任务可以交付。去领奖励吗？",
	["Antes de la mazmorra te falta:"] = "进地下城之前你还需要：",
	["Antes de pelear"] = "战斗之前",
	["Antes de pelear: abre con Piroexplosión, tu hechizo más fuerte."] = "战斗之前：用炎爆术开场，这是你最强的法术。",
	["Antes de restaurar"] = "恢复之前",
	["Antes de salir de caza, configura Alfa a tu medida: el idioma, cómo se ve, qué hace sola por ti y si quieres que la manada te vea en el mapa del juego."] = "出发狩猎之前，按你的喜好设置 Alfa：语言、外观、它能替你做什么，以及是否让狼群在游戏地图上看到你。",
	["Antes de una misión de élite o de grupo, un aviso con «Llamar a la manada»."] = "精英或组队任务之前，会提醒你并附上“呼唤狼群”。",
	["Antes esto era un pantano. La magia del portal y la guerra lo dejaron rojo, seco y sin vida."] = "这里以前是一片沼泽。传送门的魔法和战争让它变得赤红、干涸、毫无生机。",
	["Antes hay que hacer otra misión"] = "需要先完成另一个任务",
	["Antes necesitas"] = "前置条件",
	["Antes necesitas otra misión"] = "需要先完成另一个任务",
	["Antes pide %s (%s)"] = "前置：%s（%s）",
	["Antes que los elfos, los trols tuvieron grandes imperios en Azeroth, como el Amani en el norte y el Gurubashi en el sur."] = "在精灵之前，巨魔就在艾泽拉斯建立过伟大的帝国，例如北方的阿曼尼和南方的古拉巴什。",
	["Antes, el reino de Ventormenta se llamaba Azeroth, igual que el mundo; Ventormenta era solo el nombre de su capital."] = "暴风王国以前叫做艾泽拉斯，跟这个世界同名；暴风城只是它首都的名字。",
	["Antes: %s"] = "先完成：%s",
	["Antes: %s."] = "先完成：%s。",
	["Antes: %s. Ahora: %s."] = "之前：%s。现在：%s。",
	["Anunciar"] = "通报",
	["Anunciar en el chat"] = "在聊天中通报",
	["Anunciar en el grupo"] = "通报给队伍",
	["Anuncios animados"] = "动态公告",
	["Anuncios animados y la manada a la vista"] = "动画通知与身边的狼群",
	["Apaga la viñeta, el grano, las barras y el tinte de un clic."] = "一键关闭暗角、颗粒、黑边和色调。",
	["Apagada"] = "已关闭",
	["Apagadas"] = "已关闭",
	["Apagado"] = "已关闭",
	["Apagado en los ajustes de abajo."] = "已在下方设置中关闭。",
	["Apagado, el grano se queda quieto."] = "关闭时，颗粒保持静止。",
	["Apagado, solo las acepta y la entrega la haces tú."] = "关闭时只自动接受，交付由你自己来。",
	["Apagados"] = "已关闭",
	["Apagar la parte de Alfa que choca"] = "关闭冲突的 Alfa 部分",
	["Apagarlo"] = "关闭",
	["Aparece al final del evento del Discípulo de Naralex: protege al druida mientras camina."] = "他在纳拉雷克斯的信徒事件结束时出现：在德鲁伊行走时保护他。",
	["Aparece al tocar el gong por tercera vez, después de dos oleadas de arañas."] = "第三次敲响铜锣时出现，前面会先来两波蜘蛛。",
	["Aparece con una misión de la Horda (un objeto en el agua). Lanza escarcha."] = "通过一个部落任务（水中的一件物品）召唤出来。会施放冰霜法术。",
	["Aparece en cuanto termines la bienvenida de Alfa."] = "完成 Alfa 的欢迎设置后，她就会出现。",
	["Aparece en el evento de la explosivista: protégela mientras llegan oleadas de troggs."] = "他在爆破专家的事件中出现：在一波波穴居人冲来时保护她。",
	["Aparecen marcos de ejemplo: arrástralos a donde los quieras y ajusta su tamaño. Así se verá tu grupo."] = "会出现示例框体：把它们拖到你想要的位置并调整大小。你的队伍就会这样显示。",
	["Aplaudir"] = "鼓掌",
	["Aplica la nitidez de abajo aunque no uses el escalado de resolución."] = "即使不使用分辨率缩放，也套用下方的锐化。",
	["Aplicar"] = "应用",
	["Aplicar %d puntos"] = "应用 %d 点",
	["Aprende %s"] = "学习 %s",
	["Aprende Cocina con un instructor."] = "向训练师学习烹饪。",
	["Aprende Cocina para encender fogatas."] = "学习烹饪才能点燃篝火。",
	["Aprende Minería o Herboristería"] = "学习采矿或草药学",
	["Aprende Pesca"] = "学习钓鱼",
	["Aprende Pesca con un instructor"] = "向训练师学习钓鱼",
	["Aprende Pesca con un instructor de pesca y compra una caña: la guía te lleva."] = "向钓鱼训练师学习钓鱼并买一根鱼竿：指南会带你去。",
	["Aprende Pesca con un instructor, compra una caña y pesca en tu zona de inicio o en la capital. Pide el rango Oficial desde 50."] = "向训练师学习钓鱼，买一根鱼竿，然后在你的新手区域或主城钓鱼。50 点起去学中级。",
	["Aprende equitación con %s"] = "向%s学习骑术",
	["Aprende las dos, consigue una caña y cocina lo que pescas hasta 75."] = "两个都学，弄一根鱼竿，把钓到的东西烹饪到 75。",
	["Aprender %s"] = "学习%s",
	["Aprender de tus búsquedas"] = "从你的搜索中学习",
	["Aprender una profesión o llegar a un nivel en ella."] = "学习一项专业，或在该专业达到某个等级。",
	["Aprendiste %s. %s"] = "你学会了%s。%s",
	["Aprendiste un hechizo que le queda mejor a tus clics:"] = "你学会了一个更适合点击施法的法术：",
	["Aprendiz"] = "初级",
	["Aprendí un hechizo nuevo, ¿para qué sirve?"] = "我学会了新法术：它有什么用？",
	["Apréndelos con el entrenador de tu clase, en cualquier capital."] = "向你的职业训练师学习，任何主城都有。",
	["Apunto el primer día que te vi. Cada año, ese día, lo festejamos juntos. Y el 16 de noviembre es el cumpleaños de Alfa."] = "我记下了第一次见到你的那天。每年的那一天，我们都一起庆祝。11 月 16 日是 Alfa 的生日。",
	["Apágalo si no quieres que Alfa toque tus teclas, tu equipo ni tus ajustes al pescar."] = "如果不想让 Alfa 在钓鱼时改动你的按键、装备或设置，请关闭此项。",
	["Aquí"] = "这里",
	["Aquí adentro se caza en equipo: espera a que quien cura tenga maná antes de seguir."] = "这里要团队狩猎：等治疗者有法力了再继续。",
	["Aquí aparecerán los demás módulos de Alfa (bolsas, rutas, mundo y más) en cuanto estén instalados."] = "Alfa 的其他模块（背包、路线、世界等）安装后会显示在这里。",
	["Aquí el juego no da tu posición (por ejemplo, dentro de una mazmorra)."] = "游戏在这里不提供你的位置（例如在地下城内）。",
	["Aquí el juego no deja compartir nada. Al salir, tu rastro vuelve a salir solo."] = "游戏在这里不允许共享任何内容。离开后，你的踪迹会自动恢复发送。",
	["Aquí empieza tu historia. Y yo voy contigo."] = "你的故事从这里开始。我和你一起走。",
	["Aquí estoy, como siempre. Nunca dejo a nadie atrás."] = "我在这儿，一如既往。我从不丢下任何人。",
	["Aquí estoy. Si no sabes por dónde empezar, toca «¿Por dónde empiezo?»."] = "我在这儿。不知道从哪开始，就点“从哪里开始？”。",
	["Aquí está el Portal Oscuro: por él cruzó la Horda desde Draenor para invadir Azeroth en la Primera Guerra."] = "黑暗之门就在这里：第一次战争时，部落从德拉诺穿过它入侵艾泽拉斯。",
	["Aquí está la tumba de Uther el Iluminado, el maestro de Arthas. Murió a manos de su propio alumno, defendiendo las cenizas del rey Terenas."] = "这里是光明使者乌瑟尔的陵墓，他是阿尔萨斯的导师。他为守护泰瑞纳斯国王的骨灰，死在了自己学生的手里。",
	["Aquí juntas XP descansada poco a poco (más si cierras sesión aquí): luego ganas el doble por enemigo hasta gastarla."] = "在这里会慢慢积累休息经验（在这里下线积累更多）：之后每个敌人给双倍经验，直到用完。",
	["Aquí la lees completa: cómo empieza, qué te piden y cómo termina."] = "在这里读完整的故事：如何开始、要你做什么、如何结束。",
	["Aquí no hay nodos que recolectar"] = "这里没有可采集的采集点",
	["Aquí sale por qué se activó la habilidad."] = "这里会显示技能被触发的原因。",
	["Aquí verás cuánto llevas descubierto de cada zona de tu continente."] = "在这里你会看到你所在大陆每个区域已探索了多少。",
	["Aquí ves cuántas llevas, dónde sale y qué hacer con ella."] = "在这里可以看到你有多少、从哪里获得以及怎么处理它。",
	["Aquí ves todo lo que hay que saber, con qué hacer después."] = "这里显示你需要知道的一切，以及接下来该做什么。",
	["Aquí: %s %.1f, %.1f. Se guarda este punto."] = "此处：%s %.1f, %.1f。已保存此地点。",
	["Arañazo: sangrado con el tiempo."] = "斜掠：持续流血。",
	["Arcano"] = "奥术",
	["Arcano para subir"] = "奥术（升级）",
	["Archimonde subió a Hyjal para robar la energía del Árbol del Mundo; en vez de eso, el árbol fue su final."] = "阿克蒙德登上海加尔山，想夺取世界之树的能量；结果世界之树反而成了他的末日。",
	["Arco"] = "弓",
	["Arcos, ballestas y armas de fuego"] = "弓、弩和枪械",
	["Arena"] = "沙色",
	["Arma"] = "武器",
	["Arma con tu ruta lo que necesitas para poder tomarla: el nivel o las misiones de antes."] = "用你的路线安排接取它所需的条件：等级或前置任务。",
	["Arma de asta"] = "长柄武器",
	["Arma de dos manos"] = "双手武器",
	["Arma de dos manos, sellos y juicios: el paladín que mejor sube en solitario."] = "双手武器、圣印和审判：单人升级最快的圣骑士。",
	["Arma de fuego"] = "枪械",
	["Arma de puño"] = "拳套",
	["Arma el plan para cerrar las misiones de tu registro y te lleva a cada una."] = "制定完成任务日志中任务的计划，并带你逐一前往。",
	["Arma tu grupo de 5 (buscador de grupos o tu manada)."] = "组好你的 5 人队伍（寻求组队或你的狼群）。",
	["Arma tu primer plan"] = "制定你的第一个计划",
	["Arma una ruta de %s en %s"] = "创建%s路线（%s）",
	["Arma y escudo"] = "武器和盾牌",
	["Armadura"] = "护甲",
	["Armaduras"] = "护甲",
	["Armando"] = "创建中",
	["Armando el circuito de la zona..."] = "正在规划区域环线……",
	["Armando «Cerrar mis misiones»..."] = "正在创建“完成我的任务”...",
	["Armar el grupo"] = "组建队伍",
	["Armar la ruta"] = "创建路线",
	["Armar lo que falta"] = "补齐缺少的部分",
	["Armar mi plan"] = "创建我的计划",
	["Armar un plan nuevo"] = "制定新计划",
	["Armas"] = "武器",
	["Armas a dos manos"] = "双手武器战",
	["Armas a muerte"] = "全力武器战",
	["Armas contra jugadores"] = "PvP 武器战",
	["Armas para grupo"] = "组队武器战",
	["Armas pensado para mazmorras: mucho daño en varios enemigos con Golpes de barrido, Golpe mortal para los jefes y más precisión para no fallar."] = "为地下城设计的武器战：用横扫攻击对多个敌人打出高伤害，用致死打击对付首领，还有更高的命中以免打空。",
	["Armas pensando primero en no morir: paras más golpes, frenas a los que huyen y terminas con un poco de Protección para recibir menos daño."] = "以生存为先的武器战：招架更多攻击，减速逃跑的敌人，最后点一些防护天赋来减少受到的伤害。",
	["Armas seguro"] = "稳健武器战",
	["Armas, armaduras, materiales, recetas y monturas: quién los suelta y quién los vende."] = "武器、护甲、材料、配方和坐骑：谁掉落、谁出售。",
	["Arrastra cada marco de combate adonde te acomode. Cuando termines, fíjalos para que no estorben."] = "把每个战斗框体拖到合适的位置。完成后锁定，以免碍事。",
	["Arrastra lo que quieras mover. Clic derecho en uno: vuelve a su lugar de siempre."] = "把想移动的东西拖过去。右键点一个：它会回到原来的位置。",
	["Arrastra otra bolsa aquí para cambiarla."] = "将另一个背包拖到这里来替换。",
	["Arrastra para mover tus marcos. Cambia el tamaño y las columnas en la página Curación."] = "拖动以移动框体。可在“治疗”页面调整大小和列数。",
	["Arrastra para mover tus marcos. Haz clic (con o sin Mayús, Ctrl o Alt) para ver qué lanzaría."] = "拖动以移动框体。点击（可搭配 Shift、Ctrl 或 Alt）查看会施放什么。",
	["Arrastra tus marcos de combate adonde te acomoden. Para fijarlos, vuelve a Combate o escribe /alfa combate mover."] = "把战斗框体拖到你顺手的位置。要锁定它们，回到“战斗”或输入 /alfa combate mover。",
	["Arrastra una bolsa aquí para ponerla."] = "将背包拖到这里来装备。",
	["Arreglos: «Cerrar mis misiones» vuelve a armar tu ruta, la ayuda de rotación vuelve a decirte qué usar y el mapa ya no muestra rectángulos pegados al acercar."] = "修复：“完成我的任务”重新为你规划路线，循环助手再次告诉你该用什么，放大地图时也不再出现贴上去的矩形。",
	["Arriba a la derecha, el ícono de magia, maldición, veneno o enfermedad. Al pasar el ratón te dice qué clic lo quita."] = "右上角显示魔法、诅咒、中毒或疾病的图标。鼠标移上去会告诉你用哪个点击驱散。",
	["Arriba de la ventana, cada bolsa equipada con su espacio: pasa el ratón para resaltar lo que lleva y arrastra otra bolsa para cambiarla."] = "窗口顶部显示每个已装备的背包及其空间：鼠标指向可高亮其中的物品，拖入另一个背包即可替换。",
	["Arriba de tus marcos, el maná de quienes curan en tu grupo. Se destaca al terminar cada pelea."] = "在你的框体上方显示队伍中治疗者的法力值。每场战斗结束后会醒目显示。",
	["Arriba en esta ventana está lo último que te dije, con sus botones. Para ver los 20 más recientes: /alfa lya historial."] = "这个窗口顶部是我最后说的话，附带按钮。最近 20 条：/alfa lya historial。",
	["Arriba, lo que Alfa recomienda. Un clic y empiezas."] = "上方是 Alfa 的推荐。点一下就能开始。",
	["Arriesgado"] = "激进",
	["Arrodillarse"] = "跪下",
	["Arrojadiza"] = "投掷武器",
	["Arrástralo para moverlo"] = "拖动以移动",
	["Arrástralo para moverlo."] = "拖动即可移动。",
	["Arrástralo para moverlo. Clic derecho: vuelve a su lugar de siempre."] = "拖动即可移动。右键：回到原来的位置。",
	["Artefacto"] = "神器",
	["Artesano"] = "专家",
	["Artesanía y comercio"] = "制造与商品",
	["Arthas mató a Kel'Thuzad en Andorhal, pero después lo revivió como liche con el poder de la Fuente del Sol."] = "阿尔萨斯在安多哈尔杀了克尔苏加德，但后来又用太阳之井的力量把他复活成巫妖。",
	["Arthas mató al archimago Antonidas en Dalaran, y después Archimonde destruyó la ciudad."] = "阿尔萨斯在达拉然杀死了大法师安东尼达斯，之后阿克蒙德摧毁了这座城市。",
	["Arthas purgó Stratholme porque su grano estaba infectado. Esa decisión lo separó para siempre de Uther y de Jaina."] = "阿尔萨斯屠戮了斯坦索姆，因为那里的谷物已被感染。这个决定让他与乌瑟尔和吉安娜永远决裂。",
	["Arthas tomó la espada Agonía de Escarcha en Rasganorte creyendo que salvaría a su pueblo. La espada le robó el alma."] = "阿尔萨斯在诺森德拿起了霜之哀伤，以为它能拯救他的子民。这把剑却夺走了他的灵魂。",
	["Arthas y Jaina se querían antes de que la plaga los separara."] = "在瘟疫拆散他们之前，阿尔萨斯和吉安娜曾经相爱。",
	["Asesinato"] = "刺杀",
	["Asesinato para subir"] = "刺杀（升级）",
	["Aspecto"] = "守护",
	["Astranaar es el pueblo élfico en medio de Vallefresno, en una isla del lago."] = "阿斯特兰纳是灰谷中央的精灵城镇，坐落在湖中的一座岛上。",
	["Asusta a los enemigos cercanos. Cuidado: pueden correr y traer a otros."] = "恐惧附近的敌人。小心：它们可能会逃跑并引来别的。",
	["Asusta a los enemigos cercanos. Te da tiempo para escapar o curarte."] = "恐惧附近的敌人。为你争取逃跑或治疗的时间。",
	["Asusta a todos los enemigos cercanos."] = "恐惧附近所有敌人。",
	["Asusta a todos los que están cerca: si te asusta, intenta no correr hacia otras celdas."] = "他会恐惧附近所有人：被恐惧时尽量别跑进其他牢房。",
	["Asusta a un enemigo y lo hace huir. Cuidado: puede traer a otros."] = "让一个敌人恐惧逃跑。小心：它可能会引来别的。",
	["Asusta un momento al enemigo y te cura. Tu escape de emergencia."] = "让敌人恐惧片刻并治疗你。你的紧急脱身技。",
	["Asusta y duerme a los jugadores: si te asusta, intenta no correr hacia más enemigos."] = "他会恐惧和催眠玩家：被恐惧时尽量别跑向更多敌人。",
	["Así la manada se encuentra para cazar juntos. Es tu decisión, y la cambias cuando quieras."] = "狼群就是这样相聚一起狩猎的。由你决定，随时可改。",
	["Así queda tu Alfa"] = "这就是你的 Alfa",
	["Así sabes qué hace cada clic antes de tu próxima pelea."] = "这样在下一场战斗前，你就知道每次点击的作用。",
	["Así se lee tu ayuda de rotación"] = "如何看懂你的输出循环助手",
	["Así se ve en pantalla. Vuelve a Combate con /alfa combate."] = "在屏幕上就是这样。用 /alfa combate 回到“战斗”。",
	["Así se ven tus avisos"] = "你的提醒会是这个样子",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo, en Marcos. Pulsa Listo cuando termines."] = "你的框体会是这个样子。拖动来移动它们，并在下方“框体”中调整大小。完成后点击“完成”。",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo. Pulsa Listo cuando termines."] = "你的框体会是这个样子。拖动可以移动，下方可以调整大小。完成后点击“完成”。",
	["Así terminó «%s»… ¿Te cuento el final?"] = "“%s”就这样结束了……要我告诉你结局吗？",
	["Así: /alfa cita mañana 21:30 Minas de la Muerte"] = "例如：/alfa cita tomorrow 21:30 死亡矿井",
	["Atacas más rápido según tus puntos de combo. Mantenlo en las peleas largas."] = "按连击点数提高攻击速度。长时间战斗中保持它。",
	["Atajos"] = "快捷操作",
	["Ataque de tormenta: mucho daño, cada vez que esté listo."] = "风暴打击：高伤害，冷却好就用。",
	["Ataques más rápidos después de un crítico."] = "暴击后攻击速度加快。",
	["Atardecer"] = "黄昏",
	["Atenuar a quien está lejos"] = "淡化超出距离的队友",
	["Atiesh, el Gran Bastón del Guardián, fue de Medivh. En el Clásico se puede rehacer con fragmentos que caen en Naxxramas."] = "埃提耶什，守护者的传说之杖，曾属于麦迪文。在经典版中，可以用纳克萨玛斯掉落的碎片重新打造它。",
	["Atrapa al enemigo en su lugar. Para alejarte y lanzar tranquilo."] = "把敌人定在原地。拉开距离安心施法。",
	["Atravesar objetos pequeños"] = "穿过小型物体",
	["Atronar fuerte: juntas varios monstruos y los frenas a todos."] = "强力的雷霆一击：把几个怪聚在一起，全部减速。",
	["Atronar más barato para agarrar varios."] = "更便宜的雷霆一击，方便拉住多个敌人。",
	["Atronar más fuerte y barato: agarras a varios enemigos a la vez."] = "更强、更便宜的雷霆一击：能同时拉住多个敌人。",
	["Atrás"] = "返回",
	["Aturde al enemigo en forma de oso. Úsalo para interrumpir."] = "熊形态下让敌人昏迷。用来打断。",
	["Aturde al enemigo unos segundos. Úsalo para interrumpir o para escapar."] = "让敌人昏迷几秒。用来打断或逃跑。",
	["Aturde al tanque con su martillo: mantén la vida del tanque alta."] = "他会用锤子击晕坦克：保持坦克的血量充足。",
	["Aturde según tus puntos de combo. Úsalo para interrumpir o rematar."] = "按连击点数造成昏迷。用来打断或收尾。",
	["Aturdes a uno mientras peleas con otro."] = "一边打一个，一边击晕另一个。",
	["Aturdes al enemigo más peligroso."] = "击晕最危险的敌人。",
	["Aturdimiento a demanda."] = "随时可用的击晕。",
	["Auberdine es el puerto de los elfos de la noche: de ahí salen barcos a Teldrassil y a los Reinos del Este."] = "奥伯丁是暗夜精灵的港口：从那里有船开往泰达希尔和东部王国。",
	["Aullar al completar una misión"] = "完成任务时嚎叫",
	["Aullar con tu grupo"] = "和队伍一起嚎叫",
	["Aullido"] = "嚎叫",
	["Aullido al abrir Alfa"] = "打开 Alfa 时狼嚎",
	["Aun de día el Bosque del Ocaso está oscuro. Aquí nunca sale el sol del todo."] = "就算是白天，暮色森林也很暗。这里的太阳从来不会完全露脸。",
	["Aura"] = "光环",
	["Automática"] = "自动",
	["Automático"] = "自动",
	["Automático: el del buscador de grupo, o por tu clase y tu forma (postura defensiva u oso tanquean)."] = "自动：用队伍查找器的职责，或按你的职业和形态判断（防御姿态或熊形态为坦克）。",
	["Automático: el que marcaste en tu grupo, o tu actitud o forma."] = "自动：你在队伍中标记的职责，或你的姿态或形态。",
	["Avanza en tu guía con la flecha"] = "用箭头推进你的指南",
	["Avanzado"] = "高级",
	["Aventura"] = "冒险",
	["Aventura (2): explorar todo el mapa del mundo con un personaje y terminar la cadena de Lord Valthalak (el conjunto de mazmorra 2)."] = "冒险（2）：用一个角色探索整个世界地图，并完成瓦塔拉克公爵任务线（地下城套装 2）。",
	["Aventura, Personaje, Mundo, Oficios, Manada y Ajustes. Cada una tiene sus páginas."] = "冒险、角色、世界、专业、狼群和设置。每一项都有自己的页面。",
	["Aventura: descanso más rápido, vida y maná tras cada muerte, ver mejor a los sigilosos, talentos hasta 5 niveles antes y vuelos más baratos y rápidos."] = "冒险：休息经验积累更快、每次击杀后恢复生命值和法力值、更容易发现潜行者、天赋最多提前 5 级开放，飞行更便宜更快。",
	["Avienta a todos los que están cerca: si peleas de lejos, aléjate."] = "他会击退身边所有人：远程玩家请站远一点。",
	["Avienta y aturde a todos los que están cerca: ponte con la espalda en la pared."] = "她会击退并击晕身边所有人：背靠墙站。",
