	["Buena caza hoy: %s Descansa, que yo cuido tu lugar."] = "今天狩猎得不错：%s 好好休息，我帮你守着位置。",
	["Buenas noches, lobo. Si te vas a ir pronto, termina en una posada para descansar bien."] = "晚上好，狼。如果你快下线了，就在旅店结束，好好休息。",
	["Buenas tardes. Es buena hora para entregar misiones y ver qué hay de nuevo."] = "下午好。正适合交任务，看看有什么新鲜事。",
	["Buff activo"] = "增益效果已生效",
	["Buff fuera de combate"] = "非战斗增益效果",
	["Buffs"] = "增益效果",
	["Build completo"] = "方案已完成",
	["Build importado"] = "导入的方案",
	["Build importado de una cadena. Alfa lo resuelve en tu árbol y te avisa si algún talento no existe."] = "从字符串导入的方案。Alfa 会把它对应到你的天赋树上，并提示不存在的天赋。",
	["Busca %s en: %s."] = "在这些地方找 %s：%s。",
	["Busca addons que chocan con Alfa, partes apagadas y ajustes raros, con el arreglo a un clic. También con /alfa diagnostico."] = "查找与 Alfa 冲突的插件、被关闭的部分和异常设置，一键修复。也可用 /alfa diagnostico。",
	["Busca al entrenador de tu clase en la ciudad."] = "到城里找你的职业训练师。",
	["Busca cualquier cosa del juego"] = "搜索游戏中的任何东西",
	["Busca cualquier cosa, en español o en inglés…"] = "搜索任何东西，可用西班牙语或英语…",
	["Busca el arma de dos manos con más daño por segundo: es lo que más sube tu daño."] = "找每秒伤害最高的双手武器：这最能提升你的伤害。",
	["Busca el arma de dos manos más lenta y fuerte: tus sellos pegan con ella."] = "找速度最慢、伤害最高的双手武器：你的圣印靠它打出伤害。",
	["Busca la zona de la misión entre las guías de subir de nivel."] = "在升级指南中寻找该任务所在的区域。",
	["Busca lo mejor que puedes usar"] = "寻找你能用的最佳装备",
	["Busca por aquí"] = "在这附近找找",
	["Busca siempre el arco, arma de fuego o ballesta con más daño por segundo."] = "总是找每秒伤害最高的弓、枪械或弩。",
	["Busca un escudo con valor de bloqueo alto: sube el daño de Embate con escudo."] = "找格挡值高的盾牌：能提高盾牌猛击的伤害。",
	["Busca un objeto en las bolsas, bancos y equipo de todos tus personajes. Los demás, con lo último que guardó Alfa."] = "在你所有角色的背包、银行和装备中查找物品。其他角色以 Alfa 最后一次保存的内容为准。",
	["Busca una misión, un PNJ, una zona o una palabra…"] = "搜索任务、NPC、区域或关键词……",
	["Busca una versión nueva de Alfa"] = "检查 Alfa 新版本",
	["Busca y elige un objeto."] = "搜索并选择一件物品。",
	["Busca y elige una misión."] = "搜索并选择一个任务。",
	["Buscador"] = "查询",
	["Buscando a la manada…"] = "正在寻找狼群…",
	["Buscando a un oficial..."] = "正在寻找官员...",
	["Buscando lo mejor para tu nivel…"] = "正在寻找适合你等级的最佳装备…",
	["Buscando misiones cerca..."] = "正在寻找附近的任务...",
	["Buscando otras misiones..."] = "正在寻找其他任务...",
