	["Buscar"] = "搜索",
	["Buscar ajustes"] = "搜索设置",
	["Buscar cerca"] = "搜索附近",
	["Buscar cerca (vuelo, posada, reparar...)"] = "搜索附近（飞行点、旅店、修理……）",
	["Buscar cerca no está disponible."] = "搜索附近功能不可用。",
	["Buscar cerca y tus planes"] = "搜索附近与你的计划",
	["Buscar cerca..."] = "搜索附近……",
	["Buscar cerca:"] = "搜索附近：",
	["Buscar cerca: vuelo, posada, banco…"] = "搜索附近：飞行点、旅店、银行……",
	["Buscar en el diario"] = "在图鉴中搜索",
	["Buscar en todos tus personajes"] = "搜索你所有角色",
	["Buscar equipo para mi nivel"] = "查找适合我等级的装备",
	["Buscar guías por nombre o zona"] = "按名称或区域搜索指南",
	["Buscar otra vez"] = "重新搜索",
	["Buscar por nombre, zona o quién lo mandó"] = "按名称、区域或发送者搜索",
	["Buscar un lugar..."] = "搜索地点……",
	["Buscar «%s» en la Enciclopedia"] = "在百科中搜索“%s”",
	["Buscar: pasto, niebla, sombras..."] = "搜索：草、雾、阴影……",
	["Buzones, entrenadores, banco, subasta, reparar..."] = "邮箱、训练师、银行、拍卖行、修理……",
	["Buzón"] = "邮箱",
	["Básico"] = "基础",
	["Búscalo en %s."] = "去%s找找。",
	["Búscalo en la Enciclopedia: objetos, PNJ, misiones, zonas y raros, con dónde están y el botón «Guíame»."] = "在百科里搜：物品、NPC、任务、区域和稀有怪，有位置和“带我去”按钮。",
	["Búscalo por su nombre; se cumple cuando lo tienes en tus bolsas."] = "按名称搜索；当它在你的背包中时即达成。",
	["CPS"] = "HPS",
	["Cabeza"] = "头部",
	["Cada 2 niveles"] = "每 2 级",
	["Cada Aspecto guía un vuelo de dragones: Alexstrasza el rojo, Ysera el verde, Nozdormu el bronce, Malygos el azul y Neltharion el negro."] = "每位守护巨龙都领导一支龙军团：阿莱克丝塔萨是红龙，伊瑟拉是绿龙，诺兹多姆是青铜龙，玛里苟斯是蓝龙，耐萨里奥是黑龙。",
	["Cada ajuste que Alfa cambió vuelve al valor que tenía antes. Los filtros no cambian."] = "Alfa 更改过的每项设置都会恢复为之前的数值。滤镜不会改变。",
	["Cada aviso y cada porqué sale con texto hasta %d veces y luego solo queda el ícono."] = "每个提示和每条原因最多显示 %d 次文字，之后只保留图标。",
	["Cada año, el día que empezaron a cazar juntos, Lya lo festeja. Y también el cumpleaños de Alfa."] = "每年在你们开始一起狩猎的那一天，莉娅都会庆祝。Alfa 的生日也一样。",
	["Cada bloqueo te da ira: nunca te falta."] = "每次格挡都给你怒气：永远不缺怒气。",
	["Cada bolsa en su bloque, con su nombre y su espacio."] = "每个背包单独成块，显示名称和空间。",
	["Cada botón de acción con el borde y el fondo del estilo, el ícono cuadrado y la letra de Alfa en la tecla y la cuenta."] = "每个动作按钮都使用该风格的边框和背景、方形图标，按键和数量使用 Alfa 的字体。",
	["Cada casilla en su lugar, como en tus bolsas."] = "每一格都在原位，和你的背包一样。",
	["Cada clase da retos del Legado al llegar a 25, 45 y 60: subir otras clases también le suma a tu cuenta."] = "每个职业在 25、45 和 60 级时都会给传承挑战：练其他职业也会为你的账号加分。",
	["Cada clic que cura también selecciona a ese compañero, para seguir con otro poder, un buff o quitarle una maldición o un veneno."] = "每次点击治疗也会选中那名队友，方便接着用其他技能、加增益效果，或帮他驱散诅咒或中毒。",
	["Cada cofre o tesoro conocido."] = "每个已知的宝箱或宝藏。",
	["Cada crítico hace sangrar."] = "每次暴击都会造成流血。",
	["Cada domingo en Tuercespina: el primero en llevar 40 pescados sabrosos de los bancos especiales gana. También salen peces raros que se cambian por premios."] = "每周日在荆棘谷：第一个从特殊鱼群中带回 40 条美味鱼的人获胜。还会钓到稀有鱼，可以换取奖品。",
	["Cada entrada de mazmorra y banda con su rango de niveles. Clic: su página; Mayús+clic: la flecha te lleva."] = "每个地下城和团队副本的入口及其等级范围。点击：打开其页面；Shift+点击：箭头带你过去。",
	["Cada frase sale tres veces como mucho. Con esto vuelven a salir desde el principio."] = "每句话最多出现三次。用这个可以让它们从头再出现。",
	["Cada golpe crítico deja al enemigo sangrando: daño extra sin hacer nada."] = "每次暴击都会让敌人流血：不用操作就有额外伤害。",
	["Cada grupo de la banda en su propia columna (o fila), como en la ventana de banda. Con el orden por grupo."] = "团队的每个小队各占一列（或一行），就像团队窗口一样。配合按小队排序。",
	["Cada hierba pide más habilidad que la anterior: recoge todo lo que puedas y sube sola. Enciende el rastreo de hierbas."] = "每种草药需要的技能都比上一种高：能采的都采，技能自己就会涨。记得打开寻找草药。",
	["Cada hierba tiene su lugar: unas junto al agua, otras en las montañas o bajo los árboles."] = "每种草药都有自己的生长地：有的在水边，有的在山上或树下。",
	["Cada lugar conocido donde aparece un enemigo raro."] = "每个已知的稀有敌人出没地点。",
	["Cada lunes te pongo tres retos chiquitos: misiones, raros y uno sorpresa. Tu avance está en mi página y cada reto cumplido vale una salchicha de premio."] = "每周一我会给你三个小挑战：任务、稀有怪和一个惊喜。你的进度在我的页面上，每完成一个挑战就能赢得一根奖励香肠。",
	["Cada lunes, tres retos chiquitos con su salchicha de premio. Tu avance sale arriba, en esta página."] = "每周一，三个小挑战，奖品是香肠。你的进度显示在本页上方。",
	["Cada meseta de Cima del Trueno tiene su función: una para los ancianos y los druidas, otra para los espíritus y otra para los cazadores."] = "雷霆崖的每座台地都有自己的用途：一座给长者和德鲁伊，一座给灵魂，一座给猎人。",
	["Cada misión que terminas te hace más fuerte."] = "你完成的每个任务都会让你更强。",
	["Cada muelle con cuánto falta para que llegue su barco o zepelín."] = "每个码头都显示它的船或飞艇还有多久到达。",
	["Cada muelle con cuánto falta para que llegue."] = "每个码头都显示还有多久到达。",
	["Cada nivel"] = "每级",
	["Cada paso de la bienvenida deja bajar hasta el final, sin cerrar y volver a abrir."] = "欢迎设置的每一步都可以一路往下滚动，不用关掉再重新打开。",
	["Cada preajuste llena tus clics con los hechizos que ya sabes. Después cambias lo que quieras en la página Curación."] = "每个预设都会用你已学会的法术填满点击设置。之后可在“治疗”页面随意更改。",
	["Cada reto da 1 punto. Al salir Forever hay %d retos, y cada personaje puede gastar hasta %d."] = "每个挑战给 1 点。Forever 上线时共有 %d 个挑战，每个角色最多可花费 %d 点。",
	["Cada semana guardo una copia de tus ajustes y perfiles. En Ajustes > Estilo y sonido, en «Respaldos», vuelves a una con un clic."] = "每周我都会保存一份你的设置和配置档。在 设置 > 风格与声音 的“备份”里，点一下就能恢复。",
	["Cada versión nueva te recibe con la intro del lobo y sus notas, como estas."] = "每个新版本都会用狼的开场动画和更新说明迎接你，就像现在这样。",
	["Cada vez que aprendes uno de los principales de tu clase te digo en corto para qué sirve y cuándo usarlo."] = "每次你学会职业的主要技能，我都会简单告诉你它有什么用、何时使用。",
	["Cada vez que entras al juego, la intro del lobo y la luna te da la bienvenida. Un clic o Esc la saltan."] = "每次进入游戏，狼与月亮的开场动画都会欢迎你。点击或按 Esc 可跳过。",
	["Cada vez: %s."] = "每次：%s。",
	["Cada zona con lobos y cuántos hay en cada guarida. En el mapa del mundo también sale."] = "每个有狼的区域，以及每个巢穴里有几只。世界地图上也会显示。",
	["Cada ícono del mapa con su tamaño exacto en tu pantalla, nítido de orilla a orilla."] = "地图上的每个图标都以屏幕上的精确尺寸显示，边缘清晰锐利。",
	["Cairne Pezuña de Sangre gobierna desde Cima del Trueno, aunque Magatha, de los Tótem Siniestro, no lo quiere tanto como aparenta."] = "凯恩·血蹄在雷霆崖统治，不过恐怖图腾的玛加萨并不像她表面上那样敬爱他。",
	["Cairne Pezuña de Sangre peleó en el Monte Hyjal junto a Thrall contra la Legión."] = "凯恩·血蹄曾和萨尔并肩在海加尔山对抗燃烧军团。",
	["Caja para escribir con el estilo"] = "输入框套用风格",
	["Calculando"] = "计算中",
	["Calculando la vuelta más corta…"] = "正在计算最短环线…",
	["Calidad"] = "品质",
	["Calidad de la niebla"] = "雾效质量",
	["Calidad de las sombras"] = "阴影质量",
	["Calla las voces de /bailar, /reír, /aplaudir y otros gestos."] = "静音 /dance、/laugh、/applaud 等表情的语音。",
	["Calla los ruidos de las mascotas, como el bostezo de los gatos de cazador."] = "静音宠物的声音，比如猎人猫打哈欠。",
	["Calma, que la cacería no se va a ningún lado. Come algo, repara y, si es mucho, la manada te echa la mano."] = "别急，猎物跑不了。吃点东西，修理一下，要是太难，狼群会搭把手。",
	["Cambia a «Todo» para ver su botín completo."] = "切换到“全部”即可查看完整战利品。",
	["Cambia al mapa de Alfa en esta zona: todo el mundo en un solo mapa, con zoom y tus marcadores."] = "在此区域切换到 Alfa 地图：整个世界在一张地图上，可缩放并显示你的标记。",
	["Cambia de plano cuando está lleno, «¿Quién tiene...?» y los festejos de la manada."] = "人多时切换位面、“谁有……？”以及狼群的庆祝。",
	["Cambia el modo limpio del mapa"] = "切换地图的简洁模式",
	["Cambia lo que quieras: se guarda al momento."] = "想改什么都行：会立即保存。",
	["Cambiar"] = "更换",
	["Cambiar de forma te quita lentitudes y raíces: úsalo para escapar."] = "变换形态可以解除减速和定身：用它来脱身。",
	["Cambiar de plano"] = "切换位面",
	["Cambiar de plano si está lleno"] = "人多时切换位面",
	["Cambiar de plano: te pasa al de un lobo de la manada con su guarida abierta"] = "切换位面：把你转到一只开着巢穴的狼群伙伴的位面",
	["Cambiar el tamaño"] = "调整大小",
