	["Cambiar nombre..."] = "重命名...",
	["Cambiar o borrar"] = "更改或删除",
	["Cambias de actitud según la pelea sin perder ira."] = "根据战斗需要切换姿态，不损失怒气。",
	["Cambias de actitud sin perder ira."] = "切换姿态不损失怒气。",
	["Cambias de actitud sin perder ira: puedes pasar a defensiva cuando se complica."] = "切换姿态不损失怒气：情况不妙时可以切到防御姿态。",
	["Cambias vida por maná. Úsalo y luego recupera tu vida comiendo."] = "用生命值换法力。用完后吃东西把生命值补回来。",
	["Cambiaste %d ajustes aquí. Volver a ponerlos al entrar está apagado (Avanzado)."] = "你在这里更改了 %d 项设置。登录时重新套用已关闭（高级）。",
	["Camina"] = "步行",
	["Camina por el agua: espérenlo en tierra y atráiganlo con un ataque a distancia."] = "他在水里走动：在岸上等他，用远程攻击把他拉过来。",
