	["Canal oculto: %s (%s, número %s, intentos %d)"] = "隐藏频道：%s（%s，编号 %s，尝试 %d 次）",
	["Cancelar"] = "取消",
	["Cantidad: %d"] = "数量：%d",
	["Capas de Alfa"] = "Alfa 图层",
	["Capas de Alfa: elige qué se ve en el mapa"] = "Alfa 图层：选择地图上显示的内容",
	["Capas del mapa"] = "地图图层",
