	["Capturas"] = "渔获",
	["Capturas: %d de %d"] = "渔获：%d / %d",
	["Carbón cálido y el naranja de las brasas, como la manada junto al fuego."] = "温暖的炭黑配上余烬的橙色，就像围在火边的狼群。",
	["Carcaj"] = "箭袋",
	["Carcajs"] = "箭袋",
