	["Cargando tus cartas..."] = "正在载入你的信件...",
	["Cargando…"] = "载入中…",
	["Cargar en actitud defensiva."] = "防御姿态下也能冲锋。",
	["Cargar en actitud defensiva: empiezas cada pelea sin cambiar de actitud."] = "防御姿态下也能冲锋：每场战斗都不用切换姿态就能开打。",
	["Cargar te da más ira al empezar: la pelea arranca a tu favor."] = "冲锋在开场时给你更多怒气：战斗一开始就占上风。",
	["Carrete"] = "卷线声",
	["Casa de subastas"] = "拍卖行",
