	["Cazar juntos"] = "一起狩猎",
	["Caíste %d veces, pero saliste de pie."] = "倒下了 %d 次，但你站着走了出来。",
	["Caíste %d veces, pero siempre te levantaste."] = "你倒下了 %d 次，但每次都爬了起来。",
	["Caíste %d vez, pero te levantaste."] = "你倒下了 %d 次，但爬了起来。",
