	["Cebo: %s"] = "鱼饵：%s",
	["Cebos"] = "鱼饵",
	["Cecina dura"] = "硬肉干",
	["Celestes"] = "天裔",
	["Cenarius, el señor del bosque, es hijo de Malorne, el Ciervo Blanco. Los druidas de la Alianza y de la Horda lo honran por igual."] = "森林之王塞纳留斯是白色雄鹿玛洛恩之子。联盟和部落的德鲁伊都同样敬奉他。",
