	["Citas de la manada"] = "狼群集合",
	["Citas de la manada, «¿Quién va?», raros con reloj y notas en tu mapa."] = "狼群集合、“谁去？”、稀有怪计时和地图笔记。",
	["Citas y notas sin compartir tu ubicación, el oro del buzón aparte y Alfa más ligero."] = "约会和笔记无需分享位置，邮箱金币单独计算，Alfa 更轻巧。",
	["Ciudad"] = "城镇",
	["Ciudad Manitas, dentro de Forjaz, es el barrio de los gnomos: ruido, vapor e inventos por todos lados."] = "铁炉堡里的侏儒区是侏儒的街区：到处都是噪音、蒸汽和发明。",
	["Clase"] = "职业",
	["Clases (27): llegar a nivel 25, 45 y 60 con cada una de las 9 clases."] = "职业（27）：用 9 个职业各自达到 25、45 和 60 级。",
	["Clic derecho (o Mayús+clic): un marcador ahí. Ctrl+clic: la flecha y la ruta te llevan ahí sin guardar nada."] = "右键（或 Shift+点击）：在那里放置标记。Ctrl+点击：箭头和路线带你过去，不保存任何东西。",
	["Clic derecho en la misión, en tu registro o en el rastreador: «Ver la cadena completa». Te digo cuáles hiciste y el premio del final."] = "在任务日志或追踪器中右键点击任务：“查看完整任务链”。我会告诉你做过哪些，以及最终奖励。",
	["Clic derecho en su retrato o en su nombre del chat y elige «Invitar al clan». A tu hermandad le llega con un clic."] = "右键他的头像或聊天里的名字，选“邀请进氏族”。公会邀请一点就发出。",
	["Clic derecho en un jugador (su retrato, su nombre en el chat o tu grupo) y elige tu hermandad: la invitación le llega sin escribir su nombre. Para una comunidad, Alfa te deja el nombre listo para pegar en la ventana del juego."] = "右键点击一名玩家（头像、聊天中的名字或你的队伍），选择你的公会：无需输入名字，邀请就会送达。对于社区，Alfa 会准备好名字，让你粘贴到游戏窗口中。",
	["Clic derecho en un jugador y «Invitar al clan»: eliges tu hermandad o tu comunidad y la invitación le llega sin escribir su nombre."] = "右键点击一名玩家并选择“邀请加入公会或社区”：选好你的公会或社区，无需输入名字，邀请就会送达。",
	["Clic derecho: dejarla sin acción."] = "右键：设为无动作。",
	["Clic derecho: opciones de esta guía"] = "右键点击：此指南的选项",
	["Clic derecho: reiniciar, quitar o llevar a Mis planes."] = "右键点击：重新开始、移除或加入“我的计划”。",
	["Clic en Llévame: la flecha te lleva"] = "点击“带我去”：箭头会带你过去",
	["Clic en un marcador: su ficha (cambiarlo, compartirlo, borrarlo o seguirlo). Mayús+clic: seguirlo de una vez. Clic derecho en cualquier otro pin: seguirlo o guardarlo como marcador."] = "点击标记：打开其详情（更改、分享、删除或跟随）。Shift+点击：直接跟随。右键点击其他任何图钉：跟随或保存为标记。",
	["Clic en una casilla para elegir qué hace sobre el compañero bajo tu ratón; clic derecho la deja sin acción. Los cambios se aplican fuera de combate."] = "点击格子，选择对鼠标下的队友执行什么；右键设为无动作。更改会在脱离战斗后生效。",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta."] = "点击其中一个：Alfa 地图会移到它那里。“跟随”会设置箭头和路线。",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta; la huella del grupo lo comparte con quien use Alfa."] = "点击其中一个：Alfa 地图会移到它那里。“跟随”会设置箭头和路线；狼群爪印会把它分享给使用 Alfa 的人。",
	["Clic en uno: el mapa va hasta él. Clic derecho en el mapa: uno nuevo."] = "点击其中一个：地图会移到它那里。在地图上右键：新建一个。",
