	["Entrañas son las criptas y catacumbas bajo la antigua capital de Lordaeron."] = "幽暗城是洛丹伦旧都地下的墓穴和地下墓窟。",
	["Entrañas tiene barrios para magos, pícaros, guerreros y boticarios, y en el anillo central están el banco y la casa de subastas."] = "幽暗城有法师、盗贼、战士和药剂师各自的区域，中央环区有银行和拍卖行。",
	["Entre Entrañas y Grom'gol también hay zepelín: así bajas al sur sin cruzar todo el continente."] = "幽暗城和格罗姆高之间也有飞艇：这样不用横穿整片大陆就能南下。",
	["Entre los druidas están los de la Garra, que se vuelven osos, y los del Espolón, que toman forma de cuervo."] = "德鲁伊中有会变成熊的利爪德鲁伊，也有会化身乌鸦的猛禽德鲁伊。",
