	["Equipo %d %%"] = "装备 %d %%",
	["Equipo a punto de romperse."] = "装备快要损坏了。",
	["Equipo de pesca"] = "钓鱼装备",
	["Equipo reparado, comida, espacio y lo de tu clase: a cazar con la manada."] = "装备修好了，食物、空间和职业材料都备齐：和狼群一起去狩猎吧。",
	["Equipo y banco"] = "装备与银行",
	["Equipo y cebos"] = "装备与鱼饵",
	["Equipo y estadísticas"] = "装备与属性",
	["Equipo, bolsas, comida y lo de tu clase"] = "装备、背包、食物和职业材料",
	["Equipo, consumibles, misiones, materiales... con encabezados que se pliegan."] = "装备、消耗品、任务物品、材料……标题可折叠。",
	["Equitación"] = "骑术",
	["Equitación de aprendiz (nivel 40)"] = "初级骑术（40 级）",
	["Equitación de oficial (la rápida, nivel 60)"] = "中级骑术（快速，60 级）",
	["Eranikus, el consorte de Ysera, quedó atrapado en la pesadilla; su sombra ronda el Templo de Atal'Hakkar."] = "伊瑟拉的配偶伊兰尼库斯被困在梦魇中；他的阴影在阿塔哈卡神庙中徘徊。",
	["Eres de la manada"] = "你是狼群的一员",
	["Eres nivel %d"] = "你的等级是 %d",
	["Eres nivel %d y se recomienda el %d: desde ahí cuenta así."] = "你是 %d 级，推荐 %d 级：从那里开始这样计算。",
	["Eres nivel %d."] = "你的等级是 %d。",
	["Error"] = "错误",
	["Errores atrapados"] = "捕获的错误",
	["Errores de Alfa"] = "Alfa 的错误",
	["Errores de Lua de Alfa en esta sesión:"] = "本次游戏中 Alfa 的 Lua 错误：",
	["Errores de Lua de Alfa en esta sesión: ninguno"] = "本次游戏中 Alfa 的 Lua 错误：无",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "副本很短，就在暴风城里面。囚犯关在两侧的牢房里：慢慢推进。",
	["Es de la otra facción"] = "属于另一阵营",
	["Es de una misión."] = "这是任务物品。",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "这是联盟某个任务要求击杀的首领：进去前检查一下你的任务。",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "这是第一个首领，很简单。他死后，本阵营的囚犯会打开通往庭院的门。",
	["Es el primer reto: con él se abre el Legado."] = "这是第一个挑战：完成后传承就会开启。",
	["Es el punto %d de %d de tu build."] = "这是你方案的第 %d/%d 点。",
	["Es el que toca ahora."] = "现在该点这个。",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "墓地的最后一个首领。会向四周喷射火焰：远程玩家请站远一点。",
	["Es el único lobo a la vista."] = "视野中只有这一只狼。",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "副本很大，容易迷路：跟紧一个人，别单独乱跑。",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "这是斯尼德的机器：把它打坏，他就会出来战斗。",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "部落的第一个地下城：很短，适合学习组队玩法。",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "联盟的第一个大型地下城：慢慢推进，一次只拉一群怪。",
	["Es la que más vale al venderla."] = "这是卖价最高的。",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "副本很长，有两个入口。很多敌人是石头做的，打人很痛。",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "副本很长，机器人很多：有些会放炸弹，或拉响警报引来更多敌人。",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "他移动很慢：远程玩家可以趁他靠近时输出。",
	["Es muy veloz: frénalo si tu clase puede."] = "他速度很快：如果你的职业能减速就减速他。",
	["Es opcional. Si dices que sí, los lobos de La Jauría que usan Alfa ven a tu personaje en el mapa de WoW, como ves a tu grupo, y pueden llegar a donde estás con la flecha; y tú a ellos. Alfa solo comparte dónde anda tu personaje dentro del juego: la zona, el punto en el mapa, su nivel y su clase. Nada de tu ubicación real, tu computadora ni tu cuenta."] = "这是可选的。如果你同意，使用 Alfa 的 La Jauría 狼群成员就能在 WoW 地图上看到你的角色，就像你看到自己的队伍一样，还能用箭头找到你；你也能找到他们。Alfa 只分享你的角色在游戏中的位置：区域、地图上的点、等级和职业。绝不涉及你的真实位置、你的电脑或你的账号。",
	["Es opcional: tu personaje aparece en el mapa de WoW de los lobos de La Jauría que usan Alfa, y ellos en el tuyo, para encontrarse y llegar con la flecha. Solo se comparte dónde anda tu personaje dentro del juego (zona, punto en el mapa, nivel y clase), nunca tu ubicación real ni nada de tu computadora, y nunca dentro de mazmorras. Va por un canal oculto que no sale en el chat, aunque alguien que entre a él con otro addon podría verlo. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "这是可选的：你的角色会出现在使用 Alfa 的 La Jauría 狼群的 WoW 地图上，他们也会出现在你的地图上，方便互相找到并用箭头前往。只分享你的角色在游戏中的位置（区域、地图上的点、等级和职业），绝不分享你的真实位置或电脑里的任何东西，在地下城中也不会分享。它通过一个不会显示在聊天中的隐藏频道发送，不过用其他插件加入该频道的人可能会看到。你的队伍始终可见。可以随时在 La Jauría 中更改。",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "适合 %s 级，你是 %d 级：还差 %d 级。",
	["Es para otra raza."] = "适用于其他种族。",
	["Es raro del Cementerio y no siempre aparece."] = "墓地的稀有首领，不一定会出现。",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "墓地的稀有首领，不一定会出现。会施毒：记得驱毒。",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "墓地的稀有首领，不一定会出现。能沉默施法者。",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "稀有首领，很少出现。会在身边释放火焰。",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "稀有首领，在一个隐蔽的洞穴里。是一只攻击很快的蝙蝠。",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "稀有首领，不一定会出现。以他的等级来说打人非常痛：拉怪时要小心。",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "稀有首领，不一定在。会重击面前的所有人。",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "稀有首领。会放下大地图腾：打掉它。",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "稀有首领：不一定在。会催眠玩家，并在身边引发魔法爆炸。",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "很简单：正好趁打最终首领前喝口水。",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "他是施法者：如果你的职业能打断就打断他（脚踢、盾击、地震术……）。",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "他是带图腾的萨满：打掉图腾，它们很容易打。",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "持盾的矮人：很耐打，但没什么特殊技能。",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "矿洞里的强力敌人：把他当成小首领来打。",
	["Es un grupo: cada uno suelta su propio botín."] = "这是一组敌人：每个都会掉落自己的战利品。",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "他是圣骑士，会用圣光术治疗自己。打断他的治疗。",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "动作很快的萨特，会施毒：如果你的职业能驱毒，就用上。",
	["Es un trogg que lanza rayos: interrúmpelo."] = "会施放闪电的穴居人：打断他。",
	["Es una mejora para ti"] = "对你是提升",
	["Es una mejora para ti."] = "这对你是提升。",
	["Es una montura de tu clase: pregunta a tu instructor de clase cuándo y cómo se consigue."] = "这是你职业专属的坐骑：问问你的职业训练师何时以及如何获得。",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "护甲很厚的巨龟：攻击慢但很痛。",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "非常耐打的乌龟，但只会普通攻击：没什么特殊技能。",
	["Es viejo: escanea para tenerlo al día."] = "数据旧了：扫描一下保持更新。",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "该字符串中没有 Alfa 可评分的属性。",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "那一排还没解锁：该系天赋的点数不够。",
	["Esa tecla ya tiene dueño"] = "这个按键已被占用",
	["Esa ya me la diste, ¡gracias! Guárdame la siguiente."] = "这根你已经给过我了，谢谢！下一根留给我吧。",
	["Esbirros enemigos"] = "敌方仆从",
	["Escala de estadísticas"] = "属性权重",
	["Escalas:"] = "中转站：",
	["Escaneando..."] = "扫描中...",
	["Escanear ahora"] = "立即扫描",
	["Escanear con Alfa"] = "用 Alfa 扫描",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "完整扫描：%s 种物品有价格（%s 件拍卖品）。",
	["Escarcha"] = "冰霜",
	["Escarcha en cono frente a ti que hace lentos a los enemigos."] = "在你前方喷出一片冰霜，减速敌人。",
	["Escarcha para subir"] = "冰霜（升级）",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "钓鱼时隐藏 NPC 的姓名板和名字（敌对目标仍显示名字），让鱼漂更容易看见和点到。",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "隐藏技能要求高于你当前技能的采集点。不勾选时会以灰色淡化显示。",
	["Escribe %s o haz clic en el lobo del minimapa para abrirla. Empieza en Hoy, con lo que toca a tu clase; %s muestra u oculta la ventana de guía."] = "输入 %s 或点击小地图上的狼即可打开。窗口先显示“今天”，列出你的职业需要的东西；%s 可显示或隐藏指南窗口。",
	["Escribe %s y cuéntanos en el Discord de La Jauría."] = "输入 %s，然后在 La Jauría 的 Discord 告诉我们。",
	["Escribe /alfa diagnostico: reviso si otro addon choca con Alfa, si falta una parte o si un ajuste quedó raro, y te doy el arreglo a un clic."] = "输入 /alfa diagnostico：我会检查是否有其他插件与 Alfa 冲突、是否缺少部分或设置异常，并给你一键修复。",
	["Escribe /alfa teclas: ahí están todas, y con un clic pulsas la que quieras."] = "输入 /alfa teclas：所有按键都在那里，点一下就能按下你想要的那个。",
	["Escribe al menos 3 letras del objeto."] = "至少输入物品名称的 3 个字。",
	["Escribe al menos dos letras."] = "请至少输入两个字。",
	["Escribe algo y pulsa «Nota aquí»: queda en tu mapa donde estás parado. Un clic en la marca y la flecha te lleva."] = "写点什么，然后点“在这里记笔记”：笔记会留在你站立处的地图上。点一下标记，箭头就会带你过去。",
	["Escribe algo y pulsa «Nota aquí»: queda en tu mapa donde estás parado. «Spot aquí» marca un buen lugar para farmear, en dorado. Un clic en la marca y la flecha te lleva."] = "写点东西，然后点“在这里记笔记”：它会留在你地图上你站的位置。“此处刷点”会用金色标出一个适合刷的好地方。点击标记，箭头就会带你去。",
	["Escribe arriba el nombre de una mazmorra para buscarla."] = "在上方输入地下城名称进行搜索。",
	["Escribe cuánto oro (1 o más)."] = "输入多少金币（1 或以上）。",
	["Escribe el número que quieras y presiona Enter."] = "输入你想要的数字，然后按 Enter。",
	["Escribe el top %d en el chat de tu grupo o banda."] = "在你的小队或团队聊天中发布前 %d 名。",
	["Escribe en el chat del grupo cuando terminas un objetivo de una misión compartida. Viene apagado para no llenar el chat de nadie."] = "完成共享任务的一个目标时，在队伍聊天中发言。默认关闭，以免刷屏。",
	["Escribe lo que buscas: un ajuste, o algo del juego, y te lo busco en la Enciclopedia."] = "输入你要找的：一个设置，或游戏里的东西，我帮你在百科里找。",
	["Escribe qué buscas: «Minas de la Muerte, falta sanador»."] = "写下你要找什么：“死亡矿井，缺治疗”。",
	["Escribe qué dice la nota: /alfa nota Aquí sale el mineral"] = "写下笔记内容：/alfa nota 这里刷矿",
	["Escribe qué se farmea ahí: /alfa spot Lobos para pieles"] = "写下那里刷什么：/alfa spot 刷狼皮",
	["Escribe qué van a hacer (una mazmorra, una misión, lo que sea)."] = "写下要做什么（地下城、任务，什么都行）。",
	["Escribe tu nota."] = "写下你的备注。",
	["Escribe un nivel (2 o más)."] = "输入一个等级（2 或以上）。",
	["Escribe un nombre corto para reconocerla."] = "输入一个简短的名字，方便辨认。",
	["Escribe un nombre para este conjunto."] = "为这套装备输入一个名称。",
	["Escribe un objeto y pulsa «Buscar»: te contestan los lobos de tu hermandad que lo permiten."] = "输入物品并点“搜索”：公会里允许回应的狼会回答你。",
	["Escribir a %s"] = "给%s发消息",
	["Escuchar"] = "试听",
	["Escuchar el aullido"] = "试听狼嚎",
	["Escudo"] = "盾牌",
	["Escudo de relámpagos"] = "闪电之盾",
	["Escudo y defensa: aguantas a todos los monstruos para que tu grupo no sufra."] = "盾牌和防御：扛住所有怪物，让队友不受伤害。",
	["Escudo y luz sagrada: un tanque muy resistente que recupera su propio maná."] = "盾牌加神圣之光：一个非常耐打、能自己回复法力值的坦克。",
	["Escudos y curas preventivas: aguantas mucho y apoyas al grupo."] = "护盾和预防性治疗：非常耐打，还能支援队伍。",
	["Ese build es para otra clase."] = "这个方案是给其他职业的。",
	["Ese día ni la manada te alcanzaba."] = "那天连狼群都追不上你。",
	["Ese respaldo ya no está."] = "那份备份已经不在了。",
	["Ese talento necesita antes otro talento completo (la flecha del árbol)."] = "这个天赋需要先点满另一个天赋（天赋树中的箭头）。",
	["Ese texto es demasiado largo para un build."] = "这段文字太长，不是有效的方案。",
	["Ese texto es demasiado largo para una cadena de escala."] = "该文本过长，不是有效的权重字符串。",
	["Ese texto no es un perfil de Alfa. Copia el que da «Exportar» completo."] = "这段文字不是 Alfa 配置档。请完整复制“导出”给出的文字。",
	["Ese texto no es una ruta de Alfa."] = "这段文字不是 Alfa 路线。",
	["Esmeralda"] = "翡翠",
	["Eso no es una cadena de build de Alfa. Empieza con ALFA1;"] = "这不是 Alfa 的方案字符串。它应该以 ALFA1; 开头",
	["Eso no es una cadena de escala de estadísticas. Empieza con ( Pawn: v1: \"Nombre\": ..."] = "这不是属性权重字符串。它以 ( Pawn: v1: \"名称\": ... 开头",
	["Eso se puede al salir de combate."] = "脱离战斗后才能这样做。",
	["Espacio"] = "空格",
	["Espacio libre"] = "剩余空间",
	["Espacio y dinero"] = "空间和金钱",
	["Espacios libres para el botín"] = "放战利品的空格",
	["Espada de dos manos"] = "双手剑",
	["Espada de una mano"] = "单手剑",
	["Espalda"] = "背部",
	["Español, inglés y siete idiomas más, en toda la interfaz."] = "西班牙语、英语及另外七种语言，覆盖整个界面。",
	["Espera %s"] = "请等待 %s",
	["Espera a que el tanque tenga al enemigo bien agarrado antes de pegar fuerte."] = "等坦克稳稳拉住敌人后再全力输出。",
	["Espera a que termine el combate."] = "正在等待战斗结束。",
	["Espera a salir de combate para probarla."] = "请脱离战斗后再测试。",
	["Espera a salir de combate."] = "请等脱离战斗后再试。",
	["Espera a terminar de entrar al juego."] = "请等待完全进入游戏。",
	["Espera de unos %d min; va a %s"] = "约等 %d 分钟；开往 %s",
	["Espera unos segundos antes de buscar otra vez."] = "等几秒再搜索。",
	["Espera unos segundos antes de volver a poner tu anuncio."] = "请等几秒再重新发布你的公告。",
	["Espera · nivel %d"] = "等待 · %d 级",
	["Esperando"] = "等待中",
	["Esperando su respuesta"] = "等待他的回复",
	["Espíritu"] = "精神",
	["Esquiva"] = "躲闪",
	["Esquivar"] = "躲闪",
	["Esquivas casi todo unos segundos. Tu salvavidas cuando te pegan muchos."] = "几秒内几乎能躲开一切攻击。被很多敌人围攻时的救命技。",
	["Esquivas más cuerpo a cuerpo. Úsalo si el enemigo te alcanza."] = "近战中更容易躲闪。敌人贴近你时使用。",
	["Esta clase no tiene pesos de estadísticas en Alfa."] = "Alfa 中没有这个职业的属性权重。",
	["Esta clase no tiene pesos de estadísticas."] = "这个职业没有属性权重。",
	["Esta es Hoy"] = "这是“今天”",
	["Esta explicación no saldrá más. En Combate puedes volver a encenderlas."] = "这条说明不会再出现。可以在“战斗”中重新开启。",
	["Esta guía no tiene un paso para ti ahora"] = "这份指南现在没有适合你的步骤",
	["Esta guía no tiene un paso para ti ahora: puede que hayas omitido lo que queda o que aún no te toque. Elige otra guía o vuelve a esta más adelante."] = "这个指南现在没有你的步骤：可能你跳过了剩下的，或者还没轮到你。选择其他指南，或稍后再回来。",
	["Esta misión va sola: no pide otra ni abre otra."] = "这个任务是独立的：不需要前置，也不开启后续。",
	["Esta semana llevas %s"] = "本周你已有：%s",
	["Esta semana todavía no cazamos nada. ¿Salimos?"] = "这周还没狩猎呢。出发吗？",
	["Esta semana, entre %d lobos: %s"] = "本周，%d 只狼一起：%s",
	["Esta sesión"] = "本次游戏",
	["Esta sesión, por recurso"] = "本次，按资源",
	["Esta sesión: %d capturas de %d lanzamientos. Desde siempre: %d."] = "本次：%d 次渔获，共 %d 次抛竿。累计：%d。",
	["Esta sesión: %s"] = "本次游戏：%s",
	["Esta sesión: +%s"] = "本次登录：+%s",
	["Esta sesión: +%s · %s por hora"] = "本次登录：+%s · 每小时 %s",
	["Esta subasta no permite el escaneo completo."] = "这个拍卖行不支持完整扫描。",
	["Esta va de %s y %s… ¿Te la cuento?"] = "这个故事关于%s和%s……要我讲给你听吗？",
	["Esta va de %s y de lobos… me toca de cerca. ¿Te la cuento?"] = "这个故事关于%s和狼……跟我很有关系。要我讲给你听吗？",
	["Esta vez conviene el ángel."] = "这次找灵魂医者更划算。",
	["Esta zona"] = "本区域",
	["Esta zona huele a aventura. ¿Tú qué hueles?"] = "这个区域闻起来有冒险的味道。你闻到了什么？",
	["Establos"] = "兽栏管理员",
	["Estadísticas"] = "属性",
	["Estadísticas [pesca]"] = "统计",
	["Este aviso ya no mostrará texto: solo el ícono. En Combate puedes volver a encenderlos."] = "这个提示以后不再显示文字：只显示图标。可以在“战斗”中重新开启。",
	["Este banco no vende más espacio."] = "这个银行不再出售更多空间。",
	["Este build pega muchísimo, pero aguanta poco: elige bien cuándo entrar."] = "这个方案伤害极高，但不耐打：要选好出手时机。",
	["Este clic no hace nada. Elígele algo en Tu ratón, en la página Curación."] = "这个点击没有任何作用。请在“治疗”页面的“你的鼠标”中为它选择。",
	["Este cliente no carga los mosaicos del minimapa: se ve el arte pintado."] = "此客户端不加载小地图图块：显示的是手绘地图。",
	["Este cliente no da el arte del mapa"] = "此客户端不提供地图美术资源",
	["Este cliente no deja compartir"] = "此客户端不允许共享",
	["Este cliente no deja compartir marcadores."] = "此客户端不允许分享标记。",
	["Este cliente no deja copiar tu mapa solo: se abrió la ventana de clic para lanzar de Blizzard para que lo armes ahí."] = "此客户端无法自动复制你的鼠标绑定：已打开暴雪的点击施法窗口，请在那里设置。",
	["Este cliente no tiene %d de estos ajustes: no se muestran."] = "此客户端缺少其中 %d 项设置：不会显示。",
	["Este cliente no tiene el clic para lanzar de Blizzard. Tus clics funcionan en los marcos de Alfa."] = "此客户端没有暴雪的点击施法功能。你的点击设置在 Alfa 框体上有效。",
	["Este paso"] = "此步骤",
	["Este paso es para cerrar tus misiones de %s. Cuando estés allá, «Llévame» te lleva a cada una."] = "这一步是完成你在%s的任务。到了那里，“带我去”会带你去每一个。",
	["Este paso no tiene punto en el mapa."] = "此步骤在地图上没有位置。",
	["Este paso une el Bosque del Ocaso con el Pantano de las Penas, y casi todos lo cruzan sin detenerse."] = "这条小径连接暮色森林和悲伤沼泽，几乎所有人都是一路穿过，不作停留。",
	["Este talento no está en tu build."] = "这个天赋不在你的方案中。",
	["Este tramo quedó vacío."] = "这个路段是空的。",
	["Estilo"] = "风格",
	["Estilo de las barras"] = "动作条风格",
	["Estilo del chat"] = "聊天风格",
	["Estilo del mapa"] = "地图风格",
	["Estilo del minimapa"] = "小地图风格",
	["Estilo y sonido"] = "风格与声音",
	["Esto está lleno de cazadores"] = "这里挤满了猎人",
	["Esto huele a historia grande. Pon atención."] = "这闻起来像个大故事。注意听。",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "战斗中无法更改。请在战斗结束后再试。",
	["Esto no se puede vincular."] = "这个无法链接。",
	["Esto te sirve más en el banco o con otro de tus personajes (mándaselo por correo). Con un banquero, se guarda con un clic."] = "这个放在银行或给你的其他角色更有用（用邮件寄给他）。在银行职员旁边，点一下就能存入。",
	["Estos filtros los dibuja Alfa, no el juego: quedan detrás de toda la interfaz (nunca la tapan) y también se ven con la interfaz oculta (Alt+Z), para tus capturas."] = "这些滤镜由 Alfa 绘制，而不是游戏：它们位于整个界面后方（绝不遮挡界面），隐藏界面（Alt+Z）时也能看到，方便你截图。",
	["Está en combate. Prueba en un momento."] = "他正在战斗。稍后再试。",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "在墓地。会施放持续造成伤害的暗影痛。",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "他在瀑布旁的水里：先把他拉到岸上再打。",
	["Está en la %s, otro plano de tu zona."] = "他们在%s，你所在区域的另一个位面。",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "在武器库。他大喊时会挥斧旋转，打中附近所有人：赶快离开。",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "在图书馆，带着他的猎犬：先杀猎犬，或使用范围攻击。",
	["Está en tu lista de compras."] = "它在你的购物清单里。",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "藏在大教堂里。会施放诅咒并治疗自己：打断他。",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "到处都是野猪人和荆棘隧道：每次少拉一点怪。",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "他身边围着干活的地精：先把这些地精一个一个拉走。",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "他被鱼人围着：先把他的同伴拉走再打他。",
