	["Golpea a todos los de alrededor y los hace atacar más lento. Ideal cuando te rodean varios."] = "攻击你周围的所有敌人并减慢它们的攻击速度。被多个敌人包围时很棒。",
	["Golpea a todos los que están cerca y los avienta: si peleas cuerpo a cuerpo, cuida tu vida."] = "他会攻击并击退附近所有人：近战玩家注意自己的血量。",
	["Golpea a todos los que tiene enfrente: ataca desde su espalda si peleas cuerpo a cuerpo."] = "他会攻击面前的所有人：近战玩家请从他背后攻击。",
	["Golpea a todos los que tiene enfrente: si peleas cuerpo a cuerpo, ataca por detrás."] = "他会攻击面前的所有人：近战玩家请绕到背后攻击。",
	["Golpea a tu objetivo y a otro cercano. Para cuando pelean dos o más."] = "攻击你的目标和附近的另一个敌人。有两个以上敌人打你时用。",
