	["Grim Batol fue una ciudad enana. Después, los orcos Faucedraco la usaron para tener presa a Alexstrasza, la Reina Dragón."] = "格瑞姆巴托曾是一座矮人城市。后来，龙喉兽人利用它囚禁了巨龙女王阿莱克丝塔萨。",
	["Grito de batalla"] = "战斗怒吼",
	["Grito de batalla para el guerrero; Intelecto Arcano y una armadura para el mago; Entereza y Fuego interno para el sacerdote; y lo suyo para cada clase."] = "战士的战斗怒吼；法师的奥术智慧和护甲法术；牧师的真言术：韧和心灵之火；其他职业也各有对应。",
	["Grom Grito Infernal fue el primer jefe orco en beber la sangre de Mannoroth, y así ató a su pueblo a los demonios."] = "格罗姆·地狱咆哮是第一个饮下玛诺洛斯之血的兽人酋长，从此把他的族人和恶魔绑在了一起。",
	["Grom Grito Infernal y Varian Wrynn son guerreros legendarios de la historia."] = "格罗姆·地狱咆哮和瓦里安·乌瑞恩都是历史上的传奇战士。",
	["Grom'gol es el campamento de la Horda en la Vega, con zepelines a Orgrimmar y a Entrañas."] = "格罗姆高是部落在荆棘谷的营地，有飞艇开往奥格瑞玛和幽暗城。",
	["Grupo"] = "小队",
	["Grupo de %d"] = "%d 人小队",
	["Grupo de 5"] = "5 人小队",
	["Guarda %d misiones: las entregas en una guía que sigue."] = "保留 %d 个任务：在后面的指南中交付。",
	["Guarda Grito intimidador para cuando estés en peligro."] = "把破胆怒吼留到危险的时候用。",
	["Guarda Muro de escudo para los peores momentos del jefe."] = "把盾墙留到首领最危险的阶段用。",
	["Guarda cómo tienes Alfa ahora con el nombre de tu personaje, para volver a ella con un clic. Útil si juegas con varios personajes."] = "用角色名保存你现在的 Alfa 设置，一键就能回来。适合玩多个角色的你。",
	["Guarda en el banco los materiales que todavía no usas, y deja las bolsas libres para el botín."] = "还用不到的材料先存进银行，把背包空出来装战利品。",
	["Guarda lo que llevas como un conjunto (curar, daño, pesca...) desde el botón de tus bolsas o en Bolsas, y póntelo con un clic. En combate te lo pongo al terminar."] = "从背包的按钮或在背包页面，把身上的装备存成一套方案（治疗、输出、钓鱼……），点一下就能穿上。战斗中我会在结束后帮你换上。",
	["Guarda lo que llevas puesto con un nombre (curar, daño, pesca...) y póntelo con un clic, fuera de combate."] = "给身上的装备取个名字保存（治疗、输出、钓鱼……），非战斗时点一下就能穿上。",
	["Guarda lo que llevas puesto con un nombre (curar, daño, pesca...) y vuelve a ponértelo con un clic. También desde el botón de tus bolsas."] = "给身上的装备取个名字保存（治疗、输出、钓鱼……），点一下就能再穿上。也可以从背包的按钮使用。",
	["Guarda o cambia tu mascota"] = "寄存或更换你的宠物",
	["Guarda tu configuración como perfil primero."] = "请先把你的设置保存为配置档。",
	["Guarda tus materiales en el banco (%d)."] = "把你的材料存进银行（%d）。",
	["Guarda un poco de tela para vendas: Primeros auxilios también la usa."] = "留一些布料做绷带：急救也要用到。",
	["Guardada el %s"] = "保存于 %s",
	["Guardar"] = "保存",
	["Guardar %d"] = "保留 %d",
	["Guardar [conservar]"] = "保留",
	["Guardar como marcador"] = "保存为标记",
	["Guardar lo que llevas"] = "保存身上的装备",
	["Guardar lo que llevas…"] = "保存身上的装备……",
	["Guardar mi configuración"] = "保存我的设置",
	["Guardar y seguir"] = "保存并跟随",
	["Guardas ira al cambiar de actitud."] = "切换姿态时保留怒气。",
	["Guardas tu ira al cambiar de actitud; así Cargar, Abrumar y Revancha salen casi gratis."] = "切换姿态时保留怒气，这样冲锋、压制和复仇几乎不花代价。",
	["Guardaste %d objeto en el banco."] = "你在银行存入了 %d 件物品。",
	["Guardaste %d objetos en el banco."] = "你在银行存入了 %d 件物品。",
	["Guardaste tu sesión de pesca y empezaste otra."] = "你保存了这次钓鱼记录，并开始了新的一次。",
	["Guardaste «%s» con %d piezas."] = "已保存“%s”，共 %d 件。",
	["Guardianes enemigos"] = "敌方守护者",
	["Guarida %s"] = "%s巢穴",
	["Guarida desconocida"] = "未知巢穴",
	["Guaridas"] = "巢穴",
	["Guaridas de la manada en %s"] = "%s 的狼群巢穴",
	["Guaridas en el mapa"] = "地图上的巢穴",
	["Guaridas y los avisos de La Jauría"] = "巢穴与 La Jauría 提醒",
	["Guerrero"] = "战士",
	["Guiarme"] = "带我去",
	["Gul'dan fue el primer brujo orco, y su historia no terminó nada bien. Tú úsalo con más cabeza."] = "古尔丹是第一个兽人术士，他的结局可一点都不好。你可要更聪明地运用这股力量。",
	["Gul'dan fundó el Consejo de la Sombra, un grupo de brujos que movía a la Horda desde las sombras."] = "古尔丹创立了暗影议会，这群术士在幕后操纵着部落。",
	["Guía"] = "指南",
	["Guía a tu manada"] = "带领你的狼群",
	["Guía abierta en una pestaña nueva: sigue la flecha."] = "已在新标签页中打开指南：跟着箭头走。",
	["Guía actual"] = "当前指南",
	["Guía de pesca"] = "钓鱼指南",
	["Guía para desbloquearla en marcha"] = "解锁指南进行中",
	["Guía: %s"] = "指南：%s",
	["Guíame"] = "指引我",
	["Guíame a Bahía del Botín"] = "指引我去藏宝海湾",
	["Guíame a la misión"] = "指引我去任务",
	["Guíame a la receta"] = "指引我去配方",
	["Guíame a una caña"] = "指引我去买鱼竿",
	["Guíame al pescador"] = "指引我去找渔夫",
	["Guíame aquí"] = "指引我到这里",
	["Guíame te lleva paso a paso."] = "“指引我”会一步步带你。",
	["Guías"] = "指南",
	["Guías con %s"] = "包含%s的指南",
	["Guías de la comunidad"] = "社区指南",
	["Guías y planes"] = "指南与计划",
	["HDR (Windows)"] = "HDR（Windows）",
	["Habilidades más baratas."] = "技能消耗更低。",
	["Habilidades más baratas: más golpes de amenaza."] = "技能消耗更低：能打出更多制造威胁的攻击。",
	["Habilidades nuevas por aprender: %d. Tu entrenador te espera."] = "有 %d 个新技能可以学习。你的训练师在等你。",
	["Habilidades por entrenar"] = "可学的技能",
	["Habilidades que vigila la ayuda de Blizzard"] = "暴雪战斗辅助监控的技能",
	["Habitual"] = "常见",
	["Habla con %s"] = "与%s交谈",
	["Habla con el maestro de vuelo de cada pueblo nuevo: así aprendes la ruta."] = "每到一个新城镇都和飞行管理员谈谈：这样就能学会航线。",
	["Habla con un banquero para comprarla."] = "与银行职员交谈即可购买。",
	["Hablar"] = "说话",
	["Hace heridas que sangran: vigila la vida del tanque."] = "他会造成流血伤口：注意坦克的血量。",
	["Hace lento al enemigo cuerpo a cuerpo. Después aléjate y dispara."] = "减缓近战敌人。然后拉开距离射击。",
	["Hace mil años, en la Guerra de las Arenas Movedizas, los elfos y los dragones encerraron a los qiraji tras el Muro del Escarabajo."] = "一千年前的流沙之战中，精灵和巨龙把其拉虫人封印在甲虫之墙后面。",
	["Hace más de diez mil años todas las tierras eran un solo continente: Kalimdor, que en élfico quiere decir «tierra de la eterna luz de las estrellas»."] = "一万多年前，所有的土地都是一块大陆：卡利姆多，在精灵语中意为“永恒星光之地”。",
	["Hace más lento al enemigo. Gana distancia para seguir disparando."] = "减速敌人。拉开距离继续射击。",
	["Hace más lento al enemigo. Úsala con los que huyen para que no traigan ayuda."] = "减速敌人。对逃跑的敌人使用，免得它们叫来朋友。",
	["Hace sangrar al enemigo un rato. Ponla al inicio de las peleas largas."] = "让敌人流血一段时间。长时间战斗开始时加上。",
	["Hace sangrar al enemigo: ponlo al empezar la pelea."] = "让敌人流血：战斗开始时施放。",
	["Hace sangrar mucho: vale la pena con enemigos que duran."] = "造成大量流血：对付耐打的敌人很值得。",
	["Hace siglos, Aegwynn venció a un avatar de Sargeras y escondió su cuerpo en la Tumba de Sargeras, en las Islas Abruptas."] = "几个世纪前，艾格文击败了萨格拉斯的化身，把他的躯体藏在破碎群岛的萨格拉斯之墓中。",
	["Hacen %d misiones contigo"] = "和你一起做 %d 个任务",
	["Hacen 1 misión contigo"] = "和你一起做 1 个任务",
	["Hacen falta al menos 3 lugares distintos de ese recurso en la zona."] = "该区域至少需要 3 个不同的该资源地点。",
	["Hacer mazmorras con tu grupo da botín, misiones y reputación: es farmeo con plática incluida."] = "和队伍一起打地下城能获得战利品、任务和声望：一边刷一边聊天。",
	["Hacer oro"] = "赚金币",
	["Haces daño"] = "你负责输出",
	["Haces de luz entre árboles, nubes y montañas."] = "穿过树木、云层和山脉的光束。",
	["Hacha de dos manos"] = "双手斧",
	["Hacha de una mano"] = "单手斧",
	["Hacia %s"] = "前往%s",
	["Hacia %s (niv. %s)"] = "前往%s（%s 级）",
	["Hacia abajo"] = "向下",
	["Hacia arriba"] = "向上",
	["Hacia dónde se acomodan tus compañeros."] = "队友的排列方向。",
	["Hacia:"] = "前往：",
	["Hacia: %s"] = "前往：%s",
	["Halloween de Azeroth"] = "万圣节",
	["Halloween recuerda el día en que los Renegados se liberaron del Rey Exánime: por eso queman al Hombre de Mimbre."] = "万圣节纪念被遗忘者摆脱巫妖王控制的那一天：所以他们会烧掉柳条人。",
	["Hamuul Tótem de Runa, el archidruida de Cima del Trueno, fue de los primeros tauren aceptados en el Círculo Cenarion."] = "雷霆崖的大德鲁伊哈缪·符文图腾是最早被塞纳里奥议会接纳的牛头人之一。",
	["Hasta dónde llegan las montañas lejanas."] = "远处山脉显示的距离。",
	["Hasta dónde puedes alejar la cámara con la rueda. El juego puede limitarlo: Alfa muestra el valor que de verdad quedó."] = "用滚轮能把镜头拉多远。游戏可能会限制：Alfa 显示的是实际生效的数值。",
	["Hasta dónde se dibuja el mundo. Es lo que más FPS cuesta."] = "世界的绘制距离。这项最耗 FPS。",
	["Hasta dónde se dibuja el pasto. Más lejos, menos «alfombra» que aparece al caminar."] = "草地的绘制距离。越远，走路时冒出来的“草毯”就越少。",
	["Hasta el alfa se cae. Lo importante es levantarse. ¡Vamos!"] = "就算是头狼也会倒下。重要的是重新站起来。走吧！",
	["Hasta el nivel 20 usa un arma de dos manos; luego cambia a dos armas de una mano."] = "20 级之前用双手武器；之后换成两把单手武器。",
	["Hasta mi nivel"] = "不超过我的等级",
	["Hasta qué distancia se ven las placas de nombre. El juego puede limitarlo."] = "姓名板能在多远的距离显示。游戏可能会限制。",
	["Hasta qué nivel"] = "到几级为止",
	["Hay enemigos que se convierten en lobos y otros que asustan: no corran si los asustan, esperen."] = "有些敌人会变成狼，有些会施放恐惧：被恐惧时别慌，等效果过去。",
	["Hay mucha agua: si nadas bajo el agua, mira tu barra de respiración y sube a tomar aire."] = "这里水很多：潜水时留意呼吸条，记得上浮换气。",
	["Hay muchas tribus trol: Amani, Gurubashi, Furiarena, Zandalar... y casi todas pelean entre sí."] = "巨魔部族有很多：阿曼尼、古拉巴什、沙怒、赞达拉……而且几乎彼此都在打仗。",
	["Hay muchos no-muertos y jabaespines: lleven algo para quitar enfermedades si su grupo puede."] = "亡灵和野猪人很多：如果队伍里有人能驱散疾病就准备好。",
	["Hay muchos troggs y elementales de fuego juntos: tiren de uno o dos grupos a la vez, no más."] = "穴居人和火元素挤在一起：一次只拉一两群，别多拉。",
	["Hay nueve clases en el Clásico, pero solo la Alianza tiene paladines y solo la Horda tiene chamanes."] = "经典版有九个职业，但只有联盟有圣骑士，只有部落有萨满。",
	["Hay que llevar el recado y hablar con quien te espera."] = "把口信送到，和等你的人谈谈。",
	["Hay una guía de Alfa"] = "有 Alfa 指南",
	["Haz %s: unas %d veces"] = "制作 %s：大约 %d 次",
	["Haz Pociones de sanación menores de más para este tramo."] = "这一段多做一些初级治疗药水。",
	["Haz clic derecho (o Mayús+clic) en el mapa donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras."] = "在地图上想要的位置右键点击（或 Shift+点击）：设置名称、图标和颜色，箭头随时都能带你过去。",
	["Haz clic en un atajo y pulsa la tecla que quieras; Esc cancela y el clic derecho lo quita. Se guardan fuera de combate."] = "点一个快捷键，再按下你想要的键；Esc 取消，右键清除。会在非战斗时保存。",
	["Haz clic en un marco de ejemplo"] = "点击一个示例框体",
	["Haz clic y pulsa la tecla que quieras (Esc cancela). Clic derecho la quita."] = "点击后按下你想要的按键（Esc 取消）。右键清除。",
	["Haz clic y pulsa la tecla, un botón del ratón o la rueda (con Mayús, Ctrl o Alt si quieres). Esc cancela; clic derecho la quita."] = "点击后按下按键、鼠标按键或滚轮（可以搭配 Shift、Ctrl 或 Alt）。Esc 取消；右键点击清除。",
	["Haz doble clic derecho en el mundo para lanzar la caña, sin usar la tecla. Nunca en combate ni en vuelo."] = "在游戏世界中右键双击即可抛竿，不用按键。战斗中和飞行中不会触发。",
	["Haz misiones de tu registro o caza enemigos de tu nivel (los grises no dan nada)."] = "做你日志里的任务，或猎杀和你同等级的敌人（灰色的不给经验）。",
	["Haz tu propia agua. Así no gastas oro en bebida."] = "自己造水。不用再花金币买饮料了。",
	["Haz tu propia comida para recuperar vida."] = "自己做食物来恢复生命值。",
	["Hazlo ya"] = "现在就做",
	["Hecha"] = "已完成",
	["Hecha %d veces"] = "已完成 %d 次",
	["Hechas"] = "已完成",
	["Hechizo del preajuste"] = "预设的法术",
	["Hechizo desconocido"] = "未知法术",
	["Hechizo elegido por ti"] = "你选择的法术",
	["Hechizo nuevo para tus clics de Curación. Ábrelo en /alfa curacion."] = "有新法术可用于你的治疗点击。请打开 /alfa curacion。",
	["Hechizos de sombras que hacen daño con el tiempo: el sacerdote que mejor sube en solitario, casi sin descansar."] = "造成持续伤害的暗影法术：单人升级最快的牧师，几乎不用休息。",
	["Hechizos de tu mascota"] = "你宠物的法术",
	["Hechizos desde lejos y raíces para que el monstruo no te alcance. Al final llega la forma de lechúcico."] = "远程施法加定身，让怪物碰不到你。最后会获得枭兽形态。",
	["Hecho"] = "完成",
	["Hemet Nesingwary organiza safaris por toda la Vega: sus encargos de cazar panteras, tigres y raptores son famosos."] = "赫米特·奈辛瓦里在整个荆棘谷组织狩猎之旅：他猎杀豹子、老虎和迅猛龙的委托远近闻名。",
	["Hemorragia: suma puntos de combo y el enemigo recibe más daño."] = "出血：累积连击点数，并让敌人受到更多伤害。",
	["Hender armadura más barato."] = "更便宜的破甲攻击。",
	["Hender armadura más barato: amenaza constante."] = "更便宜的破甲攻击：持续稳定的威胁。",
	["Hender armadura más barato: más amenaza a varios enemigos."] = "更便宜的破甲攻击：对多个敌人制造更多威胁。",
	["Hender armadura: amenaza constante y el enemigo recibe más daño."] = "破甲攻击：稳定的威胁，敌人受到的伤害提高。",
	["Herboristería"] = "草药学",
	["Herboristería combina bien con Alquimia, y también con Desollar o Minería para recolectar el doble."] = "草药学和炼金术很搭，也可以搭配剥皮或采矿，采集量翻倍。",
	["Herramienta"] = "工具",
	["Herramientas"] = "工具",
	["Herrería"] = "锻造",
	["Herrería fabrica armas y armadura de placas muy buenas para tu nivel, y Minería te da el material gratis."] = "锻造能打造适合你等级的优质武器和板甲，采矿则免费提供材料。",
	["Herrería fabrica escudos y piezas resistentes."] = "锻造能打造盾牌和耐用的装备。",
	["Herrería fabrica escudos y placas con defensa y aguante, justo lo que un tanque necesita."] = "锻造能打造带防御和耐力的盾牌和板甲，正是坦克需要的。",
	["Herrería y Minería van de la mano: tú sacas el metal y tú lo forjas."] = "锻造和采矿相辅相成：自己挖矿，自己锻造。",
	["Hiciste lo que pedía antes. Búscala con su «!» y tómala, o elige qué sigue."] = "你完成了它之前的要求。找到它的“!”接取，或选择接下来做什么。",
	["Hielo"] = "冰蓝",
	["Hierbas"] = "草药",
	["Historias"] = "故事",
	["Historias de las misiones"] = "任务故事",
	["Historias de tus misiones"] = "你的任务故事",
	["Historias guardadas"] = "已保存的故事",
	["Historias y datos curiosos"] = "故事与趣闻",
	["Hogger es un gnoll de Elwynn tan temido que, para muchos aventureros, fue su primer gran reto."] = "霍格是艾尔文森林里一只令人闻风丧胆的豺狼人，对许多冒险者来说，他是第一个大挑战。",
	["Hombros"] = "肩部",
	["Honor"] = "荣誉",
	["Horarios de barcos y zepelines"] = "船只和飞艇时刻表",
	["Horarios de barcos y zepelines en el mapa"] = "地图上的船只和飞艇时刻表",
	["Horda"] = "部落",
	["Hoy"] = "今天",
	["Hoy avanzaste %s niveles"] = "今天你升了 %s 级",
	["Hoy avanzaste 1 nivel"] = "今天你升了 1 级",
	["Hoy en Azeroth hay fiesta: %s. ¿Vamos a ver qué hay?"] = "今天艾泽拉斯有庆祝活动：%s。我们去看看？",
	["Hoy en números"] = "今日数据",
	["Hoy está difícil, ¿verdad? No pasa nada. Descansa un poco, repara y volvemos con más fuerza."] = "今天很难熬，对吧？没关系。休息一下，修理一下，我们会更强地回来。",
	["Hoy llevas %s"] = "今天你已有：%s",
	["Hoy te guía"] = "“今天”为你指路",
	["Hoy te pone tu siguiente paso primero, y en combate ninguna ventana de Alfa te deja atrapado."] = "“今天”页面会先显示你的下一步，而且战斗中不会再有 Alfa 窗口把你困住。",
	["Hoy todavía no avanzas: ¡a cazar!"] = "今天还没有进度：去狩猎吧！",
	["Hoy todavía no cazamos nada. ¿Salimos?"] = "今天还没狩猎呢。出发吗？",
	["Hoy, Aventura, Personaje, Mundo, Oficios y Manada en una sola ventana: %s o el lobo del minimapa."] = "今天、冒险、角色、世界、专业和狼群，尽在一个窗口：%s 或小地图上的狼。",
	["Hoy, a tu clase"] = "“今天”按职业定制",
	["Huele a pan recién hecho por aquí… se me antoja."] = "这里有刚出炉的面包香味……好想吃。",
	["Huele a salchichas asadas por aquí… ¿o es mi imaginación?"] = "这里有烤香肠的味道……还是我想多了？",
	["Huella"] = "爪印",
	["Huelo a botín... y a una que otra salchicha."] = "我闻到了战利品……还有一两根香肠。",
	["Humanos"] = "人类",
	["Humo, agua y efectos se funden con lo que tocan en lugar de cortarse en seco."] = "烟雾、水和特效会与接触的物体自然融合，而不是生硬地截断。",
	["Huracán: golpea a todos a tu alrededor."] = "旋风斩：攻击你周围的所有敌人。",
	["Háblame de mi gente"] = "跟我讲讲我的族人",
	["Iconos de viaje en el minimapa"] = "小地图上的旅行图标",
	["Idioma"] = "语言",
	["Igual que Alfa"] = "与 Alfa 相同",
	["Igual que lo tuyo"] = "与你的相同",
	["Igual que los otros señores: lanza rayos y se cura. Interrumpe su curación."] = "和其他尖牙领主一样：会施放闪电并治疗自己。打断他的治疗。",
	["Illidan absorbió el poder del Cráneo de Gul'dan y se volvió mitad demonio. Por eso Malfurion lo desterró."] = "伊利丹吸收了古尔丹之颅的力量，变成了半个恶魔。所以玛法里奥放逐了他。",
	["Illidan guardó agua del Pozo antes de su caída y creó uno nuevo en Hyjal. Por eso Malfurion lo encerró bajo tierra durante diez mil años."] = "永恒之井毁灭之前，伊利丹偷偷留下了井水，在海加尔山造了一口新的。所以玛法里奥把他囚禁在地底一万年。",
	["Illidan se fue a Terrallende, lo que quedó de Draenor, y ahí se hizo de un ejército propio."] = "伊利丹去了德拉诺的残余——外域，在那里建立了自己的军队。",
	["Illidan, el gemelo de Malfurion, amaba a Tyrande, pero ella eligió a su hermano. Esa herida lo acompañó por diez mil años."] = "玛法里奥的孪生兄弟伊利丹爱着泰兰德，但她选择了他的哥哥。这道伤痕伴随了他一万年。",
	["Imagen HDR"] = "HDR 输出",
	["Importa una cadena de escala de estadísticas y usa, renombra, exporta o borra las escalas que tienes."] = "导入属性权重字符串，并使用、重命名、导出或删除已有的权重。",
	["Importado"] = "已导入",
	["Importado: %s. Ya puedes seguirlo."] = "已导入：%s。现在就可以跟随它了。",
	["Importar"] = "导入",
	["Importar ajustes"] = "导入设置",
	["Importar un build"] = "导入方案",
	["Importar una ruta"] = "导入路线",
	["Importar..."] = "导入...",
	["Incapacita al enemigo un momento. Úsalo para ponerte a su espalda."] = "让敌人短暂失去行动能力。趁机绕到它背后。",
	["Inclina la cámara al subir y bajar cuestas."] = "上下坡时镜头随之倾斜。",
	["Ingeniería"] = "工程学",
	["Ingeniería da aturdimientos y trucos que ganan duelos; Minería da el material."] = "工程学提供击晕和各种小道具，帮你赢下决斗；采矿提供材料。",
	["Ingeniería da granadas y redes para controlar al rival; Minería da el material."] = "工程学提供手雷和网来控制对手；采矿提供材料。",
	["Ingeniería da granadas, redes y bombas que deciden peleas contra jugadores; Minería da el material."] = "工程学提供手雷、网和炸弹，能左右 PvP 战斗的胜负；采矿提供材料。",
	["Ingeniería te salva con trucos de escape; Sastrería hace tu ropa."] = "工程学的逃生道具能救你一命；裁缝负责做你的衣服。",
	["Inicio"] = "主页",
	["Inicio de Alfa"] = "Alfa 主页",
	["Inicio del horizonte"] = "地平线起点",
	["Insignias de La Jauría: los Alfas y los miembros llevan su lobo en el cuadro, en La Jauría y en el mapa; y quienes comparten se ven con una huella."] = "La Jauría 徽章：阿尔法和成员会在鼠标提示、La Jauría 和地图上带着他们的狼；分享位置的人会显示为爪印。",
	["Instantánea: úsala cada vez que esté lista."] = "瞬发：冷却好就用。",
	["Instructor"] = "训练师",
	["Instructor de %s"] = "%s训练师",
	["Instructor de Herboristería"] = "草药学训练师",
	["Instructor de Minería"] = "采矿训练师",
	["Instructor de equitación"] = "骑术训练师",
	["Instructor de pesca"] = "钓鱼训练师",
	["Instructores"] = "训练师",
	["Instructores de %s"] = "%s训练师",
	["Instructores de pesca"] = "钓鱼训练师",
	["Instructores y vendedores"] = "训练师与商人",
	["Intelecto"] = "智力",
	["Intelecto Arcano"] = "奥术智慧",
	["Intentar ahora"] = "立即重试",
	["Intentar otra vez"] = "重试",
	["Interceptar más seguido: el rival no se escapa."] = "更频繁地拦截：对手跑不掉。",
	["Interfaz"] = "界面",
	["Interfaz del juego"] = "游戏界面",
	["Interrumpe un hechizo con tu escudo. Úsalo con magos y curanderos enemigos."] = "用盾牌打断一个法术。对敌方施法者和治疗者使用。",
	["Interrumpe un hechizo y bloquea esa magia un rato."] = "打断一个法术，并在一段时间内封锁该系法术。",
	["Interrumpe un hechizo. Guárdalo para cuando el enemigo lance algo peligroso."] = "打断一个法术。留到敌人施放危险法术时用。",
	["Interrumpe un hechizo. Úsalo con magos y curanderos enemigos."] = "打断一个法术。对敌方施法者和治疗者使用。",
	["Interrumpes hechizos y los silencias."] = "打断法术并使其沉默。",
	["Interrumpes y silencias hechizos."] = "打断并沉默法术。",
	["Intimidación: tu mascota aturde al enemigo."] = "胁迫：你的宠物击晕敌人。",
	["Invita a tu clan con un clic, y arreglos"] = "一键邀请加入你的公会，以及修复",
	["Invitaciones a hermandades"] = "公会邀请",
	["Invitaciones de grupo de desconocidos"] = "陌生人的组队邀请",
	["Invitación a %s para %s enviada. Si no puede unirse, el juego te dirá por qué."] = "已发送加入%s的邀请给%s。如果对方无法加入，游戏会告诉你原因。",
	["Invitar"] = "邀请",
	["Invitar a %s"] = "邀请加入%s",
	["Invitar a una comunidad sin bloqueos"] = "邀请加入社区不再被阻止",
	["Invitar al clan"] = "邀请加入公会或社区",
	["Invitar al grupo"] = "邀请入队",
	["Invitar, comerciar, susurrar…"] = "邀请、交易、密语…",
	["Invitarlos"] = "邀请他们",
	["Invitaste a %s a tu grupo."] = "你邀请了%s加入队伍。",
	["Invoca un espíritu de jabalí: mátenlo o que alguien lo tanquee."] = "他会召唤野猪之灵：击杀它，或让人把它坦住。",
	["Invócalo antes de pelear."] = "战斗前先召唤它。",
	["Ir"] = "前往",
	["Ir a la zona recomendada"] = "前往推荐区域",
	["Ir a reparar"] = "去修理",
	["Ir a un lugar"] = "前往某个地点",
	["Ir a: %s"] = "前往：%s",
	["Ir al mapa del juego"] = "前往游戏地图",
	["Ir al resumen"] = "前往总结",
	["Ir de caza"] = "去狩猎",
	["Ir por el camino es más seguro que cortar por en medio: los caminos tienen menos enemigos."] = "走大路比抄近路安全：路上的敌人比较少。",
	["Ir por él"] = "去拿",
	["Ira al romper un miedo: los rivales te asustan mucho."] = "解除恐惧时获得怒气：对手经常恐惧你。",
	["Ira aunque el rival huya o te frene."] = "即使对手逃跑或减速你，也能获得怒气。",
	["Ira constante en peleas largas contra jefes."] = "长时间的首领战中怒气源源不断。",
	["Ira constante."] = "怒气源源不断。",
	["Ira constante: nunca te quedas sin poder usar habilidades."] = "怒气源源不断：永远不会没技能可用。",
	["Ira gratis cada pocos segundos, aunque nadie te pegue."] = "每隔几秒免费获得怒气，即使没人打你。",
	["Izquierdo"] = "左键",
	["Jaina Valiente fue alumna de Antonidas antes de fundar Theramore."] = "吉安娜·普罗德摩尔在建立塞拉摩之前是安东尼达斯的学生。",
	["JcJ"] = "PvP",
	["JcJ (12): rangos de honor 3, 7, 10, 13 y 14; exaltado con las 4 facciones de los campos de batalla; las semanas 4, 7 y 10 del viaje de temporada Campo de Honor."] = "PvP（12）：荣誉军衔 3、7、10、13 和 14；4 个战场阵营达到崇拜；荣誉之地赛季旅程的第 4、7 和 10 周。",
	["Jefe"] = "首领",
	["Jefe %d por descubrir"] = "首领 %d（待发现）",
	["Jefe final"] = "最终首领",
	["Jefes"] = "首领",
	["Jefes vencidos"] = "已击败的首领",
	["Jefes vencidos, mazmorras hechas y botín anotado de este personaje. No toca tus ajustes."] = "此角色已击败的首领、已完成的地下城和记录的战利品。不会影响你的设置。",
	["Jefes, botín y la entrada de cada mazmorra y banda."] = "每个地下城和团队副本的首领、战利品和入口。",
	["Juega con cada personaje una vez y Alfa recordará sus bolsas y su banco."] = "每个角色玩一次，Alfa 就会记住它的背包和银行。",
	["Juega siempre en actitud defensiva con escudo."] = "始终在防御姿态下持盾作战。",
	["Juega un rato y Alfa calcula cuánto te falta a tu ritmo."] = "玩一会儿，Alfa 就会按你的节奏算出还剩多少。",
	["Jueves"] = "星期四",
	["Jugo de baya lunar"] = "月莓汁",
	["Jugo de melón"] = "甜瓜汁",
	["Juguetes y consumibles de pesca"] = "钓鱼玩具与消耗品",
	["Junta %d de %s"] = "收集 %d 个%s",
	["Junta 100 capturas."] = "累计 100 次渔获。",
	["Junta 1000 capturas."] = "累计 1000 次渔获。",
	["Junta 500 capturas."] = "累计 500 次渔获。",
	["Junta a la manada para salir de caza"] = "召集狼群去狩猎",
	["Junta dos monstruos y usa Golpes de barrido: así subes más rápido."] = "拉两个怪物，使用横扫攻击：这样升级更快。",
	["Junta dos o tres monstruos, usa Atronar y Revancha: subes seguro y sin descansar."] = "拉两三个怪物，使用雷霆一击和复仇：升级稳当，还不用休息。",
	["Junta lo gris y lo blanco para vender: suma más de lo que parece."] = "把灰色和白色物品攒起来卖：加起来比你想的还多。",
	["Junta los montones y acomoda tus objetos con un clic."] = "一键堆叠并整理你的物品。",
	["Junta los montones y acomoda tus objetos. No funciona en combate."] = "堆叠并整理你的物品。战斗中无法使用。",
	["Junta materiales de tu profesión donde más hay."] = "到资源最多的地方收集你的专业材料。",
	["Junta materiales de tu profesión, con unas misiones de XP en medio."] = "收集你的专业材料，中间穿插几个经验任务。",
	["Junta misiones de la misma zona: haces varias en un solo viaje."] = "把同一区域的任务凑在一起：一趟就能做好几个。",
	["Junta varios monstruos: tus golpes sagrados alcanzan a todos."] = "拉多个怪物：你的神圣攻击能打到所有怪。",
	["Juntando todo lo del juego. Es solo la primera vez que la abres."] = "正在汇总游戏中的所有内容。只有第一次打开时需要。",
	["Juntar %s"] = "攒够%s",
	["Juntar los materiales de mi profesión"] = "收集我专业所需的材料",
	["Juntar materiales para vender"] = "收集材料出售",
	["Juntar nodos cercanos al alejar"] = "缩小时合并相近的采集点",
	["Juntar oro"] = "攒金币",
	["Junto a la lupa del mapa del juego: las capas, el modo limpio y «Mapa de Alfa» para cambiar al de Alfa."] = "在游戏地图的放大镜旁边：图层、简洁模式，以及切换到 Alfa 地图的“Alfa 地图”按钮。",
	["Junto a tu guía hay un botón para buscar lo que tienes cerca: vuelo, banco, subasta, reparar, comerciantes y entrenadores."] = "你的指南旁边有一个按钮，可以搜索附近的东西：飞行点、银行、拍卖行、修理、商人和训练师。",
	["Junto al botón, el nombre del objeto y cuánto llevas; una huella late cuando ya lo puedes usar."] = "按钮旁显示物品名称和你的进度；可以使用时会有一个爪印闪动。",
	["Junto al título de cada página. Tócalo y te explico esa página con sus preguntas."] = "在每页标题旁边。点一下，我就带着问题给你讲解这一页。",
	["Kael'thas fue miembro del Kirin Tor de Dalaran antes de guiar a los elfos de sangre."] = "凯尔萨斯在领导血精灵之前，是达拉然肯瑞托的成员。",
	["Karazhan, la torre de Medivh, el último Guardián, se levanta sobre un cruce de líneas de magia natural."] = "卡拉赞是最后的守护者麦迪文的高塔，矗立在天然魔力线的交汇处。",
	["Kargath, el campamento de la Horda, lleva el nombre de un viejo caudillo orco del clan Mano Destrozada."] = "部落营地卡加斯以碎手氏族一位老兽人酋长的名字命名。",
	["Kel'Thuzad era un archimago de Dalaran. Lo expulsaron por estudiar nigromancia y acabó al servicio del Rey Exánime."] = "克尔苏加德曾是达拉然的大法师。他因研究死灵法术被驱逐，最终投靠了巫妖王。",
	["Kel'Thuzad tiene un gato, el señor Bigglesworth, que lo acompaña en Naxxramas. ¡Ni se te ocurra hacerle daño!"] = "克尔苏加德有一只猫，叫比格沃斯先生，在纳克萨玛斯陪着他。你可千万别伤害它！",
	["Khadgar fue el aprendiz de Medivh. Al pelear contra su maestro poseído envejeció de golpe y se quedó con el pelo blanco."] = "卡德加是麦迪文的学徒。与被附身的导师战斗时，他一下子变老了，头发也全白了。",
	["Khaz Modan es la tierra de los enanos, desde las nieves de Dun Morogh hasta los valles de Loch Modan."] = "卡兹莫丹是矮人的土地，从丹莫罗的冰雪一直到洛克莫丹的山谷。",
	["Kil'jaeden encerró el alma de Ner'zhul en un bloque de hielo y lo arrojó a Rasganorte: así nació el Rey Exánime."] = "基尔加丹把耐奥祖的灵魂封进一块冰里，扔到了诺森德：巫妖王就是这样诞生的。",
	["Kil'jaeden engañó a Ner'zhul, el chamán más sabio de Draenor, y su aprendiz Gul'dan terminó de entregar a los orcos a la Legión."] = "基尔加丹欺骗了德拉诺最睿智的萨满耐奥祖，而他的学徒古尔丹则彻底把兽人交给了燃烧军团。",
	["Korialstrasz, el consorte de Alexstrasza, anduvo entre los mortales como Krasus, un mago del consejo de Dalaran."] = "阿莱克丝塔萨的配偶克拉苏斯曾化身为达拉然议会的法师，行走于凡人之间。",
	["Kul Tiras es un reino isleño de marineros. Su gran almirante, Daelin Valiente, era el padre de Jaina."] = "库尔提拉斯是一个水手的岛国。它的大将军戴林·普罗德摩尔是吉安娜的父亲。",
	["La %s también está en el menú del juego."] = "%s也在游戏菜单中。",
	["La Abadía de Villanorte es de las más antiguas del reino; ahí empiezan su camino muchos aventureros humanos."] = "北郡修道院是王国中最古老的修道院之一；许多人类冒险者都从这里启程。",
	["La Alianza nació en la Segunda Guerra, cuando los reinos humanos, los enanos y los altos elfos se unieron contra la Horda."] = "联盟诞生于第二次战争，当时人类诸王国、矮人和高等精灵联合起来对抗部落。",
	["La B, Mayús+B, la tecla de cada bolsa y los comerciantes abren la ventana de Alfa. Apágalo para volver a las del juego."] = "按 B、Shift+B、各背包的按键或与商人交谈时会打开 Alfa 窗口。关闭此项即可恢复游戏背包。",
	["La Capilla de la Esperanza de la Luz resistió a la Plaga en una batalla legendaria; hoy es el gran refugio del Alba Argenta."] = "圣光之愿礼拜堂在一场传奇战役中抵挡住了天灾军团；如今它是银色黎明的重要据点。",
	["La Catedral de la Luz es el corazón de la fe en Ventormenta; sus sacerdotes atienden a toda la Alianza."] = "光明大教堂是暴风城的信仰核心；那里的牧师为整个联盟服务。",
	["La Cresta de la Llama es el puesto de la Horda en las estepas, en lo alto de las rocas."] = "烈焰峰是部落在平原上的据点，位于高高的岩石上。",
	["La Cruzada Escarlata nació del dolor de Lordaeron tras la plaga, pero su odio la volvió tan cruel como lo que combate."] = "血色十字军诞生于洛丹伦遭受瘟疫后的伤痛，但仇恨让它变得和它所对抗的东西一样残忍。",
	["La Cruzada Escarlata tiene aquí su monasterio. Para ellos todo no-muerto debe arder, también los Renegados."] = "血色十字军的修道院就在这里。在他们看来，所有亡灵都该被烧掉，被遗忘者也不例外。",
	["La Cuenca de Arathi, el campo de batalla, está en estas tierras: se pelea por la granja, la mina, el aserradero, los establos y la herrería."] = "战场阿拉希盆地就在这片土地上：争夺的是农场、矿洞、伐木场、兽栏和铁匠铺。",
	["La Feria de la Luna Negra tiene su propia reputación, y se sube con sus vales y sus encargos."] = "暗月马戏团有自己的声望，可以用奖券和委托来提升。",
	["La Fortaleza de Grommash, en Orgrimmar, lleva el nombre de Grom Grito Infernal, el héroe que liberó a los orcos de la sangre demoníaca."] = "奥格瑞玛的格罗玛什要塞以格罗姆·地狱咆哮命名，正是这位英雄让兽人摆脱了恶魔之血。",
	["La Fuente del Sol, el corazón de Quel'Thalas, nació de un frasco de agua del Pozo de la Eternidad que los altos elfos se llevaron."] = "奎尔萨拉斯的核心太阳之井，源自高等精灵带走的一瓶永恒之井之水。",
	["La Garganta de Fuego quedó así por culpa del Hierro Negro: su hechicero-thane Thaurissan invocó a Ragnaros y la tierra se incendió."] = "灼热峡谷变成这样都是黑铁矮人的错：他们的术士领主索瑞森召唤了拉格纳罗斯，大地因此燃烧起来。",
	["La Gran Forja nunca se apaga: es el corazón de Forjaz y el orgullo de tu gente."] = "大锻炉从未熄灭：它是铁炉堡的核心，也是你族人的骄傲。",
	["La Gran Forja, en el corazón de Forjaz, nunca se apaga."] = "铁炉堡中心的大锻炉从未熄灭。",
	["La Guardia Nocturna es la milicia de Villa Oscura: protege el pueblo de lobos, no-muertos y worgen."] = "守夜人是夜色镇的民兵：保护城镇免受狼、亡灵和狼人的侵扰。",
	["La Guerra de los Ancestros fue la primera invasión de la Legión Ardiente a Azeroth, hace unos diez mil años."] = "上古之战是燃烧军团对艾泽拉斯的第一次入侵，大约发生在一万年前。",
	["La Hermandad del Torio son enanos Hierro Negro que se separaron de su clan. Son maestros herreros y negocian con quien los respete."] = "瑟银兄弟会是脱离了自己氏族的黑铁矮人。他们是锻造大师，愿意和任何尊重他们的人做生意。",
	["La Hermandad del Torio, en La Garganta de Fuego, enseña planos que muchos herreros sueñan."] = "灼热峡谷的瑟银兄弟会传授许多铁匠梦寐以求的设计图。",
	["La Horda arrasó Ventormenta en la Primera Guerra. Los albañiles que la reconstruyeron no recibieron su pago, y de ese enojo nació la Hermandad Defias."] = "第一次战争中部落摧毁了暴风城。重建它的石匠们没有拿到工钱，迪菲亚兄弟会就是从这股怒火中诞生的。",
	["La Horda tiene su propio pueblo al norte del marjal, para vigilar Theramore de cerca."] = "部落在沼泽北边有自己的村子，就近监视塞拉摩。",
	["La Horda tiene una aldea en la costa de Desolace, y la Alianza un campamento en las montañas del norte."] = "部落在凄凉之地的海岸有一座村庄，联盟则在北部山区有一座营地。",
	["La Jauría"] = "La Jauría",
	["La Jauría en Discord"] = "La Jauría 的 Discord",
	["La Jauría en el mapa"] = "地图上的 La Jauría",
	["La Jauría está de fiesta"] = "La Jauría 在庆祝",
	["La Jauría más cuidadosa y Alfa más ligero: el mapa del grupo, los barcos y tus bolsas trabajan menos."] = "更谨慎的 La Jauría，更轻巧的 Alfa：队伍地图、船只和背包都更省力。",
	["La Jauría nocturno"] = "La Jauría 夜色",
	["La Jauría: estado"] = "La Jauría：状态",
	["La Jauría: tu manada en el mapa, Seguir y el clan (/alfa manada ayuda)"] = "La Jauría：地图上的狼群、跟随和公会（/alfa manada ayuda）",
	["La Jauría: tus comandos"] = "La Jauría：你的命令",
	["La Legión Ardiente es el ejército de demonios de Sargeras, un titán caído que quiere quemar toda la creación."] = "燃烧军团是萨格拉斯的恶魔大军，他是一位堕落的泰坦，想要焚尽一切造物。",
	["La Liga de Arathor y los Rapiñadores se pelean la Cuenca de Arathi; las Centinelas Ala de Plata y la Escolta Grito de Guerra, la Garganta Grito de Guerra."] = "阿拉索联军和污染者争夺阿拉希盆地；银翼哨兵和战歌侦察骑兵争夺战歌峡谷。",
	["La Liga de Expedicionarios, los arqueólogos de Forjaz, busca por todo el mundo las ruinas que cuenten el origen de los enanos."] = "探险者协会是铁炉堡的考古学家，他们走遍世界，寻找能揭示矮人起源的遗迹。",
	["La Luz para los humanos y enanos, Elune para los elfos de la noche y las sombras para muchos Renegados: cada sacerdote sirve a algo distinto."] = "人类和矮人信奉圣光，暗夜精灵信奉艾露恩，许多被遗忘者则追随暗影：每位牧师侍奉的东西各不相同。",
	["La Lya de %s dice algo. Yo le contesto: «%s»"] = "%s 的莉娅说了些什么。我回答她：“%s”",
	["La Mano de Plata la fundó el arzobispo Alonsus Faol, y Uther fue su primer paladín."] = "白银之手由大主教阿隆索斯·法奥创立，乌瑟尔是它的第一位圣骑士。",
	["La Mano de Plata, la orden de paladines, la fundó el arzobispo Alonsus Faol, y Uther fue el primero de sus caballeros."] = "圣骑士骑士团白银之手由大主教阿隆索斯·法奥创立，乌瑟尔是其中第一位骑士。",
	["La Masacre fue Eldre'Thalas, una ciudad de los elfos Altonato de antes de la Gran División."] = "厄运之槌曾是埃德雷斯拉斯，一座大分裂之前上层精灵的城市。",
	["La Milicia Popular de la Colina del Centinela la formaron los propios granjeros cuando Ventormenta dejó de mandar soldados."] = "哨兵岭的人民军是暴风城不再派兵后，由农民们自己组建的。",
	["La Montaña Roca Negra se alza entre esta garganta y las Estepas Ardientes. Dentro viven los Hierro Negro, Ragnaros y los dragones negros."] = "黑石山耸立在这座峡谷和燃烧平原之间。里面住着黑铁矮人、拉格纳罗斯和黑龙。",
	["La Muralla de Thoradin separa Arathi de las Laderas de Trabalomas; lleva el nombre del rey que unió a los humanos."] = "索拉丁之墙把阿拉希与希尔斯布莱德丘陵隔开；它以统一人类的那位国王命名。",
	["La Orden de Tirisfal, los magos secretos que elegían al Guardián de Azeroth, tomó su nombre de estos claros. Medivh fue el último Guardián."] = "提瑞斯法议会是负责选出艾泽拉斯守护者的秘密法师组织，它的名字就来自这片林地。麦迪文是最后一位守护者。",
	["La Plaga es el ejército no-muerto del Rey Exánime. Kel'Thuzad la extendió por Lordaeron con grano infectado."] = "天灾军团是巫妖王的亡灵大军。克尔苏加德用染疫的谷物把它散播到整个洛丹伦。",
	["La Polimorfia convierte al enemigo en oveja. Yo me portaría muy bien con esa oveja, palabra de loba."] = "变形术会把敌人变成绵羊。我会对那只羊非常友善的，狼的承诺。",
	["La Segadora de arcanita es una de las armas más famosas que puede forjar un herrero."] = "奥金斧是铁匠能锻造的最有名的武器之一。",
	["La Sima Ígnea está bajo Orgrimmar: ahí se esconden brujos de un culto junto con troggs."] = "怒焰裂谷位于奥格瑞玛地下：一个邪教的术士和穴居人一起躲在那里。",
	["La Sociedad Real de Boticarios trabaja en Entrañas en una plaga nueva. Mejor no preguntes para quién."] = "皇家药剂师协会正在幽暗城研制一种新的瘟疫。最好别问是给谁用的。",
	["La Sociedad Real de Boticarios trabaja en secreto en una plaga nueva... y no precisamente para los humanos solamente."] = "皇家药剂师协会正秘密研制一种新的瘟疫……而且目标恐怕不只是人类。",
	["La Tercera Guerra empezó con la plaga del grano en Lordaeron y terminó en Hyjal con la caída de Archimonde."] = "第三次战争始于洛丹伦的谷物瘟疫，终于海加尔山上阿克蒙德的陨落。",
	["La Torre de Azora, en el este de Elwynn, es la casa de Theocritus, un mago al servicio del reino."] = "艾尔文森林东部的阿祖拉之塔是塞欧克瑞图斯的家，他是一位为王国效力的法师。",
	["La aldea Sen'jin, en la costa de Durotar, lleva el nombre del líder que dio su vida por su pueblo."] = "杜隆塔尔海岸的森金村以那位为族人献出生命的首领命名。",
	["La ayuda de rotación está apagada"] = "输出循环助手已关闭",
	["La barra con el nombre de la zona y la hora toma los colores y la letra del estilo. Los botones de rastreo, calendario y correo quedan como siempre."] = "显示区域名称和时间的栏会使用该风格的颜色和字体。追踪、日历和邮件按钮保持原样。",
	["La barra de acción, las barras extra, la de experiencia, el menú y las bolsas toman el estilo que elijas. Solo cambia su aspecto, fuera de combate; al apagarlo vuelven las del juego."] = "动作条、额外动作条、经验条、菜单和背包会使用你选择的风格。只在非战斗中改变外观；关闭后恢复游戏原本的样子。",
	["La barra de pesca"] = "钓鱼条",
	["La barra de tu vuelo con sus paradas sale siempre al despegar."] = "起飞时总会显示带有中途站的飞行条。",
	["La barra de vida con el color de la clase de cada uno. Apagado: barra verde y el nombre con su color."] = "生命条使用各自的职业颜色。关闭时：生命条为绿色，名字使用职业颜色。",
	["La base incluida trae %s lugares en %d zonas. Tú descubriste %s."] = "内置数据库收录了 %s 个地点，分布在 %d 个区域。你发现了 %s 个。",
	["La bienvenida con las novedades de esta versión."] = "包含此版本新内容的欢迎页面。",
	["La bienvenida ocupa toda la pantalla, con el juego oscurecido detrás."] = "欢迎设置占满整个屏幕，游戏画面在后方变暗。",
	["La básica la venden los instructores y los vendedores de suministros de pesca."] = "基础款由训练师和钓鱼用品商人出售。",
	["La búsqueda de lugares cercanos no está disponible."] = "附近地点搜索不可用。",
	["La cadena completa"] = "完整任务链",
	["La cadena de los Defias te lleva de Villadorada a los Páramos de Poniente y termina en las Minas de la Muerte, frente a VanCleef."] = "迪菲亚任务链会带你从闪金镇到西部荒野，最后在死亡矿井与范克里夫正面交锋。",
	["La cadena no trae talentos válidos."] = "字符串中没有有效的天赋。",
	["La caja donde escribes toma el estilo, con el borde de acento mientras escribes. En Clásico WoW queda la del juego."] = "输入框会使用该风格，输入时显示强调色边框。在经典 WoW 中保留游戏原本的输入框。",
	["La cambiaste fuera de Alfa (menú del juego o consola)."] = "你在 Alfa 之外更改了它（游戏菜单或控制台）。",
	["La capa de escamas de Onyxia protege del aliento de Nefarian, y en su banda la piden todos."] = "奥妮克希亚鳞片披风能抵挡奈法利安的龙息，在他的团队副本里人人都需要。",
	["La cerveza es casi sagrada para tu gente: en Kharanos está la destilería Cebatruenos."] = "啤酒对你的族人来说几乎是神圣的：雷酒酿酒厂就在卡拉诺斯。",
	["La cola está vacía."] = "队列是空的。",
	["La configuración es más visual: tres tarjetas para decidir cuánto te ayuda Alfa y tus extras en un mosaico."] = "设置更直观了：用三张卡片决定 Alfa 帮多少，额外功能用拼图选。",
	["La cura de ese clic pasa al botón central."] = "该点击的治疗会移到中键。",
	["La cámara no salta hacia ti por cada árbol o poste entre ella y tu personaje."] = "镜头不会因为你和角色之间的每棵树或每根柱子而猛然拉近。",
	["La cámara se mece un poco con tus pasos."] = "镜头会随你的步伐轻微晃动。",
	["La cámara se queda sobre el agua en lugar de meterse."] = "镜头停留在水面上，而不会进入水下。",
	["La cámara te sigue"] = "镜头跟随你",
	["La de ahora pasa a tus sesiones anteriores."] = "当前这次会移到你以前的记录中。",
	["La de ahora pasa a tus sesiones anteriores. Tu diario y tus logros no cambian."] = "当前这次会移到你以前的记录中。你的图鉴和成就不会改变。",
	["La de tu clase mientras subes: cambia sola cuando pongas talentos."] = "升级时使用你职业的优先级：分配天赋后会自动切换。",
	["La de tu nivel. Antes, revisa que lleves todo."] = "适合你等级的。先确认东西都带齐了。",
	["La derecha"] = "向右",
	["La dirección del texto sobre tu personaje."] = "你角色上方文字的方向。",
	["La empieza un objeto"] = "由物品开始",
	["La enciclopedia de La Jauría"] = "La Jauría 百科",
	["La enciclopedia no puede abrir todavía"] = "百科暂时无法打开",
	["La entrada de %s"] = "%s的入口",
	["La entrada de cada mazmorra en el minimapa, en verde las que ya hiciste. El mapa del mundo ya las marca con «Entradas de mazmorras»."] = "在小地图上显示每个地下城的入口，已完成的显示为绿色。世界地图已通过“地下城入口”标出它们。",
	["La familia Barov le entregó su castillo de Caer Darrow al Culto a cambio de vida eterna. Así nació Scholomance, y así les fue."] = "巴罗夫家族为了永生，把凯尔达隆的城堡交给了诅咒神教。通灵学院就这样诞生了，他们的下场你也看到了。",
	["La flecha"] = "箭头",
	["La flecha con el estilo de La Jauría, y «¿Cuánto tiempo tienes?» arma tu plan paso a paso."] = "La Jauría 风格的箭头，“你有多少时间？”一步步帮你制定计划。",
	["La flecha no está disponible ahora."] = "箭头目前不可用。",
	["La flecha que te guía"] = "为你指路的箭头",
	["La flecha se mueve con su rastro y se detiene al llegar."] = "箭头会随着对方的踪迹移动，到达后停止。",
	["La flecha sigue caminos por el suelo alrededor de acantilados, agua y muros, con los mapas para caminar de Alfa. Apagado: apunta directo a cada parada."] = "箭头会沿地面道路绕开悬崖、水域和墙壁，基于 Alfa 的步行地图。关闭：直接指向每个站点。",
	["La flecha te lleva a %s."] = "箭头会带你去%s。",
	["La flecha te lleva a este paso, no al de ahora."] = "箭头会带你去这一步，而不是当前步骤。",
	["La flecha te lleva a su entrada."] = "箭头会带你去它的入口。",
	["La flecha te lleva al primer paso. En Hoy ves cuánto llevas y «Siguiente» pasa al que sigue."] = "箭头会带你去第一步。“今天”会显示你的进度，“下一步”继续前进。",
	["La flecha te lleva aquí."] = "箭头会带你到这里。",
	["La flecha te lleva de un lugar al siguiente."] = "箭头会带你从一个地点到下一个地点。",
	["La flecha tomó otro destino: dejaste de seguir a %s."] = "箭头换了目的地：你已停止跟随%s。",
	["La flecha usa vuelos y tu piedra de hogar cuando conviene."] = "箭头会在划算时使用飞行和炉石。",
	["La flecha y el camino"] = "箭头与路线",
	["La flecha ya no sigue tu ruta de farmeo."] = "箭头不再跟随你的采集路线。",
	["La fuerza se cambia en la ventana, en Filtros."] = "强度在窗口的“滤镜”中调整。",
	["La gran cacería"] = "大狩猎",
	["La guarida de Onyxia está en este marjal. Onyxia, hija de Alamuerte, se hace pasar por una noble humana en Ventormenta."] = "奥妮克希亚的巢穴就在这片沼泽里。死亡之翼的女儿奥妮克希亚在暴风城假扮成一位人类贵妇。",
	["La guarida se queda contigo aunque salgas."] = "就算退出，巢穴也会留在你身边。",
	["La guía de Pesca te dice a qué agua ir según tu nivel de pesca, y la flecha te lleva."] = "钓鱼指南会按你的钓鱼技能告诉你去哪片水域，箭头带你过去。",
	["La guía en el minimapa"] = "小地图上的指南",
	["La guía que mejor te queda por tu nivel y donde estás."] = "按你的等级和所在位置最适合你的指南。",
	["La guía que sigues, tu paso de ahora y todo lo de las guías a un clic."] = "你正在跟随的指南、当前步骤，以及一键可达的所有指南功能。",
	["La guía te lleva a entrenar en %d pasos."] = "指南会在 %d 步后带你去训练。",
	["La guía te lleva a quien recibe cada una."] = "指南会带你去找每个任务的交付人。",
	["La haces de paso: abre %s."] = "顺路完成：它会开启%s。",
	["La haré"] = "我会做",
	["La historia"] = "故事",
	["La historia de Alfa"] = "Alfa 的故事",
	["La historia de Alfa y de La Jauría, el Discord, los comandos y los créditos."] = "Alfa 和 La Jauría 的故事、Discord、命令和致谢。",
	["La historia se guarda cuando el juego te muestra la misión."] = "游戏向你显示任务时，故事就会被保存。",
	["La hora, la fiesta y el lugar"] = "时间、节日和地点",
	["La lengua de la Alianza es el común y la de la Horda, el orco. Por eso lo que le dices al otro bando le llega como palabras raras."] = "联盟说通用语，部落说兽人语。所以你对另一个阵营说的话，他们听来就是一串怪词。",
	["La letra del aspecto (Inter en el de Alfa, Fira Sans en Halo, la del juego en los demás) o la que elijas."] = "皮肤的字体（Alfa 皮肤用 Inter，光环用 Fira Sans，其他皮肤用游戏字体），或你选择的字体。",
	["La lista está apagada: enciende «Tu lista de sonidos» en Comodidades (/alfa comodidades)."] = "名单未开启：请在便利功能（/alfa comodidades）中开启“你的声音名单”。",
	["La lista por nivel y tu progreso."] = "按等级排列的列表和你的进度。",
	["La llegada de la flecha, nueva; circuito de la zona y «Llévame a…» con vuelos y barcos."] = "全新的箭头抵达效果；区域环线，以及包含飞行、船只的“带我去……”。",
	["La llevan: %s"] = "接了这个任务的：%s",
	["La luna ya va bajando. Si cabeceas, descansa en una posada y ganas experiencia de descanso."] = "月亮要落下了。如果你在打瞌睡，就去旅店休息，攒点休息经验。",
	["La lupa de la cabecera del rastreador abre el menú. También: /alfa cerca o tu tecla."] = "点击追踪器标题栏的放大镜可打开菜单。也可以用 /alfa cerca 或你的按键。",
	["La línea de tiempo de Blizzard dice qué ataque viene y cuándo, y los mensajes grandes, lo peligroso. Alfa no inventa avisos: los prendes y ajustas en Ajustes."] = "暴雪的时间轴会显示接下来是什么攻击、何时到来，醒目提示会告诉你危险所在。Alfa 不会自创警报：你可以在设置中开启和调整。",
	["La línea de tu personaje ya no se corta: si no cabe, quita partes y nunca tu nombre ni tu nivel."] = "你的角色信息行不再被截断：放不下时会省略部分内容，但绝不会省略你的名字和等级。",
	["La línea del camino también en el minimapa."] = "在小地图上也显示路线。",
	["La manada a la vista"] = "视野中的狼群",
	["La manada afinada"] = "默契的狼群",
	["La manada aúlla contigo."] = "狼群与你一起嚎叫。",
	["La manada aúlla por ti."] = "狼群为你嚎叫。",
	["La manada caza junta"] = "狼群一起狩猎",
	["La manada crece"] = "狼群在壮大",
	["La manada desembarca en %s"] = "狼群将在%s后上岸",
	["La manada en calma"] = "平静的狼群",
	["La manada en el mapa, cazar juntos, el saludo al entrar y la calavera para el raro con un clic."] = "地图上的狼群、一起狩猎、登录问候，以及一键给稀有怪标骷髅。",
	["La manada en orden"] = "井然有序的狼群",
	["La manada es fuerte porque cada lobo lo es. Y tú lo eres."] = "狼群强大，是因为每一匹狼都强大。你也是。",
	["La manada no te ve en el mapa"] = "狼群在地图上看不到你",
	["La manada no ve a tu personaje en el mapa."] = "狼群在地图上看不到你的角色。",
	["La manada sabe qué misiones llevas (solo cuáles son) y tú las suyas. Si un lobo de tu zona hace una contigo, su tarjeta lo dice y Lya te propone invitarlo."] = "狼群知道你接了哪些任务（只知道是哪些），你也知道他们的。如果同区域的狼和你做同一个任务，他的卡片会显示，莉娅也会建议你邀请他。",
	["La manada sana"] = "狼群治疗",
	["La manada se organiza"] = "狼群集结",
	["La manada se organiza y tu historia"] = "狼群集结，还有你的故事",
	["La manada también la ve."] = "狼群也能看到。",
	["La manada te saluda"] = "狼群向你问好",
	["La manada te ve en el mapa"] = "狼群可以在地图上看到你",
	["La manada te ve en el mapa: %s"] = "狼群可以在地图上看到你：%s",
	["La manada unida"] = "狼群齐心",
	["La manada viaja"] = "狼群出行",
	["La manada ya no ve a tu personaje en el mapa."] = "狼群在地图上不再能看到你的角色。",
	["La manada ya ve a tu personaje en el mapa del juego."] = "狼群现在可以在游戏地图上看到你的角色了。",
	["La manada ya ve a tu personaje en el mapa del juego. Lo cambias cuando quieras en /alfa manada."] = "狼群现在可以在游戏地图上看到你的角色了。随时可以在 /alfa manada 中更改。",
	["La mazmorra"] = "地下城",
	["La mazmorra en vivo"] = "实时地下城",
	["La mazmorra para mi nivel"] = "适合我等级的地下城",
	["La mazmorra para tu nivel, sus jefes, botín, misiones y consejos."] = "适合你等级的地下城，以及它的首领、战利品、任务和提示。",
	["La mazmorra para tu nivel, sus misiones y cómo llegar."] = "适合你等级的地下城、它的任务以及如何前往。",
	["La mazmorra para tu nivel; con un nombre, esa mazmorra (también: progreso, ajustes)"] = "适合你等级的地下城；加上名称则显示该地下城（也可用：progreso、ajustes）",
	["La mañana huele a pan recién hecho en las posadas. ¿Empezamos con las misiones fáciles?"] = "早上的旅店飘着新鲜面包的香味。我们从简单的任务开始？",
	["La mejor de tus bolsas"] = "背包里最好的",
	["La mezcla de texturas del terreno."] = "地形材质的混合。",
	["La misión"] = "任务",
	["La montura"] = "坐骑",
	["La niebla con cuerpo de valles, pantanos y amaneceres."] = "山谷、沼泽和清晨里浓厚的雾气。",
	["La noche en Los Baldíos es enorme y callada. Se oyen las hienas a lo lejos."] = "贫瘠之地的夜晚辽阔又安静。能听到远处的鬣狗声。",
	["La noche en Tirisfal es más fría que el día. Huele a hojas mojadas y a cripta."] = "提瑞斯法的夜晚比白天更冷。闻起来是湿叶子和墓穴的味道。",
	["La pantalla se pone negra uno o dos segundos mientras el juego vuelve a arrancar los gráficos. No sales del juego ni pierdes nada."] = "游戏重启图形时屏幕会黑一两秒。你不会退出游戏，也不会丢失任何东西。",
	["La pesca de Alfa está apagada"] = "Alfa 钓鱼已关闭",
	["La pesca se rehízo: una sola tecla para equiparte, lanzar y recoger, con diario, logros y una guía de 1 a 300."] = "钓鱼功能已重做：一个键就能换装备、抛竿和拾取，还有图鉴、成就和 1 到 300 的指南。",
	["La piedra de hogar, clara: a dónde vuelves, qué entregas y un botón para usarla."] = "清晰的炉石：回到哪里、交什么任务，还有一个使用按钮。",
	["La piel verde de los orcos es una huella de la magia vil que usaron sus brujos en Draenor."] = "兽人的绿色皮肤是他们的术士在德拉诺使用邪能魔法留下的印记。",
	["La plática: lore y datos"] = "闲聊：背景故事和趣闻",
	["La precisión es lo más importante: con dos armas fallas mucho sin ella."] = "命中最重要：双持武器没有命中会经常打空。",
	["La primera vence en %s. Tómala antes de que regrese a quien te la mandó o se pierda."] = "第一封将在 %s 后过期。在它退回寄件人或丢失前拿走吧。",
	["La primera vez: %s%s."] = "第一次：%s%s。",
	["La princesa Moira, hija de Magni Barbabronce, vive en las Profundidades de Roca Negra como esposa del emperador Thaurissan."] = "麦格尼·铜须的女儿茉艾拉公主住在黑石深渊，是索瑞森大帝的妻子。",
	["La profesión"] = "专业",
	["La página de Bolsas; «abrir» abre tus bolsas y «banco» tu banco"] = "背包页面；“abrir”打开你的背包，“banco”打开你的银行",
	["La página de Bolsas; «abrir», «banco», «conjunto <nombre>» y «guardar <nombre>»"] = "背包页面；“abrir”（打开）、“banco”（银行）、“conjunto <名称>”（穿上方案）和“guardar <名称>”（保存方案）",
	["La que te toca, con sus misiones y su botín."] = "适合你的那个，附带任务和战利品。",
	["La recoges ahora"] = "现在接取",
	["La recomendada para ti y todas las demás"] = "为你推荐的以及其他所有",
	["La recomendada para ti y todas las demás."] = "为你推荐的以及其他所有。",
	["La ruta de %s"] = "%s的路线",
	["La ruta más rápida desde tu nivel, misión por misión."] = "从你的等级出发的最快路线，一个任务接一个任务。",
	["La ruta no trae tramos."] = "这条路线没有路段。",
	["La ruta te lleva a %s. La flecha está apagada: enciéndela en Ajustes > Guía para verla."] = "路线会带你去%s。箭头已关闭：请在“设置 > 指南”中开启才能看到。",
	["La ruta ya no se salta para siempre una misión que todavía no puede revisar."] = "路线不会再永久跳过暂时无法检查的任务。",
	["La sabes"] = "已学会",
	["La sacas de tu plan."] = "你把它从计划中移除。",
	["La sastrería usa la tela que sueltan los humanoides: lino, lana, seda, tejido mágico y tela rúnica."] = "裁缝使用人型生物掉落的布料：亚麻布、毛料、丝绸、魔纹布和符文布。",
	["La selva de Tuercespina de noche suena a mil bichos. Los trols sí ven en la oscuridad."] = "荆棘谷的丛林夜里像有一千只虫子在叫。巨魔在黑暗中看得可清楚了。",
	["La semana de caza"] = "狩猎周",
	["La semana de la manada"] = "狼群的一周",
	["La siguiente casilla cuesta %s y no te alcanza todavía."] = "下一个栏位需要 %s，你的钱还不够。",
	["La siguiente casilla cuesta %s: cómprala con el botón del banco del juego, que ya está a la vista."] = "下一个栏位需要 %s：请用游戏银行的按钮购买，它已经显示出来了。",
	["La subasta deja escanear todo cada 15 minutos. Falta %s."] = "拍卖行每 15 分钟允许完整扫描一次。还需 %s。",
	["La subasta no aceptó el escaneo. Intenta de nuevo más tarde."] = "拍卖行拒绝了扫描。请稍后再试。",
	["La subasta no envió subastas. Intenta de nuevo más tarde."] = "拍卖行没有返回拍卖数据。请稍后再试。",
	["La subasta no respondió. Puede que aún esté en espera: intenta en unos minutos."] = "拍卖行没有回应。可能还在冷却中：请过几分钟再试。",
	["La suma de lo que guardó Alfa de cada personaje (el tuyo, al día)."] = "Alfa 为每个角色保存的金币总和（当前角色为最新数据）。",
	["La tarde se presta para una mazmorra con la manada. Hay más gente conectada a estas horas."] = "下午最适合和狼群一起下地下城。这个时间在线的人更多。",
	["La tecla del botón de tu barra con esa habilidad, sobre el ícono."] = "图标上显示动作条中该技能按钮的按键。",
	["La tecla del mapa abre este mapa"] = "地图键打开此地图",
	["La tecla que abre el mapa del juego (M) abre el de Alfa; en él, un botón te lleva al del juego. Apágalo y la tecla vuelve a abrir el del juego. También puedes darle una tecla propia en Opciones > Teclado > Alfa."] = "打开游戏地图的按键（M）会打开 Alfa 地图；其中有一个按钮可前往游戏地图。关闭此项，按键会恢复打开游戏地图。你也可以在“选项 > 按键设置 > Alfa”中为它设置专属按键。",
	["La tecla que usabas en tu otro addon de pesca (%s) ahora pesca con Alfa."] = "你在其他钓鱼插件中使用的按键（%s）现在改由 Alfa 钓鱼。",
	["La tela rúnica sale de humanoides de nivel 50 o más: los trols de las Tierras del Interior o los sátiros de Frondavil son buena opción."] = "符文布来自 50 级以上的人型生物：辛特兰的巨魔或费伍德森林的萨特都是好选择。",
	["La tela sale de los enemigos humanoides de tu nivel. Los hilos los venden los proveedores de sastrería."] = "和你同等级的人型敌人会掉布料。裁缝用品商人出售线。",
	["La tela vil sale de sátiros y demonios de Frondavil y Azshara."] = "恶魔布来自费伍德森林和艾萨拉的萨特与恶魔。",
	["La tomo otra vez"] = "我再接一次",
	["La tribu Zandalar se considera la primera de todos los trols. Sus sacerdotes acampan en la Isla de Yojamba para frenar a Hakkar."] = "赞达拉部族自认为是所有巨魔中的第一支。他们的祭司在尤亚姆巴岛扎营，以阻止哈卡。",
	["La trituradora tira a la gente: vuelve a llamar su atención rápido."] = "伐木机会把人撞开：尽快重新拉住它的仇恨。",
	["La tuya tiene %d semanas: salen seguido."] = "你的版本已有 %d 周：更新很频繁。",
	["La varilla de cobre la venden los proveedores de encantamiento."] = "附魔用品商人出售铜棒。",
	["La venta se detuvo: vendiste %d de %d."] = "出售已停止：你卖出了 %d/%d 件。",
	["La ventana"] = "窗口",
	["La ventana de talentos del juego"] = "游戏的天赋窗口",
	["La ventana del Legado del juego"] = "游戏的传承窗口",
	["La última vez cazamos %s"] = "上次我们狩猎了：%s",
	["La última: %s."] = "最近一次：%s。",
	["Lady Sylvanas Brisaveloz gobierna a los Renegados. Fue general forestal de Quel'Thalas antes de que Arthas la matara."] = "希尔瓦娜斯·风行者女士统治着被遗忘者。被阿尔萨斯杀死之前，她是奎尔萨拉斯的游侠将军。",
	["Lady Vashj, que fue dama de compañía de Azshara, ahora guía a sus naga al servicio de Illidan."] = "瓦斯琪女士曾是艾萨拉的侍女，如今率领她的纳迦为伊利丹效力。",
	["Lanza bolas de fuego y fuego a su alrededor: interrúmpelo y, si peleas de lejos, aléjate."] = "他会施放火球术并在身边放火：打断他；远程玩家请站远一点。",
	["Lanza bombas de humo que aturden: sal del humo."] = "他会扔出致晕的烟雾弹：离开烟雾。",
	["Lanza enredaderas que tumban a todos los que están cerca: si peleas de lejos, quédate lejos."] = "他会放出藤蔓击倒附近所有人：远程玩家请站远一点。",
	["Lanza fuego a su alrededor: si peleas de lejos, aléjate de él."] = "他会在身边放火：远程玩家请远离他。",
	["Lanza hechizos de tierra y pone tótems: rompan los tótems primero."] = "他会施放大地法术并放下图腾：先打掉图腾。",
	["Lanza metal fundido: si no tanqueas, no te quedes pegado a él."] = "他会喷射熔化的金属：不是坦克就别贴着他站。",
	["Lanza rayos y se puede curar: interrumpe sus hechizos."] = "她会施放闪电，还能治疗自己：打断她的法术。",
	["Lanza ráfagas arcanas: interrúmpelo."] = "他会施放奥术冲击：打断他。",
	["Lanza sombras: interrúmpelo."] = "他会施放暗影法术：打断他。",
	["Lanza telarañas y una maldición: quita la maldición si puedes."] = "他会喷吐蛛网并施放诅咒：能驱散诅咒就驱掉。",
	["Lanza tormentas de arena que se mueven por la sala: no te pares en ellas."] = "他会制造在房间里移动的沙尘暴：别站在里面。",
	["Lanza tu hechizo más fuerte desde lejos y remata con los instantáneos."] = "从远处施放你最强的法术，再用瞬发法术收尾。",
	["Lanza tu hechizo más fuerte primero y remata con un choque."] = "先施放你最强的法术，再用震击收尾。",
	["Lanza una nube de veneno hacia adelante: gíralo lejos del grupo."] = "她会向前方喷出毒云：把她转向背对队伍。",
	["Lanza una red que deja quieto a un jugador: no es grave, sigue atacando."] = "他会撒网把一名玩家定住：没什么大碍，继续攻击。",
	["Lanza veneno a todos: quita el veneno si puedes."] = "他会对所有人施毒：能驱毒就驱掉。",
	["Lanzado"] = "已抛竿",
	["Lanzamientos"] = "抛竿次数",
	["Lanzamientos: %d de %d"] = "抛竿：%d / %d",
	["Las Cavernas del Tiempo guardan los momentos más importantes de la historia, y el Vuelo Bronce no deja que nadie los cambie."] = "时光之穴保存着历史上最重要的时刻，青铜龙军团不允许任何人改变它们。",
	["Las Estepas Ardientes se incendiaron cuando Ragnaros despertó, y sus brasas siguen sin apagarse."] = "拉格纳罗斯苏醒时燃烧平原燃起了大火，余烬至今仍未熄灭。",
	["Las Islas del Eco eran el hogar de los Lanza Negra, hasta que el brujo Zalazane sometió a muchos con su vudú y los demás tuvieron que mudarse a tierra firme."] = "回音群岛曾是暗矛部族的家园，直到巫医扎拉赞恩用巫毒术控制了许多族人，其余的人只好迁到大陆上。",
	["Las Lyas de tu grupo"] = "你队伍里的莉娅们",
	["Las Minas de la Muerte esconden el refugio de VanCleef... y hasta un barco pirata."] = "死亡矿井里藏着范克里夫的巢穴……甚至还有一艘海盗船。",
	["Las Montañas Crestagrana deben su nombre a sus rocas rojizas."] = "赤脊山因其泛红的岩石而得名。",
	["Las Profundidades de Roca Negra son una ciudad enana entera bajo la montaña: la capital de los Hierro Negro."] = "黑石深渊是一整座位于山下的矮人城市：黑铁矮人的首都。",
	["Las Rocas Rojas de Mulgore son un lugar sagrado: ahí descansan los ancestros de los tauren."] = "莫高雷的红石是一处圣地：牛头人的祖先安息在那里。",
	["Las Rocas Rojas son el lugar más sagrado de Mulgore: ahí descansan los ancestros de tu gente."] = "红石是莫高雷最神圣的地方：你族人的祖先安息在那里。",
	["Las Tierras de la Peste del Este siguen tristes aun de día. Aquí la Plaga no descansa."] = "东瘟疫之地白天也一样悲凉。天灾军团在这里从不休息。",
	["Las aguas de nivel 20 a 35. El rango Experto se aprende con el libro que vende el pescador de Bahía del Botín."] = "20 到 35 级的水域。高级钓鱼要用藏宝海湾渔夫出售的书来学。",
	["Las barras de abajo"] = "底部的栏",
	["Las barras de acción"] = "动作条",
	["Las barras y retratos vuelven al terminar el combate."] = "动作条和头像会在战斗结束后回来。",
	["Las bendiciones mayores duran más y cubren a toda una clase del grupo. ¡Ahorran mucho maná!"] = "强效祝福持续时间更长，能覆盖队伍中某个职业的所有人。非常省法力！",
	["Las bolsas de Alfa acomodan todo por categorías, marcan lo nuevo y lo de misión, y depositan rápido en el banco."] = "Alfa 背包按分类整理，标出新物品和任务物品，还能快速存银行。",
	["Las bolsas que coses siempre se venden: todo el mundo quiere más espacio."] = "你缝制的背包永远卖得出去：每个人都想要更多空间。",
	["Las bombas y granadas te salvan en mazmorras y en peleas contra el otro bando."] = "炸弹和手雷能在地下城里和对抗另一个阵营时救你一命。",
	["Las cajas cerradas las abren los pícaros; ofrécelas en el chat y a veces hasta te regalan el servicio."] = "上锁的箱子由盗贼来开；在聊天里问问，有时他们甚至免费帮你开。",
	["Las cartas de la Luna Negra caen de enemigos por todo el mundo; un mazo completo se cambia en la Feria por un abalorio poderoso."] = "暗月卡片会从世界各地的敌人身上掉落；集齐一整套可以在马戏团换一件强力饰品。",
	["Las casas de subastas neutrales de Bahía del Botín, Gadgetzan y Vista Eterna cobran más comisión, pero te dejan comerciar con el otro bando."] = "藏宝海湾、加基森和永望镇的中立拍卖行手续费更高，但能和另一个阵营交易。",
	["Las centinelas de Vallefresno pelean sin descanso contra los leñadores orcos de Grito de Guerra."] = "灰谷的哨兵们不停地与战歌氏族的兽人伐木工作战。",
	["Las centinelas domestican sables de hielo en Cuna del Invierno, y se los confían solo a quien se gana su respeto."] = "哨兵们在冬泉谷驯养霜刃豹，只托付给赢得她们尊重的人。",
	["Las citas de la manada en los próximos siete días. Propón una arriba, en «Citas de la manada»."] = "狼群未来七天的集合。在上方的“狼群集合”中发起一个。",
	["Las citas de la manada están apagadas (Ajustes de La Jauría)."] = "狼群集合已关闭（La Jauría 设置）。",
	["Las citas de los próximos siete días, acomodadas por día."] = "未来七天的集合，按日期排好。",
	["Las citas van a los lobos de tu hermandad: necesitas una."] = "集合会发给你公会的狼：你需要一个公会。",
	["Las criaturas que invocan los enemigos por un rato."] = "敌人暂时召唤出来的生物。",
	["Las cuentas"] = "计算明细",
	["Las cuentas de prueba no pueden compartir: el juego no lo permite."] = "试玩账号无法分享：游戏不允许。",
	["Las de tu ruta que tienes cerca"] = "附近你路线上的",
	["Las de tu ruta, las de la guía o todas: se eligen en Ajustes > Misiones, con lo demás de las misiones."] = "你的路线、指南的任务或全部：在“设置 > 任务”中与其他任务设置一起选择。",
	["Las demás"] = "其他",
	["Las demás ranuras"] = "其他栏位",
	["Las dos se suben solas mientras matas y viajas, y lo que juntas se vende bien: oro para tu montura y tus habilidades."] = "两个专业都会在你打怪和赶路时自然提升，采到的东西也很好卖：攒钱买坐骑和学技能。",
	["Las dríades son hijas de Cenarius, y los guardianes de la arboleda, sus hijos."] = "树妖是塞纳留斯的女儿，林地守护者则是他的儿子。",
	["Las especias y el agua las venden los taberneros y proveedores de cocina. Pesca te da mucho de lo que cocinas."] = "旅店老板和烹饪用品商人出售调料和水。你烹饪的很多东西都来自钓鱼。",
	["Las esquinas de la pantalla se oscurecen poco a poco, como en una foto."] = "屏幕四角逐渐变暗，就像照片一样。",
	["Las excavaciones de los enanos despertaron a los troggs, y ahora Thelsamar tiene que cuidarse de ellos."] = "矮人的挖掘惊醒了穴居人，现在塞尔萨玛得提防他们。",
	["Las explicaciones vuelven a salir."] = "说明会重新显示。",
	["Las flores cantoras corrompidas de Frondavil se pueden purificar; al hacerlo te dan una bendición que dura un buen rato."] = "费伍德森林被腐化的歌唱花可以被净化；净化后你会获得一个持续很久的祝福。",
	["Las fronteras entre zonas ya no parpadean al mover el mapa."] = "移动地图时，区域之间的边界不再闪烁。",
	["Las gafas de ingeniero solo las pueden usar ingenieros: ¡lúcelas con orgullo!"] = "工程护目镜只有工程师能戴：骄傲地戴上吧！",
	["Las guaridas de la manada"] = "狼群的巢穴",
	["Las guías y mazmorras de tu nivel al 60, y cuánto avanzas cada día."] = "从你的等级到 60 级的指南和地下城，以及你每天升了多少。",
	["Las hierbas de nivel alto se venden muy bien en la casa de subastas."] = "高等级草药在拍卖行卖得很好。",
	["Las líneas que escribe Anunciar en el chat de tu grupo o banda."] = "“通报”在你的小队或团队聊天中发布的内容。",
	["Las marca con una flecha."] = "会用箭头标出提升。",
	["Las marcas de la manada también en el minimapa, no solo en el mapa del mundo."] = "狼群的标记也显示在小地图上，而不只是世界地图。",
	["Las marcas en el suelo de hechizos y áreas. Apagarlas esconde avisos de combate: mejor dejarlas encendidas."] = "法术和区域在地面上的标记。关闭会隐藏战斗警示：最好保持开启。",
	["Las mejores misiones que ya puedes tomar cerca de ti, en el orden más corto."] = "你附近现在就能接的最佳任务，按最短顺序。",
	["Las mesetas de Cima del Trueno están unidas por puentes, y a la ciudad se sube en elevadores."] = "雷霆崖的各座台地之间由桥梁相连，要乘升降梯才能上到城里。",
	["Las metas se cumplen solas al hacerlas; las notas las marcas tú. Ordénalas como quieras."] = "目标在你完成时会自动达成；备注由你自己勾选。可以随意排序。",
	["Las misiones avisan otra vez"] = "任务通报回来了",
	["Las misiones de Molino Tarren mandan a la Horda contra las granjas humanas de las laderas."] = "塔伦米尔的任务派部落去攻打丘陵上的人类农场。",
	["Las misiones del juego"] = "游戏的任务追踪",
	["Las misiones grises dan poca XP. Entrégalas y sigue adelante."] = "灰色任务给的经验很少。交掉然后继续前进吧。",
	["Las misiones previas y el nivel que pide, para poder tomarla."] = "前置任务和所需等级，让你能接取它。",
	["Las misiones que más experiencia dan cerca de ti."] = "你附近经验最多的任务。",
	["Las misiones repetibles de reputación, como entregar tela, también son una forma de farmeo."] = "可重复的声望任务，比如上交布料，也是一种刷法。",
	["Las monturas de los gnomos son mecazancudos, aves mecánicas que ellos mismos inventaron."] = "侏儒的坐骑是机械陆行鸟，那是他们自己发明的机械鸟。",
	["Las monturas de otra raza de tu bando pueden pedir reputación con su ciudad: la de tu raza siempre se puede."] = "你阵营中其他种族的坐骑可能需要其主城的声望：你自己种族的坐骑随时都能用。",
	["Las monturas de tu raza"] = "你种族的坐骑",
	["Las monturas épicas del Clásico cuestan bastante oro; juntarlo poco a poco es parte de la aventura."] = "经典版的史诗坐骑要花不少金币；一点一点攒钱也是冒险的一部分。",
	["Las notas del lobo están apagadas (Ajustes de La Jauría)."] = "狼的笔记已关闭（La Jauría 设置）。",
	["Las ondas al caminar o nadar en el agua."] = "在水中行走或游泳时的涟漪。",
	["Las orillas de la pantalla un poco más oscuras."] = "屏幕边缘稍微暗一些。",
	["Las pestañas toman la letra y los colores del estilo; la elegida lleva la línea de acento. En Clásico WoW quedan las del juego."] = "标签页会使用该风格的字体和颜色；选中的标签页带有强调色线条。在经典 WoW 中保留游戏原本的标签页。",
	["Las piedras de afilar y los contrapesos que haces le sirven a guerreros y pícaros: siempre tienen compradores."] = "你做的磨刀石和平衡石对战士和盗贼很有用：永远有人买。",
	["Las piedras de salud que creas le salvan la vida a todo tu grupo."] = "你制造的治疗石能救全队的命。",
	["Las placas de nombre de los enemigos."] = "敌人的姓名板。",
	["Las plantas de herboristería."] = "草药学的植物。",
	["Las pociones de vida y maná siempre se venden: toda mazmorra las pide."] = "治疗药水和法力药水永远卖得出去：每个地下城都需要。",
	["Las primeras misiones de un humano en Villanorte van de kóbolds, bandidos Defias... y lobos. No todos somos buenos, ¿eh?"] = "人类在北郡的第一批任务是对付狗头人、迪菲亚强盗……还有狼。我们狼也不全是好狼，懂吧？",
	["Las profesiones de fabricación dan retos del Legado al llegar a 150, 225 y 300."] = "制造类专业达到 150、225 和 300 时会获得传承挑战。",
	["Las profesiones de recolección dan oro desde el nivel 1. ¡Hierbas o minería!"] = "采集专业从 1 级起就能赚金币。草药学还是采矿！",
	["Las que Lya ya te dijo sus tres veces. Con «Volver a mostrarlos» salen otra vez."] = "Lya 已经各说满三次的话。点“重新显示它们”就会再次出现。",
	["Las que me faltan"] = "我缺少的",
	["Las que se hacen una sola vez."] = "只能完成一次的任务。",
	["Las que se repiten cada día."] = "每天重置的任务。",
	["Las que se repiten cada semana."] = "每周重置的任务。",
	["Las que tengo"] = "我拥有的",
	["Las que vienen después, más pequeñas a la derecha."] = "接下来的技能，以较小图标显示在右侧。",
	["Las que ya hiciste no cuentan."] = "已完成的任务不计入。",
	["Las que ya no te dan casi nada y no abren otra que valga la pena. En la página Ruta, «Misiones grises»: cada una con su «Abandonar»."] = "几乎没什么收益、也不会开启值得做的后续任务的那些。在路线页面的“灰色任务”中：每个都有“放弃”。",
	["Las que ya usaste y tardan en volver. Apaga las que no quieras ver en la barra."] = "你已经用过、需要较长时间冷却的技能。关掉你不想在计时条上看到的。",
	["Las ranuras que tu tecla nunca cambia: cabeza, manos, pies, abalorios y las demás."] = "你的按键从不更换的栏位：头部、手、脚、饰品等。",
	["Las recetas se compran a vendedores de comida y algunas caen de enemigos."] = "配方可以向食物商人购买，有些会从敌人身上掉落。",
	["Las ruinas de Eldarath fueron una ciudad élfica; hoy están llenas de naga."] = "埃达拉斯废墟曾是一座精灵城市；如今满是纳迦。",
	["Las rutas y los planes que armas en la página Ruta de Alfa."] = "你在 Alfa 的“路线”页面创建的路线和计划。",
	["Las sacerdotisas de Elune guían a tu pueblo, y Tyrande lo gobierna desde el Templo de la Luna."] = "艾露恩的女祭司们引导着你的族人，泰兰德在月神殿统治他们。",
	["Las sesiones guardadas de este personaje."] = "此角色已保存的游戏记录。",
	["Las sesiones, las zonas y los objetos de este personaje."] = "此角色的采集记录、区域和物品。",
	["Las vendas suben de lino a lana, seda, tejido mágico y tela rúnica."] = "绷带从亚麻布升级到毛料、丝绸、魔纹布和符文布。",
	["Las ventanas de chat, sus pestañas y la caja para escribir toman el estilo que elijas abajo y cambian con él. Al apagarlo vuelve el chat de siempre, sin /reload."] = "聊天窗口、标签页和输入框会使用你在下方选择的风格，并随之变化。关闭后恢复原本的聊天，无需 /reload。",
	["Lavanda"] = "薰衣草色",
	["Le baja la armadura al enemigo y genera mucha amenaza. El golpe básico del tanque."] = "降低敌人护甲并产生大量仇恨。坦克的家常便饭。",
	["Le baja la armadura al enemigo y no lo deja volverse invisible."] = "降低敌人的护甲，并让它无法隐形。",
	["Le das mucho maná a un aliado. Dáselo a quien cura o úsalo en ti."] = "给一个盟友大量法力。给你的治疗者，或对自己使用。",
	["Le dijiste a %s que esta vez no puedes."] = "你告诉 %s 这次去不了。",
	["Le dijiste a %s que vas: %s."] = "你告诉 %s 你会去：%s。",
	["Le disparas a varios enemigos a la vez. Cuidado con despertar a los dormidos."] = "同时射击多个敌人。小心别把睡着的吵醒。",
	["Le falta %s."] = "缺少 %s。",
	["Le falta %s: dáselo con %s."] = "缺少 %s：用 %s 给他加上。",
	["Le falta tu buff"] = "缺少你的增益效果",
	["Le pediste a %s que te las comparta."] = "你请%s把任务共享给你。",
	["Le pregunté a la manada de tu zona. Si alguien abre su guarida en otro plano, te aviso."] = "我已经问了你区域里的狼群。如果有人在其他位面打开巢穴，我会告诉你。",
	["Le propusiste a %s ser su mentor. Te aviso cuando conteste."] = "你提议当 %s 的导师。他回复时我会告诉你。",
	["Le quita magia buena al enemigo."] = "驱散敌人身上的有益魔法。",
	["Le robas vida al enemigo y te curas. Ideal cuando vas solo."] = "偷取敌人的生命来治疗你。单刷时非常好用。",
	["Le sirve a %s"] = "%s 用得上",
	["Leche helada"] = "冰镇牛奶",
	["Lechúcico"] = "枭兽形态",
	["Lectura del agua"] = "读懂水面",
	["Lee el precio más bajo de cada objeto en toda la subasta. No compra ni publica nada. Se puede usar cada 15 minutos."] = "读取整个拍卖行中每种物品的最低价。不会购买或上架任何东西。每 15 分钟可使用一次。",
	["Lee los objetivos de la misión antes de salir: te ahorras vueltas."] = "出发前先读任务目标：省得来回跑。",
	["Leeroy Jenkins se hizo famoso por lanzarse solo, gritando su nombre, a una sala llena de dragoncitos en la Cumbre de Roca Negra."] = "里罗伊·詹金斯之所以出名，是因为他喊着自己的名字，独自冲进黑石塔一个满是雏龙的房间。",
	["Legado"] = "传承",
	["Legendario"] = "传说",
	["Lejos de aquí"] = "离这里很远",
	["Lejos de aquí: %s"] = "离这里很远：%s",
	["Letra del estilo"] = "风格字体",
	["Letra muy grande"] = "特大字体",
	["Letra más grande"] = "更大的字体",
	["Letra normal"] = "普通字体",
	["Letra: grande"] = "字体：大",
	["Letra: muy grande"] = "字体：特大",
	["Letra: normal"] = "字体：正常",
	["Letras grandes en el centro de la pantalla cuando el jefe hace algo importante."] = "首领施放重要技能时，在屏幕中央显示大字提示。",
	["Leyenda"] = "传奇",
	["Leyendo precios... %d%%"] = "正在读取价格... %d%%",
	["Leyendo tus bolsas…"] = "正在读取你的背包…",
	["Libera tu sello en el enemigo: daño extra."] = "对敌人释放你的圣印：额外伤害。",
	["Libera tu sello sobre el enemigo para un efecto extra. Pon un sello, juzga y vuelve a ponerlo."] = "对敌人释放你的圣印，获得额外效果。圣印、审判，然后再上圣印。",
	["Liberar tu espíritu en campos de batalla"] = "在战场中释放灵魂",
	["Libra a un aliado de raíces y de lentitud."] = "让盟友摆脱定身和减速。",
	["Libre"] = "空闲",
	["Libre: %d de %d"] = "剩余：%d / %d",
	["Libro"] = "书籍",
	["Ligado: no se subasta"] = "已绑定：无法拍卖",
	["Limpien a sus ayudantes antes de empezar con él."] = "先清掉他的帮手，再开始打他。",
	["Lista"] = "就绪",
	["Lista de compras"] = "购物清单",
	["Lista de compras y oficios"] = "购物清单与专业",
	["Lista de errores borrada"] = "错误列表已清空",
