	["Lista para entrar"] = "可以进入了",
	["Lista para entregar"] = "可交还",
	["Listas"] = "就绪",
	["Listas para entregar"] = "可交付",
	["Listo"] = "完成",
	["Listo [estado]"] = "就绪",
	["Listo para ayudar a tu grupo"] = "准备好支援队友了",
	["Listo para curar"] = "准备好治疗了",
	["Listo para la mazmorra"] = "地下城准备就绪",
	["Listo para pescar"] = "可以钓鱼了",
	["Listo, fijarlos"] = "完成，锁定",
	["Listo, ya no te lo digo. Si me extrañas, está en mi página: «Consejos que callaste»."] = "好，我不再说了。想念的话，在我的页面“已关闭的建议”里。",
	["Listo. Ahora: %s"] = "完成。接下来：%s",
	["Listo: %d habilidades nuevas en tu barra de %s."] = "完成：已将 %d 个新技能放到你的%s动作条上。",
	["Listo: 1 habilidad nueva en tu barra de %s."] = "完成：已将 1 个新技能放到你的%s动作条上。",
	["Listo: Alfa soltó la memoria que ya no ocupaba."] = "完成：Alfa 释放了不再需要的内存。",
	["Listo: aprendiste %d rangos de talento"] = "完成：你学会了 %d 级天赋",
	["Listo: aprendiste 1 rango de talento"] = "完成：你学会了 1 级天赋",
	["Listo: te abrimos un susurro para %s. Revisa el mensaje y pulsa Intro."] = "完成：已为你打开给%s的密语。检查消息后按回车键。",
	["Listo: tu mapa también funciona en los marcos de Blizzard."] = "完成：你的鼠标绑定在暴雪框体上也能使用了。",
	["Llama a la manada cuando necesites ayuda; los lobos de tu zona llegan con «¡Voy!». Y «Seguir» ya no se suelta al alcanzar a alguien."] = "需要帮助时呼唤狼群；区域里的狼会带着“我来了！”赶来。而且“跟随”追上后不再松开。",
	["Llama a tu mascota a tu lado."] = "把你的宠物召唤到身边。",
	["Llama a varios lobos al empezar: usen ataques en área o maten primero a los lobos."] = "开场时他会召唤几只狼：用范围攻击，或先杀狼。",
	["Llamados de la manada"] = "狼群的呼唤",
	["Llamar a la manada"] = "呼唤狼群",
	["Llamaste a la manada"] = "你呼唤了狼群",
	["Llave"] = "钥匙",
	["Llavero"] = "钥匙链",
	["Llaves"] = "钥匙",
	["Llega Lya, una loba compañera que guarda la historia de cada misión y te cuenta datos de cada zona."] = "Lya 来了，她是一匹母狼伙伴，会保存每个任务的故事，并告诉你每个区域的趣闻。",
	["Llega a 150 de habilidad."] = "技能达到 150。",
	["Llega a 225 de habilidad."] = "技能达到 225。",
	["Llega a 75 de habilidad."] = "技能达到 75。",
	["Llega a la habilidad máxima de pesca."] = "钓鱼技能达到最高。",
	["Llega a la maestría Diestro con una captura."] = "让一种渔获达到“熟练”精通。",
	["Llega a nivel %d"] = "达到 %d 级",
	["Llega a nivel 25 con cualquier clase"] = "用任意职业达到 25 级",
	["Llega al nivel 40 (te faltan %d)"] = "达到 40 级（还差 %d 级）",
	["Llega con %d puntos del legado ganados en tu cuenta."] = "在你的账号上累计获得 %d 点传承点数。",
	["Llega con ayudantes naga: mátenlos primero."] = "她带着纳迦帮手一起来：先杀帮手。",
	["Llega con guardias: tírenlos aparte si pueden."] = "他带着卫兵：能拉开就把卫兵单独拉走。",
	["Llega con lobos: elimínenlos primero."] = "他带着狼：先把狼解决掉。",
	["Llega con su perro: una persona debe tanquear a cada uno, o maten al perro primero."] = "他带着他的狗：两个各由一个人坦住，或者先杀狗。",
	["Llega en %s; va a %s"] = "%s 后抵达；开往 %s",
	["Llega en el nivel %d"] = "%d 级时获得",
	["Llegar a nivel %d"] = "达到 %d 级",
	["Llegar a un nivel"] = "达到某个等级",
	["Llegas al rival con ira para pegar de inmediato."] = "冲到对手面前时已有怒气，可以马上输出。",
	["Llegas en unos %d min"] = "大约 %d 分钟后到达",
	["Llegaste"] = "到了",
	["Llegaste al final; quedaron %d pasos sin hacer."] = "你已到达终点；还有 %d 个步骤未完成。",
	["Llegaste al tope: %d de %d"] = "已达上限：%d / %d",
	["Llegaste con %s."] = "你已到达%s身边。",
	["Llegaste con %s. La flecha te sigue llevando mientras se mueve; para soltar el rastro, «Dejar de seguir»."] = "你追上了 %s。对方移动时箭头会继续带路；要放开踪迹，点“停止跟随”。",
	["Llenar mi barra"] = "填满我的动作条",
	["Lleva al máximo la distancia de la cámara (la de Opciones > Controles). Al apagarlo vuelve la que tenías."] = "把镜头距离（选项 > 控制中的那一项）调到最大。关闭后恢复你原来的设置。",
	["Lleva siempre un sello puesto aunque estés curando."] = "即使在治疗时也要始终保持一个圣印。",
	["Lleva siempre vendas y comida: descansar poco y seguro es más rápido que morir."] = "随身带着绷带和食物：稳妥地稍作休息，总比死掉快。",
	["Llevamos %d páginas en tu historia. La más nueva: %s."] = "你的故事已有 %d 页。最新一页：%s。",
	["Llevamos un buen rato cazando… ¿no traerás por ahí una salchichita para tu loba?"] = "我们已经狩猎好一阵子了……你身上不会正好有根小香肠给你的狼吧？",
	["Llevarla a Mis planes"] = "加入“我的计划”",
	["Llevarme"] = "带我去",
	["Llevas %s ahora. Solo oro entero (10 = 10 de oro)."] = "你现在有 %s。只能填整数金币（10 = 10 金币）。",
	["Llevas %s de %s"] = "已进行 %s / %s",
	["Llevas %s jugando. Estírate, toma agua y regresas con más fuerza."] = "你已经玩了 %s。伸个懒腰、喝点水，回来会更有劲。",
	["Llevas %s. La manada te espera aunque te tomes un respiro."] = "已经 %s 了。就算你休息一下，狼群也会等你。",
	["Llevas %s. Si cierras sesión en una posada, ganas XP descansada."] = "已经 %s 了。在旅店下线可以获得休息经验。",
	["Llorar"] = "哭泣",
	["Llámala antes de pelear."] = "战斗前先召唤它。",
