	["Llévame a una zona de tu nivel"] = "带我去适合我等级的区域",
	["Llévame a..."] = "带我去……",
	["Llévame a... (el camino a cualquier lugar)"] = "带我去……（去任何地方的路线）",
	["Llévame al banco"] = "带我去银行",
	["Llévame al comerciante"] = "带我去找商人",
	["Llévame al instructor"] = "带我去找训练师",
	["Llévame con el instructor"] = "带我去找训练师",
	["Llévame con mi entrenador"] = "带我去找训练师",
	["Llévame por balas"] = "带我去买子弹",
	["Llévame por componentes"] = "带我去买施法材料",
	["Llévame por flechas"] = "带我去买箭",
	["Lo acompañan otros lanzadores: interrúmpanlos."] = "他身边还有其他施法者：打断他们。",
	["Lo alto de cada compañero."] = "每个队友框的高度。",
	["Lo ancho de cada compañero."] = "每个队友框的宽度。",
	["Lo apagas o lo enciendes cuando quieras en Manada > La Jauría."] = "随时可以在 狼群 > La Jauría 中关闭或开启。",
	["Lo aprendes con %s. Tu tope sube a %d."] = "在 %s 学习。你的上限会提高到 %d。",
	["Lo bueno en azul, los avisos en amarillo y el peligro en naranja, y los perjuicios con colores que se distinguen sin el rojo y el verde."] = "好的用蓝色，提醒用黄色，危险用橙色；减益效果使用不靠红绿也能分辨的颜色。",
	["Lo callaste el %s."] = "你在 %s 关闭了它。",
	["Lo cambias cuando quieras en Ajustes > Estilo y sonido."] = "随时可在“设置 > 风格与声音”中更改。",
	["Lo cazaron %s"] = "%s被击杀",
	["Lo cazaron %s. Ve a ver si ya salió."] = "%s被击杀。去看看它刷新了没有。",
	["Lo conozco de memoria"] = "我倒背如流",
	["Lo de %s y %s tiene su historia. ¿Te la platico?"] = "%s和%s的事有段故事。要我说给你听吗？",
	["Lo demás, de un vistazo"] = "其他内容，一目了然",
	["Lo enseña un instructor de la profesión"] = "由该专业的训练师传授",
	["Lo enseña un instructor en %s"] = "由%s的训练师传授",
	["Lo esencial"] = "基本内容",
	["Lo estás siguiendo"] = "正在跟随",
	["Lo estás siguiendo."] = "你正在跟随此人。",
	["Lo gris véndelo a los vendedores, no en la subasta: nadie lo va a comprar ahí."] = "灰色物品卖给商人，别拿去拍卖：在那里没人会买。",
	["Lo gris y lo que marcaste como chatarra. Nunca lo que marcaste para conservar ni lo que pide una misión."] = "灰色物品和你标记为垃圾的物品。绝不包括你标记为保留的物品或任务需要的物品。",
	["Lo justo para abrir la siguiente fila."] = "刚好够解锁下一排。",
	["Lo llevas puesto: %d piezas."] = "已穿在身上：%d 件。",
	["Lo marca como tu objetivo"] = "将其设为你的目标",
	["Lo mejor de los dos lados. Si no sabes cuál elegir, elige este."] = "兼顾两边的长处。如果不知道选哪个，就选这个。",
	["Lo mejor para ti"] = "最适合你的",
	["Lo mejor para tu nivel"] = "适合你等级的最佳装备",
	["Lo mejor que sacaste: %s."] = "你拿到的最好的东西：%s。",
	["Lo mejor: %s."] = "最好的：%s。",
	["Lo menos que espera Lya entre un consejo y otro. Lo importante no espera."] = "Lya 两条建议之间最少等待的时间。重要的事不用等。",
	["Lo menos que espera Lya entre una historia y otra. Nunca en combate ni en mazmorras."] = "Lya 两个故事之间最少等待的时间。战斗中和地下城中绝不会讲。",
	["Lo más cerca"] = "最近的",
	["Lo más cerca de ti"] = "离你最近的",
	["Lo más gastado va al %d %%. Te llevo con quien repare."] = "你最旧的装备只剩 %d %%。我带你去修理。",
	["Lo más ligero: para equipos modestos o para subir los FPS en peleas grandes."] = "最轻量：适合配置一般的电脑，或在大型战斗中提高 FPS。",
	["Lo más parecido"] = "最接近的",
	["Lo más útil para este momento, en grande: tu siguiente paso, lo urgente y tu camino a un par de clics."] = "此刻最有用的内容，大字显示：你的下一步、紧急事项，以及几次点击就能到的路线。",
	["Lo nuevo de esta versión"] = "本版本的新内容",
	["Lo nuevo de esta versión, en pocas palabras."] = "简要介绍此版本的新内容。",
	["Lo nuevo en Alfa %s"] = "Alfa %s 新内容",
	["Lo nuevo en Alfa 1.0"] = "Alfa 1.0 新内容",
	["Lo olimos, lo seguimos y cayó. ¡Así caza la manada!"] = "我们嗅到它、追踪它，它倒下了。狼群就是这样狩猎的！",
	["Lo pequeño que hace el juego más cómodo: el minimapa, el chat y las barras con el estilo de Alfa, marcos, cuadro de información, probador, cámara y sonidos; y en sus pestañas, viajes, invitaciones, comerciantes y más."] = "让游戏更舒适的小功能：Alfa 风格的小地图、聊天和动作条、框体、鼠标提示、试衣间、镜头和声音；在其标签页中还有旅行、邀请、商人等。",
	["Lo pequeño que hace el juego más cómodo: misiones, vuelos, minimapa, chat y barras con el estilo de Alfa, marcos, cuadro de información, probador, cámara y sonidos."] = "让游戏更舒适的小功能：任务、飞行、小地图、使用 Alfa 风格的聊天和动作条、框体、鼠标提示、试衣间、镜头和声音。",
	["Lo pescado en esta sesión"] = "本次渔获",
	["Lo pide una misión de %s."] = "%s 的一个任务需要它。",
	["Lo piden estas misiones"] = "需要它的任务",
	["Lo pones al empezar a pelear."] = "战斗开始时施放。",
	["Lo primero que puedes soltar: %s (%s)."] = "最先可以丢掉的：%s（%s）。",
	["Lo que Alfa acepta, rechaza o comparte sola. Mantén presionado Mayús para decidir tú en el momento."] = "Alfa 自动接受、拒绝或分享的内容。按住 Shift 可以当场由你决定。",
	["Lo que Lya nota"] = "莉娅注意到的事",
	["Lo que Lya sabe de aquí"] = "Lya 对这里的了解",
	["Lo que buscas en la Enciclopedia"] = "你在百科中查询的内容",
	["Lo que choca con Alfa y cómo arreglarlo"] = "什么与 Alfa 冲突以及如何解决",
	["Lo que comparte alguien de tu grupo con Alfa llega a tus marcadores, con su nombre, y te avisa para seguirlo."] = "队伍中有人用 Alfa 分享的内容会进入你的标记，附带其名字，并提醒你跟随。",
	["Lo que conoce Alfa"] = "Alfa 已知的",
	["Lo que cuentan las misiones que vas tomando"] = "你接下的任务讲述的故事",
	["Lo que da"] = "提供的东西",
	["Lo que dice el diario de monturas"] = "坐骑收藏中的说明",
	["Lo que el menú del juego no enseña, a tu gusto"] = "游戏菜单里没有的设置，随你调整",
	["Lo que elegiste al configurarlo: aceptar y entregar misiones, vender lo gris, reparar, tomar vuelos... Lo cambias cuando quieras."] = "你设置时选的：接交任务、卖灰色物品、修理、坐飞行……随时可改。",
	["Lo que encuentras en la manada"] = "在狼群中你会找到",
	["Lo que este personaje lleva en las mazmorras: se guarda solo al vencer jefes y recoger botín."] = "此角色在地下城中的进度：击败首领和拾取战利品时自动保存。",
	["Lo que falta para subir %s"] = "升级 %s 还缺的东西",
	["Lo que ganaste la última vez que jugaste con este personaje."] = "上次用此角色游戏时的收获。",
	["Lo que gastan tus hechizos"] = "你的法术消耗的材料",
	["Lo que hay dentro"] = "内含物品",
	["Lo que le sirve a otro lobo"] = "别的狼用得上的东西",
	["Lo que llevas"] = "随身物品",
	["Lo que llevas pescado: %s."] = "你目前钓到的：%s。",
	["Lo que me sirve"] = "对我有用的",
	["Lo que menos vale: %s"] = "最不值钱的：%s",
	["Lo que más conviene ahora"] = "现在最划算的",
	["Lo que más rinde cerca de ti"] = "附近最划算的事",
	["Lo que más te pegó: %s (%s)."] = "打你最痛的：%s（%s）。",
	["Lo que más te pegó: %s, de %s (%s)."] = "打你最痛的：%s，来自 %s（%s）。",
	["Lo que no está a la vista no sale aquí."] = "屏幕上看不到的东西不会出现在这里。",
	["Lo que obtuviste en esta sesión"] = "本次获得的物品",
	["Lo que pescaste"] = "你钓到的",
	["Lo que pide %s antes, en orden."] = "%s的前置条件，按顺序。",
	["Lo que quieras contarle al desarrollador de Alfa."] = "任何你想告诉 Alfa 开发者的话。",
	["Lo que quieras; la marcas tú cuando la hagas."] = "随你写什么；完成后由你自己勾选。",
	["Lo que revisé"] = "我检查了什么",
	["Lo que sabe de Alfa"] = "她知道的 Alfa",
	["Lo que sacas en %s: %s."] = "你在%s钓到的：%s。",
	["Lo que se pesca aquí"] = "这里能钓到的",
	["Lo que se queda la subasta de cada venta. Suele ser 5 % en la de tu facción y 15 % en la neutral. Es un estimado."] = "拍卖行从每笔成交中抽取的部分。本阵营拍卖行通常为 5%，中立拍卖行为 15%。这是估计值。",
	["Lo que sigue"] = "接下来",
	["Lo que sigue en tu build no está en tu árbol"] = "你方案接下来的部分不在你的天赋树中",
	["Lo que sigue para tu nivel: %s."] = "适合你等级的下一个：%s。",
	["Lo que sigue pide este nivel: hasta entonces, la guía no te manda allá."] = "接下来的内容需要这个等级：在那之前，指南不会让你过去。",
	["Lo que sugiere Alfa"] = "Alfa 的建议",
	["Lo que te falta para llegar a 300"] = "练到 300 还缺的东西",
	["Lo que te falta para una mazmorra, en un aviso. También con /alfa listo."] = "去地下城还缺什么，用提醒告诉你。也可以用 /alfa listo。",
	["Lo que te ha contado"] = "她告诉过你的话",
	["Lo que te ofrece Lya (su botón)"] = "莉娅的提议（她的按钮）",
	["Lo que te pasa a ti: curación recibida, esquivas, recursos. Puede necesitar /reload la primera vez."] = "发生在你身上的：受到的治疗、躲闪、资源。第一次可能需要 /reload。",
	["Lo que te piden"] = "要你做的事",
	["Lo que tenía ya está hecho, omitido o fuera de tu registro. Ármalo otra vez con las misiones que tienes ahora."] = "里面的内容已完成、已跳过或不在你的任务日志中。用你现在的任务重新规划。",
	["Lo que trae esta versión, contado corto. Míralo cuando quieras."] = "这个版本带来的内容，简短介绍。想看时随时看。",
	["Lo que trajo la última versión de Alfa, contado corto."] = "Alfa 最新版本带来了什么，简短说说。",
	["Lo que tu build necesita de tu equipo y dónde conseguirlo."] = "你的方案对装备的需求，以及在哪里获得。",
	["Lo que tu clase se pone antes de pelear está activo."] = "你的职业战斗前要上的增益已生效。",
	["Lo que tu profesión de recolección junta mejor."] = "你的采集专业最擅长采集的东西。",
	["Lo que vale"] = "价值",
	["Lo que ya tienes en el banco"] = "银行里已有的物品",
	["Lo recolectaste %d veces"] = "你采集过 %d 次",
	["Lo recolectaste 1 vez"] = "你采集过 1 次",
	["Lo revisa el desarrollador de Alfa. En ese canal nadie más ve tu mensaje. Si aún no estás en el Discord, entra con la invitación de arriba."] = "由 Alfa 的开发者查看。在那个频道里，其他人看不到你的消息。如果你还没加入 Discord，请用上方的邀请加入。",
	["Lo sigues"] = "正在跟随",
	["Lo sigues: el rastreador te muestra la meta de ahora y la flecha va a cada lugar."] = "正在跟随：追踪器显示当前目标，箭头会带你去每个地点。",
	["Lo siguiente"] = "接下来",
	["Lo siguiente para ti"] = "你接下来该做的",
	["Lo sueltan"] = "掉落来源",
	["Lo suma a tu lista de compras de Comercio, con lo que pide su receta."] = "把它加入交易的购物清单，包括配方需要的材料。",
	["Lo último que consultaste"] = "最近查询的内容",
	["Lo último que te dije"] = "我最后说的话",
	["Lobo"] = "狼",
	["Lobos conectados"] = "在线狼群",
	["Logrado el %s"] = "达成于 %s",
	["Logrados"] = "已达成",
	["Logro de pesca: %s"] = "钓鱼成就：%s",
	["Logros"] = "成就",
	["Logros de pesca"] = "钓鱼成就",
	["Lord Kazzak, un demonio enorme, ronda las Tierras Devastadas; en el Clásico es un jefe de mundo para bandas."] = "巨大的恶魔卡扎克领主在诅咒之地游荡；在经典版中他是需要团队挑战的世界首领。",
	["Lord Xavius, el consejero de Azshara, convenció a los Altonato de abrirle la puerta a Sargeras. Cuando murió, Sargeras lo trajo de vuelta como el primer sátiro."] = "艾萨拉的顾问萨维斯领主说服上层精灵为萨格拉斯打开大门。他死后，萨格拉斯让他复活成了第一个萨特。",
	["Los Altonato eran la nobleza élfica que vivía para la magia del Pozo. Su reina, Azshara, era tan bella que su pueblo la adoraba."] = "上层精灵是为永恒之井的魔法而活的精灵贵族。他们的女王艾萨拉美得让人民崇拜她。",
	["Los Amani pelearon contra los altos elfos durante miles de años. Su capital, Zul'Aman, está en los bosques cerca de Quel'Thalas."] = "阿曼尼与高等精灵交战了数千年。他们的首都祖阿曼位于奎尔萨拉斯附近的森林中。",
	["Los Barbabronce ganaron la Guerra de los Tres Martillos, y por eso Forjaz es suya."] = "铜须氏族赢得了三锤之战，所以铁炉堡归他们所有。",
	["Los Claros de Tirisfal guardan las ruinas de Lordaeron, el reino de Arthas. Bajo su antigua capital, los Renegados levantaron Entrañas."] = "提瑞斯法林地保存着洛丹伦——阿尔萨斯的王国——的废墟。被遗忘者在其旧都地下建起了幽暗城。",
	["Los Defias usan cosechadores mecánicos que trabajan solos en los campos... y no les gustan las visitas."] = "迪菲亚使用会自己在田里干活的收割傀儡……而且它们不喜欢访客。",
	["Los Furiarena de Zul'Farrak son trols del desierto, primos lejanos de los Lanza Negra."] = "祖尔法拉克的沙怒巨魔是沙漠巨魔，是暗矛的远亲。",
	["Los Gurubashi llamaron a Hakkar, el Desollador de Almas. Cuando vieron lo que hacía, las demás tribus se unieron para echarlo."] = "古拉巴什召唤了夺灵者哈卡。看到他的所作所为后，其他部族联手把他赶了出去。",
	["Los Hierro Negro invocaron a Ragnaros sin querer al final de la Guerra de los Tres Martillos, y desde entonces son sus esclavos."] = "三锤之战末期，黑铁矮人意外召唤了拉格纳罗斯，从此沦为他的奴隶。",
	["Los Hierro Negro también excavan en Uldaman, buscando lo mismo que los enanos de Forjaz."] = "黑铁矮人也在奥达曼挖掘，寻找和铁炉堡矮人相同的东西。",
	["Los Lanza Negra suelen terminar sus frases con un «mon». ¡Se pega, mon!"] = "暗矛部族说话常在句尾加个“mon”。会传染的，mon！",
	["Los PNJ dejan de hablar al saludarte o al darte misiones. También calla las voces de error."] = "NPC 向你打招呼或给你任务时不再说话。也会静音错误语音。",
	["Los Perdidos del pantano son draenei que llegaron de Draenor y quedaron cambiados para siempre."] = "沼泽里的失落者是从德拉诺来的德莱尼，他们永远地改变了。",
	["Los Páramos de Poniente eran el granero de Ventormenta; hoy muchas de sus granjas están en manos de la Hermandad Defias."] = "西部荒野曾是暴风城的粮仓；如今那里许多农场都落入了迪菲亚兄弟会手中。",
	["Los Renegados aguantan bajo el agua mucho más que los vivos. ¡No necesitan respirar tanto!"] = "被遗忘者在水下能待的时间比活人长得多。他们不太需要呼吸！",
	["Los Renegados entraron a la Horda gracias a los tauren, que esperaban encontrarles una cura. Muchos orcos aún no se fían de ellos."] = "被遗忘者能加入部落，多亏了牛头人，他们希望能为被遗忘者找到解药。许多兽人至今仍不信任他们。",
	["Los Renegados hicieron de Rémol, un viejo pueblo humano, su primera parada en Tirisfal."] = "被遗忘者把古老的人类城镇布瑞尔当作他们在提瑞斯法林地的第一站。",
	["Los Renegados nuevos despiertan en Camposanto, en Tirisfal, como no-muertos libres del Rey Exánime."] = "新的被遗忘者在提瑞斯法林地的丧钟镇醒来，成为摆脱巫妖王控制的亡灵。",
	["Los Renegados pueden comerse cadáveres para recuperar vida. Yo prefiero las salchichas, gracias."] = "被遗忘者可以吃尸体来恢复生命值。我还是比较喜欢香肠，谢谢。",
	["Los Renegados recuerdan quiénes fueron en vida, y eso pesa más que cualquier herida."] = "被遗忘者记得自己生前是谁，这比任何伤口都沉重。",
	["Los Renegados son no-muertos que recuperaron su voluntad cuando el poder del Rey Exánime se debilitó."] = "被遗忘者是在巫妖王力量减弱时重获自由意志的亡灵。",
	["Los Tótem Siniestro son tauren que no quieren a la Horda; su jefa Magatha vive en la misma Cima del Trueno."] = "恐怖图腾是不喜欢部落的牛头人；他们的首领玛加萨就住在雷霆崖。",
	["Los ajustes de los recordatorios están en la búsqueda de la ventana de Alfa."] = "提醒的设置可以在 Alfa 窗口的搜索中找到。",
	["Los altos elfos pelearon con la Alianza en la Segunda Guerra por una vieja deuda de sangre con el linaje de Thoradin."] = "第二次战争中，高等精灵因为对索拉丁血脉的一笔古老血债而与联盟并肩作战。",
	["Los altos elfos que sobrevivieron a la Plaga empezaron a llamarse elfos de sangre, en honor a los suyos caídos. Kael'thas los guía."] = "在天灾军团中幸存的高等精灵开始自称血精灵，以纪念他们阵亡的同胞。凯尔萨斯领导着他们。",
	["Los antídotos que haces curan venenos. ¡En las arañas de Vallefresno se agradecen!"] = "你做的抗毒药剂能解毒。对付灰谷的蜘蛛时特别受欢迎！",
	["Los anuncios esperan a que el juego termine de escribir la zona, y el botón de Alfa queda siempre a la vista en el minimapa."] = "公告会等游戏写完区域名称再出现，Alfa 的按钮在小地图上始终可见。",
	["Los aqir eran un imperio antiguo de insectos que peleó contra los trols. De ellos vienen los qiraji de Ahn'Qiraj y los nerubianos del norte."] = "阿基尔是一个与巨魔交战的古老虫族帝国。安其拉的其拉虫人和北方的蛛魔都源自他们。",
	["Los avisos"] = "提示",
	["Los avisos de viaje hablan como la manada: «La manada viaja», el lobo en el aro y una huellita que camina mientras llega tu barco."] = "旅行提醒像狼群一样说话：“狼群出行”，环中的狼，还有船到来时一路前行的爪印。",
	["Los avisos pequeños de Alfa los dice Lya en su globo, con su botón, en vez de salir arriba. Si está oculta o en combate, salen como siempre."] = "Alfa 的小提醒由莉娅在气泡里说出，带着按钮，不再弹在上方。她隐藏或你在战斗中时，照常显示。",
	["Los ayudantes de los enemigos."] = "敌人的帮手。",
	["Los botones de otros addons alrededor del minimapa solo aparecen al pasar el ratón por encima. El de Alfa siempre queda a la vista."] = "小地图周围其他插件的按钮只在鼠标移上去时才显示。Alfa 的按钮始终显示。",
	["Los cebos suben tu habilidad de pesca un rato: úsalos en aguas difíciles."] = "鱼饵能暂时提高你的钓鱼技能：在难钓的水域用上。",
	["Los cementerios del Ocaso están llenos de no-muertos levantados por nigromantes que se esconden en el bosque."] = "暮色森林的墓地里满是被藏身林中的死灵法师唤起的亡灵。",
	["Los centauros dicen descender de Zaetar, hijo del semidiós Cenarius, y de Theradras, la princesa de la tierra. Pelean entre sus clanes casi tanto como contra los demás."] = "半人马自称是半神塞纳留斯之子扎尔塔与大地公主瑟莱德丝的后代。他们各部族之间的内斗几乎和对外作战一样多。",
	["Los cinco Aspectos Dragón recibieron su poder de los titanes: Alexstrasza la vida, Ysera el sueño, Nozdormu el tiempo, Malygos la magia y Neltharion la tierra."] = "五位守护巨龙的力量来自泰坦：阿莱克丝塔萨掌管生命，伊瑟拉掌管梦境，诺兹多姆掌管时间，玛里苟斯掌管魔法，耐萨里奥掌管大地。",
	["Los clanes Gelkis y Magram de Desolace pelean entre sí, y ambos buscan aliados entre los aventureros."] = "凄凉之地的吉尔吉斯和玛格拉姆部族互相争斗，双方都在冒险者中寻找盟友。",
	["Los clanes orcos tienen historias distintas: Lobo Gélido, Grito de Guerra, Roca Negra, Faucedraco... cada uno con su orgullo."] = "兽人各氏族的历史各不相同：霜狼、战歌、黑石、龙喉……每个都有自己的骄傲。",
	["Los cruzados escarlata vienen en grupos y algunos curan: interrumpan a los que curan."] = "血色十字军成群出现，有些会治疗：打断治疗者。",
	["Los críticos hacen el doble de daño y al guerrero le dan más ira."] = "暴击造成双倍伤害，还能给战士更多怒气。",
	["Los cuatro dragones verdes de la pesadilla, Ysondre, Lethon, Emeriss y Taerar, aparecen junto a los grandes árboles del Sueño."] = "梦魇中的四只绿龙——伊森德雷、莱索恩、艾莫莉丝和泰拉尔——会出现在梦境之树旁。",
	["Los cuatro señores elementales son Ragnaros del fuego, Al'Akir del aire, Therazane de la tierra y Neptulon del agua."] = "四大元素领主是火焰的拉格纳罗斯、风的奥拉基尔、大地的塞拉赞恩和水的耐普图隆。",
	["Los cultistas del Martillo Crepuscular usan piedras de viento para invocar a sus señores; con su disfraz, tú también puedes."] = "暮光之锤的信徒用风石召唤他们的领主；穿上他们的伪装，你也可以。",
	["Los datos de Alfa no cargaron (%s)."] = "Alfa 的数据没有载入（%s）。",
	["Los datos de Alfa no traen botín propio de sus jefes."] = "Alfa 的数据中没有它的首领专属战利品。",
	["Los datos de las mazmorras no están cargados."] = "地下城数据尚未加载。",
	["Los datos de las mazmorras se cargan fuera de combate. Esta página se llena sola al terminar la pelea."] = "地下城数据会在脱离战斗后载入。战斗结束后此页面会自动填满。",
	["Los datos del mundo (Codex) no están disponibles: faltan los bancos, las misiones y de dónde sale cada cosa."] = "世界数据（Codex）不可用：缺少鱼群、任务以及各种东西的来源。",
	["Los datos del mundo de Alfa están apagados: activa «Alfa Codex» en la lista de addons."] = "Alfa 的世界数据已关闭：请在插件列表中启用“Alfa Codex”。",
	["Los datos son del medidor oficial del juego: tú, tu grupo o banda y sus mascotas."] = "数据来自游戏官方的伤害统计：你、你的小队或团队以及他们的宠物。",
	["Los dioses antiguos son seres de antes de los titanes, encerrados bajo la tierra de Azeroth. C'Thun y Yogg-Saron susurran a quien quiera escuchar."] = "上古之神是比泰坦更古老的存在，被囚禁在艾泽拉斯的地底。克苏恩和尤格-萨隆会向任何愿意倾听的人低语。",
	["Los dioses antiguos susurran en la mente de los mortales; muchos cultos, como el Martillo Crepuscular, nacieron de escucharlos."] = "上古之神在凡人的脑海中低语；许多邪教，比如暮光之锤，都是因为听信了他们而诞生的。",
	["Los dos"] = "两者",
	["Los dos bandos"] = "两个阵营",
	["Los dracoleones son las monturas voladoras de la Horda; los grifos, las de la Alianza; y los hipogrifos, las de los elfos de la noche."] = "双足飞龙是部落的飞行坐骑；狮鹫是联盟的；角鹰兽则属于暗夜精灵。",
	["Los dracónidos negros rondan la entrada de la guarida de Onyxia, al sur del marjal."] = "黑龙人在沼泽南部奥妮克希亚巢穴的入口处巡逻。",
	["Los dracónidos son los soldados de los dragones; los negros sirven a Nefarian en la Montaña Roca Negra."] = "龙人是巨龙的士兵；黑色的龙人在黑石山为奈法利安效力。",
	["Los draenei huyeron de su mundo, Argus, con el profeta Velen. Su nombre quiere decir «los exiliados»."] = "德莱尼跟随先知维伦逃离了他们的世界阿古斯。他们的名字意为“流亡者”。",
	["Los dragones cromáticos, con escamas de todos los colores, son experimentos de Nefarian. Su obra más temida es Chromaggus."] = "鳞片五颜六色的多彩龙是奈法利安的实验品。他最可怕的作品是克洛玛古斯。",
	["Los dragones negros se disfrazan de humanos para engañar: Onyxia es Lady Katrana Prestor en Ventormenta, y Nefarian se hace llamar Lord Victor Nefarius."] = "黑龙会伪装成人类来骗人：奥妮克希亚在暴风城是卡特拉娜·普瑞斯托女士，奈法利安则自称维克多·奈法里奥斯领主。",
	["Los dragones verdes siguen vigilando el templo hundido para que nadie vuelva a llamar a Hakkar."] = "绿龙仍在看守沉没的神庙，免得有人再次召唤哈卡。",
	["Los elementales de fuego de La Garganta de Fuego y del Cráter de Un'Goro sueltan materiales de fuego que piden muchas profesiones."] = "灼热峡谷和安戈洛环形山的火元素会掉落许多专业都需要的火焰材料。",
	["Los elementales de fuego y las arañas de lava son los vecinos de siempre de La Garganta de Fuego."] = "火元素和熔岩蜘蛛是灼热峡谷的老邻居。",
	["Los elfos de la noche fueron inmortales gracias a Nordrassil, hasta que lo sacrificaron para vencer a Archimonde en el Monte Hyjal."] = "暗夜精灵曾因诺达希尔而永生，直到他们为了在海加尔山击败阿克蒙德而将它牺牲。",
	["Los elfos de la noche montan sables, grandes felinos. No es por nada, pero un lobo es más simpático."] = "暗夜精灵骑的是豹，一种大型猫科动物。不是我自夸，狼可亲切多了。",
	["Los elfos de la noche nuevos empiezan en la Cañada Umbría, en Teldrassil, entre arañas y fuegos fatuos."] = "新的暗夜精灵从泰达希尔的幽影谷开始，身边是蜘蛛和小精灵。",
	["Los elfos de la noche pueden fundirse con las sombras cuando se quedan quietos."] = "暗夜精灵站着不动时能融入阴影。",
	["Los elfos de la noche se unieron a la Alianza después de la Tercera Guerra."] = "暗夜精灵在第三次战争后加入了联盟。",
	["Los enanos Hierro Negro tomaron Dun Modr, al norte de Los Humedales, y desde ahí molestan a quien cruce el puente."] = "黑铁矮人占领了湿地北部的丹莫德，在那里骚扰所有过桥的人。",
	["Los enanos creen descender de los terráneos de piedra de los titanes, y por eso la Liga de Expedicionarios excava sin parar."] = "矮人相信自己是泰坦的岩石土灵的后裔，所以探险者协会不停地挖掘。",
	["Los enanos de Forjaz pelean contra los Hierro Negro en Los Humedales y en las Tierras Inhóspitas."] = "铁炉堡的矮人在湿地和荒芜之地与黑铁矮人作战。",
	["Los enanos nuevos empiezan en un valle helado de Dun Morogh, peleando contra trols de las nieves y troggs."] = "新的矮人从丹莫罗一座冰冷的山谷开始，对抗冰霜巨魔和穴居人。",
	["Los encantadores también hacen varitas: los magos, sacerdotes y brujos te lo agradecerán."] = "附魔师也能做魔杖：法师、牧师和术士都会感谢你。",
	["Los enemigos cercanos pegan menos. Muy útil cuando tanqueas a varios."] = "附近敌人的攻击变弱。同时坦克好几个时非常有用。",
	["Los enemigos de alrededor pegan menos."] = "周围的敌人造成的伤害降低。",
	["Los enemigos de tus misiones marcados sobre su placa de nombre y los objetos de misión brillando en tus bolsas."] = "你任务中的敌人会在姓名板上标出，任务物品会在背包中发光。",
	["Los enemigos lanzan radiación y veneno: lleven pociones de vida."] = "敌人会释放辐射和毒素：带上治疗药水。",
	["Los enemigos más débiles, que el juego marca con un signo de menos."] = "最弱的敌人，游戏会用减号标示它们。",
	["Los errores de Alfa que se atraparon, para copiarlos en tu reporte."] = "捕获到的 Alfa 错误，可复制到你的报告里。",
	["Los espíritus de las elfas caídas que la Plaga esclaviza se vuelven banshees. Sylvanas es la más famosa de todas."] = "被天灾军团奴役的阵亡精灵女性的灵魂会变成女妖。希尔瓦娜斯是其中最有名的一位。",
	["Los fragmentos de alma se ganan drenando el alma del enemigo justo cuando muere."] = "在敌人死亡的那一刻吸取它的灵魂，就能获得灵魂碎片。",
	["Los frascos del Clásico duran dos horas y aguantan aunque mueras: por eso las bandas los piden tanto."] = "经典版的合剂能持续两小时，死亡也不会消失：所以团队这么需要它们。",
	["Los frascos los venden los proveedores de alquimia. Herboristería es su mejor pareja: tú juntas las hierbas."] = "炼金用品商人出售瓶子。草药学是它最好的搭档：草药自己采。",
	["Los frascos más poderosos llevan Loto negro, la hierba más rara de Azeroth."] = "最强的合剂需要黑莲花，这是艾泽拉斯最稀有的草药。",
	["Los fuegos artificiales también son ingeniería. ¡Uno para festejar cada nivel!"] = "烟花也是工程学的一部分。每升一级就放一个庆祝吧！",
	["Los fuegos fatuos son espíritus de elfos de la noche que siguen cuidando el bosque después de morir."] = "小精灵是暗夜精灵的灵魂，死后仍继续守护着森林。",
	["Los furbolgs Fauces de Madera son de los pocos que no se han corrompido; sus túneles llevan a Cuna del Invierno y al Claro de la Luna."] = "木喉熊怪是少数没有被腐化的熊怪；他们的隧道通往冬泉谷和月光林地。",
	["Los furbolgs de Costa Oscura se están corrompiendo, y los elfos de Auberdine no saben bien por qué."] = "黑海岸的熊怪正在被腐化，奥伯丁的精灵们也不太清楚原因。",
	["Los furbolgs eran un pueblo pacífico de hombres oso, pero la corrupción de los demonios enloqueció a muchas de sus tribus."] = "熊怪原本是爱好和平的熊人种族，但恶魔的腐化让他们许多部族都发了疯。",
	["Los geomantes lanzan fuego y ponen tótems: interrúmpanlos y rompan los tótems."] = "地占师会施放火焰并放下图腾：打断他们并打掉图腾。",
	["Los gnomos empiezan con los enanos en Dun Morogh: Gnomeregan está perdida y tu gente vive refugiada en Forjaz."] = "侏儒和矮人一起从丹莫罗开始：诺莫瑞根已经失守，你的族人在铁炉堡避难。",
	["Los gnomos inventaron el Tranvía Subterráneo que une Forjaz con Ventormenta."] = "侏儒建造了连接铁炉堡和暴风城的矿道地铁。",
	["Los gnomos que se quedaron en Gnomeregan quedaron dañados por la radiación; algunos perdieron la razón."] = "留在诺莫瑞根的侏儒受到了辐射伤害；有些人失去了理智。",
	["Los goblins de la fundición tienen ayudantes cerca: miren alrededor antes de atacar."] = "铸造厂里的地精附近还有帮手：动手前先看看周围。",
	["Los goblins vienen de la isla de Kezan, y su gran ciudad es Minahonda. Le son más leales al oro que a cualquier bando."] = "地精来自科赞岛，他们的大城市是安德麦。比起任何阵营，他们更忠于金币。",
	["Los grandes árboles que hablan en Darnassus y Vallefresno son Ancestros, guardianes del bosque."] = "达纳苏斯和灰谷那些会说话的大树是古树，森林的守护者。",
	["Los grifos (o dragones) a los lados de la barra principal."] = "主动作条两侧的狮鹫（或双足飞龙）。",
	["Los grifos (o dragones) a los lados de la barra principal. «Del color del estilo» necesita el estilo de las barras; «Ocultos» funciona siempre."] = "主动作条两侧的狮鹫（或双足飞龙）。“风格颜色”需要开启动作条风格；“隐藏”始终有效。",
	["Los gules, las abominaciones y las gárgolas son los soldados más comunes de la Plaga. Las abominaciones se cosen con partes de muchos cadáveres."] = "食尸鬼、憎恶和石像鬼是天灾军团最常见的士兵。憎恶是用许多尸体的部位缝起来的。",
	["Los herreros hacen llaves que abren cofres y cajas cerradas. ¡Útil y divertido!"] = "铁匠能打造钥匙，打开宝箱和上锁的箱子。又实用又好玩！",
	["Los humanos fueron los primeros en aprender magia de los altos elfos, allá en las Guerras Trol."] = "早在巨魔战争时期，人类就是第一个向高等精灵学习魔法的种族。",
	["Los infernales son demonios que la Legión arroja desde el cielo como meteoritos."] = "地狱火是燃烧军团像陨石一样从天上扔下来的恶魔。",
	["Los ingenieros pueden fabricar mascotas mecánicas, como una ardilla."] = "工程师可以制造机械宠物，比如一只松鼠。",
	["Los instructores y vendedores de pesca se ven en el mapa y el minimapa."] = "钓鱼训练师和商人会显示在地图和小地图上。",
	["Los jefes opcionales y raros se descubren al terminar la mazmorra."] = "可选首领和稀有首领会在完成地下城后揭晓。",
	["Los jefes se descubren al vencerlos: su nombre y su botín quedan ocultos hasta entonces. Sus consejos siempre se pueden ver."] = "首领在被击败后才会揭晓：在此之前其名字和战利品保持隐藏。建议则随时可以查看。",
	["Los kits de armadura que haces le sirven a todo el mundo: siempre hay quien los compre."] = "你做的护甲片对每个人都有用：总有人会买。",
	["Los kodos son los compañeros de viaje de los tauren, y en Desolace está su cementerio."] = "科多兽是牛头人的旅伴，它们的坟场在凄凉之地。",
	["Los kóbolds de las minas de Elwynn cuidan sus velas como un tesoro: bajo tierra, la luz lo es todo."] = "艾尔文森林矿洞里的狗头人把蜡烛当宝贝一样守护：在地底下，光就是一切。",
	["Los lobos aprenden Aullido furioso, que sube el daño de tu grupo. ¡Ya ves, los lobos somos lo máximo!"] = "狼会学会狂怒之嚎，能提升你队伍的伤害。看吧，我们狼是最棒的！",
	["Los lobos de tu zona saben dónde estás. Te aviso quién viene."] = "区域里的狼知道你在哪。我会告诉你谁来了。",
	["Los lobos que se dejan ver en el mapa. Un clic en su marca y la flecha te lleva."] = "允许在地图上被看到的狼。点击它们的标记，箭头就会带你过去。",
	["Los lobos que usan Alfa y se dejan ver en el mapa, y tu grupo, que ves ahora."] = "使用 Alfa 并允许在地图上被看到的狼，以及你现在看到的队伍成员。",
	["Los logros de la manada: se ganan pescando, cocinando lo que pescas y explorando aguas nuevas. Cada uno se anuncia una sola vez."] = "狼群的成就：通过钓鱼、烹饪钓到的鱼和探索新水域来获得。每个成就只宣布一次。",
	["Los lugares que pides ver en el mapa desde la Enciclopedia."] = "你从百科中要求在地图上显示的地点。",
	["Los maestros de vuelo de tu facción y los neutrales: verdes si ya los conoces, ámbar con «?» si te falta descubrirlos. Clic: seguirlo con la flecha."] = "你阵营和中立的飞行管理员：已知的显示为绿色，尚未发现的显示为琥珀色并带“?”。点击：用箭头跟随它。",
	["Los maestros de vuelo de tu zona que todavía no conoces, resaltados. Clic: la flecha te lleva."] = "你所在区域里还不认识的飞行管理员，会被高亮。点击：箭头带你去。",
	["Los magos de Dalaran forman el Kirin Tor, su consejo de sabios."] = "达拉然的法师组成了他们的贤者议会肯瑞托。",
	["Los marcos de Curación están apagados"] = "治疗框体已关闭",
	["Los marcos se mueven fuera de combate."] = "框体只能在非战斗状态下移动。",
	["Los marcos, fondos, botones y letras del propio juego, con títulos en oro."] = "游戏自带的框体、背景、按钮和字体，标题为金色。",
	["Los mismos marcadores de misiones en el minimapa."] = "在小地图上显示同样的任务标记。",
	["Los múrlocs hablan con gorgoteos y burbujas: ese «mrglglgl» es su idioma de verdad."] = "鱼人用咕噜声和泡泡说话：那句“mrglglgl”就是他们真正的语言。",
	["Los nagas y sátiros lanzan escarcha y rayos: interrumpan a los lanzadores primero."] = "纳迦和萨特会施放冰霜和闪电：先打断施法者。",
	["Los nerubianos, arañas gigantes de Rasganorte, pelearon contra el Rey Exánime y perdieron; muchos hoy le sirven."] = "诺森德的巨型蜘蛛蛛魔曾与巫妖王作战并落败；如今许多蛛魔为他效力。",
	["Los no-muertos de la Plaga no sienten miedo ni cansancio, y por eso es tan difícil detenerlos."] = "天灾军团的亡灵不知恐惧也不知疲倦，所以才这么难以阻挡。",
	["Los nodos de la zona que miras, con su nombre, nivel y cuántas veces los recolectaste al pasar el ratón. Clic en uno: la flecha te lleva."] = "你正在查看的区域中的采集点；鼠标指向可查看名称、等级和你采集过的次数。点击一个：箭头会带你过去。",
	["Los nodos que se pisarían en pantalla van en un solo pin con su cantidad. Al acercar el mapa se separan."] = "在屏幕上会重叠的采集点合并成一个图钉并显示数量。放大地图后就会分开。",
	["Los nodos que tienes cerca. El punto del rastreo del juego dice si ahora hay algo ahí."] = "你附近的采集点。游戏追踪的小点会告诉你那里现在有没有东西。",
	["Los nodos que trae Alfa. Sin esto solo ves los que tú descubriste."] = "Alfa 自带的采集点。不勾选时只显示你自己发现的。",
	["Los números de las habilidades de tu mascota."] = "你宠物技能的伤害数字。",
	["Los números de lo que curas encima de quien recibe."] = "你的治疗数字，显示在受治疗者上方。",
	["Los números de los golpes de tu mascota."] = "你宠物近战攻击的伤害数字。",
	["Los números de tu daño encima de quien golpeas."] = "你的伤害数字，显示在被你攻击的目标上方。",
	["Los números son orientativos: cada receta da puntos según su color (naranja siempre, amarillo casi siempre, verde a veces)."] = "数字仅供参考：每个配方按颜色给点数（橙色必定涨、黄色几乎都涨、绿色有时涨）。",
	["Los oasis de Los Baldíos se están secando y llenando de bestias raras: los Druidas del Colmillo, que salieron de las Cuevas de los Lamentos, los corrompen."] = "贫瘠之地的绿洲正在干涸，到处是怪异的野兽：从哀嚎洞穴出来的尖牙德鲁伊正在腐化它们。",
	["Los objetos se juntan al final de tus bolsas en lugar de al principio."] = "物品集中到背包末尾，而不是开头。",
	["Los orcos Faucedraco siguen en Los Humedales, aunque ya sin la Reina Dragón."] = "龙喉兽人还在湿地，虽然已经失去了巨龙女王。",
	["Los orcos Roca Negra de Rend se adueñaron de la cumbre de la montaña y la llaman su hogar."] = "雷德的黑石兽人占据了山顶，把那里当成自己的家。",
	["Los orcos Roca Negra ocupan una vieja fortaleza humana al este de las montañas."] = "黑石兽人占据着山脉东边一座古老的人类要塞。",
	["Los orcos llegaron de Draenor corrompidos por la sangre de Mannoroth. Thrall los sacó de los campos de internamiento y fundó la nueva Horda."] = "兽人从德拉诺来到这里时，已被玛诺洛斯之血腐化。萨尔把他们从收容所中解救出来，建立了新部落。",
	["Los orcos nuevos empiezan en el Valle de los Retos, en Durotar, donde prueban su valor."] = "新的兽人从杜隆塔尔的试炼谷开始，在那里证明自己的勇气。",
	["Los orcos vienen de Draenor, un mundo que hoy está roto y se llama Terrallende."] = "兽人来自德拉诺，那个世界如今已经破碎，被称为外域。",
	["Los otros %d puntos del plan llegan con tus próximos niveles."] = "方案中其余 %d 点会随着你接下来的升级获得。",
	["Los peleteros hacen carcajes y bolsas de munición para los cazadores."] = "制皮师会为猎人制作箭袋和弹药袋。",
	["Los polvos y las esencias salen de desencantar equipo verde o mejor. Cada tanto tu instructor te pide una varilla rúnica nueva."] = "尘和精华来自分解绿色或更好的装备。训练师时不时会要你做一根新的符文棒。",
	["Los portales a pie que puedes usar, con a dónde llevan."] = "你可以步行进入的传送门，以及它们通往哪里。",
	["Los precios cambian: después de estos días Alfa te recuerda escanear otra vez."] = "价格会变动：超过这些天数后，Alfa 会提醒你重新扫描。",
	["Los primeros caballeros de la muerte los creó Gul'dan: cuerpos de caballeros humanos caídos con almas de brujos orcos."] = "第一批死亡骑士是古尔丹创造的：阵亡人类骑士的躯体，装着兽人术士的灵魂。",
	["Los puntos de ruta que ponen otros addons, y el comando /way, apuntan la flecha de Alfa. Un addon que espere los ajustes de otro addon de puntos de ruta puede no funcionar con esto encendido."] = "其他插件设置的路径点以及 /way 命令会由 Alfa 的箭头指引。开启后，依赖其他路径点插件自身设置的插件可能无法正常工作。",
	["Los puntos de vuelo y de viaje ya se ven en el mapa."] = "飞行点和旅行地点现在会显示在地图上。",
	["Los puntos que ganas en la cuenta también llenan el registro del Legado: premios de aspecto, sin ventaja en el juego. Al salir Forever son un rifle de réplica de Forjaz (juguete), la cría de oso espectral (mascota), el tabardo del oso espectral y las riendas del oso espectral (montura)."] = "你在账号上获得的点数也会填充传承奖励进度：外观奖励，不影响游戏平衡。Forever 上线时的奖励有铁炉堡气枪复制品（玩具）、幽灵熊宝宝（宠物）、幽灵熊战袍和幽灵熊缰绳（坐骑）。",
	["Los puntos que ganas también llenan el registro del Legado, con premios de aspecto como la cría de oso espectral."] = "你获得的点数也会填充传承奖励进度，奖励有幽灵熊宝宝之类的外观物品。",
	["Los raros están apagados (página Descubrir)."] = "稀有已关闭（“发现”页面）。",
	["Los raros que cayeron hace poco"] = "最近被击杀的稀有怪",
	["Los raros también en el minimapa."] = "在小地图上也显示稀有。",
	["Los recolectaste %d veces en total"] = "你总共采集过 %d 次",
	["Los rincones de tu zona que todavía no pisas, con la experiencia que da descubrirlos."] = "你区域里还没去过的角落，以及探索它们能获得的经验。",
	["Los sacerdotes Atal'ai siguieron adorando a Hakkar en secreto. Los desterraron, y levantaron su templo en el Pantano de las Penas."] = "阿塔莱祭司秘密地继续崇拜哈卡。他们被流放后，在悲伤沼泽建起了神庙。",
	["Los servicios también en el minimapa."] = "在小地图上也显示服务。",
	["Los señores del terror, como Mal'Ganis, Balnazzar y Varimathras, eran los carceleros que la Legión le puso al Rey Exánime."] = "恐惧魔王，比如玛尔加尼斯、巴纳扎尔和瓦里玛萨斯，是燃烧军团派来看守巫妖王的狱卒。",
	["Los señores elementales servían a los dioses antiguos. Cuando los titanes encerraron a esos dioses, desterraron a los elementales a sus propios planos."] = "元素领主曾效忠于上古之神。泰坦囚禁了那些神之后，把元素放逐到了它们自己的位面。",
	["Los spots de farmeo están apagados (Ajustes de La Jauría)."] = "刷点已关闭（La Jauría 设置）。",
	["Los sumos sacerdotes de Zul'Gurub tomaron el poder de los loa animales: el murciélago, la serpiente, la araña, la pantera y el tigre."] = "祖尔格拉布的高阶祭司夺取了动物洛阿的力量：蝙蝠、蛇、蜘蛛、豹和虎。",
	["Los sátiros de Azshara sueltan tela vil, muy buscada por los sastres."] = "艾萨拉的萨特会掉落恶魔布，裁缝们非常抢手。",
	["Los talentos confirmados no se quitan gratis: revisa la lista antes de aceptar."] = "确认后的天赋无法免费重置：接受前请检查列表。",
	["Los talentos que siguen en el plan no están en tu árbol o no se pueden tomar todavía. Ponlos a mano en la ventana de talentos del juego o elige otro build."] = "方案中接下来的天赋不在你的天赋树中，或暂时无法点。请在游戏的天赋窗口中手动点，或选择其他方案。",
	["Los tauren Tótem Siniestro tienen campamentos en Las Mil Agujas, y no son nada amigables."] = "恐怖图腾牛头人在千针石林有营地，一点也不友善。",
	["Los tauren ayudaron a los Renegados a entrar a la Horda, con la esperanza de encontrarles una cura."] = "牛头人帮助被遗忘者加入了部落，希望能为他们找到解药。",
	["Los tauren de Viento Libre viven en lo alto de Las Mil Agujas, a salvo de los centauros."] = "乱风岗的牛头人住在千针石林的高处，远离半人马。",
	["Los tauren de Viento Libre viven en lo alto de las agujas, unidas por puentes colgantes, a salvo de los centauros de abajo."] = "乱风岗的牛头人住在石针顶上，彼此之间以吊桥相连，远离下方的半人马。",
	["Los tauren honran a la Madre Tierra. Dicen que el sol y la luna son sus ojos: An'she y Mu'sha."] = "牛头人崇敬大地母亲。他们说太阳和月亮是她的眼睛：安舍和穆莎。",
	["Los tauren llaman An'she al sol y Mu'sha a la luna: los ojos de la Madre Tierra."] = "牛头人把太阳叫做安舍，把月亮叫做穆莎：它们是大地母亲的眼睛。",
	["Los tauren nuevos empiezan en el Campamento Narache, en Mulgore."] = "新的牛头人从莫高雷的纳拉其营地开始。",
	["Los tauren vivían como nómadas, acosados por los centauros, hasta que Cairne Pezuña de Sangre se alió con Thrall. Con la ayuda de la Horda encontraron su hogar en Mulgore."] = "牛头人曾过着游牧生活，饱受半人马侵扰，直到凯恩·血蹄与萨尔结盟。在部落的帮助下，他们在莫高雷找到了家园。",
	["Los tesoros también en el minimapa."] = "在小地图上也显示宝藏。",
	["Los titanes dejaron guardianes de piedra y metal en Azeroth. En Uldaman todavía hay uno despierto: Archaedas."] = "泰坦在艾泽拉斯留下了岩石与金属的守护者。奥达曼里还有一位醒着：阿扎达斯。",
	["Los titanes le dieron forma a Azeroth y dejaron guardianes y ciudades, como Uldaman, para cuidar su obra."] = "泰坦塑造了艾泽拉斯，并留下守护者和像奥达曼这样的城市来照看他们的作品。",
	["Los titanes son seres colosales que recorren el cosmos poniendo orden en los mundos. Los más famosos forman el Panteón, que guiaba Aman'Thul."] = "泰坦是在宇宙中巡游、为各个世界带来秩序的巨大存在。最有名的泰坦组成了万神殿，曾由阿曼苏尔领导。",
	["Los titanes usaron este cráter como un jardín de pruebas para la vida; por eso hay dinosaurios y plantas gigantes."] = "泰坦把这个火山口当作生命的试验花园；所以这里有恐龙和巨大的植物。",
	["Los troggs huyen cuando tienen poca vida y traen amigos: deténganlos antes de que escapen."] = "穴居人血量低时会逃跑并叫来同伴：在它们逃走前拦住。",
	["Los troggs invadieron Gnomeregan, y los gnomos inundaron su propia ciudad de radiación al intentar sacarlos. Fue idea del mekigeniero Termochufe."] = "穴居人入侵了诺莫瑞根，侏儒们为了把他们赶出去，反而让自己的城市充满了辐射。这是麦克尼尔·瑟玛普拉格的主意。",
	["Los troggs salieron de las profundidades de Uldaman. Todo indica que son una creación antigua de los titanes que salió mal."] = "穴居人是从奥达曼的深处出来的。种种迹象表明，他们是泰坦一项失败的古老造物。",
	["Los trols Lanza Negra conocieron a Thrall en las islas donde naufragó su flota rumbo a Kalimdor. Su líder Sen'jin murió ahí, y desde entonces los guía su hijo Vol'jin."] = "暗矛巨魔是在萨尔前往卡利姆多途中舰队失事的岛上遇见他的。他们的首领森金死在那里，此后一直由他的儿子沃金领导他们。",
	["Los trols Lanza Negra empiezan con los orcos, en el Valle de los Retos de Durotar."] = "暗矛巨魔和兽人一起，从杜隆塔尔的试炼谷开始。",
	["Los trols adoran a espíritus llamados loa. Hakkar es uno de ellos, y de los más peligrosos."] = "巨魔崇拜一种叫做洛阿的神灵。哈卡就是其中之一，也是最危险的之一。",
	["Los trols de estas tierras descienden de los Amani, el antiguo imperio de los trols del bosque. En Jintha'Alor siguen levantando sus altares."] = "这片土地上的巨魔是阿曼尼的后裔，那是森林巨魔的古老帝国。他们仍在辛萨罗建造祭坛。",
	["Los vendedores de suministros de pesca tienen cañas, lombrices y baratijas."] = "钓鱼用品商人出售鱼竿、蚯蚓和闪亮的小玩意。",
	["Los worgen son hombres lobo de origen misterioso. Arugal los trajo a Lordaeron. ¡No me confundas con ellos, eh!"] = "狼人是来历神秘的人狼。是阿鲁高把他们带到了洛丹伦。可别把我跟他们搞混了！",
	["Los zepelines salen de las torres junto a Orgrimmar hacia Entrañas y hacia Grom'gol, en la Vega de Tuercespina."] = "飞艇从奥格瑞玛旁边的塔楼出发，开往幽暗城和荆棘谷的格罗姆高。",
	["Los árboles del Legado son tres: Profesiones, Aventura y Recursos. Al salir Forever, cada personaje gasta hasta 16 puntos."] = "传承天赋树共有三棵：专业、冒险和足智多谋。Forever 上线时，每个角色最多可花费 16 点。",
	["Los élites y los raros de tu zona que te pueden ganar: en rojo los que te pasan por mucho. Se arman al abrir el mapa de Alfa."] = "你区域里能打败你的精英和稀有怪：远高于你等级的以红色显示。打开 Alfa 地图时生成。",
	["Los íconos, los nombres y tu flecha se mueven pegados al mapa al hacer zoom o arrastrar: ya no brincan un píxel."] = "缩放或拖动时，图标、名称和你的箭头紧贴地图移动：不再跳动一个像素。",
	["Los últimos Altonato de Kalimdor siguen en La Masacre: se llaman Shen'dralar y cuidan su vieja biblioteca."] = "卡利姆多最后的上层精灵仍留在厄运之槌：他们叫辛德拉，守护着他们古老的图书馆。",
	["Los últimos puntos."] = "最后几点。",
	["Lothar cayó ante Orgrim Martillo Maldito al pie de la Montaña Roca Negra. Turalyon tomó su lugar y ganó la Segunda Guerra."] = "洛萨在黑石山脚下败给了奥格瑞姆·毁灭之锤。图拉扬接替了他，赢得了第二次战争。",
	["Luego"] = "稍后",
	["Luego cópialo con Ctrl+C."] = "然后按 Ctrl+C 复制。",
	["Lugar"] = "位置",
	["Lugar conocido: el punto del rastreo del juego dice si ahora hay algo."] = "已知地点：游戏追踪的小点会告诉你现在有没有东西。",
	["Lugar de los marcos"] = "框体位置",
	["Lugar desconocido"] = "未知地点",
	["Lugar: %s"] = "地点：%s",
	["Luna"] = "月光",
	["Lunes"] = "星期一",
	["Luz y efectos"] = "光照与特效",
	["Lya"] = "Lya",
	["Lya ahora es una loba negra de cuerpo completo, con 39 cuadros de animación: se sienta, corre, se busca la cola, bosteza y duerme enroscada."] = "Lya 现在是一匹全身的黑色母狼，有 39 帧动画：她会坐下、奔跑、追自己的尾巴、打哈欠，还会蜷成一团睡觉。",
	["Lya aprende"] = "莉娅在学习",
	["Lya apunta aquí tus pasos grandes: tu primera mazmorra, tus niveles, tu primera montura y más."] = "莉娅在这里记下你的重要时刻：第一个地下城、你的等级、第一只坐骑等等。",
	["Lya apunta tus pasos grandes (tu primera mazmorra, tus niveles, tu primera montura...) y festeja cada página nueva."] = "莉娅记下你的重要时刻（第一个地下城、你的等级、第一只坐骑……），并庆祝每一页新篇章。",
	["Lya contigo"] = "莉娅陪着你",
	["Lya cuenta historias"] = "Lya 讲故事",
	["Lya de cuerpo completo"] = "全身的 Lya",
	["Lya descansa. La llamas con /alfa lya o /alfa ayuda cuando quieras."] = "莉娅休息了。想找她就用 /alfa lya 或 /alfa ayuda。",
	["Lya en las mazmorras"] = "地下城里的莉娅",
	["Lya en las mazmorras, con ánimo, su salchicha y su despedida; y te enseña Alfa en 5 pasos."] = "莉娅进地下城、有情绪、要香肠、会道别；还会用 5 步带你认识 Alfa。",
	["Lya en tu pantalla"] = "屏幕上的 Lya",
	["Lya encontró un tesoro"] = "莉娅找到了宝藏",
	["Lya es quien olfatea los raros y los tesoros: su tarjeta trae «Ir de caza», «Su ficha» y «Seleccionarlo»."] = "稀有怪和宝藏由莉娅嗅出：她的卡片有“去狩猎”、“它的资料”和“选中它”。",
	["Lya está calladita"] = "Lya 安静下来了",
	["Lya está descansando"] = "Lya 正在休息",
	["Lya festeja cuando un lobo de tu hermandad llega al nivel 60, consigue su primera montura o caza un raro."] = "当公会里的狼升到 60 级、拿到第一匹坐骑或猎到稀有怪时，莉娅会一起庆祝。",
	["Lya fue una gran perrita: noble, leal y siempre al lado de los suyos, la gordita consentida de la casa. Alfa la recuerda así, como la loba que cuida a la manada y nunca deja a nadie atrás."] = "Lya 是一只很棒的小狗：高贵、忠诚，总是陪在家人身边，是家里被宠坏的小胖妞。Alfa 就这样记住她，把她当作守护狼群、从不丢下任何人的母狼。",
	["Lya guarda la historia de cada misión que tomas, aunque la aceptes sin leerla. Tú sigue la flecha: ella se acuerda de todo."] = "Lya 会保存你接下的每个任务的故事，即使你没读就接受了。你只管跟着箭头走：她什么都记得。",
	["Lya lleva tu historia, aprende qué consejos ya no quieres y te avisa de tus oficios."] = "莉娅记录你的故事，学会你不再想听的建议，并提醒你的专业。",
	["Lya olfateó un raro"] = "莉娅嗅到了稀有怪",
	["Lya platica mucho más: lore de Warcraft, datos de cada zona, de tu raza, tu clase y tus profesiones, y consejos de eventos y de farmeo. ¡Y le encantan las salchichas!"] = "Lya 的话多了很多：魔兽世界的背景故事、每个区域的趣闻，你的种族、职业和专业，还有节日和刷怪的建议。而且她超爱香肠！",
	["Lya platica según la hora del día, las fiestas de Azeroth y la zona donde andas."] = "莉娅会聊聊一天中的时刻、艾泽拉斯的节日，以及你所在的区域。",
	["Lya recuerda lo que te dijo, tiene una tecla para su botón y te cuenta tu semana de caza y tu mejor día."] = "莉娅记得对你说过的话，她的按钮有专属按键，还会告诉你本周狩猎和最佳一天。",
	["Lya saluda a tu mascota y, si eres cazador, te avisa cuando tiene hambre o está triste."] = "莉娅会跟你的宠物打招呼；如果你是猎人，它饿了或不开心时她会告诉你。",
	["Lya se fue a descansar. Vuelve con /alfa lya."] = "Lya 去休息了。用 /alfa lya 叫她回来。",
	["Lya se queda calladita una hora. Aquí sigue, cuidándote."] = "Lya 安静一小时。她还在这里守着你。",
	["Lya se queda en tu pantalla: consejos cortos, historias y atajos a todo Alfa."] = "莉娅留在你的屏幕上：简短建议、故事和通往 Alfa 一切的捷径。",
	["Lya te acompaña"] = "Lya 陪着你",
	["Lya te cuenta"] = "莉娅跟你说",
	["Lya te cuenta cuánto tardaron, cuántas veces caíste y lo mejor que sacaste."] = "莉娅告诉你花了多久、倒下几次，以及你拿到的最好的东西。",
	["Lya te dice los avisos"] = "莉娅说出提醒",
	["Lya te enseña la ventana de Alfa en 5 pasos"] = "莉娅用 5 步带你认识 Alfa 窗口",
	["Lya te enseña la ventana de Alfa en 5 pasos. También con /alfa recorrido."] = "莉娅用 5 步带你认识 Alfa 窗口。也可以用 /alfa recorrido。",
	["Lya te enseña tu clase"] = "莉娅教你职业",
	["Lya te enseña tu clase y te ayuda al morir; respaldos, diagnóstico y Alfa más ligero."] = "莉娅教你职业、在你死亡时帮忙；备份、诊断和更轻量的 Alfa。",
	["Lya te entiende sin acentos, te cuenta datos aunque esté oculta y su menú dice lo que hará."] = "Lya 不用重音也能听懂你，隐藏时也会讲故事，她的菜单会说明要做什么。",
	["Lya te espera"] = "Lya 在等你",
	["Lya te guía, un asistente más sencillo y las guaridas"] = "莉娅带路、更简单的设置和巢穴",
	["Lya te lo dice todo"] = "莉娅都告诉你",
	["Lya tiene mucho que contar"] = "Lya 有很多话要说",
	["Lya volvió. Dale clic cuando quieras un consejo."] = "Lya 回来了。想听建议时就点她。",
	["Lya vuelve a contarte sus consejos desde el principio."] = "Lya 会从头再给你讲一遍她的建议。",
	["Lya vuelve a decirte todos esos consejos."] = "莉娅会再次告诉你所有这些建议。",
	["Lya vuelve a decirte todos los consejos que callaste."] = "莉娅会再次告诉你所有已关闭的建议。",
	["Lya vuelve a hablar."] = "Lya 又开口说话了。",
	["Lya y su manada"] = "莉娅和她的狼群",
	["Lya y tu mascota"] = "莉娅和你的宠物",
	["Lya, la loba de confianza del Alfa"] = "Lya，Alfa 最信任的母狼",
	["Lya, la loba negra que te acompaña, está en memoria de la perrita de Toxic. Te platica de cada zona, te da consejos y, claro, le encantan las salchichas."] = "莉娅是陪在你身边的黑色母狼，为纪念 Toxic 的小狗而生。她会给你讲每个区域，给你建议，当然，她超爱香肠。",
	["Lya, la manada y tus récords"] = "莉娅、狼群和你的纪录",
	["Lya, tu guía, la flecha, los avisos, la pesca y los marcos de Combate y Curación: los arrastras a donde quieras. También con /alfa acomodar."] = "Lya、你的指南、箭头、提示、钓鱼以及战斗和治疗框体：想放哪儿就拖到哪儿。也可以用 /alfa acomodar。",
	["Lánzalo antes de la siguiente pelea."] = "在下一场战斗前施放它。",
	["Lánzalo antes de pelear."] = "战斗前施放。",
	["Línea de la ruta"] = "路线",
	["Línea de tiempo apagada"] = "时间轴已关闭",
	["Línea de tiempo del jefe"] = "首领时间轴",
	["Línea de tiempo prendida"] = "时间轴已开启",
	["Maestro"] = "大师",
	["Maestro de armas"] = "武器大师",
	["Maestro de batalla"] = "战场军官",
	["Maestro de establos"] = "兽栏管理员",
	["Maestro de vuelo"] = "飞行管理员",
	["Maestro del agua"] = "水域大师",
	["Maestros de armas"] = "武器大师",
	["Maestros de batalla"] = "战场军官",
	["Maestros de establos"] = "兽栏管理员",
	["Maestros de vuelo"] = "飞行管理员",
	["Maestría elemental: tu siguiente hechizo es crítico y gratis."] = "元素掌握：你的下一个法术必定暴击且免费。",
	["Maestría nueva: %s (%d)"] = "新的精通：%s（%d）",
	["Magia"] = "魔法",
	["Mago"] = "法师",
	["Maiev Cantosombrío fue la carcelera de Illidan durante diez mil años, al frente de las Vigilantes."] = "玛维·影歌率领守望者，做了伊利丹一万年的狱卒。",
	["Mal'Ganis, el señor del terror, guió la plaga en Lordaeron. Arthas lo persiguió hasta Rasganorte, y esa cacería lo perdió."] = "恐惧魔王玛尔加尼斯在洛丹伦主导了瘟疫。阿尔萨斯一路追他到诺森德，正是这场追猎毁了他。",
	["Maldiciones y daño con el tiempo: pones tus hechizos y el monstruo muere solo mientras pasas al siguiente."] = "诅咒和持续伤害：挂上法术，怪物会自己死掉，你可以直接去打下一个。",
	["Maldición"] = "诅咒",
	["Maldición que hace cada vez más daño."] = "伤害越来越高的诅咒。",
	["Malfurion Tempestira fue el primer druida de los elfos de la noche. Aprendió del semidiós Cenarius, a quien llamaba shan'do: «maestro honrado»."] = "玛法里奥·怒风是暗夜精灵的第一位德鲁伊。他师从半神塞纳留斯，称他为 shan'do：“尊敬的导师”。",
	["Malfurion Tempestira, el gran druida, está perdido en el Sueño Esmeralda, y Tyrande lo espera."] = "伟大的德鲁伊玛法里奥·怒风迷失在翡翠梦境中，泰兰德一直在等他。",
	["Malla"] = "锁甲",
	["Malygos, el Tejehechizos, guía a los dragones azules. La traición de Alamuerte casi acaba con su vuelo, y nunca se repuso del todo."] = "魔法之王玛里苟斯领导着蓝龙。死亡之翼的背叛几乎让他的龙军团覆灭，他从此一蹶不振。",
	["Manada"] = "狼群",
	["Manda al chat del grupo una línea con el enlace de la misión cuando completas sus objetivos, otra cuando está lista para entregar y otra al entregarla; todo el grupo la ve, con o sin Alfa. Apagado, esas líneas solo te salen a ti. Nunca en banda."] = "完成任务目标时向队伍聊天发送一行带任务链接的消息，可交付时再发一行，交付时再发一行；全队都能看到，不论有没有 Alfa。关闭时这些消息只有你能看到。团队中不发送。",
	["Mano derecha"] = "主手",
	["Mano firme"] = "稳如磐石",
	["Mano izquierda"] = "副手",
	["Mano principal"] = "主手",
	["Mano secundaria"] = "副手",
	["Manos"] = "手",
	["Mantén Furia recta encendida cuando tanquees."] = "当坦克时保持正义之怒开启。",
	["Mantén Grito de batalla siempre puesto."] = "始终保持战斗怒吼。",
	["Mantén Seccionar en el rival para que no huya."] = "让对手身上一直挂着断筋，这样他跑不掉。",
	["Mantén al monstruo lejos: tu mascota lo detiene mientras disparas."] = "让怪物远离你：宠物拖住它，你负责射击。",
	["Maná"] = "法力值",
	["Maná cada 5 s"] = "每 5 秒法力回复",
	["Maná de los curanderos"] = "治疗者的法力值",
	["Maná tras la pelea"] = "战斗后的法力值",
	["Maná: quienes curaron"] = "法力：施放过治疗的人",
	["Mapa de Alfa"] = "Alfa 地图",
	["Mapa del mundo"] = "世界地图",
	["Mapa estable y 46 arreglos"] = "地图稳定，另有 46 项修正",
	["Mapa y marcadores"] = "地图和标记",
	["Mar abierto y zonas de nivel 35 en adelante. El rango Artesano lo da Nat Pagle en el Marjal Revolcafango con su misión."] = "开阔海域和 35 级以上的区域。专家级钓鱼由尘泥沼泽的纳特·帕格通过他的任务传授。",
	["Maraudon es sagrado para los centauros: ahí descansa el espíritu de Zaetar, el padre de su raza."] = "玛拉顿是半人马的圣地：他们种族之父扎尔塔的灵魂安息在那里。",
	["Marca a los enemigos y empieza por el más peligroso."] = "给敌人打上标记，先打最危险的那个。",
	["Marca al enemigo y todos le pegan más a distancia. Ponla antes de empezar."] = "标记敌人，让大家在远程打得更痛。开打前先加上。",
	["Marca al enemigo: todos le pegan más."] = "标记敌人：所有人对它造成更多伤害。",
	["Marca de lo Salvaje"] = "野性印记",
	["Marca el botón de tu barra que tiene la habilidad sugerida."] = "标出动作条上带有建议技能的按钮。",
	["Marca en el mapa a los instructores y vendedores de pesca de tu facción."] = "在地图上标出你阵营的钓鱼训练师和商人。",
	["Marca en el minimapa la entrada de cada mazmorra (en verde las que ya hiciste). El mapa del mundo ya las marca solo."] = "在小地图上标出每个地下城的入口（已完成的为绿色）。世界地图会自动标出。",
	["Marca un spot con «Spot aquí» en La Jauría o /alfa spot. Sale dorado en tu mapa y, si lo compartes, también en el de tu hermandad."] = "在 La Jauría 中用“此处刷点”或 /alfa spot 标记刷点。它会以金色显示在你的地图上；如果你分享，也会出现在公会成员的地图上。",
	["Marca un spot de farmeo donde estás (/alfa spot <texto>)"] = "在你所在的位置标记一个刷点（/alfa spot <文字>）",
	["Marcador"] = "标记",
	["Marcador borrado"] = "标记已删除",
	["Marcador puesto: %s."] = "已放置标记：%s。",
	["Marcadores con Mayús+clic derecho en el mapa del juego"] = "在游戏地图上用 Shift+右键放置标记",
	["Marcadores propios para compartir y seguir con la flecha."] = "可共享并用箭头跟随的自定义标记。",
	["Marcar a quien te falta para una misión"] = "标出任务还需要的目标",
	["Marcar como chatarra (%d)"] = "标记为垃圾（%d）",
	["Marcar como hecha"] = "标记为已完成",
	["Marcar como hecha (o desmarcar)"] = "标记为已完成（或取消标记）",
	["Marcar con calavera"] = "标记骷髅",
	["Marcar el mejor vuelo"] = "标出最佳飞行",
	["Marcar el raro para todos"] = "为所有人标记稀有怪",
	["Marcar la mejor recompensa para ti"] = "标出最适合你的奖励",
	["Marcar las que no valen la pena"] = "标记不值得做的",
	["Marcar para abandonar"] = "标记为放弃",
	["Marcas sobre cada objeto"] = "物品上的标记",
	["Marcaste como chatarra: %s. Se vende sola al hablar con un comerciante."] = "已标记为垃圾：%s。与商人交谈时会自动卖出。",
	["Marcaste como chatarra: %s. Véndela con «Vender la chatarra» en el comerciante."] = "已标记为垃圾：%s。在商人处用“出售垃圾”卖掉它。",
	["Marcaste un spot de farmeo: «%s»."] = "你标记了一个刷点：“%s”。",
	["Marco de prueba"] = "测试框体",
	["Marco fijo"] = "固定边框",
	["Marcos"] = "框体",
	["Marcos apagados"] = "框体已关闭",
	["Marcos de Curación apagados."] = "治疗框体已关闭。",
	["Marcos de Curación encendidos."] = "治疗框体已开启。",
	["Marcos de grupo de Alfa"] = "Alfa 的队伍框体",
	["Marcos de grupo de Alfa: pasas el ratón sobre un compañero y haces clic para curarlo."] = "Alfa 的队伍框体：把鼠标移到队友身上并点击即可治疗。",
	["Marcos de grupo y banda para curar con un clic, con preajustes por clase."] = "一键治疗的小队和团队框体，并提供各职业的预设。",
	["Marcos encendidos"] = "框体已开启",
	["Marcos y barra"] = "框体与动作条",
	["Marqué %d misiones"] = "我标记了 %d 个任务",
	["Martes"] = "星期二",
	["Mascota"] = "小伙伴",
	["Mascotas"] = "宠物",
	["Mascotas enemigas"] = "敌方宠物",
	["Materiales"] = "商品",
	["Mayús"] = "Shift",
	["Mayús + clic: ponerlo en el chat"] = "Shift + 点击：发到聊天",
	["Mayús+Espacio sigue saltando"] = "Shift+空格 仍然跳跃",
	["Maza de dos manos"] = "双手锤",
	["Maza de una mano"] = "单手锤",
	["Mazmorra"] = "地下城",
	["Mazmorra a la vista. Pelea al objetivo que marque tu grupo y todo sale mejor."] = "前方有地下城。攻击队伍标记的目标，一切都会更顺利。",
	["Mazmorra: %s"] = "地下城：%s",
	["Mazmorras"] = "地下城",
	["Mazmorras (3): derrotar al último jefe de todas las mazmorras de nivel 15-25, 26-45 y 46-60 (un punto por grupo)."] = "地下城（3）：击败 15-25、26-45 和 46-60 级所有地下城的最终首领（每组一点）。",
	["Mazmorras claras"] = "地下城一目了然",
	["Mazmorras en el camino"] = "沿途的地下城",
	["Mazmorras hechas"] = "已完成的地下城",
	["Mazmorras y bandas"] = "地下城和团队副本",
	["Mazmorras: los avisos de jefes que tu juego sí trae ya no salen apagados."] = "地下城：你的游戏中有的首领警报不再显示为关闭。",
	["Mazthoril es la guarida de los dragones azules, siempre atentos a quién usa la magia."] = "麦索瑞尔是蓝龙的巢穴，他们时刻留意着谁在使用魔法。",
	["Mañana"] = "明天",
	["Me cuesta leer Alfa, ¿qué hago?"] = "Alfa 的字我看不太清，怎么办？",
	["Me encanta cazar contigo. ¡Vamos por la siguiente!"] = "我好喜欢和你一起狩猎。去打下一个吧！",
	["Me gusta cuidarte la espalda. Para eso estoy."] = "我喜欢守着你的背后。我就是为此而在。",
	["Me gusta este paso tranquilo. Así se disfruta el camino."] = "我喜欢这种悠闲的步调。这样才能好好享受旅途。",
	["Me gusta ir contigo. Se nota que sabes lo que haces."] = "我喜欢和你一起走。看得出你很清楚自己在做什么。",
	["Me morí, ¿corro por mi cuerpo o voy con el ángel?"] = "我死了：是跑回尸体，还是找灵魂医者？",
	["Me quedo aquí sentadita contigo. Tres caídas no te hacen menos lobo. ¿Reparamos y pedimos ayuda?"] = "我就坐在这里陪你。倒下三次也不会让你不像狼。我们修理一下，再求助好吗？",
	["Me salté la historia de una misión"] = "我跳过了任务剧情",
	["Media"] = "中",
	["Medianos y graves"] = "中等和严重",
	["Medias"] = "中",
	["Medidor de daño"] = "伤害统计",
	["Medio"] = "中",
	["Medivh era hijo de Aegwynn, la Guardiana anterior. Ella escondió en él el poder del Guardián sin saber que Sargeras también se escondía ahí."] = "麦迪文是上一任守护者艾格文的儿子。她把守护者的力量藏在他体内，却不知道萨格拉斯也藏在那里。",
	["Medivh era hijo de Aegwynn, la Guardiana, y de Nielas Aran, un mago de la corte de Ventormenta."] = "麦迪文是守护者艾格文与暴风城宫廷法师尼尔拉斯·阿兰之子。",
	["Medivh murió a manos de Khadgar y Lothar, pero años después regresó como el misterioso profeta que llevó a Thrall a Kalimdor."] = "麦迪文死于卡德加和洛萨之手，但多年后他以神秘先知的身份归来，带领萨尔前往卡利姆多。",
	["Medivh, poseído por Sargeras, abrió el camino para que la Horda llegara a Azeroth."] = "被萨格拉斯附身的麦迪文为部落打开了通往艾泽拉斯的道路。",
	["Mejor %s"] = "改为%s",
	["Mejor a nivel %d · niveles %d a %d"] = "最适合 %d 级 · %d 到 %d 级",
	["Mejor con la manada: llámala y cacen juntos."] = "和狼群一起更好：呼唤他们一起狩猎。",
	["Mejor no ir sin compañía: puede salir caro."] = "最好别一个人去：可能会付出代价。",
	["Mejor:"] = "最佳：",
	["Mejora"] = "增强",
	["Mejora [reporte]"] = "改进建议",
	["Mejora para subir"] = "增强（升级）",
	["Mejora tu defensa con escudo."] = "提高持盾时的防御。",
	["Mejorar el cuadro de información"] = "改进鼠标提示",
	["Mejorar el minimapa"] = "改进小地图",
	["Mejorar el probador"] = "改进试衣间",
	["Mejoras de equipo"] = "装备提升",
	["Memoria de Alfa"] = "Alfa 的内存",
	["Menos consejos"] = "更少建议",
	["Menos estorbo: Combate se calla yendo solo y los avisos de grupo esperan a que acabe la pelea."] = "更少打扰：独自一人时战斗保持安静，队伍提示会等战斗结束。",
	["Mensajes de aviso en pantalla"] = "屏幕警报提示",
	["Mensajes enviados: %d (frenados: %d) · recibidos: %d · en cola: %d"] = "已发送消息：%d（被限流：%d）· 已接收：%d · 排队中：%d",
	["Mentor"] = "导师",
	["Menú del jugador"] = "玩家菜单",
	["Menú y bolsas"] = "菜单与背包",
	["Mercancías generales"] = "杂货",
	["Meta cumplida"] = "目标已达成",
	["Meta cumplida (%d de %d)"] = "目标已达成（%d / %d）",
	["Metas de pesca"] = "钓鱼目标",
	["Mi configuración"] = "我的设置",
	["Mi entrenador"] = "我的训练师",
	["Mi oreja derecha se para sola cuando alguien dice «salchicha». Pruébalo."] = "只要有人说“香肠”，我的右耳就会自己竖起来。试试看。",
	["Mi panza hizo un ruido. No fui yo, fue la panza."] = "我的肚子咕噜叫了一声。不是我，是肚子。",
	["Mi plan"] = "我的计划",
	["Mi plan perfecto: una buena cacería y luego salchichas junto a la fogata."] = "我的完美计划：好好狩猎一场，然后在篝火旁吃香肠。",
	["Mi plan · %s"] = "我的计划 · %s",
	["Mi plan · %s · %d de %d"] = "我的计划 · %s · %d / %d",
	["Mi primera montura"] = "我的第一匹坐骑",
	["Mi propio plan"] = "我自己的计划",
	["Mi ruta"] = "我的路线",
	["Mi ruta: hacer oro"] = "我的路线：赚金币",
	["Mi ruta: subir rápido"] = "我的路线：快速升级",
	["Mientras caminas o corres, tu tecla hace lo de siempre (con Espacio, saltar)."] = "你走路或奔跑时，按键保持原本功能（设为空格时就是跳跃）。",
	["Mientras el corcho está en el agua, una línea fina con el tiempo, tu habilidad y lo último que sacaste."] = "鱼漂在水中时，显示一条细线，包含时间、你的技能和上一次的渔获。",
	["Mientras entrabas"] = "你登录期间",
	["Mientras entrabas te guardé %d cosas."] = "你进来的时候，我替你记下了 %d 件事。",
	["Mientras entrabas te guardé una cosa."] = "你进来的时候，我替你记下了一件事。",
	["Mientras estás aquí"] = "你在这里时",
	["Mientras estás aquí: %s"] = "既然在这里：%s",
	["Mientras la haces"] = "做任务的同时",
	["Mientras los druidas dormían en el Sueño Esmeralda, las Centinelas de Tyrande cuidaron solas los bosques de Kalimdor."] = "德鲁伊在翡翠梦境中沉睡时，泰兰德的哨兵们独自守护着卡利姆多的森林。",
	["Mientras más alto el nivel de las bestias, mejor el cuero que sueltan."] = "野兽的等级越高，掉落的皮革就越好。",
	["Mientras más nivel tenga la bestia, más habilidad te pide para desollarla."] = "野兽的等级越高，剥皮所需的技能就越高。",
	["Mientras pescas"] = "钓鱼时",
	["Mientras pescas se ve solo el mundo y la barra de pesca. Nunca en combate: al empezar uno, todo vuelve."] = "钓鱼时只显示世界和钓鱼条。战斗中绝不会这样：一进入战斗，一切都会恢复。",
	["Mientras pescas, el juego se sigue oyendo aunque estés en otra ventana."] = "钓鱼时，即使你切到其他窗口，也能继续听到游戏声音。",
	["Mientras tenga la maldición, cura antes de que la vida baje mucho."] = "诅咒还在时，要在血量掉太多之前提前治疗。",
	["Mientras vas solo no hay a quién mostrar. Míralos ahora con marcos de ejemplo, o prende «Verte a ti estando solo», abajo en Marcos."] = "单人时没有可显示的队友。现在用示例框体看看效果，或在下方“框体”中打开“单人时显示自己”。",
	["Mientras vuelas en grifo, la línea de tu viaje en el mapa de Alfa: por dónde vas y dónde aterrizas."] = "乘坐狮鹫飞行时，在 Alfa 地图上显示你的旅程线路：你现在在哪里，会在哪里降落。",
	["Mientras, junta el oro: con la equitación y la montura se va casi todo."] = "同时攒好金币：骑术和坐骑几乎会花光它们。",
	["Mil y un peces"] = "一千零一条鱼",
	["Mina, herboriza, pesca en un banco o abre un cofre: aquí verás cuánto, qué te dio cada nodo y en qué zona."] = "采矿、采草药、在鱼群钓鱼或打开宝箱：这里会显示数量、每个采集点给了你什么以及在哪个区域。",
	["Minas, hierbas y tesoros en tu mapa"] = "地图上的矿脉、草药和宝藏",
	["Minería"] = "采矿",
	["Minería es su mejor pareja. Necesitas un martillo de herrero y trabajar junto a un yunque."] = "采矿是它最好的搭档。你需要一把铁匠锤，并在铁砧旁工作。",
	["Minería, hierbas, pesca y tesoros en tu mapa y minimapa, con rutas de farmeo e historial."] = "在地图和小地图上显示矿点、草药、钓鱼点和宝藏，并提供采集路线和历史记录。",
	["Minería, hierbas, pesca y tesoros también en el mapa grande de Alfa: al acercarte a una zona salen agrupados, con su cantidad."] = "采矿、草药、钓鱼和宝藏也会显示在 Alfa 的大地图上：放大到某个区域时，它们会按数量分组显示。",
	["Minimapa"] = "小地图",
	["Minimapa cuadrado"] = "方形小地图",
	["Minimapa y coordenadas"] = "小地图和坐标",
	["Minutos entre consejos"] = "建议间隔（分钟）",
	["Minutos entre historias"] = "故事间隔（分钟）",
	["Mira a sus jefes y sus consejos antes de cada pelea."] = "每场战斗前查看它的首领和提示。",
	["Mira a una criatura primero: así Alfa sabe en qué plano estás."] = "先看一眼某个生物：这样 Alfa 才知道你在哪个位面。",
	["Mira a una criatura y Alfa te dice en qué guarida estás"] = "看一眼生物，Alfa 就告诉你在哪个巢穴",
	["Mira bien alrededor; las cosas importantes no se esconden tanto."] = "仔细看看四周；重要的东西不会藏得太深。",
	["Mira en la Enciclopedia de dónde sale."] = "在百科中查看它的来源。",
	["Mira la línea de tiempo: llegan tres ataques de prueba"] = "看时间轴：三个测试攻击即将到来",
	["Mira las bolsas o el banco de otro de tus personajes."] = "查看你其他角色的背包或银行。",
	["Mira quién llegó: %s, de la familia %s. Nos vamos a llevar bien... casi siempre."] = "看看谁来了：%s，%s家族的一员。我们会处得很好的……大多数时候。",
	["Mira si llevas lo que hace falta: el equipo reparado, espacio, comida y lo de tu clase."] = "检查你是否带齐所需：修好的装备、背包空间、食物和职业物品。",
	["Mira tus retos en el Legado del juego"] = "在游戏的传承中查看你的挑战",
	["Mira «Camino al 60» en Hoy: cuántas horas te faltan a tu ritmo y cuánto avanzaste hoy. «Ver el camino» te dice qué guías y mazmorras te tocan."] = "看看“今天”里的“通往 60 级之路”：按你的节奏还要几小时，以及你今天走了多远。“查看路线”会告诉你哪些指南和地下城适合你。",
