	["Moviendo"] = "移动中",
	["Mucho daño con tu arma a distancia: disparos fuertes antes de que el monstruo llegue."] = "远程武器伤害很高：在怪物靠近之前打出强力射击。",
	["Mucho daño de sombra que va creciendo. Una maldición por enemigo."] = "大量逐渐增强的暗影伤害。每个敌人只能上一个诅咒。",
	["Mucho maná y hechizos arcanos potentes: el mago que menos descansa."] = "法力充沛，奥术法术强力：休息最少的法师。",
	["Mucho tiempo sin verte, %s. Repasa tus misiones antes de salir."] = "好久不见，%s。出发前先看看你的任务。",
	["Muchos"] = "多",
	["Muchos enemigos duermen a un jugador: no es grave, el sueño se quita solo."] = "很多敌人会催眠一名玩家：没什么大碍，睡眠会自己消失。",
	["Muchos: consejos del momento y de vez en cuando uno de Alfa. Pocos: menos seguido. Solo importantes: al morir, al subir de nivel y en tus logros."] = "多：当下的建议，偶尔还有一条关于 Alfa 的。少：频率较低。只看重要的：死亡、升级和达成里程碑时。",
	["Muchísima amenaza en un golpe."] = "一击就能产生大量威胁。",
	["Muelle de %s"] = "%s码头",
	["Muelles y torres de zepelín, con a dónde van."] = "码头和飞艇塔，并标明目的地。",
	["Muertes"] = "死亡次数",
	["Muerto"] = "死亡",
	["Muestra la ventana de guía y la flecha, y cierra esta ventana para que las veas."] = "显示指南窗口和箭头，并关闭此窗口，方便你查看。",
	["Muestra la vida en número, debajo del nombre."] = "在名字下方以数字显示生命值。",
	["Muestra lo que aún no exploras, con un tono más frío para distinguirlo."] = "显示你尚未探索的区域，并用偏冷的色调加以区分。",
	["Muestra un aviso de ejemplo para que veas dónde sale."] = "显示一个示例提醒，让你看看它出现在哪里。",
	["Muestra un ícono encima del corcho: así sabes que tu tecla lo va a recoger."] = "在鱼漂上方显示图标，让你知道按键会收起它。",
	["Mueve lo de Alfa con el ratón"] = "用鼠标移动 Alfa 的元素",
	["Mueve tus marcos"] = "移动你的框体",
	["Mulgore de día: pasto hasta donde alcanza la vista y kodos pastando. Qué paz."] = "白天的莫高雷：一望无际的草原和吃草的科多兽。好宁静。",
	["Mundo"] = "世界",
	["Munición"] = "弹药",
	["Muradin Barbabronce acompañó a Arthas a Rasganorte. Cuando Arthas tomó la espada, un trozo de hielo golpeó a Muradin y lo dieron por muerto."] = "穆拉丁·铜须随阿尔萨斯前往诺森德。阿尔萨斯拿起那把剑时，一块冰击中了穆拉丁，大家都以为他死了。",
	["Muradin Barbabronce le enseñó a Arthas a pelear cuando el príncipe era joven."] = "王子年少时，是穆拉丁·铜须教会了阿尔萨斯战斗。",
	["Muro de escudo dura más."] = "盾墙持续时间更长。",
	["Muro de escudo dura más: te salva en los jefes."] = "盾墙持续时间更长：打首领时能救你一命。",
	["Muy grande"] = "特大",
	["Muy peligroso para tu nivel: mejor con grupo o rodéalo."] = "对你的等级非常危险：最好组队，或者绕开。",
	["Muy pronto"] = "即将推出",
	["Muéstrala u ocúltala. También con su tecla o con /alfa guia."] = "显示或隐藏它。也可以用它的按键或 /alfa guia。",
	["Muévete a las zonas de nivel 10 a 20. Las lombrices ayudan a que no se escapen. Pide el rango Experto desde 125."] = "转到 10 到 20 级的区域。蚯蚓能让鱼不那么容易跑掉。125 点起去学高级。",
	["Muñecas"] = "手腕",
	["Márcala cuando la hagas"] = "完成后勾选它",
	["Márcalo con la calavera y todo tu grupo lo verá."] = "给它标上骷髅，全队都能看到。",
	["Más"] = "更多",
	["Más Abrumar gracias a Desgarrar."] = "借助撕裂获得更多压制机会。",
	["Más Golpes heroicos: más daño por pelea."] = "更多英勇打击：每场战斗伤害更高。",
	["Más adelante"] = "稍后",
	["Más adelante eliges entre ingeniería gnómica y goblin: los inventos gnómicos fallan a veces de forma muy graciosa, y los goblin explotan más."] = "之后你要在侏儒工程学和地精工程学之间选择：侏儒的发明有时会以非常滑稽的方式失灵，地精的则更容易爆炸。",
	["Más adelante eliges especialidad: de escamas de dragón, elemental o tribal."] = "之后你要选择专精：龙鳞制皮、元素制皮或部族制皮。",
	["Más adelante eliges especialidad: forjador de armaduras o armero, y los armeros, entre espadas, mazas y hachas."] = "之后你要选择专精：护甲锻造师或武器锻造师，武器锻造师还要在剑、锤和斧之中选择。",
	["Más adelante: %s."] = "以后：%s。",
	["Más aguante para ti y tus amigos. Dásela a todo el grupo antes de empezar."] = "为你和朋友们提升耐力。开打前给全队加上。",
	["Más aguante y seguridad. Matas un poco más lento, pero casi no mueres."] = "更多耐力，更稳妥。杀怪稍慢一些，但几乎不会死。",
	["Más alto, atraviesa objetos más grandes antes de acercarse."] = "数值越高，镜头在拉近之前能穿过越大的物体。",
	["Más alto, los objetos lejanos tardan más en desaparecer."] = "数值越高，远处的物体越晚消失。",
	["Más alto, más nítido. Demasiado puede marcar bordes y brillos."] = "数值越高越清晰。太高可能让边缘和高光过于明显。",
	["Más alto, ves más a los lados."] = "数值越高，两侧看到的范围越大。",
	["Más amenaza."] = "更多威胁。",
	["Más amenaza: los monstruos se quedan contigo."] = "更多威胁：怪物会一直打你。",
	["Más armadura para ti y tu grupo cercano. Una buena aura para empezar."] = "为你和附近的队友提升护甲。很适合开局用的光环。",
	["Más armadura y más poder. Mantenlo siempre puesto."] = "更多护甲和更多力量。一直保持开着。",
	["Más armadura y regeneras vida. Mantenla siempre puesta."] = "更多护甲和生命恢复。一直保持开着。",
	["Más armadura, atributos y resistencias. Dásela a todo el grupo."] = "提升护甲、属性和抗性。给全队加上。",
	["Más baja, la niebla se ve más ligera y cuesta menos."] = "数值越低，雾看起来越淡，也越省资源。",
	["Más bajo, se siguen viendo objetos pequeños a lo lejos."] = "数值越低，远处的小物体仍会保持可见。",
	["Más cerca de tu paso"] = "离你的步骤最近",
	["Más consejos"] = "更多建议",
	["Más crítico en Abrumar, ideal contra pícaros que esquivan."] = "提高压制的暴击，非常适合对付会躲闪的潜行者。",
	["Más crítico."] = "更多暴击。",
	["Más daño con dos manos."] = "双手武器伤害更高。",
	["Más daño con el tiempo."] = "更多持续伤害。",
	["Más daño con escudo."] = "持盾时伤害更高。",
	["Más daño con escudo: lo que hace que Protección suba bien."] = "持盾时伤害更高：这让防护战士也能顺利升级。",
	["Más daño con tu arma de dos manos, que es la que usas."] = "提高你所用的双手武器的伤害。",
	["Más daño con tu arma de dos manos."] = "提高双手武器的伤害。",
	["Más daño de sangrado; abre Heridas profundas."] = "流血伤害更高；解锁重伤。",
	["Más daño mientras llevas escudo."] = "持盾时伤害更高。",
	["Más daño y más riesgo. Matas rápido, pero un error se paga caro."] = "伤害更高，风险也更大。杀怪很快，但一失误代价就很大。",
	["Más de 40 arreglos: combate y curación en mazmorras, el buzón cuenta bien tu dinero y la placa de llegada se va sola."] = "40 多项修正：地下城中的战斗与治疗，邮箱正确计算你的金钱，抵达牌会自己消失。",
	["Más de mi gente"] = "再讲讲我的族人",
	["Más defensa desde el principio."] = "一开始就有更多防御。",
	["Más defensa: te golpean y te hacen crítico menos seguido."] = "更多防御：被击中和被暴击的次数更少。",
	["Más defensa: te hacen menos críticos."] = "更多防御：受到的暴击更少。",
	["Más detalle al acercar el mapa"] = "放大地图时显示更多细节",
	["Más distancia, sombras finas y agua con reflejos."] = "更远的视距、细致的阴影和带反射的水面。",
	["Más en Calidad de vida"] = "更多内容见“便利功能”",
	["Más espacio en el banco"] = "更多银行空间",
	["Más firme y en tu idioma"] = "更稳定，也更懂你的语言",
	["Más fuerza para ti y tu grupo cercano."] = "为你和附近的队友提升力量。",
	["Más golpe crítico para todo lo que haces."] = "所有攻击的暴击率都更高。",
	["Más golpe crítico, que también te da más ira."] = "更高的暴击率，也能给你更多怒气。",
	["Más golpe crítico."] = "更高的暴击率。",
	["Más golpes bloqueados con el escudo, y cada bloqueo te da ira."] = "用盾牌格挡更多攻击，每次格挡都给你怒气。",
	["Más golpes críticos, pero recibes más daño. La postura para hacer daño."] = "更多暴击，但你受到的伤害也更多。输出用的姿态。",
	["Más guías"] = "更多指南",
	["Más intelecto para ti y tus amigos. Dáselo al grupo antes de empezar."] = "为你和朋友们提升智力。开打前给队伍加上。",
	["Más ira al cargar."] = "冲锋获得更多怒气。",
	["Más ira al cargar: tu primer golpe llega antes."] = "冲锋获得更多怒气：第一击来得更早。",
	["Más ira al empezar la pelea."] = "战斗开始时获得更多怒气。",
	["Más ira al empezar."] = "开场获得更多怒气。",
	["Más ira por cada golpe, sobre todo con armas rápidas."] = "每次攻击获得更多怒气，快速武器尤其明显。",
	["Más ira por cada golpe: más Golpe heroico y Golpe mortal."] = "每次攻击获得更多怒气：能打出更多英勇打击和致死打击。",
	["Más ira por golpe."] = "每次攻击获得更多怒气。",
	["Más ira por golpe: más habilidades seguidas."] = "每次攻击获得更多怒气：能连续使用更多技能。",
	["Más lugares"] = "更多地点",
	["Más maná con el tiempo. Ideal para quien cura y para ti."] = "持续恢复更多法力。很适合治疗者，也适合你。",
	["Más maná y algo de crítico con hechizos."] = "更多法力值和一些法术暴击。",
	["Más opciones"] = "更多选项",
	["Más opciones de Mundo"] = "更多世界选项",
	["Más opciones de apariencia"] = "更多外观选项",
	["Más opciones del ícono"] = "更多图标选项",
	["Más para tu personaje"] = "为你的角色提供更多",
	["Más pasto"] = "更多草地",
	["Más pasto, más horizonte, niebla ligera y rayos de sol, sin pedirle de más a tu PC. Se deshace en Mundo > Paisaje y gráficos (o /alfa paisaje)."] = "更多草地、更远的地平线、淡淡的雾和阳光光束，又不会让你的电脑太吃力。可在“世界 > 风景与图形”（或 /alfa paisaje）中撤销。",
	["Más pasto, más horizonte, niebla ligera y rayos de sol. Bonito sin pedir de más."] = "更多草地、更远的地平线、淡淡的雾和阳光光束。好看又不吃配置。",
	["Más poder de ataque a distancia. El aspecto para pelear."] = "更多远程攻击强度。战斗用的守护。",
