	["Nadie a la vista tiene ubicación ahora: en una instancia o desconectados. Cuando vuelvan al mundo, aparecen aquí y en tu mapa."] = "视野中现在没有人有位置：在副本中或已离线。回到世界后，他们会出现在这里和你的地图上。",
