	["Nadie de la manada dijo tener «%s» (todavía)."] = "狼群里（暂时）没人说有“%s”。",
	["Nadie de la manada respondió desde otro plano. Prueba en un rato o pídelo en el Discord de La Jauría."] = "狼群里没人从其他位面回应。过一会儿再试，或去 La Jauría 的 Discord 问问。",
	["Nadie de los que van está conectado ahora."] = "要去的人里现在没有人在线。",
