	["Nadie respondió desde la %s. Prueba en un rato o pídelo en el Discord de La Jauría."] = "%s里没人回应。稍后再试或去 La Jauría 的 Discord 问问。",
	["Nadie tiene esa guarida abierta ahora."] = "现在没人开着那个巢穴。",
	["Naranja"] = "橙色",
	["Nat Pagle, el pescador legendario, vive en una isla del Marjal Revolcafango."] = "传奇渔夫纳特·帕格住在尘泥沼泽的一座岛上。",
	["Nat Pagle, el pescador más famoso, vive en una isla del marjal; sus misiones son para pescadores pacientes."] = "最有名的渔夫纳特·帕格住在沼泽中的一座岛上；他的任务适合有耐心的钓客。",
	["Nat Pagle, en el Marjal Revolcafango, te pide cuatro peces raros: con su misión aprendes el rango Artesano."] = "尘泥沼泽的纳特·帕格要你带来四条稀有鱼：完成他的任务就能学会专家级钓鱼。",
	["Naxxramas, la necrópolis de Kel'Thuzad, flota sobre estas tierras como una sombra."] = "纳克萨玛斯是克尔苏加德的浮空城，像一道阴影般飘浮在这片土地上空。",
	["Necesita la base de misiones (página Misiones)."] = "需要任务数据库（“做任务”页面）。",
	["Necesita las rutas a pie de Alfa (Alfa_Nav), que se cargan solas con «Seguir caminos reales» encendido."] = "需要 Alfa 的步行路线（Alfa_Nav），开启“沿真实道路行走”后会自动加载。",
	["Necesita un monitor HDR"] = "需要 HDR 显示器",
	["Necesitas %s"] = "你需要%s",
	["Necesitas %s con %s"] = "你需要%s（%s）",
	["Necesitas %s para esta cadena: apréndela con un instructor."] = "这个任务链需要%s：请向训练师学习。",
	["Necesitas %s para juntarlo: apréndela con un instructor de profesiones."] = "需要%s才能收集：去找专业训练师学习。",
	["Necesitas al menos 2 misiones listas para entregar."] = "至少需要 2 个已完成的任务才能交。",
	["Necesitas una hermandad: el tablón es de los lobos de la tuya."] = "你需要一个公会：公告板是你公会里的狼专用的。",
	["Necesitas una hermandad: «¿Quién tiene...?» pregunta a los lobos de la tuya."] = "你需要一个公会：“谁有……？”是问你公会里的狼。",
	["Neltharion, el Guardián de la Tierra, escuchó los susurros de los dioses antiguos y se convirtió en Alamuerte."] = "大地守护者耐萨里奥听信了上古之神的低语，变成了死亡之翼。",
	["Ner'zhul abrió varios portales en Draenor y la magia desgarró el planeta. Lo que quedó flota en la nada y se llama Terrallende."] = "耐奥祖在德拉诺开启了多道传送门，魔法撕裂了整个星球。残存的部分漂浮在虚空中，被称为外域。",
	["Nethergarde es un bastión de magos de la Alianza que vigila el Portal Oscuro, por si algo vuelve a cruzar."] = "守望堡是联盟法师的要塞，负责监视黑暗之门，以防再有什么东西穿过来。",
