	["No se pudo leer el escaneo. Intenta de nuevo más tarde."] = "无法读取扫描结果。请稍后再试。",
	["No se pudo marcar: falta el motor de Alfa."] = "无法标记：缺少 Alfa 引擎。",
	["No se pudo mostrar el banco del juego para comprar la casilla."] = "无法显示游戏银行来购买栏位。",
	["No se pudo probar ahora"] = "现在无法测试",
	["No se pudo restaurar"] = "无法恢复",
	["No se puede dibujar el mapa continuo. El mapa del juego sigue funcionando con todas las capas de Alfa."] = "无法绘制无缝地图。游戏地图仍可使用 Alfa 的所有图层。",
	["No se puede en combate."] = "战斗中无法使用。",
	["No se puede ordenar en combate."] = "战斗中无法整理。",
	["No se puede vender."] = "无法出售。",
	["No se pueden cambiar bolsas en combate."] = "战斗中无法更换背包。",
	["No se sabe en qué lugar está."] = "位置未知。",
	["No se ve en pantalla. Tráela de vuelta cuando quieras (también con /alfa lya)."] = "她现在不在屏幕上。随时可以让她回来（也可以用 /alfa lya）。",
	["No siempre aparece en la mina: si lo ves, es un jefe más con buen botín."] = "他不一定会在矿洞里出现：如果碰到了，就是一个掉落不错的额外首领。",
	["No siempre aparece. Pone un dolor de sombras: cura a quien lo tenga."] = "不一定会出现。会施放暗影痛：治疗中招的人。",
	["No sigues ninguna guía"] = "你没有跟随任何指南",
	["No son para ti"] = "不适合你",
	["No sé de dónde sale este objeto."] = "我不知道这件物品的来源。",
	["No sé de eso todavía. Prueba con otra palabra, o pregúntale a la manada en el Discord."] = "这个我还不知道。换个词试试，或去 Discord 问问狼群。",
	["No sé dónde se entrega"] = "交付地点未知",
	["No sé dónde se entrega %s: la saqué de la ruta."] = "不知道%s在哪里交：已将它移出路线。",
	["No sé dónde se entrega %s: la saqué del plan."] = "我不知道%s在哪里交付：已将它移出计划。",
	["No sé dónde se junta este material."] = "不知道这种材料在哪里收集。",
	["No sé dónde se junta: búscalo en la Enciclopedia para ver de dónde sale."] = "我不知道在哪里收集：在百科中搜索它，查看来源。",
	["No sé dónde se toma esa misión."] = "我不知道这个任务在哪里接。",
	["No sé en qué zona estás."] = "无法确定你所在的区域。",
	["No sé qué misión es."] = "我不知道那是哪个任务。",
	["No sé si alguien en Azeroth cocina salchichas como las de casa... pero si encuentras una receta, ¡me avisas!"] = "不知道艾泽拉斯有没有人能做出家里那种香肠……要是你找到配方，记得告诉我！",
	["No sé si se puede tomar"] = "无法确定能否接取",
	["No te alcanza"] = "钱不够",
	["No tienes cartas."] = "你没有邮件。",
	["No tienes cebos. Los venden los vendedores de suministros de pesca; la guía dice cuáles sirven a tu habilidad."] = "你没有鱼饵。钓鱼用品商人有卖；指南会告诉你哪些适合你的技能。",
	["No tienes demonio: el abisario aguanta los golpes por ti."] = "你没有恶魔：虚空行者可以替你承受攻击。",
	["No tienes demonio: invoca uno antes de pelear."] = "你没有恶魔：战斗前先召唤一个。",
	["No tienes demonio: invócalo al instante, aun peleando."] = "你没有恶魔：立刻召唤它，即使在战斗中也行。",
	["No tienes marcadores en el mapa de Alfa. Pon uno en el mapa y vuelve aquí."] = "你在 Alfa 的地图上没有标记。在地图上放一个，然后回到这里。",
	["No tienes mascota: llámala."] = "你没有宠物：召唤它。",
