	["Para abandonar"] = "待放弃",
	["Para abrirlo con la tecla del mapa, enciende «Abrir el mapa de Alfa con la tecla del mapa» abajo."] = "要用地图键打开它，请开启下方的“用地图键打开 Alfa 地图”。",
	["Para adoptar, tu nivel debe pasar el suyo por 10 o más."] = "要收养，你的等级必须比他高 10 级或以上。",
	["Para alguien de tu hermandad, agrega su rango."] = "如果是你的公会成员，会显示其会阶。",
	["Para armar la espada legendaria de Thunderaan, el Buscavientos, hacen falta dos ataduras que sueltan Garr y el barón Geddon en el Núcleo de Magma."] = "要组装风之探寻者桑德兰王子的传说之剑，需要熔火之心里加尔和迦顿男爵掉落的两个束缚。",
	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "对每件物品，Alfa 会比较三种做法：卖给商人、放到拍卖行，或加工（用你会的配方制作，或者分解）。",
	["Para cambiar de plano con la manada, primero deja que te vea en el mapa (ajustes de La Jauría)."] = "要和狼群一起切换位面，先让它在地图上看到你（La Jauría 设置）。",
	["Para capturas y paseos. No da más FPS."] = "适合截图和观光。不会提高 FPS。",
	["Para cerrar tu rato con todo cobrado"] = "拿齐所有奖励再收尾",
	["Para cerrarle el paso a la Legión, Malfurion y sus aliados destruyeron el Pozo de la Eternidad. La explosión hundió el centro de Kalimdor."] = "为了把燃烧军团挡在门外，玛法里奥和他的盟友摧毁了永恒之井。爆炸让卡利姆多的中心沉入海底。",
	["Para comprar espacio, habla con un banquero."] = "要购买空间，请与银行职员交谈。",
	["Para conservar"] = "要保留的",
	["Para cruzar de los Reinos del Este a Kalimdor, toma un barco en el Puerto de Menethil, en Los Humedales."] = "要从东部王国前往卡利姆多，可以在湿地的米奈希尔港搭船。",
	["Para depositar, habla con un banquero."] = "要存放，请与银行职员交谈。",
	["Para empezar"] = "如何开始",
	["Para encantar necesitas una vara rúnica; con el tiempo la mejoras."] = "附魔需要一根符文棒；以后可以慢慢升级它。",
	["Para entregar"] = "待交付",
	["Para gastar"] = "可用",
	["Para invitar a %s a %s: abre «Hermandad y comunidades», elige %s, pulsa «Invitar a miembro» y escribe: %s"] = "要邀请%s加入%s：打开“公会与社区”，选择%s，点击“邀请成员”并输入：%s",
	["Para ir de Los Humedales a las Tierras Altas de Arathi cruza el Puente Thandol, pero ojo con los Hierro Negro."] = "要从湿地前往阿拉希高地，就得过萨多尔大桥，但要小心黑铁矮人。",
	["Para las recetas de %s."] = "用于 %s 的配方。",
	["Para leer mejor"] = "更易阅读",
	["Para llamar a la manada, deja que te vean en el mapa (La Jauría)."] = "想呼唤狼群，请让他们在地图上看到你（La Jauría）。",
	["Para llegar a la Fuente del Sol, la Plaga de Arthas arrasó Quel'Thalas y su capital, Lunargenta."] = "为了抵达太阳之井，阿尔萨斯的天灾军团摧毁了奎尔萨拉斯和它的首都银月城。",
	["Para lo que elegiste no hay uno con este estilo: Alfa usa el más cercano."] = "你选的组合没有这种风格的方案：Alfa 使用最接近的。",
	["Para marcarlo, clic derecho en su retrato y elige la calavera."] = "要标记它，右键点击它的头像并选择骷髅。",
	["Para mi nivel (±3)"] = "适合我的等级（±3）",
	["Para minar torio, el Cráter de Un'Goro y Cuna del Invierno tienen muchas vetas."] = "要挖瑟银的话，安戈洛环形山和冬泉谷有很多矿脉。",
	["Para mí"] = "适合我",
	["Para no chocar con él, Alfa no reemplaza tus bolsas mientras esté activo. Igual puedes abrir la ventana de Alfa desde aquí."] = "为避免冲突，它启用期间 Alfa 不会替换你的背包。你仍可以从这里打开 Alfa 窗口。",
	["Para no moverla sin querer. Sin bloquear, arrástrala a donde quieras."] = "以免不小心移动她。解锁后可以把她拖到任何地方。",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "避免队友显示两遍。需在非战斗状态下更改。",
	["Para proponer una cita, deja que la manada te vea en el mapa."] = "要提议集合，请让狼群能在地图上看到你。",
	["Para que no choquen, Alfa no toma tu tecla ni cambia tus ajustes. Desactiva uno de los dos en la lista de addons (pantalla de personajes) y recarga. Si dejas Alfa, tomará sola la tecla que usabas en el otro addon."] = "为避免冲突，Alfa 不会占用你的按键，也不会更改你的设置。请在插件列表（角色选择界面）中停用其中一个，然后重载。如果保留 Alfa，它会自动接管你在其他插件中使用的按键。",
	["Para que no dejes botín tirado por falta de espacio."] = "免得因为没有空间而放弃战利品。",
	["Para quien prefiere seleccionar con el izquierdo: la cura de ese clic pasa al botón central. Se vuelve a aplicar tu preajuste."] = "适合习惯用左键选中目标的玩家：左键的治疗会移到中键。会重新套用你的预设。",
	["Para recoger ahora"] = "现在可接取",
	["Para subir de nivel"] = "距离升级",
	["Para subir solo, el daño de las sombras ayuda mucho: los hechizos que dañan con el tiempo trabajan por ti."] = "单人升级时，暗影伤害很有帮助：持续伤害法术会替你干活。",
	["Para tela de nivel bajo, los Defias de los Páramos de Poniente sueltan lino y lana a montones."] = "要找低级布料，西部荒野的迪菲亚会掉落大量亚麻布和毛料。",
	["Para templar la espada élfica Quel'Serrar hay que dejarla en el piso y que Onyxia le eche su aliento de fuego encima."] = "要淬炼精灵之剑奎尔塞拉，得把它放在地上，让奥妮克希亚对它喷火。",
	["Para ti"] = "适合你",
	["Para ti ahora"] = "你现在适合的",
	["Para tu %s"] = "%s专属",
	["Para tu habilidad conviene pescar en: %s."] = "以你的技能，适合在这些地方钓鱼：%s。",
	["Para tu nivel"] = "适合你的等级",
	["Para tu nivel (%d)"] = "适合你的等级（%d）",
	["Para tu nivel ahora"] = "现在适合你的等级",
	["Para tu personaje de nivel %d"] = "适合你的 %d 级角色",
	["Para vender"] = "要卖的",
	["Para vender, habla con un comerciante."] = "要出售，请与商人交谈。",
	["Para ver cuánto procesador usa cada parte, escribe /console scriptProfile 1 y luego /reload. Hace el juego un poco más lento: cuando termines, /console scriptProfile 0 y /reload."] = "想看每个部分占用多少 CPU，输入 /console scriptProfile 1 然后 /reload。这会让游戏稍微变慢：用完后输入 /console scriptProfile 0 并 /reload。",
	["Para ver las guaridas de la manada, deja que te vean en el mapa."] = "想看狼群的巢穴，请让他们在地图上看到你。",
	["Para ver y romper los tótems enemigos."] = "用来发现并摧毁敌方图腾。",
	["Para verlas mejor"] = "让它们更显眼",
	["Para volver a acumularla, descansa (o cierra sesión) en una posada o una ciudad."] = "想重新累积，就在旅店或城镇中休息（或下线）。",
	["Para: %s."] = "用于：%s。",
	["Parada"] = "招架",
	["Parada %d de %d"] = "第 %d/%d 站",
	["Parar"] = "招架",
	["Paras más golpes de otros guerreros y pícaros."] = "招架更多来自其他战士和潜行者的攻击。",
	["Paras más golpes."] = "招架更多攻击。",
	["Paras más golpes: recibes menos daño desde el principio."] = "招架更多攻击：一开始就受到更少伤害。",
	["Paras un poco más."] = "招架稍微多一点。",
	["Paraste un golpe: el contraataque está listo."] = "你招架了一次攻击：反击已就绪。",
	["Paraste un golpe: tu contraataque está listo y desarma al enemigo."] = "你招架了一次攻击：你的反击已就绪，还会缴械敌人。",
	["Paraste un golpe: tu contraataque inmoviliza al enemigo."] = "你招架了一次攻击：你的反击能定住敌人。",
	["Partes de Alfa apagadas"] = "已关闭的 Alfa 部分",
	["Partes de Alfa de otra versión"] = "来自其他版本的 Alfa 部分",
	["Partes de Alfa que no cargaron"] = "没有加载的 Alfa 部分",
	["Paré por el combate: lo demás sigue en el buzón."] = "因战斗暂停：其余的还在邮箱里。",
	["Pasa el ratón por cualquier cosa de Alfa y te digo para qué sirve. Pulsa tu tecla otra vez para terminar."] = "把鼠标移到 Alfa 的任何东西上，我会告诉你它有什么用。再按一次你的按键结束。",
	["Pasa el ratón sobre un compañero y cúralo con un clic."] = "鼠标指向队友，点击一下即可治疗。",
	["Pasa el ratón sobre un compañero y haz clic: el izquierdo %s y el derecho %s."] = "鼠标指向队友并点击——左键：%s；右键：%s。",
	["Pasa enfermedades: quítalas si tu clase puede."] = "他会传播疾病：如果你的职业能驱散就驱掉。",
	["Pasa tu build a un amigo o usa el que te pasen."] = "把你的方案分享给朋友，或使用别人分享的方案。",
	["Pasar solo al siguiente paso"] = "自动进入下一步",
	["Pasas tu vida a tu demonio para curarlo."] = "把你的生命值导给你的恶魔来治疗它。",
	["Paso %d"] = "第 %d 步",
	["Paso %d de %d"] = "第 %d / %d 步",
	["Paso a paso"] = "一步一步",
	["Pasos de nivel claros"] = "清晰的等级步骤",
	["Pasos que siguen, numerados"] = "后续步骤编号",
	["Pastel de cerezas casero"] = "自制樱桃派",
	["Pata de jabalí salvaje"] = "野猪腿",
	["Pausa"] = "暂停",
	["Pausa para el lunch: tú comes, yo miro con ojitos tiernos."] = "午饭时间：你吃，我用水汪汪的眼睛看着你。",
	["Peces"] = "鱼类",
	["Pecho"] = "胸部",
	["Pedazo de pan duro"] = "硬面包",
	["Pedir ayuda a la manada"] = "向狼群求助",
	["Pedir entrar"] = "请求进入",
	["Pedir entrar a su guarida (%s)"] = "请求进入他的巢穴（%s）",
	["Pedirle un consejo"] = "向她要一条建议",
	["Pediste %s; el juego lo dejó en %s."] = "你要求的是 %s；游戏设为了 %s。",
	["Pediste ayuda con %s. Te aviso quién viene."] = "你请求帮忙对付 %s。我会告诉你谁来了。",
	["Pedírselas"] = "向其索要",
	["Pega aquí (Ctrl+V) el texto de una ruta de Alfa."] = "在这里粘贴（Ctrl+V）Alfa 路线的文字。",
	["Pega aquí el texto que copiaste con «Exportar»"] = "在这里粘贴你用“导出”复制的文字",
	["Pega aquí una cadena que empiece con ALFA1; (Ctrl + V) y pulsa Importar. Alfa revisa cada talento contra tu árbol."] = "在这里粘贴一段以 ALFA1; 开头的字符串（Ctrl + V），然后点击“导入”。Alfa 会对照你的天赋树逐一检查天赋。",
	["Pega el texto de «Exportar» para traer esa configuración. Lo de ahora queda guardado como perfil por si acaso."] = "粘贴“导出”的文字来恢复那套设置。为保险起见，当前设置会保存为配置档。",
	["Pega fuerte pero no tiene trucos: es un buen jefe para aprender."] = "打人很痛但没有特殊技能：很适合练手的首领。",
	["Pega fuerte y se protege con un escudo de luz: empieza con la vida llena."] = "他打人很痛，还会用圣光护盾保护自己：满血再开打。",
	["Pega fuerte: ve con cuidado y con la vida llena."] = "打得很痛：小心点，满血再上。",
	["Pega muchas veces seguidas al tanque: no dejes que su vida baje de la mitad."] = "他会连续多次攻击坦克：别让坦克的血量低于一半。",
	["Pega muy fuerte: empieza la pelea con la vida llena."] = "他打人非常痛：满血再开打。",
	["Pega primero una cadena de build de Alfa."] = "请先粘贴一段 Alfa 方案字符串。",
	["Pega primero una cadena de escala de estadísticas."] = "请先粘贴属性权重字符串。",
	["Pega una cadena de escala de estadísticas (Ctrl+V), la que copiaste desde donde la compartieron."] = "粘贴属性权重字符串（Ctrl+V），即你从分享处复制的那段。",
	["Pega varias veces seguidas: empieza con la vida llena."] = "他会连续攻击好几次：满血再开打。",
	["Pegas a dos: útil contra mascotas y grupos."] = "同时攻击两个目标：对付宠物和多人时很有用。",
	["Pegas más después de recibir críticos."] = "受到暴击后打得更痛。",
	["Pegas más fuerte después de recibir críticos."] = "受到暴击后打得更痛。",
	["Pegas más fuerte después de recibir un golpe crítico."] = "受到一次暴击后打得更痛。",
	["Pelea con un solo monstruo a la vez; si vienen dos, usa Golpes de barrido."] = "一次只打一个怪物；如果来了两个，就用横扫攻击。",
	["Pelea siempre con la vida llena; no encadenes monstruos sin descansar."] = "始终满血作战；别不休息就连续拉怪。",
	["Pelear contra otros jugadores: aguantar, frenar y rematar."] = "和其他玩家对战：扛得住、减速、终结。",
	["Peletería"] = "制皮",
	["Peletería hace cuero con armadura y aguante para la forma de oso."] = "制皮能做出带护甲和耐力的皮甲，适合熊形态。",
	["Peletería hace malla para ti; Desuello te da el material sin gastar oro."] = "制皮能为你做锁甲；剥皮免费提供材料，不用花金币。",
	["Peletería hace piezas de cuero con agilidad y aguante; Desuello te da el cuero."] = "制皮能做出带敏捷和耐力的皮甲；剥皮提供皮革。",
	["Peligro"] = "危险",
	["Peligros"] = "危险",
	["Peligrosa para tu nivel"] = "对你的等级很危险",
	["Pendiente"] = "待完成",
	["Pequeñas tareas que Alfa hace por ti al abrir un comerciante, al despojar y al viajar."] = "打开商人、拾取和旅行时，Alfa 替你做的小事。",
	["Pequeños íconos en cada ataque: si es para el tanque, para quien cura, si se puede quitar o si es mortal."] = "每个攻击旁的小图标：表示是针对坦克还是治疗、能否驱散，或是否致命。",
	["Perdimos el rastro de %s: ya no sabemos dónde está."] = "已失去%s的踪迹：不再知道其位置。",
	["Perfil guardado"] = "配置档已保存",
	["Perjuicios que puedes quitar"] = "你能驱散的减益效果",
	["Personaje"] = "角色",
	["Pesca"] = "钓鱼",
	["Pesca %d/%d"] = "钓鱼 %d/%d",
	["Pesca 10 de oro en valor en una sola sesión."] = "在一次钓鱼中钓到价值 10 金币的东西。",
	["Pesca 25 especies distintas."] = "钓到 25 种不同的鱼。",
	["Pesca 5 especies distintas en una misma zona."] = "在同一区域钓到 5 种不同的鱼。",
	["Pesca 5 especies distintas."] = "钓到 5 种不同的鱼。",
	["Pesca de Alfa apagada. Tu tecla y tus ajustes quedan como siempre."] = "Alfa 钓鱼已关闭。你的按键和设置保持原样。",
	["Pesca de Alfa encendida, pero en pausa mientras otro addon de pesca esté activo."] = "Alfa 钓鱼已开启，但在其他钓鱼插件启用期间暂停。",
	["Pesca de Alfa encendida."] = "Alfa 钓鱼已开启。",
	["Pesca en 10 zonas distintas."] = "在 10 个不同的区域钓鱼。",
	["Pesca en los bancos de peces que flotan en el agua: dan más que pescar en cualquier lado."] = "在水面上漂着的鱼群里钓鱼：收获比在别处钓多。",
	["Pesca en los bancos de peces que flotan en el agua: dan más y a veces sorpresas."] = "在水面上漂着的鱼群里钓鱼：收获更多，有时还有惊喜。",
	["Pesca un trofeo o un pez de concurso."] = "钓到一条奖杯鱼或大赛用鱼。",
	["Pesca una hora en una sola sesión."] = "在一次钓鱼中连续钓一小时。",
	["Pesca: si te atacan mientras vuelve tu equipo normal, ya no pierdes piezas."] = "钓鱼：如果你在换回平常装备时遭到攻击，不会再丢失装备。",
