	["Pestañas con el estilo"] = "标签页套用风格",
	["Pez"] = "鱼",
	["Picadura de serpiente: daño con el tiempo."] = "毒蛇钉刺：持续伤害。",
	["Pide %d de Cocina y aprender la receta."] = "需要烹饪 %d 并学会配方。",
	["Pide %d de habilidad de pesca."] = "需要钓鱼技能 %d。",
	["Pide al grupo que espere unos segundos antes de atacar."] = "让队友等几秒再开始攻击。",
	["Pide ayuda con %s."] = "请求帮忙对付 %s。",
	["Pide ayuda con un élite o un raro: los lobos de tu zona reciben tu lugar y te avisa quién viene."] = "遇到精英或稀有怪就请求帮助：区域里的狼会收到你的位置，你会知道谁来了。",
