	["Poder arcano: más daño un rato, mientras te sobre maná."] = "奥术强化：一段时间内伤害提高，法力有富余时使用。",
	["Poder con hechizos"] = "法术强度",
	["Poder de ataque"] = "攻击强度",
	["Poder de ataque a distancia"] = "远程攻击强度",
	["Polestar es de código abierto:"] = "Polestar 是开源的：",
	["Polvo arcano"] = "魔粉",
	["Polvo cegador"] = "闪光粉",
	["Pon Seccionar en cuanto llegues al rival y mantenlo puesto."] = "一冲到对手面前就挂上断筋，并保持住。",
	["Pon ahora"] = "现在点",
	["Pon todos tus hechizos de daño en el tiempo y deja que tu demonio aguante."] = "挂上所有持续伤害法术，让你的恶魔来扛。",
	["Pon tu escudo y tu daño en el tiempo antes de que el monstruo llegue."] = "在怪物靠近之前套上护盾、挂好持续伤害。",
	["Pon tu objeto en la pestaña de vender: a un lado te digo su precio sugerido, cómo le fue estos días y te aviso si lo das muy barato. El precio lo pones tú."] = "把物品放进出售栏：我会在旁边告诉你建议价格、这几天的行情，卖太便宜时提醒你。价格由你决定。",
	["Pon tu piedra de hogar en la posada donde tengas más misiones."] = "把炉石绑定在你任务最多的那家旅店。",
	["Pon tu tótem abrasador: dispara al enemigo por ti."] = "放下灼热图腾：它会替你攻击敌人。",
	["Pon tus tótems al empezar cada pelea grande."] = "每场大战开始时放下你的图腾。",
	["Pon un cebo 10 veces."] = "上鱼饵 10 次。",
	["Pon un tótem antes de empezar la pelea."] = "开打之前先放一个图腾。",
	["Pon una trampa antes de empezar la pelea y lleva al monstruo hacia ella."] = "开打之前先放一个陷阱，再把怪物引过去。",
	["Pon venenos en tus armas siempre."] = "武器上始终涂好毒药。",
	["Pone el enlace en el chat."] = "把链接发到聊天中。",
	["Pone la flecha ahí."] = "把箭头设在那里。",
	["Pone los ajustes de un perfil que guardaste. Algunas cosas se ven completas al recargar."] = "套用你保存的配置档设置。有些内容重载后才会完整显示。",
	["Pone los marcos donde estaban al instalar Alfa."] = "将框体放回安装 Alfa 时的位置。",
	["Pone tres ataques de prueba en la línea de tiempo para que veas dónde sale. Se borran solos. Para moverla: menú del juego (Esc) > Modo de edición."] = "在时间轴上放三个测试攻击，让你看到它显示在哪里。它们会自动消失。要移动它：游戏菜单（Esc）> 编辑模式。",
	["Pone una maldición que baja la curación que recibes: quítala si tu clase puede."] = "他会施放降低受到治疗效果的诅咒：如果你的职业能驱散就驱掉。",
	["Pone una maldición que te debilita y un fuego que quema poco a poco: quita la maldición si puedes."] = "他会施放虚弱诅咒和持续灼烧的火焰：能驱散诅咒就驱掉。",
	["Poner el cebo"] = "上鱼饵",
	["Poner la flecha aquí"] = "把箭头设在这里",
	["Poner la flecha hasta ahí"] = "把箭头指向那里",
	["Ponerme el equipo de pesca"] = "换上我的钓鱼装备",
	["Ponerme lo de pesca"] = "换上钓鱼装备",
	["Ponerme una meta"] = "给自己定个目标",
	["Ponerte la recompensa si es mejor"] = "奖励更好时就装备上",
	["Ponlo de espaldas al grupo para que su golpe solo te dé a ti."] = "让他背对队伍，这样他的攻击只会打到你。",
	["Ponlo de espaldas al grupo y aguanta: la pelea es corta."] = "让他背对队伍，撑住就行：这场战斗很短。",
	["Ponlos al empezar a pelear."] = "战斗开始时放下图腾。",
	["Ponte esto"] = "穿上这个",
	["Ponte la caña primero."] = "请先装备鱼竿。",
	["Ponte un conjunto guardado o guarda lo que llevas puesto."] = "穿上已保存的方案，或保存身上的装备。",
	["Ponte un escudo antes de empezar cada pelea."] = "每场战斗开始前先给自己套上护盾。",
	["Ponte una meta: un pez, capturas, tiempo o valor."] = "定个目标：一种鱼、渔获数、时间或价值。",
	["Ponérmelo"] = "装备上",
	["Por Costa Oscura anda un explorador de la Liga muy despistado, que siempre necesita que alguien le eche la mano."] = "黑海岸有一位非常迷糊的探险者协会勘探员，总是需要有人帮他一把。",
	["Por ahora, guárdalo todo"] = "目前全部保留",
	["Por bolsa"] = "按背包",
	["Por categorías"] = "按类别",
	["Por clase"] = "按职业",
	["Por debajo de tu nivel"] = "低于你的等级",
	["Por defecto"] = "默认",
	["Por dentro, Alfa está construido sobre Polestar, de fitzforge y The Polestar authors (GPL-3.0): su motor de guías, flecha y datos. Alfa lo adapta, le suma sus propios módulos y sigue siendo libre."] = "在内部，Alfa 构建于 fitzforge 和 The Polestar authors（GPL-3.0）的 Polestar 之上：它的指南、箭头和数据引擎。Alfa 对其进行改编，加入自己的模块，并保持自由。",
	["Por descubrir"] = "未探索",
	["Por dónde sale: %s"] = "发送途径：%s",
	["Por dónde se pasa a otra zona (caminos, pasos, túneles y puertas), con una flecha hacia ella y su rango de niveles. Se ven al acercarte a una zona."] = "通往其他区域的地方（道路、山口、隧道和大门），附指向该区域的箭头及其等级范围。放大到某个区域时就会显示。",
	["Por ejemplo: primero un objeto, luego 10 de oro, luego subir cocina y al final el banco."] = "例如：先拿一件物品，然后攒 10 金币，再提升烹饪，最后去银行。",
	["Por eso empezamos con esta configuración: para que cada quien arme su experiencia a su gusto. Todo se puede cambiar después."] = "所以我们从这个设置开始：让每个人都能按自己的喜好打造体验。之后一切都可以更改。",
	["Por estas montañas se llega al Valle de Alterac, donde la Guardia Pico Tormenta y el clan Lobo Gélido pelean sin descanso."] = "穿过这些山脉就能到达奥特兰克山谷，雷矛卫队和霜狼氏族在那里无休止地战斗。",
	["Por grupo"] = "按小队",
	["Por honor (JcJ)"] = "荣誉兑换（PvP）",
	["Por hora"] = "每小时",
	["Por hora: %s"] = "每小时：%s",
	["Por la Alianza mandan Bolvar como regente en Ventormenta, Magni en Forjaz, Tyrande en Darnassus y Mekkatorque con los gnomos."] = "联盟方面，伯瓦尔以摄政王身份统治暴风城，麦格尼统治铁炉堡，泰兰德统治达纳苏斯，梅卡托克领导侏儒。",
	["Por la selva de Feralas caminan gigantes enormes. ¡Cuidado con sus pisadas!"] = "菲拉斯的丛林里走着巨大的巨人。小心他们的脚步！",
	["Por lograr"] = "尚未达成",
	["Por los canales de Entrañas corre una baba verde que mejor ni probar."] = "幽暗城的运河里流着绿色的黏液，最好别尝。",
	["Por mazmorra"] = "按地下城",
	["Por nivel: jefes, botín, misiones, la entrada y consejos."] = "按等级：首领、战利品、任务、入口和提示。",
	["Por nombre"] = "按名字",
	["Por nombre, tipo o calidad (verde, azul...) y por nivel de objeto: 20, >20, 20-30. Lo que coincide se resalta."] = "按名称、类型或品质（绿色、蓝色……）以及物品等级搜索：20、>20、20-30。匹配的会高亮显示。",
	["Por reputación"] = "声望兑换",
	["Por rol"] = "按职责",
	["Por terminar"] = "未完成",
	["Por una salchicha te sigo hasta Rasganorte. Bueno, te seguiría igual."] = "为了一根香肠，我能跟你去诺森德。好吧，没有香肠我也会跟着你。",
	["Por unos segundos no recibes daño físico. Tu salvavidas cuando las cosas se ponen feas."] = "几秒内你不受任何物理伤害。情况变糟时的救命技。",
	["Por zona (este personaje)"] = "按区域（此角色）",
	["Porcentaje de vida"] = "生命值百分比",
	["Portal a %s"] = "通往%s的传送门",
	["Portales"] = "传送门",
	["Posada"] = "旅店",
	["Posada de %s"] = "%s旅店",
	["Posadas"] = "旅店",
	["Posadero"] = "旅店老板",
	["Posaderos"] = "旅店老板",
	["Posaderos; se marca el de tu piedra de hogar."] = "旅店老板；会标出你炉石绑定的那位。",
	["Preajuste «%s» listo para tus clics."] = "预设“%s”已套用到你的点击上。",
	["Preajustes"] = "预设",
	["Preajustes listos para usar"] = "现成的预设",
	["Preajustes, ajustes escondidos del juego, cámara, placas y filtros para que el mundo se vea mejor."] = "预设、游戏隐藏设置、镜头、姓名板和滤镜，让世界看起来更美。",
	["Precio"] = "价格",
	["Precio de %s"] = "%s的价格",
	["Precio sugerido"] = "建议价格",
	["Precios %s · %s objetos"] = "价格 %s · %s 种物品",
	["Precios al día"] = "价格为最新",
	["Precios de la subasta"] = "拍卖价格",
	["Precios viejos"] = "价格过旧",
	["Precios y qué conviene vender."] = "价格以及什么值得卖。",
	["Precisión"] = "命中",
	["Precisión con hechizos"] = "法术命中",
	["Preguntar a la manada"] = "询问狼群",
	["Preguntas"] = "问题",
	["Pregúntale a Lya"] = "问问莉娅",
	["Pregúntale a Lya: clic derecho en ella y «¿En qué te ayudo?». Te explica cada parte de Alfa y te lleva con un clic."] = "问问莉娅：右键她选“我能帮你什么？”。她讲解 Alfa 的每个部分，一点就带你过去。",
	["Pregúntale a Lya: todo lo de Alfa explicado y a un clic"] = "问问莉娅：Alfa 的一切都有解释，一点就到",
	["Pregúntale a la manada"] = "问问狼群",
	["Pregúntale a un guardia de la ciudad por el instructor de la profesión."] = "向城里的卫兵打听专业训练师在哪里。",
	["Premio final: %s"] = "最终奖励：%s",
	["Premio final: %s de experiencia"] = "最终奖励：%s 经验",
	["Premio: %s"] = "奖励：%s",
	["Prendas de lana que te enseñe tu instructor."] = "训练师教你的毛料衣物。",
	["Prendas de seda que te enseñe tu instructor."] = "训练师教你的丝绸衣物。",
	["Prendas de tejido mágico que te enseñe tu instructor."] = "训练师教你的魔纹布衣物。",
	["Prendas de tela rúnica que te enseñe tu instructor."] = "训练师教你的符文布衣物。",
	["Prende la ayuda de rotación en Combate: te sugiero qué usar ahora y qué sigue. Solo sugiero; los botones los presionas tú."] = "在“战斗”里打开循环助手：我建议现在用什么、接下来用什么。我只建议，按键是你按。",
	["Prende la línea de tiempo, los íconos de ayuda y los mensajes medianos y graves."] = "开启时间轴、辅助图标以及中等和严重级别的提示。",
	["Prende los marcos de Curación: pasas el ratón sobre un compañero y con un clic lo curas."] = "打开“治疗”框体：鼠标移到队友身上，一键治疗。",
	["Prende todo el sistema de avisos de jefes de Blizzard: la línea de tiempo y los mensajes en pantalla. Sin esto, lo demás no se ve."] = "开启暴雪的整个首领警报系统：时间轴和屏幕提示。不开启的话，其他选项都不会显示。",
	["Prender o apagar"] = "开启或关闭",
	["Prenderlo"] = "开启",
	["Prepara tus marcos de curación"] = "设置你的治疗框体",
	["Prepara tus marcos en 3 pasos"] = "3 步设置你的框体",
	["Preparando %s… %s"] = "正在准备%s… %s",
	["Preparando %s… la ficha se completa sola."] = "正在准备%s… 详情页会自动补全。",
	["Preparando la enciclopedia…"] = "正在准备百科…",
	["Preparando lo que contiene… la ficha se completa sola."] = "正在准备内含物品… 详情页会自动补全。",
	["Preparando lo que da… la ficha se completa sola."] = "正在准备提供的东西… 详情页会自动补全。",
	["Preparando lo que vende y suelta… la ficha se completa sola."] = "正在准备出售和掉落的物品… 详情页会自动补全。",
	["Preparar la mazmorra"] = "准备地下城",
	["Prepárame"] = "帮我准备",
	["Prepárate para entrar"] = "准备进入",
	["Prepárate: llega en %s"] = "准备好：%s后到达",
	["Presencia mental: tu siguiente hechizo es instantáneo."] = "气定神闲：你的下一个法术变为瞬发。",
	["Primer aviso"] = "首次提醒",
	["Primer tirón"] = "第一次咬钩",
	["Primero cobra lo que ya hiciste: una ruta por el camino más corto, junta por PNJ."] = "先交付你已完成的：一条最短路线，按 NPC 分组。",
	["Primero con el banco de la hermandad"] = "优先使用公会银行",
	["Primero crea una ruta: /alfa recoleccion ruta"] = "请先创建路线：/alfa recoleccion ruta",
	["Primero defensa: paras muchos más golpes y descansas menos."] = "防御优先：招架更多攻击，休息更少。",
	["Primero elige tu build"] = "请先选择你的方案",
	["Primero necesitas %s, que se toma a nivel %d."] = "首先你需要%s，%d 级可接。",
	["Primero pelean contra el Comandante Mograine; cuando cae, ella llega y lo resucita."] = "先和莫格莱尼指挥官战斗；他倒下后，她会赶来复活他。",
	["Primero prende la línea de tiempo del jefe."] = "请先开启首领时间轴。",
	["Primero sale su trituradora; al romperla, Sneed baja y pelea a pie."] = "先出来的是他的伐木机；打坏后，斯尼德会跳下来徒步战斗。",
	["Primero toma %s"] = "先接取%s",
	["Primero un objeto, luego oro, luego una profesión y al final el banco: tú eliges el orden."] = "先拿一件物品，然后金币，再一项专业，最后去银行：顺序由你决定。",
	["Primero: %s"] = "首先：%s",
	["Primeros auxilios"] = "急救",
	["Primeros auxilios le sirve a cualquier clase, sobre todo a las que no se curan solas."] = "急救对任何职业都有用，尤其是不能自我治疗的职业。",
	["Primeros auxilios sirve a cualquier clase: unas vendas te sacan de apuros."] = "急救对任何职业都有用：几条绷带就能帮你脱困。",
	["Principal"] = "主",
	["Principal [mano]"] = "主手",
	["Probador"] = "试衣间",
	["Probar"] = "试一下",
	["Probar con 20"] = "用 20 人测试",
	["Probar con 5"] = "用 5 人测试",
	["Probar el aviso"] = "测试提醒",
	["Probar la línea de tiempo"] = "测试时间轴",
	["Probar la pantalla limpia"] = "试试清爽画面",
	["Probar la ventana"] = "试用窗口",
	["Probar otra vez"] = "重试",
	["Probar un aviso"] = "测试提醒",
	["Procesador: Alfa usa %.2f ms por cuadro ahora. Lo que más usa:"] = "CPU：Alfa 现在每帧占用 %.2f 毫秒。占用最多的：",
	["Procesador: Alfa usó %.0f ms desde que entraste o recargaste. Lo que más usa:"] = "CPU：自你登录或重载以来，Alfa 共用了 %.0f 毫秒。占用最多的：",
	["Profesiones"] = "专业",
	["Profesiones (18): llegar a 150, 225 y 300 en Alquimia, Herrería, Encantamiento, Ingeniería, Peletería y Sastrería."] = "专业（18）：炼金术、锻造、附魔、工程学、制皮和裁缝分别达到 150、225 和 300。",
	["Profesiones que te sirven"] = "对你有用的专业",
	["Profesiones: más puntos de habilidad, más recursos al recolectar, mejores precios con los vendedores, más platos y más peces."] = "专业：更多技能点数、采集时获得更多资源、商人价格更优惠、更多菜肴和更多鱼。",
	["Profesión"] = "专业",
	["Promedio de la sesión: %s XP por hora."] = "本次平均：每小时 %s 经验。",
	["Promedio de la sesión: %s XP por hora. XP ganada: %s."] = "本次平均：每小时 %s 经验。获得经验：%s。",
	["Proponer"] = "提议",
	["Proponer la siguiente guía"] = "推荐下一个指南",
	["Propusiste una cita"] = "你提议了一次集合",
	["Propón qué, el día y la hora: a los lobos de tu hermandad con Alfa les llega con «Voy». Te recuerdo 15 minutos antes."] = "提议做什么、哪天、几点：你公会里装了 Alfa 的狼会收到，并附“我去”按钮。我会提前 15 分钟提醒你。",
	["Propón una salida a la manada (/alfa cita mañana 21:30 Minas)"] = "向狼群提议一次出行（/alfa cita tomorrow 21:30 矿井）",
	["Propón una salida con día y hora y recibe las de tu hermandad con «Voy». Lya te la recuerda 15 minutos antes."] = "提议一次带日期和时间的出行，并通过“我去”接收公会的提议。莉娅会提前 15 分钟提醒你。",
	["Protección"] = "防护",
	["Protección [paladín]"] = "防护",
	["Protección para subir"] = "防护（升级）",
	["Protección para subir [paladín]"] = "防护（升级）",
	["Protege a un aliado de todo daño físico un momento. Salva a quien cura."] = "让一个盟友在片刻内免疫所有物理伤害。救你的治疗者。",
	["Proyectiles"] = "弹药",
	["Prueba"] = "测试",
	["Prueba con %d: arrastra para mover"] = "%d 人测试：拖动以移动",
	["Prueba con el nombre del pueblo o de la zona."] = "试试城镇或区域的名字。",
	["Prueba con otra búsqueda o quita un filtro."] = "试试其他搜索词或移除一个筛选条件。",
	["Prueba con otra palabra o elige Todas."] = "试试其他词，或选择“全部”。",
	["Prueba con otra palabra o quita el filtro."] = "试试别的关键词，或取消筛选。",
	["Prueba con otra palabra, como «pasto», «niebla» o «sombras»."] = "试试别的关键词，例如“草”、“雾”或“阴影”。",
	["Prueba con otra palabra, en español o en inglés, o quita un filtro."] = "试试其他词（西班牙语或英语），或移除一个筛选条件。",
	["Prueba con otra palabra."] = "试试其他词。",
	["Prueba con otro filtro."] = "试试其他筛选条件。",
	["Prueba de Alfa %d"] = "Alfa 测试 %d",
	["Prueba tus clics"] = "测试你的点击",
	["Pruébala fuera de mazmorras y bandas."] = "请在地下城和团队副本之外测试。",
	["Préndelo para ver jefes, botín, misiones y consejos de cada mazmorra."] = "开启后可查看每个地下城的首领、战利品、任务和提示。",
	["Préndelos abajo, en «Lya y su manada»."] = "在下方的“莉娅和她的狼群”中开启。",
	["Publicar"] = "发布",
	["Puede controlar la mente de un jugador: no lo ataquen, esperen a que se le pase."] = "他能控制一名玩家的心智：别攻击那名玩家，等效果结束。",
	["Puede convertir a alguien en huargo: no ataquen a ese jugador, se le pasa solo."] = "他能把人变成狼人：别攻击那名玩家，效果会自己消失。",
	["Puede dormir a alguien del grupo: sigue peleando, se despierta solo."] = "她能让队伍中的某人睡着：继续战斗，那人会自己醒来。",
	["Puede dormir a alguien y golpear a todos los que están cerca."] = "他能让人睡着，还会攻击附近所有人。",
	["Puede lanzarte por los aires con un gancho: regresa rápido para que no vaya tras quien cura."] = "他的上勾拳能把你打飞：赶快跑回来，免得他去追治疗。",
	["Puede pisotear a los que pelean cuerpo a cuerpo: mantén su vida alta."] = "他会践踏近战玩家：保持他们的血量充足。",
	["Puede que el archivo se dañara. Tienes un respaldo del %s."] = "文件可能损坏了。你有一份 %s 的备份。",
	["Puede que hayas omitido lo que queda o que aún no te toque. Elige otra guía o vuelve a esta más adelante."] = "你可能跳过了剩下的部分，或者还没轮到。选择另一份指南，或稍后再回来。",
	["Puedes Cargar en actitud defensiva: empiezas a tanquear sin cambiar de actitud."] = "防御姿态下也能冲锋：不用切换姿态就能开始坦怪。",
	["Puedes abrir cerraduras: practica con cajas fuertes y cofres, y ofrécele el servicio a tu grupo."] = "你能开锁：拿保险箱和宝箱练手，再为你的队伍提供这项服务。",
	["Puedes cambiar cada tramo."] = "每个路段都可以更换。",
	["Puedes crear comida y agua para todo el grupo. ¡Y si un día aprendes a hacer salchichas, me avisas!"] = "你能为全队制造食物和水。要是哪天你学会做香肠，记得告诉我！",
	["Puedes desollar casi cualquier bestia que mates: el cuero sale de todos lados."] = "你杀的野兽几乎都能剥皮：皮革到处都有。",
	["Puedes hacerte amigo de los piratas Velasangre matando goblins de Bahía del Botín... aunque luego los guardias goblin te odiarán."] = "杀藏宝海湾的地精可以和血帆海盗交朋友……不过之后地精卫兵会恨死你。",
	["Puedes revivir a tus compañeros fuera de combate: en una mazmorra eres de lo más valioso."] = "你能在非战斗状态下复活同伴：在地下城里你是最宝贵的人之一。",
	["Puedes revivirte tú solo al morir. Necesitas un ankh."] = "你死后可以自己复活。需要一个十字章。",
	["Puedes tomarla"] = "你可以接取",
	["Puedes usarlo"] = "你可以使用",
	["Puedes vender %d cosas por unos %s."] = "你可以卖掉 %d 件东西，约 %s。",
	["Puedes vender %s (unos %s)."] = "你可以卖掉%s（约 %s）。",
	["Puedes vender %s por %s."] = "你可以把%s卖出%s。",
	["Puedes volver a ese paso desde «Ver detalle»."] = "你可以从“查看详情”回到那一步。",
	["Puedo usar"] = "我能用的",
	["Puesto"] = "已套用",
	["Pulsa %s %s"] = "按 %s %s",
	["Pulsa Cocinar: cada clic hace un lote. Tienes que estar junto a un fuego."] = "点击“烹饪”：每次点击做一批。你必须在火堆旁边。",
	["Pulsa Guiarme y la flecha te lleva de parada en parada desde la más cercana."] = "点击“带我去”，箭头会从最近的站点开始逐站带你。",
	["Pulsa una tecla…"] = "请按一个键…",
	["Pulsa «Cambiar de plano» en La Jauría o escribe /alfa plano: le pido a un lobo con su guarida abierta en otro plano que te invite. Acepta, y al llegar sales del grupo."] = "在 La Jauría 点“切换位面”或输入 /alfa plano：我会请一只在其他位面开着巢穴的狼邀请你。接受邀请，到了之后离开队伍。",
	["Punta de Torio es el campamento de la Hermandad del Torio, y ahí se juntan Alianza y Horda para hacer negocios."] = "瑟银哨塔是瑟银兄弟会的营地，联盟和部落都在那里做生意。",
	["Puntería"] = "射击",
	["Puntería para subir"] = "射击（升级）",
	["Punto %d de tu build (nivel %d), hasta %d/%d."] = "你方案的第 %d 点（%d 级），到 %d/%d。",
	["Puntos %d a %d de tu build (niveles %d a %d)."] = "你方案的第 %d 到 %d 点（%d 到 %d 级）。",
	["Puntos de ruta"] = "路径点",
	["Puntos de vuelo"] = "飞行点",
	["Puntos del legado"] = "传承点数",
	["Puntos por gastar"] = "有未分配点数",
	["Página Ruta"] = "“路线”页面",
	["Pásale el ratón: en su cuadro te digo lo que ganas y lo que pierdes contra lo que llevas puesto, con números. Lo primero es lo que más le sirve a tu clase."] = "把鼠标移上去：在它的提示框里，我会用数字告诉你和身上装备相比得到和失去什么。最前面的是对你职业最有用的。",
	["Pégalo en %s del Discord de La Jauría."] = "把它粘贴到 La Jauría Discord 的 %s。",
	["Pícaro"] = "潜行者",
	["Pídeme el «Circuito de la zona» (página Ruta o el menú del rastreador): junto las que llevas y las que puedes tomar aquí y te llevo por el camino más corto."] = "找我要“区域环线”（路线页面或追踪器的菜单）：我会把你身上的任务和这里能接的任务集合起来，带你走最短的路。",
	["Pídeselas y, si quieres, sigue su ruta: tu flecha irá con la suya."] = "向其索要，如果愿意还可以跟随其路线：你的箭头会跟着对方的。",
	["Que Lya te la cuente"] = "让莉娅讲给你听",
	["Que a ese compañero le falta el buff de tu clase. Pasa el ratón sobre su marco: te digo con qué clic se lo das."] = "表示那名队友缺少你职业的增益效果。把鼠标移到他的框体上：我会告诉你用哪个点击给他加上。",
	["Que la manada vea a mi personaje en el mapa"] = "让狼群在地图上看到我的角色",
	["Que me vean en el mapa"] = "让他们在地图上看到我",
	["Que suene también cuando vas solo por el mundo."] = "你独自在世界中冒险时也播放提示音。",
	["Queda 1"] = "剩 1 个",
	["Queda lejos: unos %s de camino"] = "距离很远：约 %s 路程",
	["Quedan %d"] = "剩 %d 个",
	["Quedan %d casillas libres y no llevas nada que convenga vender: guarda algo en el banco."] = "剩余 %d 个空格，且没有值得卖的东西：存一些到银行吧。",
	["Quedan %d casillas libres. Puedes vender %s (unos %s)."] = "剩余 %d 个空格。你可以卖掉%s（约 %s）。",
	["Quedan %s"] = "剩余 %s",
	["Quedó sin pasos: agrega tramos o recalcula."] = "没有任何步骤：请添加路段或重新计算。",
	["Quema al enemigo de golpe y durante un rato. Buen inicio de pelea."] = "立即灼烧敌人并持续燃烧。很好的起手技。",
	["Quema al enemigo un rato."] = "让敌人燃烧一段时间。",
	["Quien instala Alfa ya tiene encendidos los colores de clase, el cuadro de información, el probador, el minimapa y las barras con el estilo de Alfa."] = "新安装的 Alfa 已默认开启职业颜色、鼠标提示、试衣间、小地图和 Alfa 风格的动作条。",
	["Quien lleva la insignia de La Jauría la luce en el borde de su retrato: en el tuyo, el de tu objetivo y el de tu foco."] = "拥有 La Jauría 徽章的人会在头像边缘显示它：你的、你目标的和你焦点的头像。",
	["Quien recibe la misión"] = "任务交付人",
	["Quien repara tu equipo"] = "能修理装备的人",
	["Quien te pegue cuerpo a cuerpo se lastima. Pónsela al que tanquea."] = "近战攻击你的人会受到伤害。给你的坦克加上。",
	["Quien use Alfa en tu grupo lo recibe y puede seguirlo."] = "队伍中使用 Alfa 的人会收到并可以跟随。",
	["Quienes apoyan y construyen Polestar, el motor en el que se basa Alfa."] = "支持和开发 Polestar 的人们，Polestar 是 Alfa 所基于的引擎。",
	["Quienes apoyan, construyen y reportan errores de Polestar, el motor en el que se basa Alfa."] = "支持、开发 Polestar 并报告其错误的人们，Polestar 是 Alfa 所基于的引擎。",
	["Quienes usan Alfa y comparten te ven en su mapa y pueden seguirte, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase cada 10 segundos mientras te mueves (cada 4 minutos si estás quieto), nunca dentro de mazmorras. Va por un canal oculto de Alfa: no sale en el chat, pero alguien que entre a ese canal con otro addon podría leerlo."] = "使用 Alfa 并分享位置的人能在地图上看到你并跟随你，你也能跟随他们。移动时每 10 秒（静止时每 4 分钟）发送你的区域、位置、等级和职业，在地下城中从不发送。它通过 Alfa 的隐藏频道发送：不会显示在聊天中，但用其他插件加入该频道的人可以读取。",
	["Quienes van contigo y usan Alfa ven cómo vas en las misiones que comparten."] = "和你同行并使用 Alfa 的人可以看到你在共享任务中的进度。",
	["Quiero"] = "我想要",
	["Quiero unirme"] = "我要加入",
	["Quieto"] = "站立",
	["Quita el corte visible donde termina una capa de sombra y empieza la siguiente."] = "消除一层阴影结束、下一层开始处的明显接缝。",
	["Quita la columna de botones junto al chat (menú, canales y voz). Los comandos como /s, /g o /canal siguen igual."] = "移除聊天框旁的一列按钮（菜单、频道和语音）。/s、/g 或 /频道 等命令照常可用。",
	["Quita los grifos de los lados de la barra principal. Edit Mode también tiene su propia opción para esto."] = "移除主动作条两侧的狮鹫。编辑模式也有自己的相应选项。",
	["Quita magia mala a un aliado, o magia buena a un enemigo."] = "移除盟友身上的有害魔法，或敌人身上的有益魔法。",
	["Quita un perfil que ya no usas. Tus ajustes de ahora no cambian."] = "删除不再使用的配置档。你当前的设置不会改变。",
	["Quita un veneno a un aliado."] = "移除盟友身上的一种毒药。",
	["Quita un veneno o una enfermedad a un aliado."] = "移除盟友身上的一种毒药或疾病。",
	["Quita una enfermedad. Úsala en lugares llenos de no-muertos."] = "移除一种疾病。在满是亡灵的地方使用。",
	["Quita una maldición a un aliado."] = "移除盟友身上的一个诅咒。",
	["Quita veneno, enfermedad y magia. Úsalo cuando alguien trae algo malo encima."] = "移除毒药、疾病和魔法。有人身上有讨厌的东西时使用。",
	["Quitar"] = "移除",
	["Quitar de Cerrar mis misiones"] = "从“完成我的任务”中移除",
	["Quitar del mapa"] = "从地图上移除",
	["Quitar del plan"] = "从计划中移除",
	["Quitar el silencio"] = "取消静音",
	["Quitar esta meta"] = "移除此目标",
	["Quitar este tramo"] = "移除此路段",
	["Quitar filtros"] = "清除筛选",
	["Quitar la meta"] = "移除目标",
	["Quitar la niebla del horizonte"] = "去除地平线上的雾",
	["Quitar la prueba"] = "结束测试",
	["Quitar perjuicios"] = "驱散减益效果",
	["Quitar todos los filtros"] = "移除所有滤镜",
	["Quién la da"] = "任务提供者",
	["Quién la da, qué pide, qué te dan y qué necesitas antes."] = "谁提供、要求什么、奖励什么，以及需要先完成什么。",
	["Quién tiene «%s»"] = "谁有“%s”",
	["Quién vende cañas y cebos. Se llenan al abrir la guía de pesca."] = "谁出售鱼竿和鱼饵。打开钓鱼指南后就会填入。",
	["Qué es Alfa"] = "Alfa 是什么",
	["Qué estadísticas buscar"] = "要找的属性",
	["Qué estadísticas buscar y lo mejor que puedes usar en tu nivel."] = "要找的属性，以及你在这个等级能用的最佳装备。",
	["Qué está confirmado"] = "已确认的内容",
	["Qué fabricar con lo que tienes"] = "用现有材料能做什么",
	["Qué guardar"] = "存什么",
	["Qué habilidad presionar ahora y cuáles siguen, avisos de reacción y el top de daño de tu grupo."] = "现在该按哪个技能、接下来按哪些、反应提醒，以及你队伍的伤害排行。",
	["Qué habilidad presionar ahora, cuándo cortar, tu amenaza, tus recargas y el resumen de cada pelea."] = "现在该按哪个技能、何时打断、你的仇恨、你的冷却，以及每场战斗的总结。",
	["Qué hace: %s"] = "效果：%s",
	["Qué hacer ahora, cerrar tus misiones y tus rutas propias."] = "现在该做什么、完成你的任务和你的专属路线。",
	["Qué hacer con ella"] = "要怎么处理它",
	["Qué hacer con lo que llevas"] = "随身物品怎么处理",
	["Qué hacías, qué esperabas y qué pasó. Si puedes, cómo hacer que vuelva a pasar."] = "你当时在做什么、期望发生什么、实际发生了什么。如果可以，说说怎样能让它再次发生。",
	["Qué hay que hacer"] = "要做什么",
	["Qué lugar"] = "哪个地点",
	["Qué me falta"] = "我还缺什么",
	["Qué mensajes mostrar"] = "显示哪些提示",
	["Qué muestran"] = "显示内容",
	["Qué necesitas a tu nivel, paso a paso."] = "你这个等级需要什么，一步一步来。",
	["Qué necesitas a tu nivel: equitación, oro y a quién ir."] = "你这个等级需要什么：骑术、金币以及该找谁。",
	["Qué necesitas a tu nivel: la equitación, el oro, a quién ir y tu montura de clase."] = "你这个等级需要什么：骑术、金币、该找谁以及你的职业坐骑。",
	["Qué nivel"] = "哪个等级",
	["Qué pide"] = "需要什么",
	["Qué presionar y en qué orden, avisos de reacción, la barra de golpe y el medidor de daño."] = "该按什么、按什么顺序、反应提醒、攻击计时条和伤害统计。",
	["Qué quieres buscar"] = "你想查询什么",
	["Qué recolectar"] = "采集什么",
	["Qué recolectar, fabricar o vender hoy."] = "今天该采集、制造或出售什么。",
	["Qué se pinta en tus mapas"] = "你的地图上显示什么",
	["Qué se refleja en el agua: el cielo, el terreno y lo demás."] = "水面反射的内容：天空、地形和其他一切。",
	["Qué se ve"] = "显示内容",
	["Qué son"] = "是什么",
	["Qué son, cómo se gana cada uno, en qué se gastan y cuántos tienes."] = "它们是什么、每一点如何获得、用在哪里，以及你有多少。",
	["Qué talento poner ahora y por qué, tu build en dos clics, tu árbol y tu equipo."] = "现在该点哪个天赋及原因、两下点击搞定方案、你的天赋树和装备。",
	["Qué talento poner y por qué, ayuda de rotación y el daño del grupo."] = "该点哪个天赋及原因、输出循环助手，以及队伍的伤害。",
	["Qué tan definidas se ven las sombras del mundo y de los personajes."] = "世界和角色阴影的清晰程度。",
	["Qué tan difíciles pueden ser las misiones que Alfa elige (siempre de las que ya puedes tomar)."] = "Alfa 所选任务的难度上限（始终是你现在就能接的任务）。",
	["Qué tan grande escribe Lya en su globo. También con clic derecho sobre ella."] = "莉娅在气泡里写字的大小。也可以右键点她。",
	["Qué tan grande se ve Lya."] = "Lya 显示的大小。",
	["Qué tan grande se ve cada casilla."] = "每个格子显示的大小。",
	["Qué tan grandes salen las que vienen después, comparadas con el ícono principal."] = "后续图标相对于主图标显示的大小。",
	["Qué tan rápido se acerca y aleja la cámara."] = "镜头拉近和拉远的速度。",
	["Qué tanto se ve el ícono mientras no peleas."] = "非战斗时图标的显示程度。",
	["Qué te gustaría que Alfa hiciera, o hiciera mejor, y para qué te serviría."] = "你希望 Alfa 做什么或做得更好，以及这对你有什么帮助。",
	["Qué vender y qué conservar"] = "该卖什么、该留什么",
	["Rama"] = "天赋系",
	["Rango %d de %d"] = "等级 %d/%d",
	["Rango de honor %d"] = "荣誉等级 %d",
	["Rango en tu hermandad:"] = "公会会阶：",
	["Ranura vacía"] = "空栏位",
	["Ranura vacía:"] = "空栏位：",
	["Rapidez del doble clic"] = "双击速度",
	["Raro"] = "稀有",
	["Raro de la manada: %s"] = "狼群的稀有怪：%s",
	["Raro élite"] = "稀有精英",
	["Raros"] = "稀有",
	["Raros con reloj"] = "稀有怪计时",
	["Raros de la manada"] = "狼群的稀有怪",
	["Raros de la manada: cuando un lobo encuentra un raro en tu zona, te avisa en qué guarida está, con «Ir de caza» o «Pedir entrar»."] = "狼群的稀有怪：狼在你的区域发现稀有怪时，会告诉你在哪个巢穴，附带“去狩猎”或“请求进入”。",
	["Raros en el mapa"] = "地图上的稀有",
	["Raros en el minimapa"] = "小地图上的稀有",
	["Raros y tesoros"] = "稀有和宝藏",
	["Rasganorte es el continente helado del norte. En su centro está la Corona de Hielo, el trono del Rey Exánime."] = "诺森德是北方的冰雪大陆。它的中心是寒冰皇冠，巫妖王的王座所在。",
	["Rastreador propio y misiones que se liberan o se recogen en un clic."] = "专属任务追踪器，一键清理或接取任务。",
	["Ravenholdt, la casa de los pícaros, se esconde en las Montañas de Alterac."] = "盗贼之家拉文霍德隐藏在奥特兰克山脉中。",
	["Ravenholdt, la mansión de los pícaros, se esconde en las montañas de Alterac. Si no te invitan, ni la buscas."] = "盗贼的庄园拉文霍德藏在奥特兰克的山里。没人邀请的话，就别去找了。",
	["Rayos de sol"] = "阳光光束",
	["Rayos que dañan a quien te pegue. Mantenlo puesto."] = "对攻击你的人造成伤害的闪电。保持它的效果。",
	["Rayos y fuego desde lejos: mucho daño de golpe."] = "从远处施放闪电和火焰：瞬间爆发伤害很高。",
	["Razas"] = "种族",
	["Raíz espinosa silvestre"] = "野生棘根草",
	["Reactivos %s  ·  el producto vale %s"] = "材料 %s  ·  成品价值 %s",
	["Reanudar"] = "继续",
	["Rearmar el plan"] = "重新规划",
	["Recalcular"] = "重新计算",
	["Recargar ahora"] = "立即重载",
	["Recargar y seguir"] = "重载并继续",
	["Recargas largas"] = "长冷却",
	["Receta"] = "配方",
	["Receta: %s%s. Cada unidad rinde ≈ %s."] = "配方：%s%s。每件约可得 %s。",
	["Recetas"] = "配方",
	["Recetas de pescado"] = "鱼类配方",
	["Rechaza las de quien no es tu amigo ni de tu hermandad."] = "拒绝非好友、非公会成员的邀请。",
	["Rechaza las invitaciones a hermandades, salvo de tus amigos."] = "拒绝公会邀请，好友发来的除外。",
	["Rechaza los duelos, salvo de tus amigos y tu hermandad."] = "拒绝决斗，好友和公会成员发来的除外。",
	["Rechaza por ti"] = "替你拒绝",
	["Recibes menos daño y generas más amenaza. Es la postura para tanquear en mazmorras."] = "受到的伤害更少，产生更多仇恨。坦克地下城用的姿态。",
	["Recibir marcadores de tu grupo"] = "接收队伍的标记",
	["Recibiste %s y %s."] = "你收到了 %s 和 %s。",
