	["Rexxar, el señor de las bestias, recorre los caminos de Desolace con su osa Misha."] = "兽王雷克萨带着他的熊米莎在凄凉之地的道路上游荡。",
	["Rexxar, mitad orco y mitad ogro, es un señor de las bestias que ayudó a fundar Durotar. Siempre lo acompaña su osa Misha."] = "雷克萨是半兽人半食人魔的兽王，曾协助建立杜隆塔尔。他的熊米莎总是陪在他身边。",
	["Reír"] = "大笑",
