	["Sanador"] = "治疗",
	["Sangrado fuerte desde el nivel 13; lo necesitas para Heridas profundas."] = "13 级起就有强力流血；点重伤需要它。",
	["Sangrado fuerte; abre Heridas profundas."] = "强力流血；解锁重伤。",
	["Sangre fría: tu siguiente remate es crítico seguro."] = "冷血：你的下一个终结技必定暴击。",
	["Sapphiron, el dragón de escarcha de Naxxramas, fue un dragón azul antes de que la Plaga lo levantara."] = "纳克萨玛斯的冰霜巨龙萨菲隆，在被天灾军团复活之前是一条蓝龙。",
	["Sargeras fue el gran campeón del Panteón. De tanto pelear contra demonios concluyó que la creación no tenía remedio, y fundó la Legión Ardiente."] = "萨格拉斯曾是万神殿的伟大勇士。与恶魔战斗太久之后，他认定创造已无可救药，于是建立了燃烧军团。",
	["Sastrería"] = "裁缝",
	["Sastrería hace tu ropa con lo que cae en mazmorras, y Encantamiento deshace lo que no usas y mejora tu equipo."] = "裁缝用地下城掉落的材料做你的衣服，附魔则分解你用不上的装备，并强化你的装备。",
	["Sastrería y Encantamiento: tu equipo siempre al día."] = "裁缝和附魔：让你的装备始终跟上等级。",
	["Scholomance, en la isla de Caer Darrow, es la escuela donde la Plaga enseña nigromancia. Antes fue el hogar de la familia Barov."] = "通灵学院位于凯尔达隆岛上，是天灾军团教授死灵法术的学校。它以前是巴罗夫家族的宅邸。",
	["Se abandona con «Abandonar marcadas», que pide confirmación."] = "用“放弃已标记的”放弃，会要求确认。",
	["Se abre a nivel %d: te faltan %d niveles. Mientras, sigue tu ruta."] = "%d 级开放：还差 %d 级。在此期间，继续你的路线。",
	["Se abre al salir de combate."] = "脱离战斗后打开。",
	["Se abre al terminar %s."] = "完成%s后开放。",
	["Se abren con la B. Elige la vista (todo junto, por categorías o por bolsa), busca por nombre o nivel y arrastra tus bolsas en su barra para cambiarlas."] = "按 B 打开。选择视图（全部合并、按类别或按背包），按名称或等级搜索，并在背包栏中拖动背包来替换。",
	["Se acabaron los textos cortados con «…» en Hoy, La Jauría, Buscar cerca y la Enciclopedia."] = "“今天”、La Jauría、“搜索附近”和百科中不再有被“…”截断的文字。",
	["Se acabó el aviso «Alfa_Builds se ha bloqueado…»: la ventana de talentos, el clic para lanzar y el Legado ahora los abre el juego, y tus hechizos se lanzan sin problema desde el libro."] = "不会再出现“Alfa_Builds 已被阻止……”的警告了：天赋窗口、点击施法和传承现在都由游戏自己打开，你的法术也能从法术书正常施放。",
	["Se acabó tu XP descansada"] = "你的精力充沛经验用完了",
	["Se acelera a sí mismo y lanza rayos: interrúmpelo."] = "他会给自己加速并施放闪电：打断他。",
	["Se acelera a sí mismo: interrúmpelo si puedes."] = "他会给自己加速：能打断就打断。",
	["Se activó Claridad: tu siguiente hechizo es gratis."] = "节能施法已触发：你的下一个法术免费。",
	["Se activó Claridad: tus Misiles arcanos salen gratis."] = "节能施法已触发：你的奥术飞弹免费。",
	["Se activó Trance de las Sombras: tu Descarga de las Sombras es instantánea."] = "暗影冥思已触发：你的暗影箭变为瞬发。",
	["Se agregó el sonido %d a tu lista."] = "已将声音 %d 加入你的名单。",
	["Se aplica al salir de combate."] = "脱离战斗后套用。",
	["Se aprende con %s"] = "向%s学习",
	["Se borra el progreso de mazmorras de este personaje. No se puede deshacer."] = "将删除此角色的地下城进度。此操作无法撤销。",
	["Se borran las sesiones guardadas de este personaje. La sesión de ahora sigue contando."] = "将删除此角色已保存的游戏记录。当前这次游戏会继续统计。",
	["Se borran las sesiones, las zonas y los objetos de este personaje. No se puede deshacer."] = "将删除此角色的采集记录、区域和物品数据。此操作无法撤销。",
	["Se borran los %d marcadores de todos tus personajes. No se puede deshacer."] = "将删除你所有角色的 %d 个标记。此操作无法撤销。",
	["Se borran los jefes vencidos, las veces completada y el botín anotado de %s para este personaje."] = "将删除此角色在%s中已击败的首领、完成次数和记录的战利品。",
	["Se borran los precios guardados de la subasta de este reino y facción. Tus recetas se quedan."] = "将删除本服务器和本阵营已保存的拍卖价格。你的配方会保留。",
	["Se borran todas las peleas guardadas, también en la ventana del medidor del juego."] = "清除所有已保存的战斗，游戏的伤害统计窗口中的也会清除。",
	["Se borran tus sesiones, tu diario, tus logros y tus metas de este personaje. Tu habilidad de pesca no cambia."] = "会清除此角色的钓鱼记录、图鉴、成就和目标。你的钓鱼技能不会改变。",
	["Se carga al salir de combate"] = "脱离战斗后载入",
	["Se cerró el buzón antes de terminar."] = "完成前邮箱关闭了。",
	["Se cerró la subasta antes de recibir los precios. Vuelve a intentarlo después."] = "在收到价格之前拍卖行就关闭了。请稍后再试。",
	["Se cerró la ventana de clic para lanzar de Blizzard. Vuelve a pulsar «Abrir clic para lanzar» para abrirla."] = "暴雪的点击施法窗口已关闭。再次点击“打开点击施法”即可打开。",
	["Se cumple al llegar a ese nivel."] = "达到该等级时即达成。",
	["Se cura a sí mismo: interrumpe su curación."] = "他会治疗自己：打断他的治疗。",
	["Se cura comiendo: mátenlo rápido."] = "他会靠吃东西回血：尽快击杀。",
	["Se cura: interrúmpelo."] = "他会治疗自己：打断他。",
	["Se descubren todos los jefes de %s, como si la hubieras terminado. Si te equivocas, puedes olvidar tu progreso aquí."] = "会显示%s的所有首领，就像你已经通关一样。如果弄错了，可以在这里清除你的进度。",
	["Se detuvo al cerrar el banco: guardaste %d y faltaron %d."] = "银行已关闭，已停止：存入 %d 件，剩下 %d 件。",
	["Se detuvo al entrar en combate: guardaste %d y faltaron %d."] = "进入战斗，已停止：存入 %d 件，剩下 %d 件。",
	["Se enciende cuando el enemigo esquiva: pega fuerte y no se puede esquivar. Úsalo en cuanto brille."] = "敌人躲闪后亮起：伤害高且无法被躲闪。一亮就用。",
	["Se enciende tras bloquear, esquivar o parar. Barato y con mucha amenaza: el favorito del tanque."] = "格挡、躲闪或招架后亮起。便宜又仇恨高：坦克的最爱。",
	["Se enfurece al final: guarden su mejor daño."] = "他在最后会激怒：留好最强的输出。",
	["Se enfurece con poca vida: termínenlo rápido."] = "他血量低时会激怒：尽快解决他。",
	["Se enfurece y pega más fuerte con el tiempo: mátenlo rápido."] = "他会越来越狂暴，打得越来越痛：尽快击杀。",
	["Se entrega con %s"] = "交给%s",
	["Se entrega dentro"] = "在副本内交付",
	["Se escapó"] = "鱼跑掉了",
	["Se fabrica"] = "制造",
	["Se marcan como chatarra"] = "会被标记为垃圾",
	["Se me antoja un buen filete de jabalí. Solo digo."] = "好想吃一块野猪排。我就说说。",
	["Se pelea bajo el agua: vigila tu barra de respiración y sube a tomar aire si hace falta."] = "要在水下和他战斗：留意呼吸条，需要时上浮换气。",
	["Se pesca"] = "钓鱼获得",
	["Se protege con su escudo y aturde: ataquen a los otros dos primero."] = "他会用盾牌保护自己并击晕敌人：先打另外两个。",
	["Se puede al salir de combate."] = "脱离战斗后即可。",
	["Se puede anunciar al salir de combate."] = "脱离战斗后即可通报。",
	["Se puede enviar ahora: %s"] = "现在可以发送：%s",
	["Se pueden conseguir"] = "可获得",
	["Se pusieron %d ajustes. Algunas cosas se ven completas al recargar."] = "已套用 %d 项设置。有些内容重载后才会完整显示。",
	["Se pusieron %d ajustes. Las líneas que no eran válidas (%d) se dejaron fuera."] = "已套用 %d 项设置。无效的行（%d 行）已略过。",
	["Se pusieron %d de %d opciones"] = "已设置 %d/%d 个选项",
	["Se queda en el modo limpio."] = "保持简洁模式。",
	["Se quita %s de tu lista de compras."] = "已从你的购物清单中移除 %s。",
	["Se quita de tu lista. Si lo necesitas otra vez, vuelve a importar su cadena."] = "它将从你的列表中移除。如果以后还需要，请重新导入它的字符串。",
	["Se quitan los nodos que anotaste al recolectar y cuántas veces los recolectaste. La base incluida se queda. No se puede deshacer."] = "将移除你采集时记录的采集点及采集次数。内置数据库会保留。此操作无法撤销。",
	["Se quitan todas las metas. Tus objetos no se tocan."] = "所有目标都会被移除。不会动你的物品。",
	["Se quitó el sonido %d de tu lista."] = "已将声音 %d 移出你的名单。",
	["Se saltan (no están en tu árbol): %s."] = "已跳过（不在你的天赋树中）：%s。",
	["Se teletransporta a las orillas de la sala: si peleas cuerpo a cuerpo, síguelo."] = "他会传送到房间边缘：近战玩家请跟上他。",
	["Se toma dentro de la mazmorra: ahí la verás."] = "在地下城内接取：你会在那里看到它。",
	["Se ve completo al recargar."] = "重载后才会完全显示。",
	["Se ve después de reiniciar los gráficos."] = "重启图形后才会显示。",
	["Se vende ahora"] = "现在就卖",
	["Se vende en"] = "出售处",
	["Se vende en %s cada uno."] = "每个售价 %s。",
	["Seccionar puede inmovilizar al rival: no se te escapa."] = "断筋有几率定住对手：他跑不掉。",
	["Seccionar puede inmovilizar: nadie se te escapa para traer amigos."] = "断筋有几率定身：谁也别想跑去叫帮手。",
	["Secundaria"] = "副",
	["Secundaria [mano]"] = "副手",
	["Secundario: no cuenta en tus dos"] = "副专业：不计入你的两个专业",
	["Sed de sangre: tu golpe más fuerte, cada vez que esté listo."] = "嗜血：你最强的攻击，冷却好就用。",
	["Seguimiento"] = "跟随",
	["Seguir"] = "跟随",
	["Seguir (flecha y ruta)"] = "跟随（箭头和路线）",
	["Seguir a %s"] = "跟随%s",
	["Seguir con %s"] = "继续%s",
	["Seguir el terreno"] = "随地形调整",
	["Seguir esta guía"] = "跟随此指南",
	["Seguir esta ruta"] = "跟随此路线",
	["Seguir este build"] = "跟随这个方案",
	["Seguir este plan"] = "跟随此计划",
	["Seguir jugando"] = "继续游戏",
	["Seguir muestra tu guía y la flecha, y cierra esta ventana para que las veas."] = "“继续”会显示你的指南和箭头，并关闭此窗口让你看到它们。",
	["Seguir por aquí"] = "走这条路",
	["Seguir ruta"] = "跟随路线",
	["Seguir sola con la siguiente guía"] = "自动继续下一份指南",
	["Seguir su ruta"] = "跟随其路线",
	["Seguir un build de %s"] = "跟随一个%s方案",
	["Segundos junto a la barra"] = "在进度条旁显示秒数",
	["Según su leyenda, los jabaespines nacieron de la sangre de Agamaggan, el gran jabalí semidiós. Por eso viven entre espinas gigantes."] = "根据他们的传说，野猪人诞生于野猪半神阿迦玛甘的鲜血。所以他们住在巨大的荆棘之间。",
	["Seleccionar objetivo"] = "选中目标",
	["Seleccionar para copiar"] = "选中以复制",
	["Seleccionar todo"] = "全选",
	["Seleccionarlo"] = "选中它",
	["Sello"] = "圣印",
	["Semilla de Tuercespina"] = "荆棘谷种子",
	["Semilla de arce"] = "枫树种子",
	["Semilla de carpe"] = "角树种子",
	["Semilla de fresno"] = "灰木种子",
	["Semilla de palo de hierro"] = "铁木种子",
	["Sencillo"] = "简洁",
	["Sencillo: solo Hoy, Ruta, Mapa, Bolsas, Talentos y Lya a la vista, y menos avisos. Completo: todo Alfa. Lo demás sigue funcionando."] = "简洁：只显示今天、路线、地图、背包、天赋和莉娅，提醒也更少。完整：Alfa 的全部。其他功能照常运作。",
	["Sepia"] = "怀旧棕",
	["Servicio"] = "服务",
	["Servicios"] = "服务",
	["Servicios en el minimapa"] = "小地图上的服务",
	["Será una mejora más adelante"] = "以后会是提升",
	["Sesiones anteriores"] = "以前的记录",
	["Sesiones que guarda el diario"] = "日志保存的游戏次数",
	["Sesiones, diario, logros y metas de este personaje. No se puede deshacer."] = "此角色的钓鱼记录、图鉴、成就和目标。无法撤销。",
	["Sesión de pesca nueva."] = "新的钓鱼记录。",
	["Señalar"] = "指向",
	["Señor de las aguas"] = "水域之主",
	["Si Toxic, el fundador de La Jauría, anda cerca, Alfa te avisa para que lo saludes."] = "如果La Jauría的创始人Toxic在附近，Alfa会提醒你去打个招呼。",
	["Si aguantas bien, usa Golpe heroico con la ira sobrante para más amenaza."] = "如果扛得住，就用多余的怒气打英勇打击，制造更多威胁。",
	["Si algo sale mal, tu habilidad para desaparecer te saca de la pelea. Úsala antes de que sea tarde."] = "情况不妙时，你的消失技能能让你脱离战斗。要趁还来得及时用。",
	["Si alguien de la manada te pasa uno, impórtalo y Alfa te guía con él punto por punto."] = "如果狼群里有人给你一个方案，导入后 Alfa 会一点一点地带你点。",
	["Si alguien de tu grupo también trae Alfa, nuestras Lyas se saludan al juntarse y a veces platican. Es poquito y nunca en combate. Se apaga en mi página: «Lya y su manada»."] = "如果队伍里也有人用 Alfa，组队时我们的莉娅会互相打招呼，有时还会聊几句。只聊一点点，战斗中从不聊。可以在我的页面关闭：“莉娅和她的狼群”。",
	["Si alguien de tu grupo también trae Alfa, sus Lyas se saludan y a veces platican. Poquito y nunca en combate."] = "如果队伍里也有人用 Alfa，你们的莉娅会互相打招呼，有时还会聊几句。只聊一点点，战斗中从不聊。",
	["Si alguien huye, puede traer a más presos: deténganlo con un ataque que lo frene."] = "逃跑的敌人可能会叫来更多囚犯：用减速技能拦住它。",
	["Si alguna vez ves salchichas en una posada, guárdame una… o dos."] = "要是在旅店看到香肠，给我留一根……或者两根。",
	["Si bajas por el Gran Elevador, verás por qué se llama así: cientos de agujas de roca."] = "搭大升降梯下去，你就会明白为什么叫这个名字：数百根石针。",
	["Si casi todo lo que vas a entregar está en el pueblo de tu piedra y estás lejos, Lya te lo dice."] = "如果你要交的几乎都在炉石所在的城镇，而你离得很远，莉娅会告诉你。",
	["Si cierras tres veces el mismo tipo de consejo, Lya te pregunta si ya no quieres que te lo diga."] = "如果你关掉同一类建议三次，莉娅会问你是否不想再听了。",
	["Si en estas fechas ves calabazas en las posadas, es Halloween: los posaderos te dan dulces con truco o trato, y a veces un disfraz."] = "如果这个时候你在旅店看到南瓜，那就是万圣节：旅店老板会在不给糖就捣蛋时给你糖果，有时还有服装。",
	["Si en estas fechas ves faroles y fuegos artificiales, es el Festival Lunar: visita a los Ancestros por el mundo, que cada uno te da una moneda."] = "如果这个时候你看到灯笼和烟花，那就是春节：去拜访世界各地的长者，每位都会给你一枚硬币。",
	["Si en febrero las ciudades huelen a perfume, es «Amor en el aire»: la gente reparte regalos y hasta los guardias reciben detalles."] = "如果二月的城市里飘着香水味，那就是“情人节”：人们互赠礼物，连卫兵都会收到小礼物。",
	["Si encuentras un hueso, es mío. ¿Trato hecho?"] = "要是找到骨头，就归我了。说定了？",
	["Si eres desollador, las zonas llenas de bestias, como raptores, kodos o felinos, te dan cuero sin parar."] = "如果你是剥皮者，到处是野兽的区域，比如迅猛龙、科多兽或豹子，能源源不断地给你皮革。",
	["Si está fuera de tu alcance, su marco se ve más tenue."] = "超出你的距离时，其框体会变淡。",
	["Si estás en combate, espera a que termine."] = "如果在战斗中，会等战斗结束。",
	["Si fabricas para otros, cobra justo: la gente vuelve y te recomienda."] = "如果你为别人制作物品，收费要公道：人家会回头并推荐你。",
	["Si hay fiesta te lo digo al entrar. Y según la hora y la zona te cuento lo que pasa por ahí."] = "如果有节日，你登录时我会告诉你。我还会根据时间和区域，告诉你附近在发生什么。",
	["Si hoy cuesta, mañana sale. Aquí sigo contigo."] = "今天不顺，明天就会好。我还在这里陪着你。",
	["Si juegas sin grupo, la ventana se esconde."] = "不在队伍中时，窗口会隐藏。",
	["Si la abandonas, pierdes la cadena: después sigue “%s”."] = "放弃的话，你会失去这条任务线：接下来是“%s”。",
	["Si la pelea va mal, desvanécete y vuelve a empezar."] = "如果战斗不利，就使用消失，重新再来。",
	["Si la recompensa tiene varias opciones, eliges tú."] = "如果奖励有多个选项，由你选择。",
	["Si la terminas"] = "如果完成它",
	["Si la vida baja de la mitad y el sanador no llega, usa Último recurso."] = "如果血量低于一半而治疗跟不上，就使用破釜沉舟。",
	["Si le dices «Ya no» a un consejo, sale aquí para que puedas devolverlo cuando quieras."] = "如果你对某条建议说“不用了”，它会出现在这里，随时可以恢复。",
	["Si le haces el gesto de gallina a una gallina de granja muchas veces, a veces te pide ayuda... y la historia termina en mascota."] = "如果你对农场的小鸡做很多次小鸡表情，有时它会向你求助……故事的结局是一只宠物。",
	["Si levantas algo que se puede regalar y le sirve a un lobo conectado, Alfa te lo dice con «Regalárselo»."] = "如果你拾取到可以赠送、而在线的狼用得上的东西，Alfa 会用“送给他”告诉你。",
	["Si llega a 0 % se rompe y deja de darte sus estadísticas. Repara cuanto antes con un herrero o un vendedor que repare."] = "耐久度降到 0% 时装备会损坏，不再提供属性。请尽快找铁匠或能修理的商人修理。",
	["Si llegas a exaltado con otra raza de tu bando, te venden sus monturas. ¡Un kodo para un orco o un sable de la noche para un humano!"] = "如果你和本阵营另一个种族达到崇拜，他们就会卖坐骑给你。兽人骑科多兽，人类骑夜刃豹！",
	["Si llevas puesto el abalorio del Alba Argenta, los no-muertos de las Tierras de la Peste sueltan piedras que cambias por reputación y fichas."] = "如果你戴着银色黎明的饰品，瘟疫之地的亡灵会掉落石头，可以换取声望和徽记。",
	["Si lo que te dan mejora tu equipo, te lo pones al salir de combate."] = "如果得到的东西能提升你的装备，脱离战斗后就会自动装备。",
	["Si moviste los avisos y ya no los encuentras."] = "如果你移动过提醒，现在找不到了。",
	["Si mueres seguido, cambia al estilo Tranquilo."] = "如果经常死，就改用“稳健”风格。",
	["Si necesitas silencio, con clic derecho me callas un rato."] = "如果你需要安静，右键点我，我就安静一会儿。",
	["Si no eres druida, al Claro de la Luna se llega por los túneles de los Fauces de Madera, desde Frondavil."] = "如果你不是德鲁伊，就要从费伍德森林穿过木喉隧道才能到月光林地。",
	["Si no eres tanque: con cuánta amenaza se pone amarilla."] = "如果你不是坦克：仇恨到多少时变黄。",
	["Si no tienes ninguna abierta, abre la recomendada para tu nivel."] = "如果你没有打开任何指南，就打开适合你等级的推荐指南。",
	["Si nos perdemos en %s, tú lees el mapa y yo sigo el rastro."] = "如果我们在%s迷路了，你看地图，我来追踪气味。",
	["Si peleas de lejos, quédate lejos de ella."] = "远程玩家请远离她。",
	["Si quieres matar más rápido en solitario, cambia a Armas cuando tengas oro para reiniciar."] = "如果想单人杀怪更快，等攒够重置天赋的金币后改成武器天赋。",
	["Si quieres, tu personaje aparece en el mapa del juego de los lobos que usan Alfa, y ellos en el tuyo: quién anda cerca, dónde y, con un clic, la flecha te lleva. Solo es el lugar de tu personaje dentro de WoW, nunca tu ubicación real. Tu grupo se ve siempre."] = "如果你愿意，你的角色会出现在使用 Alfa 的狼的游戏地图上，他们也会出现在你的地图上：谁在附近、在哪里，点一下箭头就会带你过去。这只是你的角色在 WoW 中的位置，绝不是你的真实位置。你的队伍总是可见。",
	["Si sigues el consejo"] = "按建议处理",
	["Si sigues la cadena del mariscal Windsor, en Ventormenta destaparás quién es en realidad Lady Prestor."] = "跟着温德索尔元帅的任务链走，你会在暴风城揭穿普瑞斯托女士的真面目。",
	["Si sigues la historia del Templo Sumergido, en el pantano te espera Itharius, un dragón verde."] = "如果你继续追查沉没的神庙的故事，绿龙伊萨里奥斯会在沼泽里等你。",
	["Si sigues los consejos"] = "按建议处理",
	["Si sigues los consejos ganas %s"] = "按建议操作可赚 %s",
	["Si sueltan poco, no te desesperes. Pasa en toda buena caza."] = "掉得少也别灰心。好的狩猎都会这样。",
	["Si te alcanzan, usa tus golpes cuerpo a cuerpo y aléjate otra vez."] = "如果被追上，就用近战技能，然后再拉开距离。",
	["Si te baja mucho la vida, cambia a actitud defensiva: tu ira no se pierde."] = "如果血量掉得很多，就切换到防御姿态：怒气不会损失。",
	["Si te invitan a su grupo, acepta con el botón del juego: el juego te pasa a su guarida al rato."] = "如果他们邀请你入队，用游戏按钮接受：不久后游戏会带你去他们的巢穴。",
	["Si te invitan a su grupo, acepta con el botón del juego: el juego te pasa a su plano al rato."] = "如果他们邀请你入队，用游戏的按钮接受：游戏很快就会把你转到他们的位面。",
	["Si te llega equipo mejor que lo que llevas, te aviso con «Ponte esto» y un botón para ponértelo. Solo con tu clic, y nunca en combate."] = "如果你拿到比身上更好的装备，我会用“穿上这个”告诉你，并附上装备按钮。只在你点击时，战斗中绝不会。",
	["Si te pegan mientras te vendas, se corta: aléjate un poco antes de usarla."] = "包扎时被打就会中断：使用前先稍微走远一点。",
	["Si te quedas sin lanzar"] = "如果你停止抛竿",
	["Si te sobra un pedacito de carne, aquí hay una panza que lo recibe con gusto."] = "如果你还剩一小块肉，这里有个肚子很乐意收下。",
	["Si tienes poco tiempo, si no tienes con quién jugar o quién te ayude, puedes apoyarte en Alfa y en Lya en tu travesía."] = "如果你时间不多，或者没人一起玩、没人帮你，可以在旅途中依靠 Alfa 和 Lya。",
	["Si tu caña no tiene cebo, tu tecla pone el mejor que tengas (o el que prefieras) antes de lanzar."] = "如果鱼竿上没有鱼饵，你的按键会在抛竿前装上你最好的鱼饵（或你偏好的那种）。",
	["Si tu clase lo puede quitar, su marco se pinta del color del perjuicio y sale su ícono arriba a la derecha. Pasa el ratón y te digo con qué clic se quita; si ningún clic lo hace, elígelo en «Tus clics»."] = "如果你的职业能驱散，他的框体会染成该减益效果的颜色，右上角显示它的图标。鼠标移上去我会告诉你用哪个点击驱散；如果没有，请在“你的点击”中选择。",
	["Si tu objetivo es un jugador, su fondo toma el color de su clase en lugar del de su reacción."] = "如果你的目标是玩家，其背景会使用职业颜色，而不是敌友关系的颜色。",
	["Si tu plano se llena de cazadores, Lya te propone pasarte al de un lobo de la manada con su guarida abierta. Una vez cada 15 minutos."] = "如果你的位面挤满了猎人，莉娅会建议你转到一只开着巢穴的狼群伙伴的位面。每 15 分钟一次。",
	["Si tu rango lo permite, la hermandad paga y tu dinero pone el resto."] = "如果你的公会级别允许，就由公会支付，不足部分用你自己的钱。",
	["Si tú o tus personajes pueden"] = "你或你的角色会时",
	["Si un día ganamos mucho oro, yo ya sé en qué gastarlo: salchichas."] = "要是哪天我们赚了好多金币，我早就想好怎么花了：香肠。",
	["Si un enemigo te persigue, no corras: acércate al tanque."] = "如果有敌人追你，别乱跑：靠近坦克。",
	["Si un enemigo viene hacia ti, llévalo hacia el tanque: no corras lejos."] = "如果有敌人冲向你，把它带到坦克身边：别跑远。",
	["Si un lobo de tu hermandad busca un objeto que llevas, Alfa le dice cuántos tienes. Solo eso y solo cuando pregunta."] = "如果公会里的狼在找你身上带的物品，Alfa 会告诉他你有几个。只有这个，而且只在他问的时候。",
	["Si un lugar está lleno de jugadores farmeando lo mismo, cámbiate de zona: te rinde más."] = "如果某个地方挤满了刷同样东西的玩家，就换个区域：收获会更多。",
	["Si un monstruo esquiva, usa Abrumar enseguida (Alfa te avisa)."] = "怪物躲闪时，立刻使用压制（Alfa 会提醒你）。",
	["Si una misión se pone difícil, pide ayuda en el chat. En manada todo pesa menos."] = "任务变难时，就在聊天里求助。在狼群中，一切都会轻松些。",
	["Si una subasta no se vende, pierdes el depósito: no pongas precios fuera de la realidad."] = "拍卖没卖出去的话，你会损失保证金：别定离谱的价格。",
	["Si vendes todo al comerciante"] = "全部卖给商人",
	["Si ves a otro lobo por ahí, salúdalo de mi parte."] = "如果你在附近看到别的狼，替我打个招呼。",
	["Si ves carpas de colores en Villadorada o en Mulgore, llegó la Feria de la Luna Negra: hay juegos, premios y cartas que se juntan en mazos."] = "如果你在闪金镇或莫高雷看到彩色帐篷，就是暗月马戏团来了：有游戏、奖品，还有能凑成整套的卡片。",
	["Si viajas con un mago, pídele un portal a la capital: te ahorra mucho camino."] = "如果和法师同行，请他开一个去主城的传送门：能省下很多路。",
	["Siempre"] = "总是",
	["Siempre con cebo"] = "始终带饵",
	["Siempre: te ofrece la historia de cada misión y un dato de cada zona nueva. A veces: de las misiones que tomas sin leer, y no siempre. Solo si le pido: con clic derecho, «Cuéntame algo de aquí». Las historias se guardan igual."] = "总是：她会提出讲每个任务的故事，以及每个新区域的一则趣闻。有时：针对你没读就接下的任务，而且不是每次都讲。只在我要求时：右键点击“跟我讲讲这里”。无论如何故事都会被保存。",
	["Siete días de caza contigo. Esto ya es costumbre, y me encanta."] = "和你一起狩猎七天了。这已经成了习惯，我好喜欢。",
	["Sigilo"] = "潜行",
	["Sigilo y emboscadas: tú eliges cuándo pelear y desapareces cuando quieres."] = "潜行和伏击：由你决定何时开战，想走就走。",
	["Siglos después de la División, los Altonato que no soltaban la magia arcana fueron desterrados. Cruzaron el mar y fundaron Quel'Thalas: son los altos elfos."] = "大分裂之后数百年，不肯放弃奥术魔法的上层精灵被流放。他们渡海建立了奎尔萨拉斯：他们就是高等精灵。",
	["Siglos después, los orcos Faucedraco usaron el Alma de Demonio para tener presa a Alexstrasza y criar dragones de guerra para la Horda."] = "数百年后，龙喉兽人利用恶魔之魂囚禁了阿莱克丝塔萨，为部落繁育战龙。",
	["Sigue a tu lado, pero no habla hasta las %s."] = "她还在你身边，但要到 %s 才会说话。",
	["Sigue a tu lado, pero no habla por un rato."] = "她还在你身边，只是暂时不说话。",
	["Sigue con los pasos de la guía"] = "继续按照指南的步骤来",
	["Sigue donde ibas"] = "继续上次进度",
	["Sigue la flecha."] = "跟着箭头走。",
	["Sigue la flecha: las paradas van en el orden más corto, juntas por PNJ."] = "跟着箭头走：站点按最短顺序排列，按 NPC 分组。",
	["Sigue la ruta de tu grupo y pide las misiones que lleva tu compañero."] = "跟随队伍的路线，向同伴请求他身上的任务。",
	["Sigue subiendo: %d de %d"] = "继续提升：%d / %d",
	["Sigue tu guía"] = "跟着你的指南",
	["Sigue: %s"] = "下一步：%s",
	["Sigue: %s. Lee sus consejos antes de la pelea."] = "下一个：%s。战斗前先看它的提示。",
	["Sigues a %s"] = "正在跟随%s",
	["Sigues con tu equipo de pesca."] = "你还穿着钓鱼装备。",
	["Sigues la ruta de %s"] = "你正在跟随%s的路线",
	["Siguiendo"] = "跟随中",
	["Siguiendo a %s."] = "正在跟随%s。",
	["Siguiendo el rastro"] = "正在追踪",
	["Siguiendo el rastro de %s. La flecha te lleva hasta su posición."] = "正在追踪%s。箭头会带你到其位置。",
	["Siguiendo tu ruta de %s"] = "正在跟随你的%s路线",
	["Siguiente"] = "下一步",
	["Siguiente lugar"] = "下一个地点",
	["Siguiente parada:"] = "下一站：",
	["Siguiente paso de la guía"] = "指南的下一步",
	["Siguiente rango: %s"] = "下一个等级：%s",
	["Siguiente: %s (%d de %d)"] = "下一个：%s（%d / %d）",
	["Silencia los sonidos que agregues por su número de archivo (FileDataID): /alfa silenciar <número>; /alfa silenciar quitar <número> lo quita."] = "按文件编号（FileDataID）静音你添加的声音：/alfa silenciar <编号>；/alfa silenciar quitar <编号> 将其移除。",
	["Silenciar 1 hora"] = "静音 1 小时",
	["Silenciar sonidos"] = "静音声音",
	["Silenciar un sonido por su número (FileDataID)"] = "按编号（FileDataID）静音声音",
	["Silithus es la puerta de Ahn'Qiraj, donde los silítidos y los qiraji sirven al dios antiguo C'Thun."] = "希利苏斯是安其拉的门户，异种虫和其拉虫人在那里侍奉上古之神克苏恩。",
	["Sin Minería no ves filones; sin Herboristería, hierbas; sin Pesca, bancos. Los tesoros siempre se ven."] = "没有采矿就看不到矿脉，没有草药学就看不到草药，没有钓鱼就看不到鱼群。宝藏始终显示。",
	["Sin Pesca"] = "未学钓鱼",
	["Sin XP descansada"] = "没有精力充沛经验",
	["Sin acción"] = "无动作",
	["Sin activar"] = "未启用",
	["Sin aprender"] = "未学会",
	["Sin aullido"] = "不要狼嚎",
	["Sin bloqueos y más claro"] = "不再被阻止，也更清楚",
	["Sin cadena"] = "无任务链",
	["Sin cambiar de forma."] = "未变形。",
	["Sin cambios"] = "没有变化",
	["Sin consejos para este jefe: vayan con calma y escuchen al tanque."] = "这个首领没有提示：慢慢来，听坦克的。",
	["Sin datos"] = "没有数据",
	["Sin demonio"] = "没有恶魔",
	["Sin el ratón encima, la barra guarda sus botones y deja solo lo que pasa."] = "鼠标不在上面时，钓鱼条会收起按钮，只显示正在发生的事。",
	["Sin encantar"] = "未附魔",
	["Sin fuente conocida"] = "无已知来源",
	["Sin grupo"] = "未组队",
	["Sin historial todavía."] = "还没有价格记录。",
	["Sin límite de tiempo"] = "无时间限制",
	["Sin mascota"] = "没有宠物",
	["Sin metas todavía"] = "还没有目标",
	["Sin metas todavía. Pulsa + para ponerte una: un pez, capturas, tiempo o valor."] = "还没有目标。按 + 设定一个：一种鱼、渔获数、时间或价值。",
	["Sin metas todavía: ábrelo y agrégale una."] = "还没有目标：打开它并添加一个。",
	["Sin munición"] = "没有弹药",
	["Sin objeto"] = "没有物品",
	["Sin otros personajes, uno solo puede ganar 29: 3 por subir de nivel, 6 de profesiones, 12 de JcJ, 2 de aventura y 6 de mazmorras y bandas. El resto sale de subir otras clases."] = "没有小号的话，一个角色最多能获得 29 点：升级 3 点、专业 6 点、PvP 12 点、冒险 2 点、地下城和团队副本 6 点。其余的来自练其他职业。",
	["Sin precio todavía: escanea la subasta."] = "还没有价格：请扫描拍卖行。",
	["Sin precios"] = "没有价格",
	["Sin precios todavía"] = "还没有价格",
	["Sin profesión"] = "没有专业",
	["Sin sello"] = "没有圣印",
	["Sin tecla"] = "无按键",
	["Sin tener una tecla abajo: lo prendes o lo apagas con su atajo, o aquí."] = "不用一直按住按键：用它的快捷键开启或关闭，或者在这里。",
	["Sin tinte"] = "无色调",
	["Sin ubicación"] = "无位置",
	["Sin ubicación ahora: en una instancia o fuera del mapa"] = "目前无位置：在副本中或不在地图上",
	["Sin veneno"] = "没有毒药",
	["Sin zona"] = "无区域",
	["Sobre Lya"] = "关于 Lya",
	["Sobre tu compañero, este clic %s."] = "对队友，这个点击会%s。",
	["Solo %s"] = "仅限%s",
	["Solo al acabarse"] = "仅在用完时",
	["Solo al moverte"] = "仅在移动时",
	["Solo buffs"] = "仅增益效果",
	["Solo con quienes usan Alfa y aceptaron compartir. Tú decides."] = "只与使用 Alfa 并同意共享的人共享。由你决定。",
	["Solo cuando estás en grupo"] = "仅在队伍中时",
	["Solo cuando te llame"] = "叫你时再来",
	["Solo el botín que me sirve"] = "只显示我能用的战利品",
	["Solo ellos: tú no la tienes."] = "只有他们有：你没有这个任务。",
	["Solo en una fiesta del año"] = "仅限年度节日期间",
	["Solo en warcraft.wiki.gg e Icy Veins: cuántos puntos pide cada premio (15, 25, 40 y 55). Ninguna fuente publica cuánto cuesta cada rango de los árboles: míralo en la ventana del Legado."] = "只有 warcraft.wiki.gg 和 Icy Veins 列出了每个奖励需要多少点（15、25、40 和 55）。没有任何来源公布天赋树每一级的花费：请在传承窗口中查看。",
	["Solo encontré %d misiones que te sirvan ahora."] = "现在只找到 %d 个适合你的任务。",
	["Solo hay que llevar el recado. ¡Fácil, como pedirme una salchicha!"] = "只要把口信送到就行。很简单，就像跟我要一根香肠一样！",
	["Solo importantes"] = "只看重要的",
	["Solo la animación"] = "只播放动画",
	["Solo la animación: lo demás (tu sesión anterior, avisos, lo nuevo) te espera en Hoy y con Lya. Animación y avisos: como antes."] = "只播放动画：其他内容（你的上次会话、提醒、新内容）都在“今天”和莉娅那里等你。动画和提醒：和以前一样。",
	["Solo la entrada"] = "只去入口",
	["Solo las misiones de tu ruta"] = "只接你路线上的任务",
	["Solo las que puedes tomar: tu bando, raza, clase y nivel, y que no hayas hecho."] = "只显示你能接的：你的阵营、种族、职业和等级，且尚未完成。",
	["Solo lo de mi papel"] = "只显示我的职责",
	["Solo lo esencial a la vista. Las barras y retratos se esconden al terminar el combate."] = "只显示必要的东西。动作条和头像会在战斗结束后隐藏。",
	["Solo lo esencial a la vista. Pulsa tu tecla otra vez para ver todo."] = "只显示必要的东西。再按一次你的按键就能看到全部。",
	["Solo lo esencial a la vista: Hoy, Ruta, Mapa, Bolsas, Talentos y Lya, y menos avisos. Lo demás sigue ahí cuando lo busques."] = "只显示最重要的：今天、路线、地图、背包、天赋和莉娅，提醒也更少。其他的需要时随时都在。",
	["Solo lo que tu clase puede usar y le conviene a tu especialización."] = "只显示你的职业能用且适合你专精的。",
	["Solo lo que tu personaje puede usar hoy: clase, armadura, armas, nivel y profesión."] = "只显示你的角色现在能用的：职业、护甲、武器、等级和专业。",
	["Solo lo que ya puedes recolectar"] = "只显示你现在能采集的",
	["Solo los consejos importantes"] = "只要重要的建议",
	["Solo los de la zona donde estás."] = "只显示你所在区域的。",
	["Solo los de tus profesiones, en el mapa del mundo y en el minimapa."] = "只显示你的专业相关的，在世界地图和小地图上。",
	["Solo los graves"] = "仅严重",
	["Solo los que me apuntan a mí"] = "只显示针对我的",
	["Solo misiones de XP, las mejores cerca de ti, en tres tandas."] = "只做经验任务，挑你附近最好的，分三批进行。",
	["Solo para %s."] = "仅限%s。",
	["Solo para mirar: tu paso de ahora no cambia. Alfa avanza sola cuando lo cumples."] = "仅供查看：你的当前步骤不会改变。完成当前步骤后，Alfa 会自动前进。",
	["Solo peleas de al menos"] = "只统计至少持续",
	["Solo pide tela: guarda la que te sale de los enemigos y sube mientras viajas."] = "它只需要布料：留着敌人掉的布，在旅途中顺便练。",
	["Solo puedes tener dos principales a la vez; las secundarias son libres. Se aprenden con su entrenador en las ciudades."] = "同一时间只能有两个主要专业；次要专业不受限制。在城市中向对应的训练师学习。",
	["Solo salen los clanes donde puedes invitar, y Alfa te confirma en el chat a quién invitaste. Lo apagas en La Jauría > Invitar."] = "只会显示你有权限邀请的地方，Alfa 会在聊天中确认你邀请了谁。可在 La Jauría > 邀请 中关闭。",
	["Solo se admite la versión 1 de la cadena de escala."] = "仅支持第 1 版权重字符串。",
	["Solo si falta"] = "仅在缺少时",
	["Solo si le pido"] = "只在我要求时",
	["Solo sirve con un monitor HDR y el HDR de Windows encendido (Configuración > Pantalla). Sin eso, déjalo apagado: los colores se ven lavados."] = "只在使用 HDR 显示器并开启 Windows HDR（设置 > 显示）时有效。否则请保持关闭：颜色会显得发白。",
	["Solo su atajo"] = "只用它的快捷键",
	["Solo tocan gráficos: nunca la cámara, el ratón ni la interfaz. «Deshacer» devuelve lo que tenías antes del último que aplicaste."] = "它们只改动图形：绝不改动镜头、鼠标或界面。“撤销”会恢复你套用上一个预设之前的设置。",
	["Solo tu grupo y quienes usan Alfa y aceptaron compartir."] = "仅限你的队伍以及使用 Alfa 并同意共享的人。",
	["Solo tú"] = "只有你",
	["Solo tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "只显示你、你的队伍、你的标记和指南的下一步。",
	["Solo él ve tu nivel, tu zona y tu misión de ahora."] = "只有他能看到你的等级、区域和当前任务。",
	["Soltar las %d"] = "全部放弃 %d 个",
	["Soltaste %d misiones grises."] = "你放弃了 %d 个灰色任务。",
	["Soltaste 1 misión gris."] = "你放弃了 1 个灰色任务。",
	["Sombra"] = "暗影",
	["Sombra para subir"] = "暗影（升级）",
	["Sombra suave en rincones, pliegues y bajo los objetos: da volumen a todo."] = "角落、褶皱和物体下方的柔和阴影：让一切更有立体感。",
	["Sombras"] = "阴影",
	["Sombras con bordes más finos. Usa más memoria de video."] = "阴影边缘更精细。会占用更多显存。",
	["Sombras suaves"] = "柔和阴影",
	["Son %s más que venderlo todo al comerciante."] = "比全部卖给商人多 %s。",
	["Son puntos de tu cuenta: los ganas con los retos del Legado (logros de Forever) en cualquier personaje, y cada personaje los gasta por su cuenta en sus árboles."] = "这是账号点数：在任何角色上完成传承挑战（Forever 的成就）即可获得，每个角色各自将其花在自己的天赋树上。",
	["Son tres enanos que pelean juntos: uno dispara de lejos, otro es muy veloz y otro se protege con escudo. Mátenlos uno por uno."] = "三个矮人一起作战：一个在远处射击，一个速度很快，一个会用盾牌保护自己。逐个击杀。",
	["Sonido"] = "声音",
	["Sonido con el juego en segundo plano"] = "游戏在后台时的声音",
	["Sonido de los avisos"] = "提醒音效",
	["Sonido en los avisos urgentes"] = "紧急提醒播放声音",
	["Sonido suave"] = "柔和的声音",
	["Sonido y avisos"] = "声音与提醒",
	["Sonidos de gestos"] = "表情声音",
	["Sonidos de mascotas"] = "宠物声音",
	["Sonidos en tu lista (%d): %s"] = "你名单中的声音（%d）：%s",
	["Sonidos suaves del juego: nada de voces ni sonidos repetidos."] = "游戏中的柔和音效：没有语音，也没有重复的声音。",
	["Sorpresa"] = "惊喜",
	["Sorpresas y cofres"] = "惊喜与宝箱",
	["Soy Lya, la loba de confianza del Alfa. Te acompaño, te cuento el lore de cada lugar y te ayudo con todo lo de Alfa. Y me encantan las salchichas."] = "我是莉娅，头狼信赖的狼。我陪着你，讲每个地方的传说，帮你搞定 Alfa 的一切。我超爱香肠。",
	["Spot aquí"] = "此处刷点",
	["Spot de farmeo"] = "刷点",
	["Spot de farmeo de %s"] = "%s 的刷点",
	["Spots de farmeo"] = "刷点",
	["Stromgarde, la heredera de Strom, resiste a medias: trols, ogros y el Sindicato se pelean por sus ruinas."] = "斯托姆的继承者激流堡勉强支撑着：巨魔、食人魔和辛迪加在它的废墟上争斗。",
	["Su arpón envenena: quita el veneno si puedes."] = "他的鱼叉带毒：能驱毒就驱掉。",
	["Su botín está por descubrir"] = "战利品待发现",
	["Su electricidad salta de un jugador a otro: sepárense."] = "他的闪电会在玩家之间跳跃：分散站位。",
	["Su ficha"] = "它的资料",
	["Su final no alcanzó a guardarse."] = "它的结局没来得及保存。",
	["Su grupo está lleno o no puede invitar."] = "他的队伍已满或无法邀请。",
	["Su guarida ya no está abierta."] = "他的巢穴已不再开放。",
	["Su mordida envenena: quita el veneno si puedes."] = "他的撕咬带毒：能驱毒就驱掉。",
	["Su nombre ya está en el correo: pon %s y envíalo."] = "他的名字已经填在邮件里了：放入 %s 并发送。",
	["Su oro y sus recompensas ya son tuyos: solo falta entregarlas."] = "它们的金币和奖励已经是你的了：只差交付。",
	["Su plano está lleno de gente. Si le abres tu guarida, Alfa lo invita a tu grupo y sale solo al llegar."] = "他们的位面很拥挤。如果你打开巢穴，Alfa 会邀请他们入队，到了之后他们就会离开。",
	["Su rayo salta de un jugador a otro: no se queden todos juntos."] = "他的闪电会在玩家之间跳跃：别全挤在一起。",
	["Su rayo salta de un jugador a otro: sepárense un poco."] = "他的闪电会在玩家之间跳跃：稍微分散一点。",
	["Suave"] = "柔和",
	["Subasta"] = "拍卖行",
	["Subasta:"] = "拍卖行：",
	["Subastador"] = "拍卖师",
	["Subastadores"] = "拍卖师",
	["Subastar"] = "拍卖",
	["Subastar %d"] = "拍卖 %d",
	["Sube %d nivel"] = "升 %d 级",
	["Sube %d niveles"] = "升 %d 级",
	["Sube al nivel"] = "升到等级",
	["Sube al nivel %d"] = "升到 %d 级",
	["Sube al nivel %d: te falta %d%%"] = "升到 %d 级：还差 %d%%",
	["Sube al nivel %d: te faltan %s de experiencia"] = "升到 %d 级：还差 %s 经验",
	["Sube hasta %d con los pasos de abajo."] = "按下面的步骤把它提升到 %d。",
	["Sube los efectos y baja la música y el ambiente para que oigas el chapoteo. Al terminar, todo vuelve a como estaba."] = "调高音效、调低音乐和环境音，让你听得到水花声。钓完后一切都会恢复原样。",
	["Sube tu profesión o junta sus materiales donde más hay."] = "提升你的专业，或在材料最多的地方收集。",
	["Sube tus oficios con lo que tienes cerca."] = "用附近的资源提升你的专业。",
	["Subidón de adrenalina: recuperas energía mucho más rápido."] = "冲动：能量恢复速度大幅提高。",
	["Subir"] = "上移",
	["Subir %s"] = "提升 %s",
	["Subir %s a %d"] = "将%s提升到 %d",
	["Subir cocina y pesca juntas"] = "同时提升烹饪和钓鱼",
	["Subir como tanque: más lento que Armas, pero casi nunca mueres, juntas varios monstruos a la vez y llegas listo para tanquear cualquier mazmorra."] = "以坦克身份升级：比武器天赋慢，但几乎不会死，能一次拉好几个怪，升到满级时也已准备好坦任何地下城。",
	["Subir de nivel"] = "升级",
	["Subir de nivel, profesiones, hacer oro o mazmorras: dos clics y Alfa te lleva."] = "升级、专业、赚金币或地下城：点两下，Alfa 就会带你去。",
	["Subir de nivel, profesiones, oro o mazmorras."] = "升级、专业、金币或地下城。",
	["Subir el sonido al pescar"] = "钓鱼时调高声音",
	["Subir rápido"] = "快速升级",
	["Subir solo"] = "单人升级",
	["Subir una profesión"] = "提升一项专业",
	["Succionar vida: daño con el tiempo que te cura."] = "生命虹吸：持续伤害，同时治疗你。",
	["Suelta"] = "掉落",
	["Suelta el lanzamiento de ahora y lanza otra vez, sin poner equipo ni cebo."] = "放弃当前这一竿并重新抛竿，不换装备也不上鱼饵。",
	["Suelta lo que tienes en el cursor y vuelve a intentarlo."] = "先放下光标上拿着的东西，再试一次。",
	["Suelta una carta que empieza una misión: revisa su botín."] = "他会掉落一封能开始任务的信：检查他的战利品。",
	["Suelta una llave que abre una puerta más adelante: alguien debe recogerla."] = "他会掉落一把钥匙，能打开前面的门：要有人拾取。",
	["Suelta una nube de enfermedad a su alrededor: quiten enfermedades."] = "他会在身边释放疾病之云：驱散疾病。",
	["Suelta una ola de fuego a su alrededor: si peleas de lejos, quédate lejos de él."] = "他会向四周放出一圈火焰：远程玩家请远离他。",
	["Suena ahora, aunque el aullido esté apagado."] = "立即播放，即使狼嚎已关闭。",
	["Sueño con una montaña de salchichas... y yo en la punta, feliz."] = "我梦见一座香肠堆成的山……我开心地站在山顶。",
	["Sugerida para ti: %s"] = "为你推荐：%s",
	["Sugerir la piedra de hogar"] = "建议使用炉石",
	["Sugerir qué guardar"] = "建议存放的物品",
	["Sugerir qué vender"] = "建议该卖什么",
	["Sugiere con la prioridad de Alfa para tu clase. Apagado, usa la ayuda de Blizzard cuando el juego da una sugerencia que Alfa puede leer; en combate Forever la oculta, así que ahí sigue la de Alfa."] = "按 Alfa 为你职业设定的优先级给出建议。关闭时，若游戏给出 Alfa 能读取的建议，则使用暴雪的战斗辅助；战斗中 Forever 会隐藏它，因此仍使用 Alfa 的。",
	["Sulfuras es el martillo de Ragnaros. Con su ojo, los más valientes pueden forjar una versión legendaria."] = "萨弗拉斯是拉格纳罗斯的战锤。凭借萨弗拉斯之眼，最勇敢的人能锻造出它的传说版本。",
	["Suma tus sesiones de hoy con este personaje."] = "此角色今天所有游戏的总和。",
	["Suma «conseguir este objeto» a tu plan de ahora (o a uno nuevo)."] = "把“获得这件物品”加入你当前的计划（或一个新计划）。",
	["Supervivencia"] = "生存",
	["Supervivencia para subir"] = "生存（升级）",
	["Sus antojos y salchichas"] = "她的馋嘴和香肠",
	["Sus bolas de sombra pegan mucho: interrúmpelo."] = "他的暗影箭伤害很高：打断他。",
	["Sus cariñitos"] = "她的暖心话",
	["Sus consejos"] = "她的建议",
	["Sus consejos te esperan en Alfa."] = "它的提示在 Alfa 中等着你。",
	["Sus jefes, su botín, sus misiones y cómo llegar."] = "它的首领、战利品、任务以及如何前往。",
	["Sus misiones dan"] = "任务可获得",
	["Sus rayos saltan entre jugadores: sepárense."] = "她的闪电会在玩家之间跳跃：分散站位。",
	["Susurrar"] = "密语",
	["Susurrar a %s"] = "密语 %s",
	["Sutileza"] = "敏锐",
	["Sutileza para subir"] = "敏锐（升级）",
	["Sylvanas era hermana de Alleria y de Vereesa Brisaveloz. Hoy guía a los Renegados con mano firme."] = "希尔瓦娜斯是奥蕾莉亚和温蕾萨·风行者的姐妹。如今她以铁腕领导被遗忘者。",
	["Sylvanas recibe en el Barrio Real de Entrañas, con Varimathras a su lado."] = "希尔瓦娜斯在幽暗城的皇家区接见来客，瓦里玛萨斯就在她身旁。",
	["Sylvanas tiene dos hermanas: Alleria, que se fue más allá del Portal Oscuro, y Vereesa, que se casó con el mago Rhonin."] = "希尔瓦娜斯有两个姐妹：去了黑暗之门另一边的奥蕾莉亚，以及嫁给法师罗宁的温蕾萨。",
	["Sábado"] = "星期六",
	["Sí"] = "是",
	["Sí, que la manada me vea"] = "是的，让狼群看到我",
	["Sí, que me vean"] = "是的，让他们看到我",
	["Sí, sígueme diciendo"] = "好，继续告诉我",
	["Sí, ya la hice"] = "是的，我打过了",
	["Sí: Alfa, Clásico WoW o Cristal, con tu color. También puede vestir el chat, el minimapa y las barras."] = "能：Alfa、经典 WoW 或水晶，配你的颜色。还能装扮聊天框、小地图和动作条。",
	["Sí: con /alfa limpia, o con tu tecla de pantalla limpia, escondo el chat, el minimapa y lo demás que elijas. Otra vez y vuelve todo."] = "可以：用 /alfa limpia 或你的清爽画面按键，我会隐藏聊天框、小地图和你选的其他东西。再按一次就全部回来。",
	["Sí: con el modo foco, en mazmorras y en combate me hago chiquita y me callo. Al terminar vuelvo. Está en mis ajustes."] = "可以：开启专注模式后，在地下城和战斗中我会变小并保持安静。之后我就回来。这在我的设置里。",
	["Sí: en Ajustes > Estilo y sonido elige «Sencillo» en «Cómo ves Alfa». Dejo a la vista solo lo esencial y te aviso menos."] = "可以：在 设置 > 风格与声音 的“Alfa 的显示方式”里选“简洁”。我只留下最重要的，提醒也会更少。",
	["Sí: en las asignaciones de teclas del juego, en la sección Alfa, ponle una tecla a «Pregúntale a Lya» y otra a «Lo que te ofrece Lya», que hace lo de su botón."] = "可以：在游戏按键设置的 Alfa 分类里，给“问问莉娅”设一个键，再给“莉娅的提议”设一个，它会执行她按钮的操作。",
	["Sí: en las asignaciones de teclas del juego, en la sección Alfa, ponle una tecla a «Pregúntale a Lya»."] = "可以：在游戏按键设置的 Alfa 分类里，给“问问莉娅”设个键。",
	["Sí: en «Mentor», pulsa «Adoptar» junto a un lobo 10 niveles menor. Si acepta, ves cómo va y te aviso si se atora."] = "可以：在“导师”中，点一只比你低 10 级的狼旁边的“收养”。如果他接受，你能看到他的进展，他卡住时我会告诉你。",
	["Sí: escribe /alfa nota y tu texto, o usa «Nota aquí» en La Jauría. Sale en tu mapa donde estás; un clic y la flecha te lleva."] = "可以：输入 /alfa nota 加上内容，或在 La Jauría 中点“在这里记笔记”。笔记会出现在你站立处的地图上；点一下，箭头就会带你过去。",
	["Sí: sale «[Misión] está lista para entregar» y «¡Misión completada!» en el chat del grupo. Solo, te sale a ti."] = "会：队伍聊天里会出现“[任务] 可以交付了”和“任务完成！”。单人时只有你看到。",
	["Símbolo de reyes"] = "王者印记",
	["Tabardo"] = "战袍",
	["Talentos"] = "天赋",
	["Talentos de %s"] = "%s的天赋",
	["Talentos te dice cuál sigue."] = "“天赋”会告诉你下一个点哪个。",
	["Talentos y combate"] = "天赋与战斗",
	["Talentos: qué poner ahora y tu build (/alfa builds aplicar | equipo | compartir)"] = "天赋：现在该点什么和你的方案（/alfa builds aplicar | equipo | compartir）",
	["Tamaño"] = "大小",
	["Tamaño de la barra"] = "钓鱼条大小",
	["Tamaño de las casillas"] = "格子大小",
	["Tamaño de las que siguen"] = "后续图标的大小",
	["Tamaño de lo que atraviesa"] = "可穿过的物体大小",
	["Tamaño de su letra"] = "字体大小",
	["Tamaño del ícono"] = "图标大小",
	["Tamaño en el mapa"] = "地图上的大小",
	["Tamaño en el minimapa"] = "小地图上的大小",
	["También con /alfa dps. No se cierra con Esc, para que la tengas a la vista al pelear."] = "也可用 /alfa dps。按 Esc 不会关闭，让你战斗时一直看得到。",
	["También con /alfa limpia."] = "也可以用 /alfa limpia。",
	["También cuando el juego hace brillar otra habilidad"] = "游戏让其他技能发光时也提醒",
	["También dentro de cuevas, criptas y edificios."] = "在洞穴、墓穴和建筑物内也一样。",
	["También el de venenos, sangrados y efectos que duran."] = "也包括毒药、流血和持续效果造成的伤害。",
	["También en el minimapa"] = "也显示在小地图上",
	["También en montura"] = "坐骑上也可用",
	["También está en el menú de opciones del juego."] = "也在游戏的选项菜单中。",
	["También fuera de combate"] = "非战斗时也显示",
	["También las de las mascotas de enemigos."] = "也包括敌人宠物的。",
	["También las que no son de la guía (de esas se encarga \"Aceptar misiones de la guía\"). No toma misiones grises, no entrega las que piden oro, monedas o materiales de oficio, y si hay varias recompensas eliges tú. Mantén presionado Mayús para hacerlo tú."] = "也包括指南以外的任务（指南内的由“接受指南任务”负责）。不接灰色任务，不交付需要金币、货币或专业材料的任务，有多个奖励时由你来选。按住 Shift 可以手动操作。",
	["También las que no son de tu guía"] = "也包括指南以外的任务",
	["También tu foco"] = "也包括你的焦点",
	["También usa Alfa: salúdalo."] = "也在用 Alfa：去打个招呼吧。",
	["También yendo solo"] = "单人时也播放",
	["Tanque"] = "坦克",
	["Tanque de amenaza"] = "仇恨型坦克",
	["Tanque de escudo"] = "盾牌坦克",
	["Tanque en apuros"] = "坦克告急",
	["Tanque muralla"] = "铁壁坦克",
	["Tanqueas"] = "你负责坦克",
	["Taretha Foxton, una muchacha humana de Durnholde, fue la amiga de Thrall y lo ayudó a escapar."] = "敦霍尔德的人类姑娘塔蕾莎·福克斯顿是萨尔的朋友，帮助他逃了出去。",
	["Tarjeta de habilidades nuevas al subir de nivel"] = "升级时显示新技能卡片",
	["Tauren"] = "牛头人",
	["Te abrimos un susurro para %s con tu mensaje. Revísalo y pulsa Intro para enviarlo."] = "已为你打开给%s的密语并填好消息。检查后按回车键发送。",
	["Te acompaña"] = "陪伴你",
	["Te avisa al momento de %s."] = "%s亮起时立即提醒你。",
	["Te avisa cuando tu clase tiene algo que aprovechar ahora, como una habilidad que se encendió."] = "当你的职业现在有可以利用的东西时提醒你，例如刚被点亮的技能。",
	["Te aviso con «Regalárselo»: abre el comercio si está a tu lado o te deja su nombre en el correo. Necesitan compartir su clase y nivel."] = "我会用“送给他”提醒你：他在你旁边就打开交易，否则把他的名字填进邮件。对方需要分享自己的职业和等级。",
	["Te conviertes en felino: mucho daño cuerpo a cuerpo y puedes acechar."] = "你变成猎豹：近战伤害很高，还能潜行。",
	["Te conviertes en foca: nadas rápido y respiras bajo el agua."] = "你变成海豹：游得快，还能在水下呼吸。",
	["Te conviertes en guepardo y corres más rápido. Solo al aire libre."] = "你变成猎豹，跑得更快。只能在户外使用。",
	["Te conviertes en lobo y corres más rápido. ¡Como yo!"] = "你变成狼，跑得更快。就像我一样！",
	["Te conviertes en oso: más armadura y más vida. Para tanquear y aguantar."] = "你变成熊：更多护甲和生命值。用来坦克和扛伤害。",
	["Te cura toda la vida a cambio de tu maná. Guárdalo para una emergencia."] = "用你的法力把自己治疗到满血。留着应急用。",
	["Te da %s."] = "可获得%s。",
	["Te da consejos cortos y ánimo sin repetirse: cada frase sale tres veces como mucho. Dale clic para pedirle uno; clic derecho para sus opciones."] = "她会给你简短的建议和鼓励，而且不会重复：每句话最多出现三次。点她就能要一条；右键点击可打开她的选项。",
	["Te da ira a cambio de un poco de vida. Úsala para empezar una pelea con ira."] = "用一点生命值换怒气。开打前用来攒怒气。",
	["Te da poder de ataque: cada golpe pega más. Para el guerrero también sube el bloqueo con escudo."] = "提供攻击强度：每次攻击都打得更痛。对战士来说还能提高盾牌格挡值。",
	["Te damos la bienvenida a Alfa, el todo en uno de La Jauría."] = "欢迎使用 Alfa，La Jauría 的一体化插件。",
	["Te dice qué comprar a tu nivel y te lleva al vendedor de comida más cercano. El agua, solo si usas maná."] = "告诉你这个等级该买什么，并带你去最近的食物商人。只有用法力的才需要水。",
	["Te dice qué pieza está por romperse, para que la repares a tiempo."] = "告诉你哪件装备快坏了，让你及时修理。",
	["Te enseña %s."] = "可学会%s。",
	["Te enseña Pesca y sus rangos. También vende la caña básica."] = "教授钓鱼及其等级。也出售基础鱼竿。",
	["Te falta"] = "缺少",
	["Te falta %s"] = "缺少%s",
	["Te falta 1 nivel para el 60"] = "还差 1 级到 60 级",
	["Te falta 1 nivel para tomarla."] = "还差 1 级才能接取。",
	["Te falta 1 paso"] = "还差 1 步",
	["Te falta 1 rincón."] = "还剩 1 个角落。",
	["Te falta Aspecto del halcón: más poder a distancia."] = "你缺少雄鹰守护：提高远程攻击强度。",
	["Te falta Aura de disparo certero: más poder a distancia para tu grupo."] = "缺少强击光环：为你的队伍提供更多远程攻击强度。",
	["Te falta Bendición de poderío: más poder de ataque."] = "你缺少力量祝福：提高攻击强度。",
	["Te falta Escudo de relámpagos."] = "你缺少闪电之盾。",
	["Te falta Escudo sagrado: bloqueas más."] = "你缺少神圣之盾：提高格挡。",
	["Te falta Espinas."] = "你缺少荆棘术。",
	["Te falta Fuego interior: más armadura."] = "你缺少心灵之火：提高护甲。",
	["Te falta Grito de batalla: más poder de ataque para ti y tu grupo."] = "你缺少战斗怒吼：提高你和队伍的攻击强度。",
	["Te falta Intelecto Arcano: más maná."] = "你缺少奥术智慧：提高法力值。",
	["Te falta Marca de lo Salvaje."] = "你缺少野性印记。",
	["Te falta Palabra de poder: entereza: más vida."] = "你缺少真言术：韧：提高生命值。",
	["Te falta aprender la receta."] = "你还需要学会配方。",
	["Te falta el tótem de Fuerza de la tierra: más fuerza."] = "缺少大地之力图腾：更多力量。",
	["Te falta este vuelo: háblale al maestro de vuelo para aprenderlo."] = "你还没有这条飞行路线：和飞行管理员交谈来学会它。",
	["Te falta ira: Enfurecer te la da."] = "怒气不足：激怒可以给你怒气。",
	["Te falta ira: Ira sangrienta te la da gratis."] = "怒气不足：血性狂暴可免费提供怒气。",
	["Te falta ira: esta habilidad te la da al recibir golpes."] = "怒气不足：这个技能会在你受到攻击时给你怒气。",
	["Te falta la forma de las Sombras: más daño de sombras y menos daño recibido."] = "缺少暗影形态：更高的暗影伤害，受到的伤害更少。",
	["Te falta la forma de lechúcico lunar: más daño con tus hechizos."] = "缺少枭兽形态：你的法术伤害更高。",
	["Te falta la profesión"] = "缺少该专业",
	["Te falta reputación"] = "声望不足",
	["Te falta tu armadura demoníaca."] = "缺少你的恶魔护甲。",
	["Te falta tu armadura: ponte una."] = "缺少护甲：施放一个。",
	["Te falta un aspecto: el del halcón da más poder a distancia."] = "缺少守护：雄鹰守护提供更多远程攻击强度。",
	["Te falta un aspecto: el del mono te ayuda a esquivar."] = "缺少守护：灵猴守护帮助你躲闪。",
	["Te falta una bendición: Poderío da más poder de ataque."] = "缺少祝福：力量祝福提供更多攻击强度。",
	["Te falta una bendición: Sabiduría te devuelve maná."] = "缺少祝福：智慧祝福为你恢复法力值。",
	["Te falta una bendición: Santuario reduce el daño que recibes."] = "缺少祝福：庇护祝福减少你受到的伤害。",
	["Te faltan %d de %d materiales"] = "你还缺 %d / %d 种材料",
	["Te faltan %d niveles para tomarla."] = "还差 %d 级才能接取。",
	["Te faltan %d pasos"] = "还差 %d 步",
	["Te faltan %d rincones."] = "还剩 %d 个角落。",
	["Te faltan %s"] = "还差 %s",
	["Te faltan %s XP para el nivel %d"] = "还差 %s 经验升到 %d 级",
	["Te faltan %s XP para el nivel %d, a tu ritmo actual."] = "还需 %s 经验才能升到 %d 级（按你当前的速度）。",
	["Te faltan %s de experiencia para el nivel %d"] = "还差 %s 经验升到 %d 级",
	["Te faltan %s niveles para el %d"] = "还差 %s 级到 %d 级",
	["Te faltan ingredientes para el siguiente lote."] = "下一批缺少材料。",
	["Te faltan ingredientes."] = "缺少材料。",
	["Te faltan niveles para llegar a %d: la guía te lo marca y sigues subiendo con tu ruta."] = "你还需要升级才能到 %d 级：指南会标出来，你继续按路线升级。",
	["Te faltan niveles: cada nivel desde el 10 te da un punto."] = "等级不够：从 10 级起每升一级获得一个天赋点。",
	["Te haces el muerto y los enemigos te olvidan. Tu mejor salida si algo sale mal."] = "你装死，敌人就会忘了你。情况不妙时最好的脱身办法。",
	["Te la da %s, en %s."] = "由%s提供，位于%s。",
	["Te la da %s."] = "由%s提供。",
	["Te la dio %s"] = "由%s给予",
	["Te la dio %s · Se entrega con %s"] = "由%s给予 · 交给%s",
	["Te la dio y la recibe %s"] = "由%s给予并交付",
	["Te lleva a las misiones de tu ruta que ya puedes tomar."] = "带你去接你路线上已经可以接的任务。",
	["Te lleva al Claro de la Luna, un lugar tranquilo para entrenar."] = "带你去月光林地，一个安静的训练之地。",
	["Te llevo a %s"] = "带你去%s",
	["Te llevo a entregarlas todas en el mejor orden."] = "我带你按最佳顺序全部交掉。",
	["Te llevo a la mejor fuente. Recuerda que una montura pide nivel, equitación y oro."] = "带你去最佳来源。记住，坐骑需要等级、骑术和金币。",
	["Te llevo a quien recibe cada una y recoges las que siguen."] = "我会带你去找每个任务的交付人，你再接取后续任务。",
	["Te llevo la cuenta de tu día de caza: misiones, niveles, oro, raros y el tiempo. Escribe /alfa lya dia y te lo cuento."] = "我会记录你的狩猎日：任务、等级、金币、稀有怪和时间。输入 /alfa lya dia 我就告诉你。",
	["Te llevo la cuenta de tu semana de caza y tu mejor día. Escribe /alfa lya semana y te lo cuento."] = "我会记录你本周的狩猎和最佳一天。输入 /alfa lya semana 我就告诉你。",
	["Te lo da un PNJ"] = "由 NPC 给予",
	["Te lo enseña cualquier instructor de este oficio en las ciudades. Puedes tener dos oficios principales; Cocina y Primeros auxilios no cuentan."] = "主城里任何一位该专业的训练师都能教。你可以学两个主专业；烹饪和急救不算。",
	["Te lo enseña cualquier instructor de pesca. Hasta que lo aprendas, tu habilidad no pasa del tope."] = "任何钓鱼训练师都能教你。在你学会之前，技能无法超过上限。",
	["Te lo enseña tu entrenador."] = "你的训练师会教你。",
	["Te lo enseñan desde el nivel %d."] = "从 %d 级开始可以学。",
	["Te lo pido de corazón: nunca desuelles a un lobo enfrente de mí, ¿sí?"] = "我真心拜托你：千万别在我面前剥狼皮，好吗？",
	["Te los enseña tu entrenador."] = "你的训练师会教你。",
	["Te perdiste esto"] = "你错过了这个",
	["Te piden tus misiones"] = "有人向你索要任务",
	["Te presento a Lya"] = "认识一下莉娅",
	["Te pusiste «%s»: %d piezas."] = "你穿上了“%s”：%d 件。",
	["Te queda 1 casilla libre."] = "还剩 1 个空格子。",
	["Te queda 1 espacio"] = "只剩 1 格",
	["Te queda 1."] = "你还剩 1 个。",
	["Te queda muy poco maná: Estimular lo recupera."] = "你的法力值所剩无几：激活可以恢复。",
	["Te queda muy poco maná: Evocación lo recupera."] = "你的法力值所剩无几：唤醒可以恢复。",
	["Te queda poca XP descansada"] = "你的精力充沛经验不多了",
	["Te queda poca agua"] = "你的水快没了",
	["Te queda poca comida"] = "你的食物快没了",
	["Te queda poca comida y agua"] = "你的食物和水快没了",
	["Te queda poco maná y te sobra vida: cambia vida por maná."] = "法力值不多而生命值有富余：用生命换法力。",
	["Te queda poco maná: cambia vida por maná."] = "法力值不足：用生命值换取法力值。",
	["Te queda poco maná: usa tu varita."] = "法力值不多了：用你的魔杖。",
	["Te quedan %d casillas libres."] = "还剩 %d 个空格子。",
	["Te quedan %d de %d espacios"] = "剩余 %d / %d 格",
	["Te quedan %d espacios en las bolsas. Vende lo gris o guarda en el banco."] = "背包只剩 %d 格。卖掉灰色物品或存进银行。",
	["Te quedan %d."] = "你还剩 %d 个。",
	["Te quedaste sin agua"] = "你的水没了",
	["Te quedaste sin comida"] = "你的食物没了",
	["Te quedaste sin comida ni agua"] = "你的食物和水都没了",
	["Te saluda según la hora, comenta la zona y a veces se sienta a pedirte algo con su huesito."] = "她会按时间跟你打招呼，评论所在的区域，有时还会叼着小骨头坐下来向你讨东西。",
	["Te sobra ira y hay varios enemigos: tu siguiente golpe alcanza a dos."] = "怒气充足且有多个敌人：你的下一次攻击能命中两个目标。",
	["Te sobra ira: gástala en tu siguiente golpe."] = "怒气充足：在下一次攻击中消耗掉。",
	["Te sobra ira: tu siguiente golpe es más fuerte."] = "怒气充足：你的下一次攻击更强。",
	["Te sugiere objetivos de pasos más adelante que tienes muy cerca."] = "推荐离你很近的后续步骤目标。",
	["Te sugiere qué habilidad usar ahora y cuáles siguen. Solo sugiere: nunca presiona nada por ti."] = "建议现在该用哪个技能以及接下来用哪些。它只是建议：绝不会替你按任何键。",
	["Te teletransporta a tu ciudad. Necesitas una runa de teletransporte."] = "把你传送到你的主城。需要一个传送符文。",
	["Te teletransportas unos metros hacia adelante. Para escapar de raíces y aturdimientos."] = "把你向前传送几码。能摆脱定身和昏迷。",
	["Te vuelve inmune un rato. Úsalo para salvarte o para escapar."] = "让你免疫一段时间。用来自救或逃跑。",
	["Te vuelves invisible al caminar. Acércate sin que te vean y elige cómo empezar."] = "你在行走时隐形。悄悄靠近，自己决定怎么开打。",
	["Tecla del modo pesca"] = "钓鱼模式按键",
	["Tecla fija para pescar"] = "固定钓鱼按键",
	["Tecla grande"] = "大号按键显示",
	["Tecla para abrir o cerrar el modo"] = "打开或关闭此模式的按键",
	["Tecla para volver a lanzar"] = "重新抛竿按键",
	["Tecla y modo pesca"] = "按键与钓鱼模式",
	["Tela"] = "布甲",
	["Teldrassil es tan grande que entre sus ramas hay colinas, lagos y cuevas."] = "泰达希尔大到枝干上有山丘、湖泊和洞穴。",
	["Teldrassil es un árbol del mundo que los elfos de la noche plantaron sin la bendición de los dragones. Por eso no les dio la inmortalidad."] = "泰达希尔是暗夜精灵在没有巨龙祝福的情况下种下的世界之树。所以它没有赐予他们永生。",
	["Teldrassil se plantó para recuperar la inmortalidad, pero sin la bendición de los dragones. Algo en él no anda bien."] = "种下泰达希尔是为了找回永生，但没有得到巨龙的祝福。它有些地方不太对劲。",
	["Teldrassil siempre tiene una luz suave, como si el árbol mismo nos cuidara."] = "泰达希尔总有一抹柔光，好像那棵树在守护着我们。",
	["Ten siempre a mano una poción de vida: este build no perdona errores."] = "随时备好一瓶治疗药水：这个方案容不得失误。",
	["Tenga o no"] = "无论是否拥有",
	["Tengo hambre… ¿me compartes algo de tu mochila?"] = "我饿了……能从你的背包里分我点吃的吗？",
	["Tengo muchas misiones a medias, ¿qué hago?"] = "我有很多做了一半的任务，怎么办？",
	["Tengo poco tiempo, ¿qué hago?"] = "我没多少时间，该做什么？",
	["Terenas Menethil, rey de Lordaeron, unió a los reinos en la Alianza de Lordaeron. Años después, su propio hijo Arthas lo mató en su trono."] = "洛丹伦国王泰瑞纳斯·米奈希尔把各王国联合成洛丹伦联盟。多年后，他的亲生儿子阿尔萨斯在王座上杀死了他。",
	["Termina la configuración para usar Alfa (2 minutos)."] = "完成设置即可使用 Alfa（2 分钟）。",
	["Terminada"] = "已完成",
	["Terminado: cumpliste todas sus metas."] = "已完成：你达成了它的所有目标。",
	["Terminar"] = "结束",
	["Terminar la cadena de Lord Valthalak también es un reto del Legado."] = "完成瓦塔拉克公爵的任务链也是一项传承挑战。",
	["Terminaste %d de sus misiones: entrégalas y recoge las que siguen."] = "你完成了它的 %d 个任务：交付后接取后续任务。",
	["Terminaste 1 de sus misiones: entrégala y recoge las que siguen."] = "你完成了它的 1 个任务：交付后接取后续任务。",
	["Terminaste esta guía."] = "你完成了这个指南。",
	["Terminaste esta guía. Elige la siguiente para seguir subiendo."] = "你完成了这个指南。选择下一个继续升级。",
	["Termínala antes de entregarla."] = "先完成再交付。",
	["Terreno, como el minimapa"] = "地形，像小地图一样",
	["Terreno: al acercarte se ve el suelo real del minimapa, con sus montañas, ríos y tonos. Clásico: solo el mapa pintado del juego."] = "地形：放大后会显示小地图的真实地面，包括山脉、河流和色调。经典：只显示游戏的手绘地图。",
	["Tesoro"] = "宝藏",
	["Tesoro de la manada: %s"] = "狼群的宝藏：%s",
	["Tesoros"] = "宝藏",
	["Tesoros en el mapa"] = "地图上的宝藏",
	["Tesoros en el minimapa"] = "小地图上的宝藏",
	["Texto de combate flotante"] = "浮动战斗信息",
	["Texto sobre tu personaje"] = "角色上方的文字",
	["Textos y cajas mejor alineados en las ventanas de Alfa."] = "Alfa 各窗口中的文字和方框对齐得更好了。",
	["Texturas del mundo"] = "世界材质",
	["Texturas del suelo"] = "地面材质",
	["Texturas proyectadas"] = "投影材质",
	["Texturas y nitidez"] = "材质与锐化",
	["Theradras, la princesa de la tierra, es hija de Therazane. Amó a Zaetar, hijo de Cenarius, y sus hijos, los centauros, terminaron matándolo."] = "大地公主瑟莱德丝是塞拉赞恩的女儿。她爱上了塞纳留斯之子扎尔塔，而他们的孩子半人马最后却杀了他。",
	["Theramore la fundó Jaina Valiente con los humanos que salieron de Lordaeron antes de su caída."] = "塞拉摩由吉安娜·普罗德摩尔和在洛丹伦陷落前离开的人类共同建立。",
	["Thrall eligió esta tierra roja y seca para que los orcos libres empezaran de nuevo, lejos de los campos de internamiento de los humanos."] = "萨尔选择了这片赤红干燥的土地，让获得自由的兽人远离人类的收容所，重新开始。",
	["Thrall es el chamán más famoso: los elementos le responden como a nadie."] = "萨尔是最有名的萨满：元素对他的回应无人能比。",
	["Thrall gobierna la Horda desde Orgrimmar como jefe de guerra, con la mirada puesta en la paz."] = "萨尔以酋长身份在奥格瑞玛统治部落，目光放在和平上。",
	["Thrall liberó a los orcos de los campos de internamiento con la ayuda de Grom Grito Infernal y de Orgrim Martillo Maldito."] = "萨尔在格罗姆·地狱咆哮和奥格瑞姆·毁灭之锤的帮助下，把兽人从收容所中解放出来。",
	["Thrall nació en Draenor, hijo de Durotan y Draka. Aedelas Blackmoore lo encontró de bebé y lo llamó «Thrall», que quiere decir esclavo."] = "萨尔出生在德拉诺，是杜隆坦和德拉卡的儿子。埃德拉斯·布莱克摩尔在他还是婴儿时发现了他，给他取名“萨尔”，意思是奴隶。",
	["Thrall quiere que los orcos recuperen el honor que tenían antes de la corrupción demoníaca."] = "萨尔希望兽人找回他们在被恶魔腐化之前拥有的荣耀。",
	["Tiempo"] = "时间",
	["Tiempo de juego por sesión"] = "每次游戏时长",
	["Tiempo hasta que pica"] = "到鱼上钩的时间",
	["Tiempo máximo entre los dos clics. Súbelo si tus dobles clics no lanzan."] = "两次点击之间的最长间隔。如果双击没能抛竿，请调高此值。",
	["Tiempo pescando"] = "钓鱼时长",
	["Tiempo: %s"] = "时间：%s",
	["Tiene cuatro partes que se hacen por separado: Cementerio, Biblioteca, Armería y Catedral, de la más fácil a la más difícil."] = "它分为四个区域，各自独立进行：墓地、图书馆、武器库和大教堂，难度由易到难。",
	["Tiene un perjuicio que puedes quitar:"] = "有一个你能驱散的减益效果：",
	["Tienes"] = "你拥有",
	["Tienes %d"] = "你有 %d 个",
	["Tienes %d  ·  en %s"] = "你有 %d  ·  在%s",
	["Tienes %d casillas libres"] = "你有 %d 个空格",
	["Tienes %d de %d"] = "你拥有 %d / %d",
	["Tienes %d de %d casillas de bolsa en el banco."] = "你有 %d/%d 个银行背包栏位。",
	["Tienes %d de %d casillas de bolsa. La siguiente cuesta %s; después pon una bolsa en ella."] = "你有 %d/%d 个背包栏位。下一个需要 %s；之后放一个背包进去。",
	["Tienes %d encendidas. Abajo está cada una, con lo que hace, por si quieres cambiar algo."] = "你已开启 %d 项。下方列出每一项及其作用，方便你调整。",
	["Tienes %d misiones listas"] = "你有 %d 个已完成的任务",
	["Tienes %d misiones listas para entregar"] = "你有 %d 个任务可交付",
	["Tienes %d misiones listas para entregar. ¿Las juntamos en una ruta?"] = "你有 %d 个任务可以交付。要把它们排成一条路线吗？",
	["Tienes %d para gastar"] = "你有 %d 点可用",
	["Tienes %d piezas mejores para pescar en tus bolsas."] = "你的背包里有 %d 件更好的钓鱼装备。",
	["Tienes %d puntos de talento: empieza por %s"] = "你有 %d 个天赋点：先点%s",
	["Tienes %d puntos fuera de %s. Alfa nunca quita talentos: para seguir este build, reinicia tus talentos con tu entrenador de clase y Alfa te los vuelve a poner con un clic. O elige el build de la rama que ya llevas."] = "你有 %d 点不在%s中。Alfa 绝不会移除天赋：要跟随这个方案，请找职业训练师重置天赋，Alfa 会一键帮你重新点好。或者选择你已点的天赋系的方案。",
	["Tienes %d puntos libres, pero los talentos que siguen en %s no existen en tu árbol (puede que cambiaran con un parche). Ponlos a mano en la ventana del juego o prueba otro estilo."] = "你有 %d 个未分配点数，但%s中接下来的天赋在你的天赋树中不存在（可能已被补丁改动）。请在游戏窗口中手动点，或试试其他风格。",
	["Tienes %s de %s"] = "你有 %s / %s",
	["Tienes %s precios de tus búsquedas. Para conocer todos, escanea en la casa de subastas."] = "你有 %s 个来自搜索的价格。想知道全部价格，请在拍卖行进行扫描。",
	["Tienes 1 misión lista para entregar"] = "你有 1 个任务可交付",
	["Tienes 5 puntos de combo y estás en grupo: el sangrado rinde más."] = "你有 5 个连击点数且在队伍中：流血效果更划算。",
	["Tienes 5 puntos de combo: el remate más fuerte."] = "你有 5 个连击点数：最强的终结技。",
	["Tienes 5 puntos de combo: muerde fuerte."] = "你有 5 个连击点数：狠狠咬下去。",
	["Tienes 6 guías abiertas"] = "你打开了 6 个指南",
	["Tienes activado «Rechazar invitaciones a hermandad» en Ajustes > Comodidades > Social: apágalo para que te llegue la invitación."] = "你在“设置 > 便利功能 > 社交”中开启了“拒绝公会邀请”：请关闭它，才能收到邀请。",
	["Tienes cambios sin confirmar en la ventana de talentos: se descartan antes de aplicar."] = "天赋窗口中有未确认的更改：应用前会先丢弃它们。",
	["Tienes cambios sin guardar en la ventana de talentos del juego: guárdalos o deshazlos ahí primero"] = "游戏的天赋窗口中有未保存的更改：请先在那里保存或撤销",
	["Tienes encendido «solo las misiones de mi ruta»: solo acepta las de tu ruta."] = "你已开启“只接我路线上的任务”：只会接受你路线上的任务。",
	["Tienes furia: úsalo antes de la siguiente pelea, te da más poder de ataque a ti y a tu grupo."] = "你有怒气了：在下一场战斗前使用它，可以提高你和队友的攻击强度。",
	["Tienes habilidades nuevas"] = "你有新技能可学",
	["Tienes habilidades sin aprender (%d). Aprenderlas te hace más fuerte."] = "你有 %d 个技能尚未学习。学会它们会让你更强。",
	["Tienes la %s, %d versiones atrás."] = "你的版本是 %s，落后 %d 个版本。",
	["Tienes la %s."] = "你的版本是 %s。",
	["Tienes misiones grises: mira cuáles ya no valen la pena y suéltalas para hacer espacio."] = "你有灰色任务：看看哪些已经不值得做，放弃它们来腾出空间。",
	["Tienes más rangos de los que pide tu build."] = "你点的等级比方案要求的多。",
	["Tienes puesto «%s». Abre la ventana para afinar cada detalle: distancia, pasto, niebla, agua, cámara, placas y filtros."] = "你已套用“%s”。打开窗口可以微调每个细节：距离、草地、雾、水、镜头、姓名板和滤镜。",
	["Tienes puntos fuera del plan: Alfa no los quita, solo agrega."] = "你有方案以外的点数：Alfa 不会移除它们，只会继续加点。",
	["Tienes seis guías abiertas: cierra una y vuelve a intentarlo."] = "你打开了六个指南：关闭一个后再试。",
	["Tienes todo %s"] = "你已拥有全部%s",
	["Tienes un hechizo para ir al Claro de la Luna, el santuario de los druidas."] = "你有一个法术能前往德鲁伊的圣地月光林地。",
	["Tienes un punto de talento: %s"] = "你有一个天赋点：%s",
	["Tienes una misión de clase"] = "你有一个职业任务",
	["Tinte de color"] = "色调",
	["Tipo"] = "类型",
	["Tirion Vadín fue expulsado de la Mano de Plata por defender a Eitrigg, un orco que le salvó la vida. Hoy Eitrigg aconseja a Thrall en Orgrimmar."] = "提里奥·弗丁因为维护救过他一命的兽人埃特里格，被逐出了白银之手。如今埃特里格在奥格瑞玛为萨尔出谋划策。",
	["Tirion Vadín, el paladín expulsado de la orden, vive solo en una cabaña de estas tierras."] = "被逐出骑士团的圣骑士提里奥·弗丁独自住在这片土地上的一间小屋里。",
	["Toca %s."] = "该%s了。",
	["Toca ahora"] = "该点了",
	["Toca el interruptor para poner o quitar una; lo que tocas manda sobre el filtro."] = "拨动开关来加入或移除；你的手动选择优先于筛选条件。",
	["Toca una tarjeta para prenderla o apagarla. Las encendidas llevan el borde de color."] = "点卡片开启或关闭。开启的卡片有彩色边框。",
	["Toca «Seleccionarlo» otra vez, o usa el botón de raros."] = "再点一次“选中它”，或使用稀有怪按钮。",
	["Tocando a la puerta de la %s"] = "正在敲%s的门",
