	["Tuya"] = "你的",
	["Tyrande liberó a Illidan para pelear contra la Plaga, y Maiev, su carcelera, nunca se lo perdonó."] = "泰兰德释放了伊利丹来对抗天灾军团，他的狱卒玛维从未原谅她。",
