	["Un arma en cada mano y mucha ira: el que más daño hace en grupo."] = "双手各持一把武器，怒气充足：组队时输出最高。",
	["Un arma grande de dos manos y golpes que hacen sangrar. La forma más fácil de subir."] = "一把大双手武器，加上造成流血的攻击。最简单的升级方式。",
	["Un aturdimiento cuando lo necesites."] = "随时可用的击晕。",
	["Un aullido corto cada vez que entregas una misión. Viene apagado."] = "每次交任务时短促地嚎叫一声。默认关闭。",
	["Un aullido de lobo, del propio juego, la primera vez que abres Alfa en cada sesión."] = "每次登录后第一次打开 Alfa 时，播放一声游戏自带的狼嚎。",
	["Un aviso con sus jefes y lo que llevas vencido, con un clic a sus consejos."] = "一条提醒，显示它的首领和你已击败的数量，点一下即可查看提示。",
	["Un aviso corto con el lugar, su zona y el tiempo de camino."] = "一条简短提示，包含地点、所在区域和路程时间。",
	["Un aviso corto cuando se activa una habilidad que depende de lo que pasó, como Abrumar después de que el enemigo esquive."] = "当依赖刚才情况的技能被触发时（例如敌人躲闪后的压制），显示简短提醒。",
	["Un aviso cuando juntas todo lo de un material o la lista entera."] = "集齐某种材料或整份清单时提醒你。",
	["Un aviso cuando vences a un jefe nuevo, con un clic a su botín."] = "击败新首领时的提醒，点一下即可查看它的战利品。",
	["Un aviso y una franja en tus bolsas con qué vender, qué conservar y a qué comerciante ir, con un clic para marcar la chatarra."] = "一条提醒和背包中的一栏，告诉你该卖什么、该留什么、去找哪个商人，一键标记垃圾。",
	["Un barrido oscuro y suave sobre los íconos mientras su recarga corre."] = "冷却期间，图标上会有一层柔和的深色转圈。",
	["Un borde del color de la calidad: verde, azul, morado..."] = "按品质着色的边框：绿色、蓝色、紫色……",
	["Un borde verde que late sobre el botón de tu barra con la habilidad sugerida, para encontrarlo rápido."] = "在动作条上带有建议技能的按钮周围显示闪动的绿色边框，方便你快速找到。",
	["Un botón «Alfa» en el menú Esc, como el ícono del minimapa: clic, abre la ventana de Alfa; clic derecho, el menú de Alfa."] = "Esc 菜单中的「Alfa」按钮，和小地图图标一样：单击打开 Alfa 窗口，右键单击打开 Alfa 菜单。",
	["Un brujo con dos compañeros puede invocar al resto del grupo a la entrada de una mazmorra."] = "术士在两名同伴的帮助下，可以把队伍其他人召唤到地下城入口。",
	["Un buzón"] = "邮箱",
	["Un clic bajito cuando Lya te dice algo."] = "Lya 跟你说话时发出轻轻的咔嗒声。",
	["Un clic te pone el conjunto (fuera de combate; en combate, al terminar). Lo que esté en el banco no se puede poner."] = "点一下穿上这套装备（非战斗时；战斗中则在结束后）。银行里的东西无法穿上。",
	["Un clic y queda solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "点一下就只保留必要内容：你、你的队伍、你的标记和指南的下一步。",
	["Un compañero tiene %s y tú lo puedes quitar, pero ningún clic lo hace. Elige «%s» en Tus clics, en la página Curación."] = "有队友中了 %s，你可以驱散，但没有设置对应的点击。到治疗页面的“你的点击”中选择“%s”。",
	["Un consejo"] = "小提示",
	["Un cuadro pequeño y movible con tu vida y las estadísticas que más pesan para tu clase. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "一个可移动的小框，显示你的生命值和对你职业最重要的属性。战斗中游戏会隐藏部分数字：会保留最后读到的数值。",
	["Un disparo instantáneo extra. Úsalo mientras corres o para rematar."] = "额外的瞬发射击。移动中或收尾时用。",
	["Un enemigo"] = "单体",
	["Un error, una mejora o un comentario, directo al desarrollador"] = "错误、改进建议或意见，直接发给开发者",
	["Un escudo que absorbe daño. Ponlo antes de que te peguen o en quien tanquea."] = "吸收伤害的护盾。挨打前先加上，或给你的坦克加上。",
	["Un fondo del color de tu clase bajo tu nombre."] = "在你的名字下方显示职业颜色的背景。",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "用盾牌打出巨大伤害，并产生大量威胁。",
	["Un golpe más para gastar ira."] = "多一个消耗怒气的攻击。",
	["Un golpe nuevo y fuerte para tu barra."] = "为你的动作条添一个强力新攻击。",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "对付难打的怪物时大幅提升伤害；还能让你免疫恐惧。",
	["Un grano fino de cine sobre el mundo."] = "世界上覆盖一层细致的电影颗粒。",
	["Un grano fino, como de cine. Casi no cuesta: se mueve unas 14 veces por segundo y solo mientras se ve."] = "细致的电影风格颗粒。几乎不耗资源：每秒变化约 14 次，而且只在可见时才运作。",
	["Un hechizo de tus barras tiene un rango viejo"] = "你的动作条上有一个法术是旧等级",
	["Un lobo de La Jauría anda cerca"] = "La Jauría 的一匹狼就在附近",
	["Un lobo de nivel %d te quiere echar la mano: ve tu nivel, tu zona y tu misión, solo él. Acepta aquí o en La Jauría."] = "一只 %d 级的狼想帮你一把：只有他能看到你的等级、区域和任务。在这里或在 La Jauría 中接受。",
	["Un mapa de una pieza: al acercar ya no se ven pedazos pegados, y el terreno se une sin rayas ni cuadros."] = "浑然一体的地图：放大时不再看到拼接的碎块，地形无缝相连，没有线条或方格。",
	["Un mapa impecable"] = "完美无瑕的地图",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "任务所需物品显示金色边框（能开始任务的带“!”）。",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo, con lo que haga falta antes."] = "你想要的物品：Alfa 会规划获取它的路线，包括所需的前置条件。",
	["Un paisaje más bonito"] = "更美的风景",
	["Un paseíto y unas palabras. Así también se hace manada."] = "散散步、说几句话。狼群也是这样形成的。",
	["Un pescadito asado no me caería nada mal."] = "来条烤小鱼也挺不错的。",
	["Un pescadito asado para la loba que te acompaña no estaría nada mal, ¿eh?"] = "给陪着你的母狼来一条烤小鱼，好像也不错，对吧？",
	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "在接下来几步要去的地方显示带编号的小图钉。",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "少量暴击、躲闪和护甲。",
	["Un poco de vida de vuelta después de críticos."] = "暴击后恢复少量生命值。",
	["Un poco más de defensa."] = "稍微多一点防御。",
	["Un poco más de ira al cargar."] = "冲锋时多一点怒气。",
	["Un punto azul abajo a la derecha si a ese compañero le falta el buff de tu clase. Se revisa fuera de combate."] = "如果那名队友缺少你职业的增益效果，右下角会出现一个蓝点。在非战斗时检查。",
	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "用一点解锁下一排，并稍微减少未命中。",
	["Un raro vuelve más o menos entre media hora y una hora después de caer. Aquí ves hace cuánto lo cazaron tú o la manada."] = "稀有怪死后大约半小时到一小时会再刷新。这里显示你或狼群多久前击杀了它。",
	["Un raro: %s"] = "稀有怪：%s",
	["Un rayo que salta entre varios enemigos."] = "在多个敌人之间跳跃的闪电。",
	["Un reto de Lya para esta semana."] = "莉娅本周给你的一个挑战。",
	["Un rincón de %s que todavía no pisas."] = "%s 里一个你还没踏足的角落。",
	["Un servicio cercano, un marcador de tu mapa, donde estás ahora o la entrada de una mazmorra."] = "附近的服务、你地图上的标记、你现在的位置或地下城入口。",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "在提供适合你等级任务的人头上显示感叹号。",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "在可以交付已完成任务的人头上显示问号。",
	["Un solo addon con todo lo que usas al jugar: guías paso a paso con flecha y ruta, mapa, bolsas, builds, curación con clic, recolección, mazmorras, pesca y comercio. Todo con el mismo estilo."] = "一个插件包含游戏中用到的一切：带箭头和路线的分步指南、地图、背包、天赋方案、点击治疗、采集、地下城、钓鱼和交易。风格统一。",
	["Un solo aviso: el de tus bolsas, que también te dice qué vender."] = "只有一个提醒：来自背包的提醒，它也会告诉你卖什么。",
	["Un solo día de precios: el historial crece con cada escaneo o búsqueda."] = "只有一天的价格：每次扫描或搜索，记录都会增加。",
	["Un solo menú de Alfa: el ícono del minimapa, la lista de addons y el botón Alfa del menú Esc abren lo mismo."] = "一个 Alfa 菜单：小地图图标、插件列表和 Esc 菜单中的 Alfa 按钮打开的都一样。",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "打得很痛的坦克：为高输出队伍提供大量威胁，代价是额外防御较少。适合有一定经验的坦克。",
	["Un tramo más en la ruta que armas en la página Ruta: Alfa elige el camino para conseguirlo."] = "在“路线”页面创建的路线中再加一段：由 Alfa 选择获取它的路线。",
	["Un tótem que atrae los golpes de los enemigos. Te da un respiro."] = "一个吸引敌人攻击的图腾。让你喘口气。",
	["Un tótem que cura poco a poco a tu grupo."] = "一个缓慢治疗你队伍的图腾。",
	["Un tótem que hace lentos a los enemigos cercanos. Para escapar o pelear con ventaja."] = "一个减速附近敌人的图腾。用来逃跑或占得优势。",
	["Un tótem que le dispara fuego al enemigo. Ponlo al empezar."] = "一个向敌人喷火的图腾。开打时放下。",
	["Un tótem que quita el miedo, el sueño y el encanto a tu grupo."] = "一个为你的队伍移除恐惧、沉睡和魅惑的图腾。",
	["Un tótem que reduce el daño que recibes cuerpo a cuerpo."] = "一个减少你受到的近战伤害的图腾。",
	["Un zarpazo fuerte en forma de oso. Genera mucha amenaza."] = "熊形态下的强力挥击。产生大量仇恨。",
	["Un «?» en cada página de Alfa para que Lya te la explique, y su propia tecla."] = "Alfa 每页都有让莉娅讲解的“?”，还有她专属的按键。",
	["Un ícono con la habilidad que conviene ahora. Solo muestra: nunca aprieta nada por ti."] = "一个显示现在最适合的技能的图标。只负责显示：绝不会替你按任何键。",
	["Un ícono de misión en la placa de nombre de los enemigos y personajes que todavía necesitas para una misión de tu registro. En mazmorras el juego oculta esos datos y no se marcan."] = "在你任务日志中仍需要的敌人和角色的姓名板上显示任务图标。在地下城中游戏会隐藏这些数据，因此不会标记。",
	["Un'Goro de día: dinosaurios por todas partes. Yo me quedo atrás de ti, ¿va?"] = "白天的安戈洛：到处都是恐龙。我待在你后面，好吗？",
	["Una acción recomendada en grande y tu camino en un par de clics."] = "一个醒目的推荐操作，点几下就能看到你的路线。",
	["Una barra bajo el buzón para tomar el dinero y los objetos de tus cartas con un clic, y lo que recibiste al final."] = "邮箱下方的一条按钮栏，一键拿取邮件中的金钱和物品，最后显示你收到了什么。",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "一条显示首领即将使用的攻击及各自剩余时间的计时条，让你知道何时该移动或防御。",
	["Una bienvenida nueva en 9 pasos con la intro del lobo: eliges el idioma de Alfa (hay 10) y cada cosa que hace sola por ti."] = "全新的 9 步欢迎设置，附狼的开场动画：选择 Alfa 的语言（共 10 种），以及它替你自动做的每一件事。",
	["Una cadena de texto lleva un build completo: la copias, la pasas y la pegan."] = "一段文字就能包含完整的方案：你复制、发送，对方粘贴即可。",
	["Una cantidad de oro; se cumple cuando la llevas encima."] = "一定数量的金币；当你身上带有这么多时即达成。",
	["Una carta con objetos vence pronto"] = "一封带物品的邮件即将过期",
	["Una categoría…"] = "某个类别…",
	["Una cuenta de prueba no puede compartir"] = "试玩账号无法共享",
	["Una curación muy rápida pero cara. Para emergencias."] = "非常快但很耗法力的治疗。紧急时用。",
	["Una curación más fuerte. Para cuando la vida baja mucho."] = "更强的治疗。生命值掉很多时用。",
	["Una curación que salta entre tus compañeros heridos."] = "在受伤的朋友之间跳跃的治疗。",
	["Una curación rápida y barata. Perfecta para mantener a todos de pie."] = "快速又便宜的治疗。让大家都站着的完美选择。",
	["Una curación rápida. Para cuando no hay tiempo."] = "快速治疗。没时间时用。",
	["Una fila con vuelo, posada, reparar, banco, buzón y tu entrenador, a un clic."] = "一排按钮：飞行、旅店、修理、银行、邮箱和你的训练师，一键直达。",
	["Una flecha en pantalla que apunta a tu siguiente objetivo, con la distancia. Apagada: tú decides por dónde ir."] = "屏幕上的箭头会指向你的下一个目标，并显示距离。关闭：由你自己决定怎么走。",
	["Una flecha verde en cada objeto de tus bolsas que es una mejora para tu especialización."] = "在背包中每件对你专精有提升的物品上显示绿色箭头。",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "根据你的职业和等级，在比身上更好的装备上显示绿色箭头。",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "浅绿色条显示正在施放中的治疗量。",
	["Una gran curación para todo el grupo mientras canalizas."] = "引导期间为全队大量治疗。",
	["Una guía para tu nivel y tu zona, o tu propia ruta de misiones."] = "适合你等级和区域的指南，或你自己的任务路线。",
	["Una hora de caza"] = "一小时的狩猎",
	["Una hora de caza, aviso de cadena, «Deshacer» al omitir y cuánto te falta de tu guía."] = "一小时狩猎、任务链提醒、跳过后“撤销”，以及指南还剩多久。",
	["Una huella sobre la mejor para tu clase (o la que más vale al venderla) y «Alfa te recomienda». Nunca elige por ti."] = "在最适合你职业的奖励（或卖价最高的）上标一个爪印和“Alfa 推荐”。从不替你选择。",
	["Una lista de las grises que ya no valen la pena, con «Abandonar» en cada una (tú lo confirmas)."] = "列出不再值得做的灰色任务，每个都有“放弃”（由你确认）。",
	["Una loba gordita como yo necesita sus tres comidas... y sus botanas."] = "像我这样胖乎乎的母狼需要一日三餐……还有零食。",
	["Una loba negra que te da consejos y ánimo en el camino, sin estorbar. En memoria de una gran perrita."] = "一匹黑色母狼，在路上给你建议和鼓励，又不碍事。纪念一只很棒的小狗。",
	["Una loba que cuida tan bien a su lobo merece una salchicha, ¿no crees?"] = "这么会照顾自己狼的狼，值得一根香肠，你说是不是？",
	["Una línea con el enlace de la misión cuando completas sus objetivos, otra cuando está lista para entregar y otra al entregarla. En grupo la ve todo el grupo, con o sin Alfa; solo, sale en tu chat. Nunca en banda."] = "完成任务目标时发一行带任务链接的消息，可交付时再发一行，交付时再发一行。组队时全队都能看到，不论有没有 Alfa；单人时显示在你的聊天框。团队中不发送。",
	["Una línea corta debajo del ícono, como «Golpe mortal: recarga lista». Cada una sale hasta 4 veces y luego se calla; su × la calla antes."] = "图标下方的一行短文字，例如“致死打击：冷却完毕”。每条最多显示 4 次，之后就不再出现；点它的 × 可以提前关闭。",
	["Una línea debajo del aviso con lo que pasó."] = "提醒下方一行说明刚才发生了什么。",
	["Una línea roja arriba avisa cuando un enemigo va por ese compañero."] = "当敌人盯上该队友时，顶部会出现一条红线提醒。",
	["Una mano"] = "单手",
	["Una meta que marcas tú (el botón de hecha del rastreador o de esta lista)."] = "由你自己勾选的目标（追踪器或此列表中的完成按钮）。",
	["Una misión"] = "一个任务",
	["Una moneda sobre lo gris y lo que marcaste como chatarra."] = "在灰色物品和你标记为垃圾的物品上显示一枚硬币。",
	["Una nota con el instructor más cercano cuando tienes habilidades nuevas."] = "当你有新技能时，提示最近的训练师。",
	["Una piedra de salud para emergencias. Haz una antes de cada mazmorra."] = "一块应急用的治疗石。每次进地下城前都做一块。",
	["Una piedra que deja revivir al morir. Pónsela a quien cura."] = "一块让人死后能复活的石头。给你的治疗者用。",
	["Una revisión completa de todos los módulos: más de 60 arreglos."] = "全面检查了所有模块：修复了 60 多处问题。",
	["Una revisión completa para la versión estable: más de 20 arreglos en mazmorras con grupo, combate, el mapa, Pesca, Talentos y más."] = "为稳定版进行的全面检查：在组队地下城、战斗、地图、钓鱼、天赋等方面修复了 20 多处问题。",
	["Una ruta es tu árbol de tramos: misiones de XP, de oro, de clase, materiales u objetos. Elige una de estas para empezar:"] = "路线是由路段组成的树：经验、金币或职业任务、材料或物品。选择下面其中一个开始：",
	["Una ruta necesita al menos 3 lugares que tu habilidad alcance. Elige otro tipo o recurso abajo, o recolecta aquí: Alfa anota cada nodo que encuentras."] = "一条路线至少需要 3 个你的技能能采集的地点。请在下方选择其他类型或资源，或在这里采集：Alfa 会记录你发现的每个采集点。",
	["Una ruta por los mejores lugares para tu habilidad, con unas misiones de XP en medio."] = "一条经过适合你技能的最佳地点的路线，中间穿插一些经验任务。",
	["Una salchicha al día mantiene a la loba feliz. Es ciencia."] = "一天一根香肠，母狼开心一整天。这是科学。",
	["Una semana de caza juntos"] = "一起狩猎的一周",
	["Una sesión termina tras 20 minutos sin lanzar o cuando empiezas otra; entonces aparece aquí con lo que sacaste y dónde."] = "20 分钟没有抛竿或你开始新的一次时，本次钓鱼就会结束；之后它会显示在这里，附上你钓到的东西和地点。",
	["Una sesión tranquila: nada nuevo que contar."] = "平静的一次游戏：没有什么新鲜事。",
	["Una sola voz: Hoy, las bolsas y Lya ya no repiten lo mismo."] = "一个声音：今日、背包和 Lya 不再重复同样的话。",
	["Una tecla para todo: equipo, cebo, lanzar y recoger. Con diario, guía, cocina, metas y estadísticas."] = "一个键包办一切：装备、鱼饵、抛竿和收竿。还有图鉴、指南、烹饪、目标和统计。",
	["Una tormenta de hielo en un área. Ideal contra grupos."] = "在一片区域降下冰风暴。对付成群敌人很棒。",
	["Una vuelta de recolección en tu zona"] = "在你的区域采集一圈",
	["Une los %d lugares que tu habilidad alcanza en una vuelta corta, la dibuja en el mapa y la flecha te lleva de parada en parada."] = "把你的技能能采集的 %d 个地点连成一条短环线，画在地图上，箭头会逐站带你。",
	["Unir las capas de sombra"] = "融合阴影层",
	["Unirte al grupo de tus amigos"] = "加入好友的队伍",
	["Uno de los dragones verdes de la pesadilla aparece en el Bosque del Ocaso, junto a un gran árbol."] = "梦魇中的一只绿龙会出现在暮色森林的一棵巨树旁。",
	["Uno menos"] = "少一个",
	["Uno más"] = "多一个",
	["Unos %d pasos a tu ritmo"] = "按你的节奏大约 %d 步",
	["Unos %s de juego a tu ritmo (%s XP por hora)."] = "按你的节奏大约还要玩 %s（每小时 %s 经验）。",
	["Unos materiales: %s."] = "关于这些材料：%s。",
	["Unos pocos altos elfos siguen con la Alianza; viven en Quel'Danil, en las Tierras del Interior."] = "少数高等精灵仍留在联盟；他们住在辛特兰的奎尔丹尼尔。",
	["Unos prefieren que yo haga lo aburrido y otros quieren hacerlo todo. Tú dime, y si cambias de idea, lo cambias cuando quieras."] = "有人喜欢让我做无聊的事，有人想全部自己来。告诉我吧，改主意了随时可改。",
	["Usa %s"] = "使用%s",
	["Usa %s: tu tecla lo pone."] = "使用%s：你的按键会帮你装上。",
	["Usa Bloquear con escudo cuando un jefe pegue fuerte."] = "首领打得痛时使用盾牌格挡。",
	["Usa Deseo de muerte al empezar contra un jefe."] = "打首领时开场就用死亡之愿。",
	["Usa Deseo de muerte con monstruos difíciles, no con los fáciles."] = "死亡之愿留给难打的怪物，别浪费在容易的怪身上。",
	["Usa Golpe mortal sobre todo contra sanadores."] = "致死打击优先对治疗者使用。",
	["Usa Golpes de barrido cuando haya dos o más enemigos juntos."] = "有两个或更多敌人聚在一起时使用横扫攻击。",
	["Usa Ira rabiosa para romper miedos."] = "用狂暴之怒解除恐惧。",
	["Usa Revancha cada vez que se ilumine y Hender armadura para sumar amenaza."] = "复仇一亮就用，再用破甲攻击叠加威胁。",
	["Usa Transfusión de vida para recuperar maná a cambio de vida."] = "用生命分流以生命值换取法力值。",
	["Usa a tu demonio para frenar al monstruo mientras lanzas."] = "施法时让你的恶魔拖住怪物。",
	["Usa el juicio y vuelve a poner tu sello enseguida."] = "使用审判后立刻重新挂上圣印。",
	["Usa el número de abajo en lugar del que detecta el juego."] = "使用下方的数值，而不是游戏检测到的数值。",
	["Usa el número de abajo para el blanco normal."] = "使用下方的数值作为一般白色。",
	["Usa el resaltado del propio juego sobre el botón de la habilidad sugerida."] = "在建议技能的按钮上使用游戏自带的高亮效果。",
	["Usa la forma felina con un monstruo y la de oso si vienen varios."] = "单个怪物用猎豹形态，来了好几个就用熊形态。",
	["Usa tu golpe principal para juntar puntos de combo y gástalos en tu remate."] = "用主力攻击攒连击点，再用终结技消耗掉。",
	["Usa tu piedra de hogar"] = "使用你的炉石",
	["Usa tu piedra de hogar: te lleva a tu posada."] = "使用你的炉石：它会把你带回旅店。",
	["Usa tu varita cuando quieras ahorrar maná."] = "想节省法力时就用魔杖。",
	["Usa tus hechizos de control si se te juntan dos monstruos."] = "被两个怪物围住时使用控制法术。",
	["Usa un arma lenta y fuerte: tus mejoras de arma pegan con cada golpe."] = "使用慢速高伤害的武器：你的武器强化效果每次攻击都会生效。",
	["Usa una varita para rematar enemigos sin gastar maná."] = "用魔杖补刀，不用花法力。",
