	["Ve con cuidado: la presa también muerde."] = "小心点：猎物也会咬人。",
	["Ve quién de tu hermandad busca grupo y pon tu anuncio. Se quita solo en una hora."] = "看看公会里谁在找队伍，并发布你的公告。一小时后会自动撤下。",
