	["Y una prueba nueva que juega Alfa de punta a punta antes de cada versión, para que estos errores no regresen."] = "还有一项新测试，每次发布前都会让 Alfa 从头到尾跑一遍，确保这些错误不再出现。",
	["Ya casi no cabe nada: %d libres. Lo gris es oro fácil con cualquier vendedor."] = "快装不下了：只剩 %d 格。灰色物品卖给任何商人都是轻松的金币。",
