	["{dia}/{mes}"] = "{mes}月{dia}日",
	["¡%d misiones entregadas hoy! Así se caza en manada."] = "今天已经交了 %d 个任务！狼群就是这样狩猎的。",
	["¡%d misiones hoy! A este paso me debes una salchicha."] = "今天 %d 个任务！照这速度你要欠我一根香肠了。",
	["¡%d misiones hoy! Estás que no te para nadie."] = "今天完成了 %d 个任务！谁也挡不住你。",
	["¡%s al máximo: %d/%d! Ya no hay nada que te enseñen. Qué orgullo, de verdad."] = "%s 已满级：%d/%d！已经没有什么可以教你的了。真为你骄傲。",
	["¡%s cazó a %s!"] = "%s 猎到了 %s！",
	["¡%s es tu aprendiz!"] = "%s 成了你的学徒！",
	["¡%s llegó al nivel %d!"] = "%s 升到了 %d 级！",
	["¡%s subió a nivel %d! Auuuu, felicidades."] = "%s 升到了 %d 级！嗷呜，恭喜。",
	["¡%s tiene su primera montura!"] = "%s 拿到了第一匹坐骑！",
	["¡%s ya está feliz! Así sí da gusto cazar juntos."] = "%s 开心了！一起狩猎就该是这样。",
	["¡%s!"] = "%s！",
	["¡%s! Hace días que no te veía. En Hoy te digo dónde íbamos."] = "%s！好几天没见到你了。在“今天”里我会告诉你我们上次到哪儿了。",
	["¡%s! Si algo te pega, corre hacia el tanque, no lejos de él."] = "%s！被打的时候，往坦克那边跑，别跑远。",
	["¡%s! Te extrañé mucho. Vine corriendo en cuanto te vi llegar."] = "%s！我好想你。一看到你来，我就跑过来了。",
	["¡%s, listo! La manada aúlla por ti. Auuuu. ¿Y mi salchicha?"] = "%s，完成！狼群为你嚎叫。嗷呜呜。那我的香肠呢？",
	["¡%s, volviste! Te extrañé tanto que no paraba de mover la cola."] = "%s，你回来啦！我想你想得尾巴都摇个不停。",
	["¡Abrumar!"] = "压制！",
	["¡Ahora sí te sigo corriendo con la lengua de fuera!"] = "现在我要吐着舌头追着你跑啦！",
	["¡Ahí estás, %s! Si quieres un consejo, dame clic."] = "你在这儿呀，%s！想要建议就点我。",
	["¡Ahí estás, %s! Te estaba esperando… te extrañé."] = "你在这儿呀，%s！我一直在等你……好想你。",
	["¡Al máximo!"] = "满级了！",
	["¡Arriba, lobo! Antes de volver a pelear, recupera vida y maná."] = "起来吧，狼！再次战斗之前，先恢复生命值和法力值。",
	["¡Arriba, lobo! Caer es parte de la cacería. Al revivir, repara tu equipo."] = "起来吧，狼！倒下也是狩猎的一部分。复活后记得修理装备。",
	["¡Arriba, lobo! Libera tu espíritu: la flecha te dice si conviene tu cuerpo o el sanador."] = "起来吧，狼！释放灵魂：箭头会告诉你是回到尸体更划算，还是找灵魂医者。",
	["¡Arriba, lobo! Si eran muchos, la próxima jálalos de uno en uno."] = "起来吧，狼！如果怪太多，下次一只一只地拉。",
	["¡Arriba, nivel %d! Si tienes un punto de talento libre, no lo olvides."] = "升到 %d 级了！如果有未分配的天赋点数，别忘了。",
	["¡Así se ve un aviso!"] = "提醒就是这个样子！",
	["¡Ataque de la victoria!"] = "乘胜追击！",
	["¡Auuu! Juntas cazamos mejor."] = "嗷呜！我们一起狩猎更厉害。",
	["¡Auuu! Toda la manada está de fiesta."] = "嗷呜！整个狼群都在庆祝。",
	["¡Auuuu! La manada unida no se rinde."] = "嗷呜呜！团结的狼群绝不放弃。",
	["¡Auuuu! ¡Nivel %d y dos niveles en menos de media hora! Vas como lobo en luna llena."] = "嗷呜！%d 级了，不到半小时就升了两级！你就像满月下的狼。",
	["¡Bien hecho! %s"] = "干得好！%s",
	["¡Buen día, %s! El sol ya salió en Azeroth. ¿Vamos?"] = "早安，%s！艾泽拉斯的太阳已经升起来了。走吧？",
	["¡Buenas noches, %s! Las lobas cazamos mejor de noche."] = "晚上好，%s！我们母狼在夜里最会狩猎。",
	["¡Buenas tardes, %s! Buena hora para unas misiones."] = "下午好，%s！正是做几个任务的好时候。",
	["¡Buenas, %s! Paso a paso se llega lejos."] = "你好，%s！一步一步就能走得很远。",
	["¡Buenos días! Un buen desayuno y a cazar, que la mañana rinde."] = "早上好！吃顿好早餐就去狩猎：早上效率最高。",
	["¡Buenos días, %s! Me estiro, bostezo y estoy lista."] = "早上好，%s！伸个懒腰，打个哈欠，我准备好啦。",
	["¡Bájale, casi se lo quitas al tanque!"] = "收着点，你快把仇恨从坦克那里抢过来了！",
	["¡Claro! Saludo a tu mascota cuando la llamas y, si eres cazador, te aviso cuando tiene hambre o está triste para que le des de comer."] = "当然！你召唤宠物时我会跟它打招呼；如果你是猎人，它饿了或不开心时我会告诉你，好让你喂它。",
	["¡Completaste %s!"] = "你完成了%s！",
	["¡Contraataque!"] = "反击！",
	["¡Cumplido! Salchicha ganada."] = "完成！赢得一根香肠。",
	["¡Córtale a tu foco!"] = "打断你的焦点！",
	["¡Córtalo!"] = "打断它！",
	["¡De vuelta con la manada!"] = "欢迎回到狼群！",
	["¡De vuelta en la manada, %s!"] = "欢迎回到狼群，%s！",
	["¡Ejecutar!"] = "斩杀！",
	["¡En Thelsamar venden morcilla! La morcilla de Thelsamar es casi una salchicha... ¿me compras una?"] = "塞尔萨玛有卖血肠！塞尔萨玛血肠差不多就是香肠了……给我买一根好吗？",
	["¡Es Halloween de Azeroth! Pide dulces a los posaderos: a veces te disfrazan de algo chistoso."] = "万圣节到了！向旅店老板要糖果：有时他们会把你变成好玩的样子。",
	["¡Es ahora! Hasta las %s"] = "就是现在！持续到 %s",
	["¡Es el Festival del Fuego del Solsticio! Visita las hogueras de las ciudades y honra su llama."] = "仲夏火焰节到了！去主城的篝火看看，向它们的火焰致敬。",
	["¡Espera! Dejas %d misiones listas sin entregar. Si no, mañana empezamos por ahí."] = "等等！你还有 %d 个已完成的任务没交。不交的话，下次我们就从那儿开始。",
	["¡Esto le sirve a %s!"] = "这个 %s 用得上！",
	["¡Está lanzando!"] = "它在施法！",
	["¡Explorada completa!"] = "已全部探索！",
	["¡Felicidades por el nivel %d, %s! Auuuu."] = "恭喜升到 %d 级，%s！嗷呜。",
	["¡Feliz cumpleaños!"] = "生日快乐！",
	["¡Feliz cumpleaños, Alfa!"] = "Alfa，生日快乐！",
	["¡Gracias! Ya van %d salchichas que me das. Las llevo contadas, eh."] = "谢谢！你已经给我 %d 根香肠了。我可都数着呢。",
	["¡Hasta pronto! Aquí te espero, cuidando tu lugar."] = "回头见！我在这里等你，帮你守着位置。",
	["¡Hasta pronto! Hoy cazamos %s Aquí te espero."] = "回头见！今天我们猎到了：%s 我在这里等你。",
	["¡Hay algo nuevo en Alfa: %s! ¿Te lo enseño?"] = "Alfa 有新东西：%s！要我带你看看吗？",
	["¡Hola!"] = "你好！",
	["¡Hola! Pregúntame lo que quieras de Alfa: te lo explico corto y te llevo."] = "嗨！关于 Alfa 随便问：我简单讲讲，再带你过去。",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Cuido a la manada y voy contigo en el camino."] = "你好！我是 Lya，Alfa 最信任的母狼。我守护狼群，也会陪你一路同行。",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Voy a acompañarte en esta configuración y después en tu camino."] = "嗨！我是莉娅，头狼信赖的狼。我会陪你完成这次设置，之后陪你上路。",
	["¡Hola, %s!"] = "你好，%s！",
	["¡Hola, %s! Familia %s y de buena casta. Tú y yo vamos a cuidar a nuestro alfa."] = "你好，%s！%s家族，血统优良。你和我一起照顾我们的头狼吧。",
	["¡Hola, %s! Hoy huele a buena cacería."] = "你好，%s！今天闻起来是个狩猎的好日子。",
	["¡Hola, %s! La tarde pinta tranquila. ¿Qué cazamos hoy?"] = "你好，%s！今天下午看起来很平静。我们去猎点什么？",
	["¡Hola, %s! Noche de luna: perfecta para la manada."] = "你好，%s！月夜——最适合狼群了。",
	["¡Hola, %s! Tú y yo vamos a cuidar a nuestro alfa."] = "你好，%s！你和我一起照顾我们的头狼吧。",
	["¡Hoy Alfa cumple %d años! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "今天是 Alfa 的 %d 岁生日！La Jauría 用心为你打造了它。我们用一根香肠来庆祝好吗？",
	["¡Hoy Alfa cumple 1 año! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "今天是 Alfa 的 1 岁生日！La Jauría 用心为你打造了它。我们用一根香肠来庆祝好吗？",
	["¡Hoy cumplimos %d años cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "今天我们一起狩猎满 %d 年了，%s！谢谢你让我当你的母狼。嗷呜呜。",
	["¡Hoy cumplimos 1 año cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "今天我们一起狩猎满 1 年了，%s！谢谢你让我当你的母狼。嗷呜呜。",
	["¡La Lya de %s me contestó el saludo! Ya somos manada."] = "%s 的莉娅回应了我的招呼！我们现在是一个狼群了。",
	["¡La Lya de %s me saludó! Entre lobas nos entendemos."] = "%s 的莉娅跟我打招呼了！母狼之间最懂彼此。",
	["¡Le encantan! Pero las mías son más ricas."] = "它超爱的！不过我的更好吃。",
	["¡Listo! %s precios guardados."] = "完成！已保存 %s 个价格。",
	["¡Listo! Alfa ya es tuyo"] = "完成！Alfa 已经属于你",
	["¡Llegó el Festival de Invierno! En Forjaz y Orgrimmar el árbol se llena de luces y regalos."] = "冬幕节到了！铁炉堡和奥格瑞玛的大树挂满了灯和礼物。",
	["¡Lo lograste: %s! Esa salchicha de premio me la voy a comer despacito."] = "你做到了：%s！那根奖励香肠我要慢慢吃。",
	["¡Lo tienes! %s ×%d"] = "到手了！%s ×%d",
	["¡Martillo de cólera!"] = "愤怒之锤！",
	["¡Mi primera salchicha contigo! Esta no la voy a olvidar nunca."] = "和你的第一根香肠！这根我永远不会忘。",
	["¡Misión completada: %s!"] = "任务完成：%s！",
	["¡Mmm, qué rica! Gracias, eres el mejor lobo de la manada."] = "嗯，真好吃！谢谢，你是狼群里最好的狼。",
	["¡Mordedura de mangosta!"] = "猫鼬撕咬！",
	["¡Nivel %d! Date un momento para presumirlo, te lo ganaste."] = "%d 级了！花点时间炫耀一下吧，这是你应得的。",
	["¡Nivel %d! Paso firme y colmillo afilado."] = "%d 级了！脚步稳健，獠牙锋利。",
	["¡Nivel %d! Tu esfuerzo se nota. Sigue así."] = "%d 级了！你的努力看得见。继续保持。",
	["¡Nivel %d! ¡Auuu! Así se sube en manada."] = "%d 级了！嗷呜——狼群就是这样升级的。",
	["¡Nivel %d, bien hecho! Revisa si tu entrenador tiene algo nuevo."] = "%d 级了，干得好！看看你的训练师有没有新东西。",
	["¡Nivel %d, y el anterior hace nada! Aúllo dos veces, una por cada uno. ¡Auuuu, auuuu!"] = "%d 级，上一级才刚升！我嚎两声，一级一声。嗷呜，嗷呜！",
	["¡Nivel 10! Ya tienes talentos: elígelos con calma, Talentos te ayuda."] = "10 级了！你有天赋了：慢慢选，“天赋”会帮你。",
	["¡Nivel 20! Ya puedes con mazmorras de verdad. ¿Armamos grupo?"] = "20 级了！你可以挑战真正的地下城了。组个队吧？",
	["¡Nivel 30! Ya vas a la mitad del camino. ¡Qué orgullo de manada!"] = "30 级了！你已经走完一半了。狼群真为你骄傲！",
	["¡Nivel 40! Ya puedes aprender a montar. ¡Tu primera montura te espera!"] = "40 级了！你可以学骑术了。你的第一匹坐骑在等你！",
	["¡Nivel 50! Ya se huele la cima. Junta oro para lo que viene."] = "50 级了！已经闻到顶峰的气息了。为接下来的事攒点金币。",
	["¡Nivel 60! ¡Lo lograste, alfa! Ahora toca cazar en grande."] = "60 级了！你做到了，头狼！现在该来一场大狩猎了。",
	["¡Nueva página en tu historia: %s! %s"] = "你的故事翻开新的一页：%s！%s",
	["¡Nuevo récord: %d misiones en un día! Ni la manada te alcanza."] = "新纪录：一天 %d 个任务！狼群都追不上你。",
	["¡Ojo! Tu precio está %d %% por debajo de lo que vale."] = "小心！你的价格比它的价值低了 %d %%。",
	["¡Otro nivel tan pronto! Nivel %d. ¡Auuuu, esta racha no la para nadie!"] = "这么快又升级了！%d 级。嗷呜，谁也挡不住这股势头！",
	["¡Perdiste su atención!"] = "你失去了它的仇恨！",
	["¡Plan cumplido!"] = "计划完成！",
	["¡Plan terminado!"] = "计划完成！",
	["¡Primera vez! Nuevo en tu diario"] = "第一次！已加入你的图鉴",
	["¡Qué buena racha traes! Sigue así."] = "你的状态真好！继续保持。",
	["¡Qué bueno tenerte de vuelta, %s! Aquí sigo, cuidándote la espalda."] = "真高兴你回来了，%s！我还在这里守着你的背后。",
	["¡Qué gusto verte de vuelta! Esto es lo que trae esta versión para ti y tu manada."] = "真高兴再次见到你！这是本版本为你和你的狼群带来的内容。",
	["¡Qué gusto verte, %s! La manada ya te esperaba."] = "真高兴见到你，%s！狼群一直在等你。",
	["¡Repara tu equipo!"] = "修理你的装备！",
	["¡Reto cumplido: %s! Me gané una salchicha... digo, te la ganaste tú. Bueno, nos la ganamos."] = "挑战完成：%s！我赢得了一根香肠……我是说，是你赢的。好吧，是我们一起赢的。",
	["¡Revancha!"] = "复仇！",
	["¡Salchicha! *mueve la cola a toda velocidad* Gracias, gracias."] = "香肠！*尾巴摇得飞快* 谢谢，谢谢。",
	["¡Salimos de %s! %s adentro."] = "我们走出%s了！在里面 %s。",
	["¡Salimos de la mazmorra! %s adentro."] = "我们走出地下城了！在里面 %s。",
	["¡Sesenta! Lo lograste. Me debes una salchicha gigante."] = "六十级！你做到了。你欠我一根超大香肠。",
	["¡Subiste a nivel %d! Cada nivel te hace más fuerte."] = "你升到了 %d 级！每升一级都让你更强。",
	["¡Sí, acompáñame!"] = "好，陪着我！",
	["¡Te está atacando a ti!"] = "它在攻击你！",
	["¡Te extrañé, %s! Corrí hasta aquí para verte."] = "我好想你，%s！我一路跑过来，就是为了见你。",
	["¡Te extrañé, %s! Tu ruta sigue donde la dejaste."] = "我好想你，%s！你的路线还在你离开的地方。",
	["¡Terminaste %s!"] = "你完成了%s！",
	["¡Terminaste esta guía!"] = "你完成了这个指南！",
	["¡Terminaste esta guía! Elige la siguiente y sigue subiendo con la manada."] = "你完成了这个指南！选择下一个，和狼群一起继续升级吧。",
	["¡Terminaste tu guía!"] = "你完成了你的指南！",
	["¡Tienes todo!"] = "全都有了！",
	["¡Tierra a la vista! La manada desembarca en %s"] = "看到陆地了！狼群在%s登岸",
	["¡Tierra a la vista: %s!"] = "看见陆地了：%s！",
	["¡Todo listo para la mazmorra!"] = "地下城准备就绪！",
	["¡Tu %s llegó a %d/%d! Ya puedes aprender el rango %s."] = "你的%s达到了 %d/%d！现在可以学习%s等级了。",
	["¡Tu lista de compras está completa!"] = "你的购物清单齐了！",
	["¡Tú!"] = "你！",
	["¡Va! Te lo sigo diciendo, con gusto."] = "好嘞！我会继续告诉你，乐意之至。",
	["¡Van %d misiones hoy! La manada está orgullosa."] = "今天 %d 个任务！狼群为你骄傲。",
	["¡Volviste, %s! Estira las patas y vámonos."] = "你回来了，%s！伸伸腿，我们出发吧。",
	["¡Voy!"] = "我来了！",
	["¡Vuelta completa!"] = "路线完成！",
	["¡Ya eres nivel %d! La manada aúlla por ti."] = "你已经 %d 级了！狼群为你嚎叫。",
	["¡Ya estamos en %s! Deja que el tanque jale primero y quédate cerca de quien cura."] = "我们到%s了！让坦克先拉怪，你待在治疗者附近。",
	["¡Ya estamos en la mazmorra! Deja que el tanque jale primero y quédate cerca de quien cura."] = "我们进地下城了！让坦克先拉怪，你待在治疗者附近。",
	["¡Ya estás en la %s!"] = "你到了%s！",
	["¡Ya estás en otro plano!"] = "你已经在另一个位面了！",
	["¡Ya la desbloqueaste!"] = "你解锁了！",
	["¡Ya llegaste al 60!"] = "你到 60 级了！",
	["¡Ya llegaste, %s! Te extrañé. ¿A dónde vamos hoy?"] = "你来啦，%s！我好想你。今天我们去哪儿？",
	["¡Ya llegó! Vamos, manada"] = "到了！走吧，狼群",
	["¡Ya terminaste %d misiones! Vamos a cobrar la recompensa."] = "你已经完成了 %d 个任务！我们去领奖励吧。",
	["¡Ya!"] = "就是现在！",
	["¡Yo te la guardé! En Historias está todo lo que cuentan tus misiones, para leerlo cuando quieras."] = "我帮你存着！“故事”里有你任务讲过的一切，随时可读。",
	["¡Ñam! Con esta van %d. Eres mi persona favorita de todo Azeroth."] = "啊呜！这是第 %d 根了。你是全艾泽拉斯我最喜欢的人。",
	["«%s» tiene su historia. ¿Te la cuento?"] = "“%s”有一段故事。要我讲给你听吗？",
	["«%s» ya quedó. Su final vale la pena, ¿te lo cuento?"] = "“%s”已经完成了。它的结局很值得一听，要我讲给你听吗？",
	["«%s»: hay que llevar el recado y hablar con quien te espera."] = "“%s”：把口信送到，和等你的人谈谈。",
	["«%s»: toca %s."] = "“%s”：该%s了。",
	["«Alejar más la cámara» de Comodidades está encendido y manda sobre este valor al entrar."] = "便利功能中的“镜头拉得更远”已开启，登录时会覆盖此数值。",
	["«Buscar cerca» en la página Hoy"] = "“今天”页面中的“搜索附近”",
	["«Buscar cerca» te lleva con flecha a lo que necesitas, y «Mis planes» arma tus propias metas, que se marcan solas."] = "“搜索附近”会用箭头带你去你需要的地方，“我的计划”可以制定你自己的目标，完成后会自动勾选。",
	["«Camino al 60» en Hoy"] = "“今天”里的“通往 60 级之路”",
	["«Cerrar mis misiones» está al día"] = "“完成我的任务”已是最新",
	["«Igual que Alfa» sigue el estilo de Ajustes > Apariencia y cambia con él."] = "“与 Alfa 相同”会跟随“设置 > 外观”中的风格，并随之变化。",
	["«Invitar al clan» en el clic derecho"] = "右键菜单中的“邀请加入公会或社区”",
	["«Llévame a…» (página Ruta, tu tecla o /alfa llevame): eliges el lugar y te llevo con vuelos, barcos, zepelines y portales, tramo por tramo."] = "“带我去……”（路线页面、你的按键或 /alfa llevame）：选好地点，我会用飞行、船只、飞艇和传送门一段一段带你去。",
	["«Llévame» pone la flecha en este paso; «Siguiente» lo da por hecho y te lleva al que sigue."] = "“带我去”让箭头指向这一步；“下一步”标记完成并带你去下一步。",
	["«Ponte esto» con el equipo mejor"] = "更好的装备提示“穿上这个”",
	["«Ponte esto», lista de compras, oficios del 1 al 300 y subastar fácil."] = "“装备上”、购物清单、专业 1 到 300 和轻松拍卖。",
	["«Prepárame» recoge solo las que ya puedes tomar y te lleva a la entrada."] = "“帮我准备”只会接取你现在能接的任务，并带你去入口。",
	["«Reportar» ya los lleva."] = "“报告”里已经包含了。",
	["«Seguir» en La Jauría ya no se suelta cuando tu guía cambia de paso ni cuando vas por tu cuerpo: al terminar, la flecha vuelve con quien sigues."] = "La Jauría 的“跟随”不会在指南换步骤或你跑回尸体时断开：结束后，箭头会重新指向你跟随的人。",
	["«Siempre» sirve si un amigo encantador te ayuda. Las tablas de desencantar son estimadas."] = "如果有附魔师朋友帮忙，可以选“总是”。分解数据表为估计值。",
	["«Tomar todo» en el buzón"] = "邮箱“全部拾取”",
	["«Tomar todo» en el buzón, tu oro por hora y aviso de bolsas casi llenas."] = "邮箱“全部拾取”、每小时金币，以及背包快满时的提醒。",
	["«Ver el siguiente» te deja mirar el paso que viene y lo dice claro; y un solo contador de pasos hechos."] = "“查看下一步”让你先看看接下来的步骤，并清楚标明正在预览；已完成步骤也只用一个计数。",
	["«[Misión] está lista para entregar» y «¡Misión completada!» en el chat del grupo, para todos. Apagado, solo te salen a ti."] = "在队伍聊天中向所有人显示“[任务] 可以交付了”和“任务完成！”。关闭时只有你看到。",
	["«[Misión] está lista para entregar» y «¡Misión completada!». En grupo lo ve todo el grupo; solo, sale en tu chat."] = "“[任务] 可以交付了”和“任务完成！”。组队时全队可见；单人时显示在你的聊天框。",
