	["¿Cómo me cambio de plano si hay mucha gente?"] = "人太多时怎么切换位面？",
	["¿Cómo me entero de raros de la manada?"] = "怎么知道狼群发现的稀有怪？",
	["¿Cómo me fue en la pelea?"] = "这场战斗打得怎么样？",
	["¿Cómo me fue esta semana?"] = "我这周怎么样？",
	["¿Cómo me fue hoy?"] = "我今天怎么样？",
	["¿Cómo pesco más fácil?"] = "怎么更轻松地钓鱼？",
	["¿Cómo pido ayuda a la manada?"] = "怎么向狼群求助？",
	["¿Cómo quieres hacerlo?"] = "你想怎么做？",
	["¿Cómo quieres que se vea Alfa?"] = "你希望 Alfa 是什么样子？",
