	["¿Cómo subo mi oficio de 1 a 300?"] = "怎么把专业从 1 练到 300？",
	["¿Cómo sé cuándo cortar un hechizo?"] = "怎么知道什么时候该打断法术？",
	["¿Cómo sé cuándo vuelven mis habilidades grandes?"] = "怎么知道我的大技能什么时候冷却好？",
	["¿Cómo sé si le voy a quitar el enemigo al tanque?"] = "怎么知道我会不会从坦克那里抢走仇恨？",
	["¿Cómo sé si lo que me cayó es mejor?"] = "怎么知道我的战利品是不是更好？",
	["¿Cómo veo toda la cadena de una misión?"] = "怎么查看一个任务的完整任务链？",
	["¿Dónde consigo un objeto o encuentro a alguien?"] = "去哪弄一件物品或找到某人？",
	["¿Dónde farmea la manada?"] = "狼群都在哪里刷？",
	["¿Dónde hay minas o hierbas?"] = "哪里有矿或草药？",
	["¿Dónde subo mi pesca?"] = "去哪练钓鱼？",
	["¿Empezar el medidor de cero?"] = "要将伤害统计清零吗？",
	["¿Empezar una sesión nueva?"] = "开始新的钓鱼记录？",
	["¿En qué guarida anda la manada?"] = "狼群在哪个巢穴？",
	["¿En qué idioma quieres Alfa?"] = "你希望 Alfa 使用哪种语言？",
	["¿En qué orden hago las misiones de mi zona?"] = "我该按什么顺序做这个区域的任务？",
	["¿En qué te ayudo?"] = "我能帮你什么？",
	["¿En qué te ayudo? Toca una pregunta o una página y te cuento."] = "我能帮你什么？点一个问题或页面，我来告诉你。",
	["¿Eso que huele es pan de la posada? Mi nariz nunca se equivoca."] = "闻到的是旅店的面包吗？我的鼻子从来不会错。",
	["¿Estoy listo para la mazmorra?"] = "我准备好去地下城了吗？",
	["¿Hay alguna fiesta hoy en Azeroth?"] = "今天艾泽拉斯有节日吗？",
	["¿La haces con tu manada o la saltas?"] = "要和狼群一起做，还是跳过？",
	["¿La vuelves a tomar o la sacas de la ruta?"] = "要重新接取，还是从路线中移出？",
	["¿Me cuentas de qué va una misión?"] = "能跟我讲讲任务是关于什么的吗？",
	["¿Mi Lya conoce a las de mi grupo?"] = "我的莉娅认识我队友的莉娅吗？",
	["¿Mi grupo ve cuando completo una misión?"] = "我完成任务时队伍能看到吗？",
	["¿Mucha gente? Te paso al plano de un lobo de la manada con su guarida abierta."] = "人太多？我把你转到一只开着巢穴的狼群伙伴的位面。",
	["¿Nos cambiamos de plano?"] = "我们换个位面吧？",
