	["¿Qué citas tiene la manada esta semana?"] = "狼群这周有哪些集合？",
	["¿Qué comida y agua compro?"] = "该买什么食物和水？",
	["¿Qué dice la nota?"] = "笔记写什么？",
	["¿Qué es Alfa?"] = "Alfa 是什么？",
