	["¿Qué gano con esta pieza?"] = "这件装备能让我得到什么？",
	["¿Qué guardo en el banco?"] = "哪些东西该放银行？",
	["¿Qué habilidad uso en combate?"] = "战斗里用哪个技能？",
	["¿Qué hace Alfa con comerciantes y viajes?"] = "Alfa 在商人和旅行方面会做什么？",
