	["¿Qué hay de nuevo? (%d)"] = "有什么新鲜事？(%d)",
	["¿Qué hizo la manada esta semana?"] = "狼群这周做了什么？",
	["¿Qué mazmorra me toca?"] = "哪个地下城适合我？",
	["¿Qué me conviene vender en la subasta?"] = "拍卖行卖什么划算？",
	["¿Qué me dijiste hace rato?"] = "你刚才跟我说了什么？",
	["¿Qué me falta para una receta?"] = "做一个配方我还缺什么？",
	["¿Qué me falta por explorar en esta zona?"] = "这个区域还有哪里没探索？",
	["¿Qué me puede caer en una mazmorra?"] = "地下城会掉什么？",
	["¿Qué misiones grises puedo abandonar?"] = "哪些灰色任务可以放弃？",
	["¿Qué nos quieres contar?"] = "你想告诉我们什么？",
	["¿Qué quieres hacer hoy?"] = "今天想做什么？",
	["¿Qué quieres hacer?"] = "你想做什么？",
	["¿Qué responde Alfa por ti a otros jugadores?"] = "Alfa 会替你如何回应其他玩家？",
