	["¿Qué talentos pongo?"] = "天赋怎么点？",
	["¿Reiniciar los gráficos?"] = "重启图形？",
	["¿Restaurar este respaldo?"] = "恢复这份备份？",
	["¿Sabías que las lobas tenemos el mejor oído de la manada? Bueno, eso digo yo."] = "你知道吗？我们母狼的听力是狼群里最好的。嗯，这是我说的。",
	["¿Sabías que…? Alfa junta tus misiones listas en una sola ruta corta."] = "你知道吗……？Alfa 会把你已完成的任务排成一条短路线。",
	["¿Sabías que…? Alfa tiene tres estilos: Alfa, Clásico WoW y Cristal. Y yo me pongo el que elijas."] = "你知道吗……？Alfa 有三种风格：Alfa、经典 WoW 和玻璃。你选哪种，我就换上哪种。",
	["¿Sabías que…? Alt+clic en un objeto lo abre en la Enciclopedia."] = "你知道吗……？Alt+点击物品就能在百科中打开它。",
	["¿Sabías que…? Buscar cerca te lleva al herrero, al banco o al vuelo más cercano."] = "你知道吗……？“搜索附近”能带你去最近的铁匠、银行或飞行点。",
	["¿Sabías que…? Comercio te dice si algo conviene venderlo, subastarlo o convertirlo."] = "你知道吗……？“交易”会告诉你某样东西是该卖给商人、拍卖还是加工。",
	["¿Sabías que…? Con /alfa reportar le cuentas a toxic3000 de un error o una idea."] = "你知道吗……？用 /alfa reportar 可以把错误或想法告诉 toxic3000。",
	["¿Sabías que…? Con Pesca lanzas y recoges con una sola tecla."] = "你知道吗……？用“钓鱼”只需一个键就能抛竿和收竿。",
	["¿Sabías que…? Con clic derecho sobre mí puedes silenciarme una hora o pedirme menos consejos."] = "你知道吗……？右键点击我，可以让我静音一小时，或让我少给点建议。",
	["¿Sabías que…? Con el botón del minimapa ocultas todo Alfa y lo vuelves a traer."] = "你知道吗……？用小地图按钮可以隐藏整个 Alfa，也能再把它叫回来。",
	["¿Sabías que…? El mapa de Alfa muestra el terreno, tus marcadores y lo que hay cerca."] = "你知道吗……？Alfa 的地图会显示地形、你的标记和附近的东西。",
	["¿Sabías que…? En Bolsas ves tus bolsas, tu banco y lo de todos tus personajes."] = "你知道吗……？在“背包”中可以看到你的背包、银行以及你所有角色的物品。",
	["¿Sabías que…? En La Jauría ves a tu grupo y a la manada que usa Alfa."] = "你知道吗……？在 La Jauría 中可以看到你的队伍和使用 Alfa 的狼群。",
	["¿Sabías que…? En Mis planes armas tu propia lista de metas y la flecha te guía."] = "你知道吗……？在“我的计划”中可以制定自己的目标清单，箭头会为你指路。",
	["¿Sabías que…? En Talentos ves qué talento poner ahora y por qué."] = "你知道吗……？在“天赋”中可以看到现在该点哪个天赋以及原因。",
	["¿Sabías que…? La Enciclopedia te dice dónde sale cada objeto, PNJ o misión."] = "你知道吗……？百科会告诉你每件物品、每个 NPC 或任务在哪里。",
	["¿Sabías que…? La página Hoy te dice qué hacer ahora y lo urgente de tu personaje."] = "你知道吗……？“今天”页面会告诉你现在该做什么，以及你角色的紧急事项。",
	["¿Sabías que…? Mazmorras te dice cuál te toca y cómo prepararte."] = "你知道吗……？“地下城”会告诉你该去哪个以及如何准备。",
	["¿Sabías que…? Recolección te marca en el mapa minerales, hierbas y bancos de peces."] = "你知道吗……？“采集”会在地图上标出矿脉、草药和鱼群。",
	["¿Soltar estas %d misiones?"] = "放弃这 %d 个任务？",
	["¿Te conté que mi comida favorita son las salchichas? Ninguna otra cosa se le acerca."] = "我说过我最爱吃的是香肠吗？别的都比不上。",
	["¿Te llevas bien con mi mascota?"] = "你和我的宠物处得来吗？",
	["¿Te puedes hacer a un lado en las peleas?"] = "战斗时你能让到一边去吗？",
	["¿Una carrerita hasta allá? Yo gano."] = "比赛跑到那边？我赢定了。",
	["¿Usar tu hechizo nuevo?"] = "使用你的新法术？",
	["¿Usar «%s»?"] = "使用“%s”？",
	["¿Vaciar tu lista de compras?"] = "清空你的购物清单？",
	["¿Vender, subastar o transformar? (escanear, precio <objeto>)"] = "卖店、拍卖还是加工？（escanear 扫描，precio <物品> 查价）",
	["¿Vender, subastar o transformar? (escanear, precio <objeto>, oficios)"] = "卖商人、拍卖还是加工？（escanear 扫描，precio <物品> 查价，oficios 专业）",
	["¿Vender, subastar o transformar? Lo que más oro te deja con cada objeto."] = "卖店、拍卖还是加工？告诉你每件物品怎样最赚钱。",
	["¿Volver a lo de antes?"] = "恢复之前的设置？",
	["¿Y el siguiente?"] = "下一个呢？",
	["¿Y si me sale algo que le sirve a otro lobo?"] = "如果我拿到别的狼用得上的东西呢？",
	["¿Y si pierdo mis ajustes?"] = "要是我的设置丢了怎么办？",
	["¿Ya exploraste todo %s? Siempre queda un rincón por ver."] = "%s你都探索完了吗？总还有角落没看过。",
	["¿Ya hiciste esta mazmorra?"] = "你已经打过这个地下城了吗？",
	["¿Ya te vas? Descansa bien. Yo me quedo vigilando hasta que vuelvas."] = "要走了吗？好好休息。我会一直守着，等你回来。",
	["¿Ya viste cómo caza %s? Me cae bien."] = "你看到 %s 是怎么狩猎的了吗？我喜欢它。",
	["¿qué quieres hacer?"] = "你想做什么？",
	["Ábrela con su botón en la barra de menú del juego: la fila de botones pequeños de abajo a la derecha."] = "用游戏菜单栏上的按钮打开它：就是右下角那排小按钮。",
	["Ábrela con tu tecla de talentos (%s) o desde el menú del juego."] = "用你的天赋键（%s）或从游戏菜单打开它。",
	["Ábrela con tu tecla de talentos o desde el menú del juego."] = "用你的天赋键或从游戏菜单打开它。",
	["Ábrela con tu tecla del Legado (%s) o con su botón en la barra de menú del juego."] = "用你的传承键（%s）或游戏菜单栏上的按钮打开它。",
	["Ábrelo con /alfa o con el lobo del minimapa. Para cambiar algo de esto: /alfa bienvenida."] = "用 /alfa 或小地图上的狼打开它。想更改这些设置：/alfa bienvenida。",
