	["última: %s"] = "上次：%s",
	["• El logo, el lobo, Lya y los módulos propios de Alfa son de toxic3000 / La Jauría (GPL-3.0)."] = "• 标志、狼、莉娅和 Alfa 自己的模块属于 toxic3000 / La Jauría（GPL-3.0）。",
	["• GatherLite, de Wuild (MIT): la base de nodos de recolección."] = "• GatherLite，作者 Wuild（MIT）：采集点数据库。",
	["• Letras Inter, Fira Sans y Open Sans (SIL Open Font License 1.1)."] = "• 字体 Inter、Fira Sans 和 Open Sans（SIL Open Font License 1.1）。",
	["• Los datos que trae Polestar también vienen de QuestieDB, Efficient Games (CC BY 4.0), VMaNGOS, CMaNGOS y Factoruide (GPL) y de ForeverLevelingBiS de Thunder (MIT); sus avisos están en cada LICENSE-DATA.txt."] = "• Polestar 的数据也来自 QuestieDB、Efficient Games（CC BY 4.0）、VMaNGOS、CMaNGOS 和 Factoruide（GPL），以及 Thunder 的 ForeverLevelingBiS（MIT）；它们的声明在各个 LICENSE-DATA.txt 中。",
	["• OpenMap, de OpenMap contributors (MIT): la lógica del mapa continuo y las máscaras de territorio."] = "• OpenMap，作者 OpenMap contributors（MIT）：无缝地图逻辑和领地遮罩。",
	["• Polestar, de The Polestar authors (GPL-3.0): el motor de guías, navegación y datos (github.com/fitzforge/polestar)."] = "• Polestar，作者 The Polestar authors（GPL-3.0）：指南、导航和数据引擎（github.com/fitzforge/polestar）。",
	["• Shortest Path Forever, de Cillian Berragan (GPL-3.0-or-later): la navegación y los servicios cercanos."] = "• Shortest Path Forever，作者 Cillian Berragan（GPL-3.0-or-later）：导航和附近服务。",
	["• TerrainWorldMap, de Dramacydal (MIT): la tabla de mosaicos del terreno del mapa."] = "• TerrainWorldMap，作者 Dramacydal（MIT）：地图地形图块表。",
